'use client';

import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import { useState, useEffect, useMemo } from 'react';
import * as api from '@modbm/sdk';
import { toast } from 'react-hot-toast';
import { useRouter } from 'next/navigation';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import PageNav from '@/components/shared/PageNav';
import { useTranslations } from 'next-intl';
import { getErrorMessage } from '@modbm/shared';

// ── Types ────────────────────────────────────────────────────────────────────

interface ApiKey {
  apiKeyId: string;
  name: string;
  prefix: string;
  role: string;
  createdOn: string;
}

interface Webhook {
  webhookId: string;
  targetUrl: string;
  eventTypes: string[];
  isActive: boolean;
  secretKey: string;
  createdOn: string;
}

export default function DevelopersPage() {
  useDocumentTitle('Developers');
  const tCommon = useTranslations('admin.common');
  const router = useRouter();

  // ── Rate Limits State ───────────────────────────────────────────────────────
  const [appForm, setAppForm] = useState<any>({});
  const [appLoading, setAppLoading] = useState(true);

  // ── API Keys State ──────────────────────────────────────────────────────────
  const [apiKeys, setApiKeys] = useState<ApiKey[]>([]);
  const [keysLoading, setKeysLoading] = useState(true);
  const [keyCreating, setKeyCreating] = useState(false);
  const [keyForm, setKeyForm] = useState({ name: '', role: 'agent' });
  const [newSecret, setNewSecret] = useState<string | null>(null);
  const [availableRoles, setAvailableRoles] = useState<any[]>([]);

  // ── Webhooks State ──────────────────────────────────────────────────────────
  const [webhooks, setWebhooks] = useState<Webhook[]>([]);
  const [webhooksLoading, setWebhooksLoading] = useState(true);
  const [webhookCreating, setWebhookCreating] = useState(false);
  const [webhookForm, setWebhookForm] = useState({ targetUrl: '', eventTypes: '' });

  // ── Data Loading ────────────────────────────────────────────────────────────

  const loadAppConfig = async () => {
    try {
      setAppLoading(true);
      const res = await api.appConfigControllerGet();
      setAppForm(res.data || {});
    } catch (err: unknown) {
      toast.error('Failed to load settings: ' + getErrorMessage(err));
    } finally {
      setAppLoading(false);
    }
  };

  const updateAppField = async (field: string, value: any) => {
    try {
      setAppForm((prev: unknown) => ({ ...((prev as Record<string, unknown>) || {}), [field]: value }));
      await api.appConfigControllerUpdate({ [field]: value });
      toast.success('Updated successfully');
    } catch (err: unknown) {
      toast.error(getErrorMessage(err));
    }
  };

  const loadKeys = async () => {
    try {
      setKeysLoading(true);
      const res = await api.apiKeysControllerList();
      setApiKeys((res.data as ApiKey[]) || []);
    } catch (err: unknown) {
      toast.error('Failed to load API keys: ' + (err as Error).message);
    } finally {
      setKeysLoading(false);
    }
  };

  const loadWebhooks = async () => {
    try {
      setWebhooksLoading(true);
      const res = await api.webhooksControllerList();
      setWebhooks((res.data as Webhook[]) || []);
    } catch (err: unknown) {
      toast.error('Failed to load Webhooks: ' + (err as Error).message);
    } finally {
      setWebhooksLoading(false);
    }
  };

  const loadRoles = async () => {
    try {
      const res = await api.rolesControllerFindAll();
      setAvailableRoles((res.data ) || []);
    } catch (err: unknown) {
      console.error('Failed to load roles', err);
    }
  };

  useEffect(() => {
    loadAppConfig();
    loadKeys();
    loadWebhooks();
    loadRoles();
  }, []);

  // ── Handlers ───────────────────────────────────────────────────────────────

  const handleCreateKey = async () => {
    if (!keyForm.name) {
      toast.error('Please provide a name');
      return;
    }
    try {
      const res = await api.apiKeysControllerCreate(keyForm);
      toast.success('API Key created');
      setNewSecret(res.data.secretKey);
      setKeyCreating(false);
      setKeyForm({ name: '', role: 'agent' });
      loadKeys();
    } catch (err: unknown) {
      toast.error(getErrorMessage(err));
    }
  };

  const handleDeleteKey = async (id: string) => {
    if (!confirm('Are you sure you want to revoke this API key?')) return;
    try {
      await api.apiKeysControllerRevoke(id);
      toast.success('API Key revoked');
      loadKeys();
    } catch (err: unknown) {
      toast.error(getErrorMessage(err));
    }
  };

  const handleCreateWebhook = async () => {
    if (!webhookForm.targetUrl || !webhookForm.eventTypes) {
      toast.error('Please provide a URL and at least one event type');
      return;
    }
    try {
      await api.webhooksControllerCreate({
        targetUrl: webhookForm.targetUrl,
        eventTypes: webhookForm.eventTypes.split(',').map(s => s.trim()).filter(Boolean),
      });
      toast.success('Webhook created');
      setWebhookCreating(false);
      setWebhookForm({ targetUrl: '', eventTypes: '' });
      loadWebhooks();
    } catch (err: unknown) {
      toast.error(getErrorMessage(err));
    }
  };

  const handleDeleteWebhook = async (id: string) => {
    if (!confirm('Are you sure you want to delete this webhook?')) return;
    try {
      await api.webhooksControllerRemove(id);
      toast.success('Webhook deleted');
      loadWebhooks();
    } catch (err: unknown) {
      toast.error(getErrorMessage(err));
    }
  };

  const navSections = useMemo(() => [
    { id: 'rate-limits', label: 'Rate Limits', show: true },
    { id: 'api-keys', label: 'API Keys', show: true },
    { id: 'webhooks', label: 'Webhooks', show: true },
  ], []);

  // ── Render ─────────────────────────────────────────────────────────────────

  return (
    <DetailsLayout
      header={
        <EntityHeader
          title="Developers"
          subtitle="Manage API access, webhooks, and rate limits"
          onBack={() => router.push('/admin')}
          actions={<PageNav sections={navSections} />}
          showPrint={false}
        />
      }
    >
      <div className="flex flex-col gap-6">
        {/* ── Rate Limits ────────────────────────────────────────────────── */}
        <div id="rate-limits" className="card">
          <h3 className="section-heading mb-4">
            <span className="material-symbols-outlined">speed</span>
            API Rate Limits
          </h3>
          <div className="flex flex-col gap-1 max-w-sm">
            <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
              Max Requests per Minute
            </label>
            <input
              type="number"
              className="input"
              value={appForm?.apiRateLimit || ''}
              onChange={(e) => setAppForm({ ...(appForm || {}), apiRateLimit: e.target.value })}
              onBlur={(e) => updateAppField('apiRateLimit', e.target.value || '1000')}
              placeholder="1000"
              disabled={appLoading}
            />
            <p className="text-xs text-muted mt-1">Applies only to requests authenticated via API Key.</p>
          </div>
        </div>

        {/* ── API Keys ───────────────────────────────────────────────────── */}
        <div id="api-keys" className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading !mb-0">
              <span className="material-symbols-outlined">key</span>
              API Keys
            </h3>
            <button className="btn btn-primary btn-sm" onClick={() => setKeyCreating(true)}>+ Create Key</button>
          </div>

          {newSecret && (
            <div className="mb-4 p-4 rounded-md border border-[var(--warning)] bg-amber-500/10 text-[var(--warning)]">
              <p className="font-medium mb-2">Please copy your API Key now. You will not be able to see it again!</p>
              <div className="flex items-center gap-2">
                <code className="p-2 rounded bg-black/20 text-white font-mono flex-1">{newSecret}</code>
                <button 
                  className="btn btn-secondary btn-sm" 
                  onClick={() => {
                    navigator.clipboard.writeText(newSecret);
                    toast.success('Copied to clipboard');
                  }}
                >
                  Copy
                </button>
              </div>
            </div>
          )}

          <table className="table-lines w-full">
            <thead>
              <tr>
                <th>Name</th>
                <th>Prefix</th>
                <th>Created</th>
                <th style={{ width: 120, textAlign: 'right' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {keyCreating && (
                <tr style={{ background: 'var(--bg-secondary)' }}>
                  <td>
                    <div className="flex flex-col gap-2">
                      <input
                        className="input"
                        autoFocus
                        placeholder="e.g. Integration Script"
                        value={keyForm.name}
                        onChange={e => setKeyForm({ ...keyForm, name: e.target.value })}
                      />
                      <select
                        className="input text-xs"
                        value={keyForm.role}
                        onChange={e => setKeyForm({ ...keyForm, role: e.target.value })}
                        style={{ background: 'var(--bg-card)', color: 'var(--text-primary)', border: '1px solid var(--border)' }}
                      >
                        <option value="agent">Agent (Read/Write)</option>
                        <option value="webhook">Webhook (Receiver)</option>
                        <option value="viewer">Viewer (Read-only)</option>
                        <option value="admin">Admin (Full Access)</option>
                        <option disabled>──────────</option>
                        {availableRoles
                          .filter(r => !['agent', 'webhook', 'viewer', 'admin'].includes(r.role))
                          .map((r) => (
                          <option key={r.role} value={r.role}>
                            {r.role} (Custom Role)
                          </option>
                        ))}
                      </select>
                    </div>
                  </td>
                  <td colSpan={2} className="text-muted text-sm">Will be generated...</td>
                  <td>
                    <div className="flex justify-end gap-2">
                      <button className="btn btn-secondary btn-xs" onClick={() => setKeyCreating(false)}>Cancel</button>
                      <button className="btn btn-primary btn-xs" onClick={handleCreateKey}>Save</button>
                    </div>
                  </td>
                </tr>
              )}
              {!keysLoading && (apiKeys?.length || 0) === 0 && !keyCreating && (
                <tr><td colSpan={4} style={{ textAlign: 'center', padding: '30px 0', color: 'var(--text-muted)' }}>No API keys found.</td></tr>
              )}
              {(apiKeys || []).map(k => (
                <tr key={k.apiKeyId}>
                  <td className="font-medium">
                    <div>{k.name}</div>
                    <div className="text-xs text-muted font-normal mt-0.5" style={{ color: 'var(--text-muted)' }}>Role: {k.role}</div>
                  </td>
                  <td className="font-mono text-sm">{k.prefix}••••••••</td>
                  <td className="text-sm text-muted">{new Date(k.createdOn).toLocaleDateString()}</td>
                  <td style={{ textAlign: 'right' }}>
                    <button className="btn btn-secondary btn-xs" style={{ color: 'var(--danger)', borderColor: 'var(--danger)' }} onClick={() => handleDeleteKey(k.apiKeyId)}>Revoke</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* ── Webhooks ───────────────────────────────────────────────────── */}
        <div id="webhooks" className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading !mb-0">
              <span className="material-symbols-outlined">webhook</span>
              Webhooks
            </h3>
            <button className="btn btn-primary btn-sm" onClick={() => setWebhookCreating(true)}>+ Add Webhook</button>
          </div>

          <table className="table-lines w-full">
            <thead>
              <tr>
                <th>Target URL</th>
                <th>Events</th>
                <th>Secret Key</th>
                <th style={{ width: 120, textAlign: 'right' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {webhookCreating && (
                <tr style={{ background: 'var(--bg-secondary)' }}>
                  <td>
                    <input
                      className="input"
                      placeholder="https://..."
                      value={webhookForm.targetUrl}
                      onChange={e => setWebhookForm({ ...webhookForm, targetUrl: e.target.value })}
                    />
                  </td>
                  <td>
                    <input
                      className="input"
                      placeholder="invoice.created, order.created"
                      value={webhookForm.eventTypes}
                      onChange={e => setWebhookForm({ ...webhookForm, eventTypes: e.target.value })}
                    />
                  </td>
                  <td className="text-muted text-sm">Auto-generated</td>
                  <td>
                    <div className="flex justify-end gap-2">
                      <button className="btn btn-secondary btn-xs" onClick={() => setWebhookCreating(false)}>Cancel</button>
                      <button className="btn btn-primary btn-xs" onClick={handleCreateWebhook}>Save</button>
                    </div>
                  </td>
                </tr>
              )}
              {!webhooksLoading && (webhooks?.length || 0) === 0 && !webhookCreating && (
                <tr><td colSpan={4} style={{ textAlign: 'center', padding: '30px 0', color: 'var(--text-muted)' }}>No webhooks found.</td></tr>
              )}
              {(webhooks || []).map(w => (
                <tr key={w.webhookId}>
                  <td className="font-medium text-sm">{w.targetUrl}</td>
                  <td className="text-sm">
                    {w.eventTypes.map(e => (
                      <span key={e} className="inline-block bg-black/20 px-2 py-0.5 rounded text-xs mr-1">{e}</span>
                    ))}
                  </td>
                  <td className="font-mono text-xs">{w.secretKey}</td>
                  <td style={{ textAlign: 'right' }}>
                    <button className="btn btn-secondary btn-xs" style={{ color: 'var(--danger)', borderColor: 'var(--danger)' }} onClick={() => handleDeleteWebhook(w.webhookId)}>Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

      </div>
    </DetailsLayout>
  );
}

'use client';

import { useState, useCallback, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import { toast } from 'react-hot-toast';
import { useTranslations } from 'next-intl';
import { getErrorMessage } from '@modbm/shared';

export function TemplateForm({ initialData, isNew }: { initialData?: any, isNew?: boolean }) {
  const t = useTranslations('admin.reporting.form');
  const [formData, setFormData] = useState({
    name: initialData?.name || '',
    slug: initialData?.slug || '',
    description: initialData?.description || '',
    template: initialData?.template || t('defaults.template'),
    outputNamePattern: initialData?.outputNamePattern || t('defaults.outputPattern'),
    contexts: (initialData?.contexts as string[]) || [],
  });
  
  const [previewVars, setPreviewVars] = useState({
    hookSlug: (initialData?.contexts as string[])?.[0] || '',
    entityId: '',
  });
  
  const [availableHooks, setAvailableHooks] = useState<any[]>([]);
  const [pdfBlobUrl, setPdfBlobUrl] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [previewing, setPreviewing] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [contextsOpen, setContextsOpen] = useState(false);
  
  const router = useRouter();

  useEffect(() => {
    api.reportsControllerGetHooks().then(res => {
      setAvailableHooks((res.data as any).data || (res.data as any) || []);
    }).catch(() => {});
  }, []);

  const handleSave = async () => {
    setSaving(true);
    try {
      if (isNew) {
        await api.reportsControllerCreateReport(formData);
        toast.success(t('toasts.created'));
        router.push('/admin/reporting');
      } else {
        await api.reportsControllerUpdateReport(initialData.id, formData);
        toast.success(t('toasts.saved'));
        router.refresh();
      }
    } catch (e: unknown) {
      toast.error(getErrorMessage(e) || t('toasts.saveFailed'));
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!window.confirm(t('toasts.deleteConfirm'))) return;
    
    setDeleting(true);
    try {
      await api.reportsControllerDeleteReport(initialData.id);
      toast.success(t('toasts.deleted'));
      router.push('/admin/reporting');
    } catch (e: unknown) {
      toast.error(getErrorMessage(e) || t('toasts.deleteFailed'));
      setDeleting(false);
    }
  };

  const handlePreview = async () => {
    setPreviewing(true);
    try {
      const res = await api.reportsControllerPreview({
        template: formData.template,
        hookSlug: previewVars.hookSlug,
        entityId: previewVars.entityId
      });
      const blob = res.data as Blob;
      const url = URL.createObjectURL(blob);
      setPdfBlobUrl(url);
    } catch (e: unknown) {
      toast.error(getErrorMessage(e) || t('toasts.previewFailed'));
    } finally {
      setPreviewing(false);
    }
  };

  const handleRandomizeId = async () => {
    if (!previewVars.hookSlug) return;
    try {
      const res = await api.reportsControllerGetRandomId(previewVars.hookSlug);
      if ((res as any).data?.id || (res as any).id) {
        setPreviewVars(p => ({ ...p, entityId: ((res as any).data?.id || (res as any).id) as string }));
      }
    } catch (err) {
      reportError(err, 'TemplateForm.randomizeId');
    }
  };

  const handleHookChange = (newHookSlug: string) => {
    setPreviewVars(p => ({ ...p, hookSlug: newHookSlug, entityId: '' }));
    if (newHookSlug) {
      // Automatically fetch a random ID when changing hooks
      api.reportsControllerGetRandomId(newHookSlug)
        .then((res: any) => {
          const newId = res.data?.id || res.id;
          if (newId) setPreviewVars(p => ({ ...p, hookSlug: newHookSlug, entityId: newId as string }));
        })
        .catch(() => {});
    }
  };

  return (
    <div className="flex flex-col gap-6 pb-12 h-full overflow-y-auto pr-2">
      {/* Top side: Form & Editor */}
      <div className="flex flex-col gap-4 w-full shrink-0">
        <div className="card p-6 flex flex-col gap-4 bg-white rounded-xl shadow-sm border border-[rgba(196,198,205,0.4)]">
          <div className="flex items-center gap-3">
            <button 
              onClick={() => router.push('/admin/reporting')} 
              className="p-1 rounded-full hover:bg-gray-100 text-gray-400 hover:text-gray-800 transition-colors flex items-center justify-center shrink-0"
              title={t('buttons.returnToList')}
            >
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined text-[20px]">arrow_back</span>
            </button>
            <h2 className="text-[1.3rem] font-bold tracking-tight text-[#041627]" style={{ fontFamily: 'Manrope, sans-serif' }}>
              {isNew ? t('newTemplate') : formData.name}
            </h2>
          </div>
          
          <div className="flex gap-4">
            <div className="flex-1">
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('labels.displayName')}</label>
              <input className="input w-full" value={formData.name} onChange={e => setFormData(d => ({ ...d, name: e.target.value }))} />
            </div>
            <div className="flex-1">
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('labels.uniqueSlug')}</label>
              <input className="input w-full" value={formData.slug} onChange={e => setFormData(d => ({ ...d, slug: e.target.value }))} placeholder={t('placeholders.slug')} />
            </div>
          </div>
          <div className="flex gap-4">
            <div className="flex-1">
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('labels.outputPattern')}</label>
              <input className="input w-full" value={formData.outputNamePattern} onChange={e => setFormData(d => ({ ...d, outputNamePattern: e.target.value }))} />
            </div>
            <div className="flex-[2]">
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('labels.description')}</label>
              <input className="input w-full" value={formData.description} onChange={e => setFormData(d => ({ ...d, description: e.target.value }))} />
            </div>
          </div>
          
          <div className="flex gap-4 mt-4">
            <div className="flex-1">
              <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-3">{t('labels.supportedContexts')}</label>
              <div className="relative w-full">
                <div 
                  className="input flex items-center justify-between cursor-pointer font-normal border-gray-300 bg-white shadow-sm"
                  onClick={() => setContextsOpen(!contextsOpen)}
                >
                  <span className="truncate pr-4 text-sm text-gray-700 font-semibold">
                    {formData.contexts.length > 0 ? formData.contexts.join(', ') : <span className="text-gray-400 font-normal">{t('placeholders.selectContexts')}</span>}
                  </span>
                  {/* eslint-disable-next-line no-restricted-syntax */}
                  <span className="material-symbols-outlined text-gray-400 text-[18px]">{contextsOpen ? 'expand_less' : 'expand_more'}</span>
                </div>
                
                {contextsOpen && (
                  <>
                    <div className="fixed inset-0 z-40" onClick={() => setContextsOpen(false)}></div>
                    <div className="absolute top-[calc(100%+4px)] left-0 w-full min-w-[200px] max-h-60 overflow-y-auto bg-white border border-[rgba(196,198,205,0.4)] rounded-lg shadow-xl z-50 py-1">
                      {availableHooks.length === 0 ? (
                        <div className="text-xs text-gray-400 italic p-3">{t('loadingContexts')}</div>
                      ) : (
                        availableHooks.map(h => (
                          <label key={h.contextSlug} className="flex items-center gap-3 px-3 py-2 cursor-pointer hover:bg-[#f8f9fa] transition-colors border-b border-gray-100 last:border-0">
                            <input 
                              type="checkbox" 
                              className="checkbox checkbox-sm checkbox-primary border-gray-300 rounded"
                              checked={formData.contexts.includes(h.contextSlug)}
                              onChange={(e) => {
                                const checked = e.target.checked;
                                setFormData(d => ({
                                  ...d,
                                  contexts: checked 
                                    ? [...d.contexts, h.contextSlug] 
                                    : d.contexts.filter(c => c !== h.contextSlug)
                                }));
                              }}
                            />
                            <span className="text-[13px] font-semibold text-gray-700">{h.contextSlug}</span>
                          </label>
                        ))
                      )}
                    </div>
                  </>
                )}
              </div>
              <p className="text-[10px] text-gray-400 mt-2 italic">
                {t('descriptions.contextHelp')}
              </p>
            </div>
          </div>

          <div className="flex flex-col flex-1 mt-4 min-h-[500px]">
            <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">{t('labels.typstSource')}</label>
            <textarea 
              className="flex-1 w-full border border-[rgba(196,198,205,0.4)] rounded-lg font-mono text-sm leading-relaxed p-4 bg-[#f8f9fa] whitespace-pre focus:outline-none focus:ring-2 focus:ring-[#006b5c]/30 focus:border-[#006b5c]"
              value={formData.template}
              onChange={e => setFormData(d => ({ ...d, template: e.target.value }))}
              spellCheck={false}
              style={{ minHeight: '500px', resize: 'vertical' }}
            />
          </div>

          <div className="flex items-center gap-3 mt-4">
            <button className="btn btn-primary px-8 py-3 text-sm font-bold rounded-lg transition-all bg-[#006b5c] text-white hover:brightness-110" onClick={handleSave} disabled={saving || deleting}>
              {saving ? t('buttons.saving') : t('buttons.save')}
            </button>
            {!isNew && (
              <button 
                className="btn btn-secondary px-8 py-3 text-sm font-bold rounded-lg border border-red-200 text-red-600 hover:bg-red-50 transition-all" 
                onClick={handleDelete} 
                disabled={saving || deleting}
              >
                {deleting ? t('buttons.deleting') : t('buttons.delete')}
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Bottom side: Live Preview */}
      <div className="flex flex-col w-full min-h-[800px] shrink-0">
        <div className="card p-6 flex flex-col gap-4 h-full bg-white rounded-xl shadow-sm border border-[rgba(196,198,205,0.4)]">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-bold text-[#041627]" style={{ fontFamily: 'Manrope, sans-serif' }}>{t('livePreview.title')}</h3>
            <span className="text-xs text-gray-400 font-semibold bg-gray-100 px-2 py-1 rounded">{t('livePreview.badge')}</span>
          </div>
          <div className="flex gap-3 items-end bg-[#f8f9fa] p-4 rounded-lg border border-[rgba(196,198,205,0.4)]">
            <div className="flex-1">
              <label className="block text-[11px] font-bold text-gray-500 uppercase tracking-wider mb-1.5">{t('labels.contextResolver')}</label>
              <select className="select w-full bg-white" value={previewVars.hookSlug} onChange={e => handleHookChange(e.target.value)}>
                <option value="">{t('none')}</option>
                {availableHooks.map(h => (
                  <option key={h.contextSlug} value={h.contextSlug}>{h.contextSlug}</option>
                ))}
              </select>
            </div>
            <div className="flex-1 relative">
              <label className="block text-[11px] font-bold text-gray-500 uppercase tracking-wider mb-1.5">{t('labels.targetRecordId')}</label>
              <div className="flex gap-2">
                 <input className="input w-full bg-white font-mono text-sm" value={previewVars.entityId} onChange={e => setPreviewVars(p => ({ ...p, entityId: e.target.value }))} placeholder={t('placeholders.uuid')} />
                 <button className="btn btn-secondary px-3 bg-white" title={t('buttons.getRandomId')} onClick={handleRandomizeId} disabled={!previewVars.hookSlug}>
                   {/* eslint-disable-next-line i18next/no-literal-string */}
                   🎲
                 </button>
              </div>
            </div>
            <button className="btn btn-secondary w-36 px-4 py-2 text-sm font-bold rounded-lg transition-all bg-white border border-[#041627] text-[#041627] hover:bg-gray-50" disabled={previewing || !previewVars.entityId} onClick={handlePreview}>
               {previewing ? t('buttons.compiling') : t('buttons.generatePdf')}
            </button>
          </div>
          
          <div className="flex-1 border border-[rgba(196,198,205,0.4)] rounded-lg bg-gray-200/50 overflow-hidden relative shadow-inner">
            {pdfBlobUrl ? (
              <iframe src={`${pdfBlobUrl}#toolbar=0`} className="w-[100%] h-[100%] border-0 object-contain" style={{ backgroundColor: '#525659' }} />
            ) : (
              <div className="absolute inset-0 flex flex-col items-center justify-center text-gray-400 gap-3">
                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line><polyline points="10 9 9 9 8 9"></polyline></svg>
                <span className="font-semibold text-sm">{t('livePreview.waiting')}</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default TemplateForm;

'use client';

import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import { useState, useEffect, useMemo, Fragment } from 'react';
import * as api from '@modbm/sdk';
import { toast } from 'react-hot-toast';
import { useRouter } from 'next/navigation';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import PageNav from '@/components/shared/PageNav';
import CsvImportButton from '@/components/shared/CsvImportButton';
import SlideOver from '@/components/shared/SlideOver';
import { SchemaBuilder } from '@/components/SchemaBuilder';
import { DynamicForm } from '@/components/DynamicForm';
import ImportCoaModal from './ImportCoaModal';
import ImportTaxModal from './ImportTaxModal';

import { getCurrency } from '@/lib/currency';
import { CURRENCIES, GL_ACCOUNT_TYPE } from '@modbm/shared';
import { useTranslations } from 'next-intl';
import { getErrorMessage } from '@modbm/shared';

// ── Types ────────────────────────────────────────────────────────────────────

interface TaxCategory {
  taxCategoryId: string;
  code: string;
  title: string;
  type: string;
  rate: string;
  isDefault: boolean;
}

interface ExchangeRate {
  exchangeRateId: string;
  currencyCode: string;
  currencyName: string;
  buyRate: string;
  sellRate: string;
  effectiveDate: string;
  updatedOn: string;
}

interface CostCenter {
  costCenterId: string;
  code: string;
  name: string;
  isSystem: boolean;
  isActive: boolean;
}

interface Activity {
  activityId: string;
  code: string;
  name: string;
  isSystem: boolean;
  isActive: boolean;
}

const TAX_TYPES = (t: any) => [
  { value: 'tax_applies', label: t('admin.settings.taxTypes.tax_applies') },
  { value: 'zero_rated', label: t('admin.settings.taxTypes.zero_rated') },
  { value: 'exempt', label: t('admin.settings.taxTypes.exempt') },
  { value: 'not_relevant', label: t('admin.settings.taxTypes.not_relevant') },
];

// ── Main Component ───────────────────────────────────────────────────────────

export default function FinancialSettingsPage() {
  const tSettings = useTranslations('admin.settings');
  const tCommon = useTranslations('admin.common');
  const t = useTranslations();
  useDocumentTitle(tSettings('title'));
  const taxTypes = useMemo(() => TAX_TYPES(t), [t]);
  const router = useRouter();

  // ── Tax state ──────────────────────────────────────────────────────────────
  const [categories, setCategories] = useState<TaxCategory[]>([]);
  const [taxLoading, setTaxLoading] = useState(true);
  const [taxEditingId, setTaxEditingId] = useState<string | null>(null);
  const [taxForm, setTaxForm] = useState<any>({});
  const [taxCreating, setTaxCreating] = useState(false);
  const [importTaxModalOpen, setImportTaxModalOpen] = useState(false);

  // ── Exchange Rates state ───────────────────────────────────────────────────
  const [rates, setRates] = useState<ExchangeRate[]>([]);
  const [rateLoading, setRateLoading] = useState(true);
  const [rateEditingId, setRateEditingId] = useState<string | null>(null);
  const [rateForm, setRateForm] = useState<any>({});
  const [rateCreating, setRateCreating] = useState(false);

  // ── Cost Centers state ─────────────────────────────────────────────────────
  const [ccs, setCcs] = useState<CostCenter[]>([]);
  const [ccLoading, setCcLoading] = useState(true);
  const [ccEditingId, setCcEditingId] = useState<string | null>(null);
  const [ccForm, setCcForm] = useState<any>({});
  const [ccCreating, setCcCreating] = useState(false);

  // ── Activities state ───────────────────────────────────────────────────────
  const [activitiesData, setActivitiesData] = useState<Activity[]>([]);
  const [activityLoading, setActivityLoading] = useState(true);
  const [activityEditingId, setActivityEditingId] = useState<string | null>(null);
  const [activityForm, setActivityForm] = useState<any>({});
  const [activityCreating, setActivityCreating] = useState(false);

  // ── GL Settings state ────────────────────────────────────────────────────────
  const [glSettings, setGlSettings] = useState<any>(null);
  const [glAccounts, setGlAccounts] = useState<any[]>([]);
  const [glLoading, setGlLoading] = useState(true);
  const [schemaObj, setSchemaObj] = useState<any>({ type: 'object', properties: {} });
  const [schemaEditorOpen, setSchemaEditorOpen] = useState(false);
  const [isImporting, setIsImporting] = useState(false);

  // ── CoA state ──────────────────────────────────────────────────────────────
  const [coaForm, setCoaForm] = useState<any>({});
  const [coaCreating, setCoaCreating] = useState(false);
  const [coaEditingId, setCoaEditingId] = useState<string | null>(null);
  const [importCoaModalOpen, setImportCoaModalOpen] = useState(false);

  const coaTree = useMemo(() => {
    const map = new Map<string | null, any[]>();
    for (const acct of glAccounts) {
      const parentId = acct.parentAccountId || null;
      if (!map.has(parentId)) map.set(parentId, []);
      map.get(parentId)!.push(acct);
    }
    const build = (parentId: string | null, depth: number = 0): any[] => {
      const children = map.get(parentId) || [];
      const result: any[] = [];
      for (const acct of children) {
        result.push({ ...acct, depth });
        if (acct.isGroup) {
          result.push(...build(acct.glAccountId, depth + 1));
        }
      }
      return result;
    };
    return build(null);
  }, [glAccounts]);

  const areaMap: Record<string, string> = {
    gl: tSettings('sections.gl'),
    tax: tSettings('sections.tax'),
    rates: tSettings('sections.rates'),
    cc: tSettings('sections.costCenters'),
    activity: tSettings('sections.activities'),
  };

  // ── GL Settings data ───────────────────────────────────────────────────────
  
  const loadGl = async () => {
    try {
      setGlLoading(true);
      const [settingsRes, accountsRes] = await Promise.all([
        api.glControllerGetSettings(),
        api.glControllerGetAccounts({} as Record<string, never>)
      ]);
      setGlSettings(settingsRes.data);
      setGlAccounts(accountsRes.data);
      setSchemaObj((settingsRes.data as any).accountMetadataSchema || { type: 'object', properties: {} });
    } catch (err: unknown) {
      toast.error(tSettings('toasts.loadFailed', { area: areaMap.gl }) + ': ' + getErrorMessage(err));
    } finally {
      setGlLoading(false);
    }
  };

  const updateGlSetting = async (field: string, value: unknown) => {
    try {
      const payload = { [field]: value };
      const res = await api.glControllerUpdateSettings(payload);
      const updated = res.data;
      setGlSettings(Object.assign({}, glSettings || {}, updated));
      toast.success('Settings updated');
    } catch (err: unknown) {
      toast.error(getErrorMessage(err));
    }
  };

  const saveSchema = async () => {
    try {
      await updateGlSetting('accountMetadataSchema', schemaObj);
      // Update local settings so the UI updates immediately after save
      setGlSettings({ ...glSettings, accountMetadataSchema: schemaObj });
      setSchemaEditorOpen(false);
    } catch (err) {
      toast.error('Failed to save schema');
    }
  };

  const openSchemaEditor = () => {
    setSchemaObj(glSettings?.accountMetadataSchema || { type: 'object', properties: {} });
    setSchemaEditorOpen(true);
  };

  const coaEdit = (acct: unknown) => { setCoaEditingId((acct as { glAccountId: string }).glAccountId); setCoaForm({ ...(acct as object) }); setCoaCreating(false); };
  const coaCreate = (parentId?: string, parentAccountType?: string) => { setCoaCreating(true); setCoaEditingId(null); setCoaForm({ accountCode: '', name: '', accountType: parentAccountType || GL_ACCOUNT_TYPE.EXPENSE, parentAccountId: parentId || null, isGroup: false, isBankAccount: false, currencyCode: 'AUD', isActive: true }); };
  const coaCancel = () => { setCoaEditingId(null); setCoaCreating(false); };

  const coaSave = async () => {
    if (!coaForm.accountCode || !coaForm.name || !coaForm.accountType) { toast.error(tCommon('errors.typeAndDateRequired') || 'Required fields missing'); return; }
    try {
      const payload = { ...coaForm };
      if (coaEditingId) {
        await api.glControllerUpdateAccount(coaEditingId, payload);
        toast.success('Saved');
      } else {
        await api.glControllerCreateAccount(payload);
        toast.success('Saved');
      }
      coaCancel(); loadGl();
    } catch (err: unknown) { toast.error(getErrorMessage(err)); }
  };

  // ── Tax data ───────────────────────────────────────────────────────────────

  const loadTax = async () => {
    try {
      setTaxLoading(true);
      const res = await api.taxCategoriesControllerFindAll();
      setCategories((res.data as TaxCategory[]).sort((a, b) => a.code.localeCompare(b.code, undefined, { numeric: true })));
    } catch (err: unknown) {
      toast.error(tSettings('toasts.loadFailed', { area: areaMap.tax }) + ': ' + getErrorMessage(err));
    } finally {
      setTaxLoading(false);
    }
  };

  const taxEdit = (cat: TaxCategory) => { setTaxEditingId(cat.taxCategoryId); setTaxForm({ ...cat }); setTaxCreating(false); };
  const taxCreate = () => { setTaxCreating(true); setTaxEditingId(null); setTaxForm({ code: '', title: '', type: 'tax_applies', rate: '0', isDefault: false }); };
  const taxCancel = () => { setTaxEditingId(null); setTaxCreating(false); };

  const taxSave = async () => {
    try {
      const payload = { ...taxForm };
      if (taxEditingId) {
        await api.taxCategoriesControllerUpdate(taxEditingId, payload);
        toast.success(tSettings('toasts.taxUpdated'));
      } else {
        await api.taxCategoriesControllerCreate(payload);
        toast.success(tSettings('toasts.taxCreated'));
      }
      taxCancel(); loadTax();
    } catch (err: unknown) { toast.error(getErrorMessage(err)); }
  };

  const taxDelete = async (id: string) => {
    if (!confirm(tSettings('confirmations.deleteTax'))) return;
    try { await api.taxCategoriesControllerRemove(id); toast.success(tSettings('toasts.taxDeleted')); loadTax(); }
    catch (err: unknown) { toast.error(getErrorMessage(err)); }
  };

  // ── Exchange Rates data ────────────────────────────────────────────────────

  const loadRates = async () => {
    try {
      setRateLoading(true);
      const res = await api.exchangeRatesControllerFindAll();
      setRates(res.data as unknown as ExchangeRate[]);
    } catch (err: unknown) {
      toast.error(tSettings('toasts.loadFailed', { area: areaMap.rates }) + ': ' + getErrorMessage(err));
    } finally {
      setRateLoading(false);
    }
  };

  const rateEdit = (r: ExchangeRate) => { setRateEditingId(r.exchangeRateId); setRateForm({ ...r }); setRateCreating(false); };
  const rateCreate = () => { setRateCreating(true); setRateEditingId(null); setRateForm({ currencyCode: '', currencyName: '', buyRate: '1.0', sellRate: '1.0', effectiveDate: new Date().toISOString().split('T')[0] }); };
  const rateCancel = () => { setRateEditingId(null); setRateCreating(false); };

  const rateSave = async () => {
    if (!rateForm.currencyCode || !rateForm.currencyName || !rateForm.buyRate || !rateForm.sellRate) {
      toast.error(tCommon('errors.typeAndDateRequired')); return;
    }
    try {
      const payload = {
        currencyCode: rateForm.currencyCode.toUpperCase(),
        currencyName: rateForm.currencyName,
        buyRate: rateForm.buyRate,
        sellRate: rateForm.sellRate,
        effectiveDate: rateForm.effectiveDate
      };
      if (rateEditingId) {
        await api.exchangeRatesControllerUpdate(rateEditingId, payload);
        toast.success(tSettings('toasts.rateUpdated'));
      } else {
        await api.exchangeRatesControllerCreate(payload);
        toast.success(tSettings('toasts.rateCreated'));
      }
      rateCancel(); loadRates();
    } catch (err: unknown) { toast.error(getErrorMessage(err)); }
  };

  const rateDelete = async (id: string) => {
    if (!confirm(tSettings('confirmations.deleteRate'))) return;
    try { await api.exchangeRatesControllerRemove(id); toast.success(tSettings('toasts.rateDeleted')); loadRates(); }
    catch (err: unknown) { toast.error(getErrorMessage(err)); }
  };

  // ── Cost Centers data ─────────────────────────────────────────────────────

  const loadCcs = async () => {
    try {
      setCcLoading(true);
      const res = await api.costCentersControllerFindAll();
      setCcs(res.data as unknown as CostCenter[]);
    } catch (err: unknown) {
      toast.error(tSettings('toasts.loadFailed', { area: areaMap.cc }) + ': ' + getErrorMessage(err));
    } finally {
      setCcLoading(false);
    }
  };

  const ccEdit = (cc: CostCenter) => { setCcEditingId(cc.costCenterId); setCcForm({ ...cc }); setCcCreating(false); };
  const ccCreate = () => { setCcCreating(true); setCcEditingId(null); setCcForm({ code: '', name: '', isActive: true }); };
  const ccCancel = () => { setCcEditingId(null); setCcCreating(false); };

  const ccSave = async () => {
    if (!ccForm.code || !ccForm.name) { toast.error(tCommon('errors.typeAndDateRequired')); return; }
    try {
      const payload = { 
        code: ccForm.code.toUpperCase(), 
        name: ccForm.name,
        isActive: ccForm.isActive ?? true 
      };
      if (ccEditingId) {
        await api.costCentersControllerUpdate(ccEditingId, payload);
        toast.success(tSettings('toasts.ccUpdated'));
      } else {
        await api.costCentersControllerCreate(payload);
        toast.success(tSettings('toasts.ccCreated'));
      }
      ccCancel(); loadCcs();
    } catch (err: unknown) { toast.error(getErrorMessage(err)); }
  };

  const ccDelete = async (id: string) => {
    if (!confirm(tSettings('confirmations.deleteCc'))) return;
    try { 
      await api.costCentersControllerDelete(id); 
      toast.success(tSettings('toasts.ccDeleted')); 
      loadCcs(); 
    }
    catch (err: unknown) { toast.error(getErrorMessage(err)); }
  };

  const handleImportCc = async (data: any[]) => {
    setIsImporting(true);
    try {
      const res = await api.costCentersControllerImport(data);
      const responseData = res.data;
      toast.success(tSettings('toasts.importSuccess', { count: responseData.count }));
      loadCcs();
    } catch (err: unknown) {
      toast.error(tSettings('toasts.importFailed', { message: getErrorMessage(err) }));
    } finally {
      setIsImporting(false);
    }
  };

  // ── Activities data ───────────────────────────────────────────────────────

  const loadActivities = async () => {
    try {
      setActivityLoading(true);
      const res = await api.activitiesControllerFindAll();
      setActivitiesData(res.data as unknown as Activity[]);
    } catch (err: unknown) {
      toast.error(tSettings('toasts.loadFailed', { area: areaMap.activity }) + ': ' + getErrorMessage(err));
    } finally {
      setActivityLoading(false);
    }
  };

  const activityEdit = (a: Activity) => { setActivityEditingId(a.activityId); setActivityForm({ ...a }); setActivityCreating(false); };
  const activityCreate = () => { setActivityCreating(true); setActivityEditingId(null); setActivityForm({ code: '', name: '', isActive: true }); };
  const activityCancel = () => { setActivityEditingId(null); setActivityCreating(false); };

  const activitySave = async () => {
    if (!activityForm.code || !activityForm.name) { toast.error(tCommon('errors.typeAndDateRequired')); return; }
    try {
      const payload = { 
        code: activityForm.code.toUpperCase(), 
        name: activityForm.name,
        isActive: activityForm.isActive ?? true 
      };
      if (activityEditingId) {
        await api.activitiesControllerUpdate(activityEditingId, payload);
        toast.success(tSettings('toasts.activityUpdated'));
      } else {
        await api.activitiesControllerCreate(payload);
        toast.success(tSettings('toasts.activityCreated'));
      }
      activityCancel(); loadActivities();
    } catch (err: unknown) { toast.error(getErrorMessage(err)); }
  };

  const activityDelete = async (id: string) => {
    if (!confirm(tSettings('confirmations.deleteActivity'))) return;
    try { 
      await api.activitiesControllerDelete(id); 
      toast.success(tSettings('toasts.activityDeleted')); 
      loadActivities(); 
    }
    catch (err: unknown) { toast.error(getErrorMessage(err)); }
  };

  const handleImportActivity = async (data: any[]) => {
    setIsImporting(true);
    try {
      const res = await api.activitiesControllerImport(data);
      const responseData = res.data;
      toast.success(tSettings('toasts.importSuccess', { count: responseData.count }));
      loadActivities();
    } catch (err: unknown) {
      toast.error(tSettings('toasts.importFailed', { message: getErrorMessage(err) }));
    } finally {
      setIsImporting(false);
    }
  };

  // ── Init ───────────────────────────────────────────────────────────────────

  useEffect(() => {
    loadTax();
    loadRates();
    loadGl();
    loadCcs();
    loadActivities();
  }, []);

  // ── Helpers ───────────────────────────────────────────────────────────────

  const typeLabel = (type: string) => taxTypes.find(t => t.value === type)?.label ?? type;

  const renderGlAccountLabel = (glAccountId?: string) => {
    if (!glAccountId) return <span className="text-muted italic">{tCommon('notConfigured')}</span>;
    const acct = glAccounts.find(a => a.glAccountId === glAccountId);
    if (!acct) return <span className="text-muted italic text-xs font-mono">{glAccountId}</span>;
    return (
      <span className="font-medium text-sm flex items-center gap-2">
        <span className="badge badge-sm badge-secondary font-mono">{acct.accountCode}</span>
        {acct.name}
      </span>
    );
  };

  // ── Row Renderers ─────────────────────────────────────────────────────────

  const renderGlAccountSelect = (field: string, value?: string) => {
    return (
      <select 
        className="input" 
        value={value || ''} 
        onChange={(e) => updateGlSetting(field, e.target.value || null)}
      >
        <option value="">{tCommon('notConfigured')}</option>
        {glAccounts.filter(a => !a.isGroup).map(a => (
          <option key={a.glAccountId} value={a.glAccountId}>
            {a.accountCode} - {a.name}
          </option>
        ))}
      </select>
    );
  };

  const renderCoaRow = (isEdit: boolean, data: any, key: string) => (
    <Fragment key={key}>
      <tr style={isEdit ? { background: 'var(--bg-secondary)' } : undefined}>
        <td style={{ paddingLeft: `${(data.depth || 0) * 20 + 8}px` }}>
          {isEdit && coaCreating
            ? <input className="input" value={coaForm.accountCode} onChange={e => setCoaForm({ ...coaForm, accountCode: e.target.value })} placeholder="Code" style={{ width: 100 }} />
            : <span className={`font-mono text-xs ${data.isGroup ? 'font-bold' : ''}`}>{data.accountCode}</span>}
        </td>
        <td>
          {isEdit
            ? <input className="input" value={coaForm.name} onChange={e => setCoaForm({ ...coaForm, name: e.target.value })} placeholder="Name" />
            : <span className={`${data.isGroup ? 'font-bold' : 'font-medium'} flex items-center gap-2`}>
                {data.isGroup ? (
                  <>
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined text-[16px]">folder</span>
                    {/* eslint-enable i18next/no-literal-string */}
                  </>
                ) : (
                  <>
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined text-[16px] text-muted">receipt_long</span>
                    {/* eslint-enable i18next/no-literal-string */}
                  </>
                )}
                {data.name}
              </span>}
        </td>
        <td>
          {isEdit && coaCreating ? (
            <select className="input" disabled={!!coaForm.parentAccountId} value={coaForm.accountType} onChange={e => setCoaForm({ ...coaForm, accountType: e.target.value })}>
              {Object.values(GL_ACCOUNT_TYPE).map(t => <option key={t} value={t}>{t.charAt(0).toUpperCase() + t.slice(1)}</option>)}
            </select>
          ) : data.accountType}
        </td>
        <td style={{ textAlign: 'center' }}>
          {isEdit && coaCreating ? (
            <input type="checkbox" checked={coaForm.isGroup} onChange={e => setCoaForm({ ...coaForm, isGroup: e.target.checked })} />
          ) : data.isGroup ? (
            <>
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined text-[16px]" style={{ color: 'var(--text-muted)' }}>check</span>
              {/* eslint-enable i18next/no-literal-string */}
            </>
          ) : null}
        </td>
        <td style={{ textAlign: 'center' }}>
          {isEdit ? (
            <input type="checkbox" checked={coaForm.isBankAccount} onChange={e => setCoaForm({ ...coaForm, isBankAccount: e.target.checked })} />
          ) : data.isBankAccount ? (
            <>
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined text-[16px]" style={{ color: 'var(--text-muted)' }}>check</span>
              {/* eslint-enable i18next/no-literal-string */}
            </>
          ) : null}
        </td>
        <td style={{ textAlign: 'center' }}>
          {isEdit ? (
            <select 
              className="select" 
              value={coaForm.currencyCode || ''} 
              onChange={e => setCoaForm({ ...coaForm, currencyCode: e.target.value })}
              style={{ width: 90 }}
            >
              <option value="">-</option>
              {CURRENCIES.map(c => (
                <option key={c.code} value={c.code}>{c.code}</option>
              ))}
            </select>
          ) : (
            <span className="font-mono text-xs text-muted">{data.currencyCode}</span>
          )}
        </td>
        <td style={{ textAlign: 'center' }}>
          {isEdit ? (
            <label className="switch" title={coaForm.isActive ? tSettings('labels.active') : tSettings('labels.inactive')}>
              <input type="checkbox" checked={coaForm.isActive} onChange={e => setCoaForm({ ...coaForm, isActive: e.target.checked })} />
              <span className="switch-slider"></span>
            </label>
          ) : (
            <span style={{ color: data.isActive ? 'var(--success, #22c55e)' : 'var(--danger, #ef4444)', fontWeight: 'bold', fontSize: '0.75rem' }}>
              {data.isActive ? tSettings('labels.active').toUpperCase() : tSettings('labels.inactive').toUpperCase()}
            </span>
          )}
        </td>
        <td style={{ textAlign: 'right' }}>
          {isEdit ? (
            <div className="flex justify-end gap-2 flex-nowrap whitespace-nowrap">
              <button className="btn btn-secondary btn-xs" onClick={coaCancel}>{tSettings('actions.cancel')}</button>
              <button className="btn btn-primary btn-xs" onClick={coaSave}>{tSettings('actions.save')}</button>
            </div>
          ) : (
            <div className="flex justify-end gap-2 flex-nowrap whitespace-nowrap">
              {data.isGroup && <button className="btn btn-secondary btn-xs" onClick={() => coaCreate(data.glAccountId, data.accountType)}>{tSettings('actions.addChild')}</button>}
              <button className="btn btn-secondary btn-xs" onClick={() => coaEdit(data)}>{tSettings('actions.edit')}</button>
              {data.isSystem && <span className="text-xs text-muted italic px-2">{tCommon('system')}</span>}
            </div>
          )}
        </td>
      </tr>
      {isEdit && glSettings?.accountMetadataSchema?.type === 'object' && (
        <tr style={{ background: 'var(--bg-secondary)' }}>
          <td colSpan={6} style={{ padding: '16px 24px', borderTop: 'none' }}>
            <div className="card bg-[var(--bg-primary)] p-4 shadow-sm border border-[var(--border)]">
              <DynamicForm 
                schema={glSettings.accountMetadataSchema} 
                data={coaForm.metadata || {}} 
                onChange={(data) => setCoaForm({...coaForm, metadata: data})} 
              />
            </div>
          </td>
        </tr>
      )}
    </Fragment>
  );

  const renderTaxRow = (isEdit: boolean, data: any, key: string) => (
    <tr key={key} style={isEdit ? { background: 'var(--bg-secondary)' } : undefined}>
      <td>
        {isEdit
          ? <input className="input" value={taxForm.code} onChange={e => setTaxForm({ ...taxForm, code: e.target.value })} placeholder={tSettings('labels.code')} />
          : <span className="font-mono text-xs">{data.code}</span>}
      </td>
      <td>
        {isEdit
          ? <input className="input" value={taxForm.title} onChange={e => setTaxForm({ ...taxForm, title: e.target.value })} placeholder={tSettings('labels.title')} />
          : <span className="font-medium">{data.title}</span>}
      </td>
      <td>
        {isEdit ? (
          <select className="input" value={taxForm.type} onChange={e => setTaxForm({ ...taxForm, type: e.target.value })}>
            {taxTypes.map(t => <option key={t.value} value={t.value}>{t.label}</option>)}
          </select>
        ) : typeLabel(data.type)}
      </td>
      <td>
        {isEdit
          ? <input className="input" value={taxForm.rate} onChange={e => setTaxForm({ ...taxForm, rate: e.target.value })} type="number" step="0.01" style={{ width: 80 }} />
          : <>{data.rate}%</>}
      </td>
      <td style={{ textAlign: 'center' }}>
        {isEdit ? (
          <input type="checkbox" checked={taxForm.isDefault === true || taxForm.isDefault === 'true'} onChange={e => setTaxForm({ ...taxForm, isDefault: e.target.checked })} />
        ) : data.isDefault ? (
          <>
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined text-[16px]" style={{ color: 'var(--primary)' }}>check_circle</span>
            {/* eslint-enable i18next/no-literal-string */}
          </>
        ) : null}
      </td>
      <td style={{ textAlign: 'right' }}>
        {isEdit ? (
          <div className="flex justify-end gap-2">
            <button className="btn btn-secondary btn-xs" onClick={taxCancel}>{tSettings('actions.cancel')}</button>
            <button className="btn btn-primary btn-xs" onClick={taxSave}>{tSettings('actions.save')}</button>
          </div>
        ) : (
          <div className="flex justify-end gap-2">
            <button className="btn btn-secondary btn-xs" onClick={() => taxEdit(data)}>{tSettings('actions.edit')}</button>
            {!data.isDefault && (
              <button className="btn btn-secondary btn-xs" style={{ color: 'var(--danger)', borderColor: 'var(--danger)' }} onClick={() => taxDelete(data.taxCategoryId)}>{tSettings('actions.delete')}</button>
            )}
          </div>
        )}
      </td>
    </tr>
  );

  const renderRateRow = (isEdit: boolean, data: any, key: string) => (
    <tr key={key} style={isEdit ? { background: 'var(--bg-secondary)' } : undefined}>
      <td>
        {isEdit && rateCreating
          ? <input className="input" value={rateForm.currencyCode} onChange={e => setRateForm({ ...rateForm, currencyCode: e.target.value.toUpperCase() })} placeholder={tSettings('placeholders.currencyCode')} style={{ width: 80 }} />
          : <span className="font-mono text-xs">{data.currencyCode}</span>}
      </td>
      <td>
        {isEdit
          ? <input className="input" value={rateForm.currencyName} onChange={e => setRateForm({ ...rateForm, currencyName: e.target.value })} placeholder={tSettings('placeholders.currencyName')} />
          : <span className="font-medium">{data.currencyName}</span>}
      </td>
      <td>
        {isEdit
          ? <input className="input" type="number" step="0.0001" value={rateForm.buyRate} onChange={e => setRateForm({ ...rateForm, buyRate: e.target.value })} style={{ width: 100 }} />
          : <span>{data.buyRate}</span>}
      </td>
      <td>
        {isEdit
          ? <input className="input" type="number" step="0.0001" value={rateForm.sellRate} onChange={e => setRateForm({ ...rateForm, sellRate: e.target.value })} style={{ width: 100 }} />
          : <span>{data.sellRate}</span>}
      </td>
      <td>
        {isEdit
          ? <input className="input" type="date" value={rateForm.effectiveDate?.split('T')[0]} onChange={e => setRateForm({ ...rateForm, effectiveDate: e.target.value })} />
          : <span className="text-xs">{new Date(data.effectiveDate).toLocaleDateString()}</span>}
      </td>
      <td style={{ textAlign: 'right' }}>
        {isEdit ? (
          <div className="flex justify-end gap-2">
            <button className="btn btn-secondary btn-xs" onClick={rateCancel}>{tSettings('actions.cancel')}</button>
            <button className="btn btn-primary btn-xs" onClick={rateSave}>{tSettings('actions.save')}</button>
          </div>
        ) : (
          <div className="flex justify-end gap-2">
            <button className="btn btn-secondary btn-xs" onClick={() => rateEdit(data)}>{tSettings('actions.edit')}</button>
            <button className="btn btn-secondary btn-xs" style={{ color: 'var(--danger)', borderColor: 'var(--danger)' }} onClick={() => rateDelete(data.exchangeRateId)}>{tSettings('actions.delete')}</button>
          </div>
        )}
      </td>
    </tr>
  );

  const renderCcRow = (isEdit: boolean, data: any, key: string) => (
    <tr key={key} style={isEdit ? { background: 'var(--bg-secondary)' } : undefined}>
      <td>
        {isEdit && ccCreating
          ? <input className="input" value={ccForm.code} onChange={e => setCcForm({ ...ccForm, code: e.target.value.toUpperCase() })} placeholder={tSettings('placeholders.ccCode')} style={{ width: 100 }} />
          : <span className="font-mono text-xs">{data.code}</span>}
      </td>
      <td>
        {isEdit
          ? <input className="input" value={ccForm.name} onChange={e => setCcForm({ ...ccForm, name: e.target.value })} placeholder={tSettings('placeholders.ccName')} />
          : <span className="font-medium">{data.name}</span>}
      </td>
      <td style={{ textAlign: 'center' }}>
        {isEdit ? (
          <label className="switch" title={ccForm.isActive ? tSettings('labels.active') : tSettings('labels.inactive')}>
            <input type="checkbox" checked={ccForm.isActive} onChange={e => setCcForm({...ccForm, isActive: e.target.checked})} />
            <span className="switch-slider"></span>
          </label>
        ) : (
          <span style={{ color: data.isActive ? 'var(--success, #22c55e)' : 'var(--danger, #ef4444)', fontWeight: 'bold', fontSize: '0.75rem' }}>
            {data.isActive ? tSettings('labels.active').toUpperCase() : tSettings('labels.inactive').toUpperCase()}
          </span>
        )}
      </td>
      <td style={{ textAlign: 'right' }}>
        {isEdit ? (
          <div className="flex justify-end gap-2">
            <button className="btn btn-secondary btn-xs" onClick={ccCancel}>{tSettings('actions.cancel')}</button>
            <button className="btn btn-primary btn-xs" onClick={ccSave}>{tSettings('actions.save')}</button>
          </div>

        ) : (
          <div className="flex justify-end gap-2">
            {!data.isSystem && (
              <>
                <button className="btn btn-secondary btn-xs" onClick={() => ccEdit(data)}>{tSettings('actions.edit')}</button>
                <button className="btn btn-secondary btn-xs" style={{ color: 'var(--danger)', borderColor: 'var(--danger)' }} onClick={() => ccDelete(data.costCenterId)}>{tSettings('actions.delete')}</button>
              </>
            )}
            {data.isSystem && <span className="text-xs text-muted italic px-2">{tCommon('system')}</span>}
          </div>
        )}
      </td>
    </tr>
  );

  const renderActivityRow = (isEdit: boolean, data: any, key: string) => (
    <tr key={key} style={isEdit ? { background: 'var(--bg-secondary)' } : undefined}>
      <td>
        {isEdit && activityCreating
          ? <input className="input" value={activityForm.code} onChange={e => setActivityForm({ ...activityForm, code: e.target.value.toUpperCase() })} placeholder={tSettings('placeholders.activityCode')} style={{ width: 100 }} />
          : <span className="font-mono text-xs">{data.code}</span>}
      </td>
      <td>
        {isEdit
          ? <input className="input" value={activityForm.name} onChange={e => setActivityForm({ ...activityForm, name: e.target.value })} placeholder={tSettings('placeholders.activityName')} />
          : <span className="font-medium">{data.name}</span>}
      </td>
      <td style={{ textAlign: 'center' }}>
        {isEdit ? (
          <label className="switch" title={activityForm.isActive ? tSettings('labels.active') : tSettings('labels.inactive')}>
            <input type="checkbox" checked={activityForm.isActive} onChange={e => setActivityForm({...activityForm, isActive: e.target.checked})} />
            <span className="switch-slider"></span>
          </label>
        ) : (
          <span style={{ color: data.isActive ? 'var(--success, #22c55e)' : 'var(--danger, #ef4444)', fontWeight: 'bold', fontSize: '0.75rem' }}>
            {data.isActive ? tSettings('labels.active').toUpperCase() : tSettings('labels.inactive').toUpperCase()}
          </span>
        )}
      </td>
      <td style={{ textAlign: 'right' }}>
        {isEdit ? (
          <div className="flex justify-end gap-2">
            <button className="btn btn-secondary btn-xs" onClick={activityCancel}>{tSettings('actions.cancel')}</button>
            <button className="btn btn-primary btn-xs" onClick={activitySave}>{tSettings('actions.save')}</button>
          </div>

        ) : (
          <div className="flex justify-end gap-2">
            {!data.isSystem && (
              <>
                <button className="btn btn-secondary btn-xs" onClick={() => activityEdit(data)}>{tSettings('actions.edit')}</button>
                <button className="btn btn-secondary btn-xs" style={{ color: 'var(--danger)', borderColor: 'var(--danger)' }} onClick={() => activityDelete(data.activityId)}>{tSettings('actions.delete')}</button>
              </>
            )}
            {data.isSystem && <span className="text-xs text-muted italic px-2">{tCommon('system')}</span>}
          </div>
        )}
      </td>
    </tr>
  );

  const navSections = useMemo(() => [
    { id: 'gl-section', label: tSettings('sections.gl'), show: true },
    { id: 'tax-section', label: tSettings('sections.tax'), show: true },
    { id: 'rates-section', label: tSettings('sections.rates'), show: true },
    { id: 'cc-section', label: tSettings('sections.costCenters'), show: true },
    { id: 'activity-section', label: tSettings('sections.activities'), show: true },
  ], [tSettings]);

  return (
    <DetailsLayout
      header={
        <EntityHeader
          title={tSettings('title') + ' - ' + tCommon('financial')}
          subtitle={tSettings('subtitle')}
          onBack={() => router.push('/')}
          actions={
            <div className="flex items-center gap-2">
              <PageNav sections={navSections} />
            </div>
          }
          showPrint={false}
        />
      }
    >
      <div className="flex flex-col gap-6">
        {/* ── General Ledger ────────────────────────────────────────── */}
        <div id="gl-section" className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading !mb-0">
              {tSettings('sections.gl')}
            </h3>
          </div>

          {glLoading ? (
            <div className="text-sm text-muted animate-pulse">{tSettings('gl.loading')}</div>
          ) : (
            <div className="flex flex-col gap-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4">
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.defaultAr')}
                  </label>
                  {renderGlAccountSelect('defaultArAccountId', glSettings?.defaultArAccountId)}
                </div>
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.defaultRevenue')}
                  </label>
                  {renderGlAccountSelect('defaultRevenueAccountId', glSettings?.defaultRevenueAccountId)}
                </div>
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.defaultAp')}
                  </label>
                  {renderGlAccountSelect('defaultApAccountId', glSettings?.defaultApAccountId)}
                </div>
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.defaultTax')}
                  </label>
                  {renderGlAccountSelect('defaultTaxAccountId', glSettings?.defaultTaxAccountId)}
                </div>
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.defaultCogs')}
                  </label>
                  {renderGlAccountSelect('defaultCogsAccountId', glSettings?.defaultCogsAccountId)}
                </div>
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.defaultExpense')}
                  </label>
                  {renderGlAccountSelect('defaultExpenseAccountId', glSettings?.defaultExpenseAccountId)}
                </div>
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.defaultInventory')}
                  </label>
                  {renderGlAccountSelect('defaultInventoryAccountId', glSettings?.defaultInventoryAccountId)}
                </div>
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.defaultGrni')}
                  </label>
                  {renderGlAccountSelect('defaultGrniAccountId', glSettings?.defaultGrniAccountId)}
                </div>
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.defaultShrinkage')}
                  </label>
                  {renderGlAccountSelect('defaultShrinkageAccountId', glSettings?.defaultShrinkageAccountId)}
                </div>
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.defaultFeeRevenue')}
                  </label>
                  {renderGlAccountSelect('defaultFeeRevenueAccountId', glSettings?.defaultFeeRevenueAccountId)}
                </div>
              </div>
              
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-4">
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.baseCurrency')}
                  </label>
                  <select 
                    className="input max-w-sm" 
                    value={glSettings?.baseCurrency || ''} 
                    onChange={(e) => updateGlSetting('baseCurrency', e.target.value)}
                  >
                    <option value="">{tCommon('notConfigured')}</option>
                    {CURRENCIES.map(c => (
                      <option key={c.code} value={c.code}>{c.code} - {c.name}</option>
                    ))}
                  </select>
                </div>
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.revenueRouting')}
                  </label>
                  <select 
                    className="input max-w-sm" 
                    value={glSettings?.revenueRoutingPrecedence || ''} 
                    onChange={(e) => updateGlSetting('revenueRoutingPrecedence', e.target.value)}
                  >
                    <option value="customer_first">{tSettings('gl.customerFirst')}</option>
                    <option value="product_first">{tSettings('gl.productFirst')}</option>
                  </select>
                </div>
                <div className="flex flex-col gap-1">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tSettings('labels.expenseRouting')}
                  </label>
                  <select 
                    className="input max-w-sm" 
                    value={glSettings?.expenseRoutingPrecedence || ''} 
                    onChange={(e) => updateGlSetting('expenseRoutingPrecedence', e.target.value)}
                  >
                    <option value="supplier_first">{tSettings('gl.supplierFirst')}</option>
                    <option value="product_first">{tSettings('gl.productFirst')}</option>
                  </select>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* ── Chart of Accounts ────────────────────────────────────────── */}
        <div id="coa-section" className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading !mb-0">{tSettings('labels.chartOfAccounts')}</h3>
            <div className="flex gap-2">
              <button className="btn btn-secondary btn-xs" onClick={() => setImportCoaModalOpen(true)}>Import CoA...</button>
              <button className="btn btn-secondary btn-xs" onClick={openSchemaEditor}>{tSettings('actions.configureMetadata')}</button>
              <button className="btn btn-primary btn-sm" onClick={() => coaCreate()}>{tSettings('actions.addRootGroup')}</button>
            </div>
          </div>

          <table className="table-lines w-full">
                  <thead>
                    <tr>
                      <th style={{ width: 180 }}>{tSettings('labels.code')}</th>
                      <th>{tSettings('labels.name')}</th>
                      <th style={{ width: 140 }}>{tSettings('labels.type')}</th>
                      <th style={{ width: 60, textAlign: 'center' }}>{tSettings('labels.group')}</th>
                      <th style={{ width: 60, textAlign: 'center' }}>{tSettings('labels.bank')}</th>
                      <th style={{ width: 90, textAlign: 'center' }}>{tSettings('labels.currency')}</th>
                      <th style={{ width: 100, textAlign: 'center' }}>{tSettings('labels.status')}</th>
                      <th style={{ width: 260, textAlign: 'right' }}>{tSettings('actions.actions')}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {coaCreating && !coaForm.parentAccountId && renderCoaRow(true, coaForm, 'new-root')}
                    {coaTree.map(acct =>
                      <Fragment key={acct.glAccountId}>
                        {coaEditingId === acct.glAccountId
                          ? renderCoaRow(true, acct, acct.glAccountId)
                          : renderCoaRow(false, acct, acct.glAccountId)
                        }
                        {coaCreating && coaForm.parentAccountId === acct.glAccountId && renderCoaRow(true, coaForm, 'new-child')}
                      </Fragment>
                    )}
                  </tbody>
                </table>
        </div>

        {/* ── Tax Categories ─────────────────────────────────────────────── */}
        <div id="tax-section" className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading !mb-0">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined">payments</span>
              {tSettings('sections.tax')}
            </h3>
            <div className="flex gap-2">
              <button className="btn btn-secondary btn-sm" onClick={() => setImportTaxModalOpen(true)}>
                {/* eslint-disable-next-line i18next/no-literal-string */}
                <span className="material-symbols-outlined text-base">upload_file</span>
                {/* eslint-enable i18next/no-literal-string */}
                {tSettings('actions.importSettings')}
              </button>
              <button className="btn btn-primary btn-sm" onClick={taxCreate}>+ {tSettings('actions.create')}</button>
            </div>
          </div>
          <table className="table-lines w-full">
            <thead>
              <tr>
                <th style={{ width: 100 }}>{tSettings('labels.code')}</th>
                <th>{tSettings('labels.title')}</th>
                <th style={{ width: 140 }}>{tSettings('labels.type')}</th>
                <th style={{ width: 80 }}>{tSettings('labels.rate')}</th>
                <th style={{ width: 80, textAlign: 'center' }}>{tSettings('labels.isDefault')}</th>
                <th style={{ width: 150, textAlign: 'right' }}>{tSettings('actions.actions')}</th>
              </tr>
            </thead>
            <tbody>
              {taxCreating && renderTaxRow(true, taxForm, 'new-tax')}
              {!taxLoading && categories.length === 0 && !taxCreating && (
                <tr><td colSpan={6} style={{ textAlign: 'center', padding: '30px 0', color: 'var(--text-muted)' }}>{tSettings('tax.empty')}</td></tr>
              )}
              {categories.map(cat =>
                taxEditingId === cat.taxCategoryId
                  ? renderTaxRow(true, cat, cat.taxCategoryId)
                  : renderTaxRow(false, cat, cat.taxCategoryId)
              )}
            </tbody>
          </table>
        </div>

        {/* ── Exchange Rates ─────────────────────────────────────────────── */}
        <div id="rates-section" className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading !mb-0">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined">currency_exchange</span>
              {tSettings('sections.rates')}
            </h3>
            <button className="btn btn-primary btn-sm" onClick={rateCreate}>+ {tSettings('actions.create')}</button>
          </div>
          <table className="table-lines w-full">
            <thead>
              <tr>
                <th style={{ width: 100 }}>{tSettings('labels.currencyCode')}</th>
                <th>{tSettings('labels.currencyName')}</th>
                <th style={{ width: 110 }}>{tSettings('labels.buyRate')}</th>
                <th style={{ width: 110 }}>{tSettings('labels.sellRate')}</th>
                <th style={{ width: 130 }}>{tSettings('labels.effectiveDate')}</th>
                <th style={{ width: 150, textAlign: 'right' }}>{tSettings('actions.actions')}</th>
              </tr>
            </thead>
            <tbody>
              {/* --- Anchor Row: Base System Currency --- */}
              <tr style={{ backgroundColor: 'rgba(var(--primary-rgb), 0.03)', fontWeight: 500 }}>
                <td>
                  <div className="flex items-center gap-2">
                    {glSettings?.baseCurrency ?? '—'}
                  </div>
                </td>
                <td>{glSettings?.baseCurrency ? getCurrency(glSettings.baseCurrency).name : '—'}</td>
                <td>1.0000</td>
                <td>1.0000</td>
                <td><span className="text-xs italic text-muted">{tSettings('labels.systemBase')}</span></td>
                <td style={{ textAlign: 'right' }}>
                  <span className="text-xs text-muted italic">{tSettings('labels.fixed')}</span>
                </td>
              </tr>

              {rateCreating && renderRateRow(true, rateForm, 'new-rate')}
              {!rateLoading && rates.length === 0 && !rateCreating && (
                <tr><td colSpan={6} style={{ textAlign: 'center', padding: '30px 0', color: 'var(--text-muted)' }}>{tSettings('rates.empty')}</td></tr>
              )}
              {rates.map(r =>
                rateEditingId === r.exchangeRateId
                  ? renderRateRow(true, r, r.exchangeRateId)
                  : renderRateRow(false, r, r.exchangeRateId)
              )}
            </tbody>
          </table>
        </div>

        {/* ── Cost Centers ─────────────────────────────────────────────────── */}
        <div id="cc-section" className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading !mb-0">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined">folder_shared</span>
              {tSettings('sections.costCenters')}
            </h3>
            <div className="flex items-center gap-2">
              <CsvImportButton onImport={handleImportCc} disabled={isImporting} />
              <button className="btn btn-primary btn-sm" onClick={ccCreate}>+ {tSettings('actions.create')}</button>
            </div>
          </div>
          <table className="table-lines w-full">
            <thead>
              <tr>
                <th style={{ width: 120 }}>{tSettings('labels.code')}</th>
                <th>{tSettings('labels.name')}</th>
                <th style={{ width: 120, textAlign: 'center' }}>{tSettings('labels.status')}</th>
                <th style={{ width: 150, textAlign: 'right' }}>{tSettings('actions.actions')}</th>
              </tr>
            </thead>
            <tbody>
              {ccCreating && renderCcRow(true, ccForm, 'new-cc')}
              {!ccLoading && ccs.length === 0 && !ccCreating && (
                <tr><td colSpan={4} style={{ textAlign: 'center', padding: '30px 0', color: 'var(--text-muted)' }}>{tSettings('costCenters.empty')}</td></tr>
              )}

              {ccs.map(cc =>
                ccEditingId === cc.costCenterId
                  ? renderCcRow(true, cc, cc.costCenterId)
                  : renderCcRow(false, cc, cc.costCenterId)
              )}
            </tbody>
          </table>
        </div>

        {/* ── Activities ───────────────────────────────────────────────────── */}
        <div id="activity-section" className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading !mb-0">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined">account_tree</span>
              {tSettings('sections.activities')}
            </h3>
            <div className="flex items-center gap-2">
              <CsvImportButton onImport={handleImportActivity} disabled={isImporting} />
              <button className="btn btn-primary btn-sm" onClick={activityCreate}>+ {tSettings('actions.create')}</button>
            </div>
          </div>
          <table className="table-lines w-full">
            <thead>
              <tr>
                <th style={{ width: 120 }}>{tSettings('labels.code')}</th>
                <th>{tSettings('labels.name')}</th>
                <th style={{ width: 120, textAlign: 'center' }}>{tSettings('labels.status')}</th>
                <th style={{ width: 150, textAlign: 'right' }}>{tSettings('actions.actions')}</th>
              </tr>
            </thead>
            <tbody>
              {activityCreating && renderActivityRow(true, activityForm, 'new-activity')}
              {!activityLoading && activitiesData.length === 0 && !activityCreating && (
                <tr><td colSpan={4} style={{ textAlign: 'center', padding: '30px 0', color: 'var(--text-muted)' }}>{tSettings('activities.empty')}</td></tr>
              )}

              {activitiesData.map(a =>
                activityEditingId === a.activityId
                  ? renderActivityRow(true, a, a.activityId)
                  : renderActivityRow(false, a, a.activityId)
              )}
            </tbody>
          </table>
        </div>
      </div>

      <SlideOver
        isOpen={schemaEditorOpen}
        onClose={() => setSchemaEditorOpen(false)}
        title={tSettings('labels.configureMetadataSchema')}
        width="max-w-2xl"
      >
        <div className="p-4 flex flex-col gap-6">
          <SchemaBuilder 
            value={schemaObj} 
            onChange={setSchemaObj} 
          />

          <div className="flex justify-end gap-2 mt-4 pt-4 border-t border-[var(--border)]">
            <button className="btn btn-secondary" onClick={() => setSchemaEditorOpen(false)}>{tSettings('actions.cancel')}</button>
            <button className="btn btn-primary" onClick={saveSchema}>{tSettings('actions.saveSchema')}</button>
          </div>
        </div>
      </SlideOver>

      {importCoaModalOpen && (
        <ImportCoaModal
          isOpen={importCoaModalOpen}
          onClose={() => setImportCoaModalOpen(false)}
          onImportComplete={loadGl}
        />
      )}

      {importTaxModalOpen && (
        <ImportTaxModal
          isOpen={importTaxModalOpen}
          onClose={() => setImportTaxModalOpen(false)}
          onImportComplete={loadTax}
        />
      )}
    </DetailsLayout>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useTranslations } from 'next-intl';
import * as api from '@modbm/sdk';
import { getErrorMessage, COUNTRIES } from '@modbm/shared';
import toast from 'react-hot-toast';

import DetailsLayout from '@/components/shared/DetailsLayout';
import EntityHeader from '@/components/shared/EntityHeader';
import { DynamicForm } from '@/components/DynamicForm';
import { InlineSettingsTable } from '@/components/shared/InlineSettingsTable';

interface ProviderConfig {
  name: string;
  type?: 'enrichment' | 'tax_engine';
  supportedCountries?: string[] | 'global';
  schema: any;
}

type TaxRule = { id: string; country: string; provider: string };
type EnrichmentRule = { id: string; field: string; country: string; provider: string };



export default function IntegrationsSettingsPage() {
  const router = useRouter();
  const tCommon = useTranslations('common');

  const [loading, setLoading] = useState(true);
  const [providers, setProviders] = useState<ProviderConfig[]>([]);

  const [expandedProvider, setExpandedProvider] = useState<string | null>(null);
  // modbm-allow-record-any
  const [configData, setConfigData] = useState<Record<string, any>>({});
  const [saving, setSaving] = useState(false);
  const [loadingConfig, setLoadingConfig] = useState(false);

  // Test Connection State
  const [testPayload, setTestPayload] = useState<string>('');
  const [testing, setTesting] = useState(false);
  const [testResult, setTestResult] = useState<{ success: boolean; data?: any; error?: string } | null>(null);

  // Routing Rules State
  const [appConfig, setAppConfig] = useState<any>(null);
  const [taxRules, setTaxRules] = useState<TaxRule[]>([]);
  const [enrichmentRules, setEnrichmentRules] = useState<EnrichmentRule[]>([]);

  useEffect(() => {
    loadProviders();
  }, []);

  const loadProviders = async () => {
    try {
      setLoading(true);
      const [provRes, configRes] = await Promise.all([
        api.enrichmentControllerGetProviders(),
        api.appConfigControllerGet()
      ]);
      setProviders((provRes.data as unknown as ProviderConfig[]) || []);

      const config = configRes.data as any;
      setAppConfig(config);

      const taxMappingRaw = (config.taxProviderMappings as Record<string, string>) || {};
      const taxRulesArr = Object.entries(taxMappingRaw).map(([country, provider]) => ({ id: country, country, provider }));
      setTaxRules(taxRulesArr);

      const enrichmentMappingRaw = (config.enrichmentProviderMappings as Record<string, Record<string, string>>) || {};
      const enrichmentRulesArr: EnrichmentRule[] = [];
      Object.entries(enrichmentMappingRaw).forEach(([field, countryMap]) => {
        Object.entries(countryMap).forEach(([country, provider]) => {
          enrichmentRulesArr.push({ id: `${field}-${country}`, field, country, provider });
        });
      });
      setEnrichmentRules(enrichmentRulesArr);
    } catch (err) {
      toast.error('Failed to load integrations: ' + getErrorMessage(err));
    } finally {
      setLoading(false);
    }
  };

  const getUpdatedConfigPayload = (newTaxRules: TaxRule[], newEnrichmentRules: EnrichmentRule[]) => {
    const newTaxMappings: Record<string, string> = {};
    newTaxRules.forEach(r => {
      newTaxMappings[r.country.toUpperCase()] = r.provider;
    });

    const newEnrichmentMappings: Record<string, Record<string, string>> = {};
    newEnrichmentRules.forEach(r => {
      if (!newEnrichmentMappings[r.field]) newEnrichmentMappings[r.field] = {};
      newEnrichmentMappings[r.field][r.country.toUpperCase()] = r.provider;
    });

    return {
      taxProviderMappings: newTaxMappings as any,
      enrichmentProviderMappings: newEnrichmentMappings as any
    };
  };

  const saveTaxRule = async (row: TaxRule, isNew: boolean) => {
    if (!row.country || row.country.trim().length !== 2) {
      toast.error("Country code must be 2 letters");
      throw new Error("Invalid country");
    }
    if (!row.provider) {
      toast.error("Provider is required");
      throw new Error("Invalid provider");
    }

    const newRules = isNew ? [...taxRules, { ...row, id: row.country }] : taxRules.map(r => r.id === row.id ? row : r);
    setTaxRules(newRules);

    await api.appConfigControllerUpdate(getUpdatedConfigPayload(newRules, enrichmentRules));
    toast.success('Tax rule saved');
    await loadProviders();
  };

  const deleteTaxRule = async (row: TaxRule) => {
    const newRules = taxRules.filter(r => r.id !== row.id);
    setTaxRules(newRules);
    await api.appConfigControllerUpdate(getUpdatedConfigPayload(newRules, enrichmentRules));
    toast.success('Tax rule deleted');
    await loadProviders();
  };

  const saveEnrichmentRule = async (row: EnrichmentRule, isNew: boolean) => {
    if (!row.field) {
      toast.error("Field is required");
      throw new Error("Invalid field");
    }
    if (!row.country || row.country.trim().length !== 2) {
      toast.error("Country code must be 2 letters");
      throw new Error("Invalid country");
    }
    if (!row.provider) {
      toast.error("Provider is required");
      throw new Error("Invalid provider");
    }

    const newRules = isNew ? [...enrichmentRules, { ...row, id: `${row.field}-${row.country}` }] : enrichmentRules.map(r => r.id === row.id ? row : r);
    setEnrichmentRules(newRules);

    await api.appConfigControllerUpdate(getUpdatedConfigPayload(taxRules, newRules));
    toast.success('Enrichment rule saved');
    await loadProviders();
  };

  const deleteEnrichmentRule = async (row: EnrichmentRule) => {
    const newRules = enrichmentRules.filter(r => r.id !== row.id);
    setEnrichmentRules(newRules);
    await api.appConfigControllerUpdate(getUpdatedConfigPayload(taxRules, newRules));
    toast.success('Enrichment rule deleted');
    await loadProviders();
  };

  const toggleProvider = async (provider: ProviderConfig) => {
    if (expandedProvider === provider.name) {
      setExpandedProvider(null);
      return;
    }

    setExpandedProvider(provider.name);
    setTestPayload('');
    setTestResult(null);
    setConfigData({});

    try {
      setLoadingConfig(true);
      const res = await api.enrichmentControllerGetConfig({ provider: provider.name });
      // modbm-allow-record-any
      const data = (res.data as Record<string, any>) || {};
      setConfigData(data);
      if (data.testPayload) {
        setTestPayload(typeof data.testPayload === 'object' ? JSON.stringify(data.testPayload, null, 2) : data.testPayload);
      } else if (provider.schema?.properties?.testPayload?.default) {
        setTestPayload(provider.schema.properties.testPayload.default);
      } else {
        setTestPayload('');
      }
    } catch (err) {
      toast.error('Failed to load configuration: ' + getErrorMessage(err));
    } finally {
      setLoadingConfig(false);
    }
  };

  const handleSaveConfig = async (provider: ProviderConfig) => {
    try {
      setSaving(true);
      const payloadToSave = { ...configData, testPayload };
      await api.enrichmentControllerUpdateConfig(
        payloadToSave,
        { provider: provider.name }
      );
      toast.success('Configuration saved');
    } catch (err) {
      toast.error('Failed to save configuration: ' + getErrorMessage(err));
    } finally {
      setSaving(false);
    }
  };

  const handleTestConnection = async (providerName: string) => {
    if (!testPayload.trim()) {
      toast.error('Please enter a test payload or query');
      return;
    }

    try {
      setTesting(true);
      setTestResult(null);

      let payload;
      let isJson = false;
      try {
        payload = JSON.parse(testPayload);
        isJson = true;
      } catch (e) {
        payload = testPayload;
      }

      if (isJson && typeof payload === 'object') {
        const res = await api.enrichmentControllerTestLookupPost({ payload }, { provider: providerName });
        // The API returns 200/201 but the payload might indicate a provider error via isValid
        const isSuccess = res.data?.isValid !== false && !(res.data?.data as any)?.error;
        setTestResult({ success: isSuccess, data: res.data });
      } else {
        const res = await api.enrichmentControllerTestLookup({ provider: providerName, query: testPayload });
        const isSuccess = res.data?.isValid !== false && !(res.data?.data as any)?.error;
        setTestResult({ success: isSuccess, data: res.data });
      }
      // Auto-save the test payload to the DB if we're testing
      if (testPayload.trim()) {
         try {
           const currentConfigRes = await api.enrichmentControllerGetConfig({ provider: providerName });
           // modbm-allow-record-any
           const currentData = (currentConfigRes.data as Record<string, any>) || {};
           await api.enrichmentControllerUpdateConfig(
             { ...currentData, testPayload },
             { provider: providerName }
           );
         } catch (e) {
           // ignore silently if saving the test payload fails during a test
         }
      }

      toast.success('Test successful');
    } catch (err) {
      setTestResult({ success: false, error: getErrorMessage(err) });
      toast.error('Test connection failed');
    } finally {
      setTesting(false);
    }
  };

  return (
    <DetailsLayout
      header={
        <EntityHeader
          title="Integrations & Enrichment"
          subtitle="Manage external integrations, data providers, and API keys"
          onBack={() => router.push('/admin/settings/system')}
          showPrint={false}
        />
      }
    >
      <div className="flex flex-col gap-6">
        {/* Routing Rules Section */}
        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading !mb-0">
              <span className="material-symbols-outlined">route</span>
              Routing Rules
            </h3>
          </div>

          <div className="grid grid-cols-1 gap-8">
            {/* Tax Engine Rules */}
            <div>
              <InlineSettingsTable<TaxRule>
                title="Tax Engines"
                columns={[
                  { 
                    key: 'country', 
                    title: 'Country', 
                    type: 'select',
                    options: [
                      { value: '', label: 'Select Country...' },
                      ...COUNTRIES.map(c => ({ value: c.code, label: `${c.name} (${c.code})` }))
                    ]
                  },
                  { 
                    key: 'provider', 
                    title: 'Provider', 
                    type: 'select', 
                    options: (row) => {
                      const taxProviders = providers.filter(p => p.type === 'tax_engine');
                      const filtered = row.country ? taxProviders.filter(p => {
                        const supported = p.supportedCountries;
                        if (supported === 'global') return true;
                        if (Array.isArray(supported)) return supported.includes(row.country!);
                        return true;
                      }) : taxProviders;

                      return [
                        { value: 'internal', label: 'Internal (Default)' },
                        ...filtered.map(p => ({ value: p.name, label: p.name }))
                      ];
                    }
                  }
                ]}
                data={taxRules}
                rowKey={(row) => row.id}
                onSave={saveTaxRule}
                onDelete={deleteTaxRule}
                onAdd={() => ({ id: '', country: '', provider: 'internal' })}
                addLabel="Add Rule"
              />
            </div>

            {/* Enrichment Rules */}
            <div>
              <InlineSettingsTable<EnrichmentRule>
                title="Data Enrichment"
                columns={[
                  { 
                    key: 'field', 
                    title: 'Field', 
                    type: 'select',
                    options: [
                      { value: '', label: 'Select Field...' },
                      { value: 'customer.business_number', label: 'Customer Business Number' },
                      { value: 'supplier.business_number', label: 'Supplier Business Number' }
                    ]
                  },
                  { 
                    key: 'country', 
                    title: 'Country', 
                    type: 'select',
                    options: [
                      { value: '', label: 'Select Country...' },
                      ...COUNTRIES.map(c => ({ value: c.code, label: `${c.name} (${c.code})` }))
                    ]
                  },
                  { 
                    key: 'provider', 
                    title: 'Provider', 
                    type: 'select', 
                    options: (row) => {
                      const enrichmentProviders = providers.filter(p => p.type === 'enrichment');
                      const filtered = row.country ? enrichmentProviders.filter(p => {
                        const supported = p.supportedCountries;
                        if (supported === 'global') return true;
                        if (Array.isArray(supported)) return supported.includes(row.country!);
                        return true;
                      }) : enrichmentProviders;

                      return [
                        { value: '', label: 'Select Provider...' },
                        ...filtered.map(p => ({ value: p.name, label: p.name }))
                      ];
                    }
                  }
                ]}
                data={enrichmentRules}
                rowKey={(row) => row.id}
                onSave={saveEnrichmentRule}
                onDelete={deleteEnrichmentRule}
                onAdd={() => ({ id: '', field: '', country: '', provider: providers[0]?.name || '' })}
                addLabel="Add Rule"
              />
            </div>
          </div>
        </div>

        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading !mb-0">
              <span className="material-symbols-outlined">extension</span>
              Available Integrations
            </h3>
          </div>

          {loading ? (
            <div className="p-6 text-center text-muted">Loading integrations...</div>
          ) : providers.length === 0 ? (
            <div className="p-6 text-center text-muted">No integrations found.</div>
          ) : (
            <div className="flex flex-col gap-4">
              {providers.map(p => {
                const isExpanded = expandedProvider === p.name;

                return (
                  <div key={p.name} className="border border-[var(--border)] rounded-xl overflow-hidden flex flex-col bg-white transition-colors">
                    <div 
                      className={`flex items-center justify-between px-5 py-4 hover:bg-[var(--bg-secondary)] cursor-pointer select-none ${isExpanded ? 'border-b border-[rgba(196,198,205,0.4)]' : ''}`}
                      onClick={() => toggleProvider(p)}
                    >
                      <div className="flex items-center gap-4">
                        <span className={`material-symbols-outlined text-[18px] transition-transform duration-200 text-[var(--accent)] ${isExpanded ? 'rotate-90' : ''}`}>
                          chevron_right
                        </span>
                        <div>
                          <div className="font-bold text-sm text-[#041627] capitalize" style={{ fontFamily: 'Manrope, sans-serif' }}>
                            {p.name.toUpperCase()}
                          </div>
                          <div className="text-xs text-[var(--text-secondary)] mt-0.5">
                            External Data Provider
                          </div>
                        </div>
                      </div>
                      <div className="flex gap-2" onClick={e => e.stopPropagation()}>
                        <button className="btn btn-secondary btn-sm" onClick={() => toggleProvider(p)}>
                          {isExpanded ? 'Close' : 'Configure'}
                        </button>
                      </div>
                    </div>

                    {isExpanded && (
                      <div className="p-5 flex flex-col gap-6">

                        {/* Configuration Section */}
                        <div>
                          <h4 className="text-sm font-bold text-[#041627] mb-3" style={{ fontFamily: 'Manrope, sans-serif' }}>
                            Configuration
                          </h4>
                          {loadingConfig ? (
                            <div className="text-sm text-muted animate-pulse p-4 bg-white rounded border border-[var(--border)]">Loading configuration...</div>
                          ) : (
                            <div className="flex flex-col gap-4">
                              <div className="bg-white p-5 border border-[var(--border)] rounded-lg">
                                {(() => {
                                  const displaySchema = { ...p.schema };
                                  if (displaySchema.properties) {
                                    displaySchema.properties = { ...displaySchema.properties };
                                    delete displaySchema.properties.testPayload;
                                  }
                                  return (
                                    <DynamicForm
                                      schema={displaySchema}
                                      data={configData}
                                      onChange={(data) => setConfigData(data)}
                                    />
                                  );
                                })()}
                              </div>
                              <div className="flex justify-end">
                                <button 
                                  className="btn btn-primary" 
                                  onClick={() => handleSaveConfig(p)}
                                  disabled={saving}
                                >
                                  {saving ? 'Saving...' : 'Save Configuration'}
                                </button>
                              </div>
                            </div>
                          )}
                        </div>

                        <hr className="border-[var(--border)]" />

                        {/* Test Connection Section */}
                        <div>
                          <h4 className="text-sm font-bold text-[#041627] mb-3" style={{ fontFamily: 'Manrope, sans-serif' }}>
                            Test Connection
                          </h4>
                          <div className="bg-white p-5 border border-[var(--border)] rounded-lg flex flex-col gap-4">
                            <div>
                              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                                Query or Payload (JSON)
                              </label>
                              <textarea
                                className="input w-full font-mono text-sm"
                                style={{ minHeight: 100, resize: 'vertical' }}
                                placeholder='e.g. "ABN_NUMBER" or { "query": "..." }'
                                value={testPayload}
                                onChange={(e) => setTestPayload(e.target.value)}
                              />
                            </div>
                            <div className="flex justify-end">
                              <button 
                                className="btn btn-secondary"
                                onClick={() => handleTestConnection(p.name)}
                                disabled={testing || !testPayload.trim()}
                              >
                                {testing ? 'Testing...' : 'Run Test'}
                              </button>
                            </div>

                            {/* Test Result */}
                            {testResult && (
                              <div className={`mt-2 p-4 rounded-lg border ${testResult.success ? 'bg-emerald-50 border-emerald-200' : 'bg-red-50 border-red-200'}`}>
                                <h5 className={`text-xs font-bold uppercase tracking-wider mb-2 ${testResult.success ? 'text-emerald-700' : 'text-red-700'}`}>
                                  {testResult.success ? 'Test Successful' : 'Test Failed'}
                                </h5>
                                {testResult.success ? (
                                  <pre className="text-xs bg-white/60 p-3 rounded border border-emerald-100 overflow-x-auto whitespace-pre-wrap font-mono text-emerald-900">
                                    {JSON.stringify(testResult.data, null, 2)}
                                  </pre>
                                ) : (
                                  <p className="text-sm text-red-600">{testResult.error}</p>
                                )}
                              </div>
                            )}
                          </div>
                        </div>

                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </DetailsLayout>
  );
}

'use client';

import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import { useTranslations } from 'next-intl';

import { useState, useEffect, useRef } from 'react';
import * as api from '@modbm/sdk';

interface LogsResponse {
  lines: string[];
}

export default function SystemLogsPage() {
  const t = useTranslations('admin.systemLogs');
  useDocumentTitle(t('title'));
  const [lines, setLines] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [lineLimit, setLineLimit] = useState(1000);
  const [service, setService] = useState('api');
  const [isInitialized, setIsInitialized] = useState(false);
  const logEndRef = useRef<HTMLDivElement>(null);
  const fetchIdRef = useRef(0);

  useEffect(() => {
    const savedService = localStorage.getItem('modbm_logs_service');
    if (savedService) {
      setService(savedService);
    }
    setIsInitialized(true);
  }, []);

  const handleServiceChange = (newService: string) => {
    setService(newService);
    localStorage.setItem('modbm_logs_service', newService);
  };

  const loadLogs = async () => {
    const fetchId = ++fetchIdRef.current;
    try {
      setLoading(true);
      const res = await api.systemControllerGetSystemLogs({ service, lines: lineLimit.toString() });
      if (fetchId === fetchIdRef.current) {
        setLines(res.data.lines);
        setError('');
      }
    } catch (err) {
      if (fetchId === fetchIdRef.current) {
        setError(err instanceof Error ? err.message : t('toasts.loadFailed'));
      }
    } finally {
      if (fetchId === fetchIdRef.current) {
        setLoading(false);
      }
    }
  };

  useEffect(() => {
    if (isInitialized) {
      loadLogs();
    }
  }, [lineLimit, service, isInitialized]);

  useEffect(() => {
    if (!autoRefresh) return;
    const interval = setInterval(loadLogs, 5000);
    return () => clearInterval(interval);
  }, [autoRefresh, lineLimit, service]);

  // Auto-scroll to bottom when lines update
  useEffect(() => {
    if (logEndRef.current) {
      logEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [lines]);

  const handleCopyLogs = () => {
    navigator.clipboard.writeText(lines.join('\n'));
    alert(t('actions.copied'));
  };

  return (
    <>
      <div style={{ maxWidth: 1200, margin: '0 auto', display: 'flex', flexDirection: 'column', height: 'calc(100vh - 100px)' }}>
        {/* Header */}
        <div className="flex items-center justify-between mb-4 shrink-0">
          <div>
            <h1 className="text-2xl font-bold">{t('title')}</h1>
            <p className="text-sm mt-1" style={{ color: 'var(--text-muted)' }}>
              {t('subtitle')}
            </p>
          </div>
          <div className="flex gap-4 items-center">
            <div className="flex items-center gap-2 text-xs">
              <label style={{ color: 'var(--text-muted)' }}>{t('filters.service')}</label>
              <select 
                className="input-field py-1 px-2 text-xs h-auto"
                value={service} 
                onChange={(e) => handleServiceChange(e.target.value)}
              >
                <option value="api">{t('filters.services.api')}</option>
                <option value="worker">{t('filters.services.worker')}</option>
                <option value="postgres">{t('filters.services.postgres')}</option>
                <option value="integration">Integration Engine</option>
              </select>
            </div>
            <div className="flex items-center gap-2 text-xs">
              <label style={{ color: 'var(--text-muted)' }}>{t('filters.limit')}</label>
              <select 
                className="input-field py-1 px-2 text-xs h-auto"
                value={lineLimit} 
                onChange={(e) => setLineLimit(Number(e.target.value))}
              >
                <option value={100}>{t('filters.limits.100')}</option>
                <option value={500}>{t('filters.limits.500')}</option>
                <option value={1000}>{t('filters.limits.1000')}</option>
                <option value={5000}>{t('filters.limits.5000')}</option>
              </select>
            </div>
            <label className="flex items-center gap-2 text-xs" style={{ color: 'var(--text-muted)' }}>
              <input
                type="checkbox"
                checked={autoRefresh}
                onChange={() => setAutoRefresh(!autoRefresh)}
              />
              {t('filters.autoRefresh')}
            </label>
            <button className="btn btn-secondary btn-sm" onClick={handleCopyLogs} disabled={lines.length === 0}>
              {t('actions.copy')}
            </button>
            <button className="btn btn-secondary btn-sm" onClick={loadLogs}>
              <span>🔄</span>
              {' '}
              {t('actions.refresh')}
            </button>
          </div>
        </div>

        {error && (
          <div
            className="mb-4 px-4 py-3 rounded-lg text-sm shrink-0"
            style={{
              background: 'rgba(239, 68, 68, 0.1)',
              border: '1px solid rgba(239, 68, 68, 0.3)',
              color: '#f87171',
            }}
          >
            {error}
          </div>
        )}

        {/* Log Viewer Terminal */}
        <div 
          className="flex-1 rounded-lg overflow-auto relative"
          style={{ 
            background: '#1e1e1e', // Dark terminal background
            border: '1px solid var(--border)',
            padding: '16px',
            fontFamily: 'monospace, "Courier New", Courier',
            fontSize: '12px',
            lineHeight: '1.5',
            color: '#d4d4d4', // Light gray text
          }}
        >
          {loading && lines.length === 0 ? (
            <div className="flex items-center justify-center h-full text-gray-500">
              {t('loading')}
            </div>
          ) : lines.length === 0 ? (
            <div className="flex items-center justify-center h-full text-gray-500">
              {t('noLogs')}
            </div>
          ) : (
            <>
              {lines.map((line, idx) => {
                // Basic coloration for log levels
                let color = '#d4d4d4'; // default
                if (line.includes('[WARN]')) color = '#f59e0b'; // warning (amber)
                else if (line.includes('[ERROR]') || line.includes('Error:')) color = '#f87171'; // error (red)
                else if (line.includes('[DEBUG]')) color = '#9ca3af'; // debug (gray)
                else if (line.includes('[INFO]')) color = '#60a5fa'; // info (blue)
                
                return (
                  <div key={idx} style={{ color, whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
                    {line}
                  </div>
                );
              })}
              <div ref={logEndRef} />
            </>
          )}
        </div>
      </div>
    </>
  );
}

'use client';

import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import { useState, useEffect } from 'react';
import * as api from '@modbm/sdk';
import { toast } from 'react-hot-toast';
import { useRouter } from 'next/navigation';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import { getErrorMessage } from '@modbm/shared';

const RESOURCES = [
  'customers', 'products', 'inventory', 'sales-orders', 'sales-returns',
  'purchase-orders', 'purchase-returns', 'suppliers', 'receptions', 'goods-received',
  'dashboard', 'tax-categories', 'settings', 'report', 'payments', 'system_logs',
  'import', 'api_keys', 'webhooks', 'events', 'roles', 'users', 'gl', 'locations'
];

const ACTIONS = ['read', 'write', 'archive', 'handle', 'invoice'];

const VALID_ACTIONS: Record<string, string[]> = {
  'customers': ['read', 'write', 'archive'],
  'products': ['read', 'write', 'archive'],
  'inventory': ['read', 'write', 'archive', 'handle'],
  'sales-orders': ['read', 'write', 'archive', 'handle', 'invoice'],
  'sales-returns': ['read', 'write', 'archive', 'handle', 'invoice'],
  'purchase-orders': ['read', 'write', 'archive', 'handle', 'invoice'],
  'purchase-returns': ['read', 'write', 'archive', 'handle', 'invoice'],
  'suppliers': ['read', 'write', 'archive'],
  'receptions': ['read', 'write', 'archive', 'handle'],
  'goods-received': ['read', 'write', 'archive', 'handle'],
  'dashboard': ['read'],
  'tax-categories': ['read', 'write', 'archive'],
  'settings': ['read', 'write', 'archive'],
  'report': ['read', 'write', 'archive'],
  'payments': ['read', 'write', 'archive'],
  'system_logs': ['read', 'write', 'archive'],
  'import': ['read', 'write', 'archive'],
  'api_keys': ['read', 'write', 'archive'],
  'webhooks': ['read', 'write', 'archive'],
  'events': ['read', 'write', 'archive'],
  'roles': ['read', 'write', 'archive'],
  'users': ['read', 'write', 'archive'],
  'gl': ['read', 'write'],
  'locations': ['read', 'write', 'archive'],
};

interface PermissionDetail {
  resource: string;
  action: string;
  effect: 'allow' | 'deny';
}

interface ImplicitPermissionDetail extends PermissionDetail {
  sourceRole: string;
}

interface RoleWithDetails {
  role: string;
  localPermissions: PermissionDetail[];
  inherits: string[];
  implicitPermissions: ImplicitPermissionDetail[];
}

export default function RolesPage() {
  useDocumentTitle('Roles & Permissions');
  const router = useRouter();

  const [roles, setRoles] = useState<RoleWithDetails[]>([]);
  const [loading, setLoading] = useState(true);

  const [editingRole, setEditingRole] = useState<string | null>(null);
  const [isCreating, setIsCreating] = useState(false);
  const [newRoleName, setNewRoleName] = useState('');
  
  // Local state for the matrix
  // Form permissions: Record<resource, Record<action, effect>>
  const [formPermissions, setFormPermissions] = useState<Record<string, Record<string, 'allow' | 'deny' | ''>>>({});
  const [formInherits, setFormInherits] = useState<string[]>([]);

  const [expandedRoles, setExpandedRoles] = useState<Record<string, boolean>>({});

  const toggleRole = (role: string) => {
    setExpandedRoles(prev => ({ ...prev, [role]: !prev[role] }));
  };

  const loadRoles = async () => {
    try {
      setLoading(true);
      const res = await api.rolesControllerFindAll();
      setRoles(res.data as unknown as RoleWithDetails[]);
    } catch (err: unknown) {
      toast.error('Failed to load roles: ' + getErrorMessage(err));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadRoles();
  }, []);

  const getRoleNames = () => roles.map(r => r.role);

  const initForm = (localPerms: PermissionDetail[], inherits: string[]) => {
    const map: Record<string, Record<string, 'allow' | 'deny' | ''>> = {};
    for (const res of RESOURCES) {
      map[res] = {};
      for (const act of ACTIONS) {
        map[res][act] = '';
      }
    }
    for (const p of localPerms) {
      if (map[p.resource]) {
        map[p.resource][p.action] = p.effect;
      }
    }
    setFormPermissions(map);
    setFormInherits([...inherits]);
  };

  const startEdit = (role: RoleWithDetails) => {
    setEditingRole(role.role);
    setIsCreating(false);
    initForm(role.localPermissions || [], role.inherits || []);
  };

  const startCreate = () => {
    setIsCreating(true);
    setEditingRole(null);
    setNewRoleName('');
    initForm([], []);
  };

  const cancel = () => {
    setEditingRole(null);
    setIsCreating(false);
  };

  const save = async () => {
    const targetRole = isCreating ? newRoleName.trim().toLowerCase() : editingRole;
    if (!targetRole) {
      toast.error('Role name is required');
      return;
    }
    
    const permissionsToSave: PermissionDetail[] = [];
    Object.entries(formPermissions).forEach(([resource, acts]) => {
      Object.entries(acts).forEach(([action, effect]) => {
        if (effect === 'allow' || effect === 'deny') {
          permissionsToSave.push({ resource, action, effect: effect as 'allow' | 'deny' });
        }
      });
    });

    try {
      await api.rolesControllerSetPermissions(targetRole, {
        permissions: permissionsToSave as any,
        inherits: formInherits,
      } as any);
      toast.success(isCreating ? 'Role created' : 'Permissions updated');
      cancel();
      loadRoles();
    } catch (err: unknown) {
      toast.error(getErrorMessage(err));
    }
  };

  const deleteRole = async (role: string) => {
    if (role === 'admin' || role === 'viewer' || role === 'webhook' || role === 'agent') {
      toast.error('Cannot delete system-critical roles');
      return;
    }
    if (!confirm(`Are you sure you want to delete role '${role}'?`)) return;
    try {
      await api.rolesControllerRemove(role);
      toast.success('Role deleted');
      loadRoles();
    } catch (err: unknown) {
      toast.error(getErrorMessage(err));
    }
  };

  const handlePermissionChange = (resource: string, action: string, effect: 'allow' | 'deny' | '') => {
    setFormPermissions(prev => ({
      ...prev,
      [resource]: {
        ...prev[resource],
        [action]: effect
      }
    }));
  };

  const handleInheritsToggle = (parentRole: string) => {
    setFormInherits(prev => 
      prev.includes(parentRole) 
        ? prev.filter(r => r !== parentRole) 
        : [...prev, parentRole]
    );
  };

  // Helper to render the permission matrix
  const renderMatrix = (isReadOnly: boolean, currentRoleItem?: RoleWithDetails) => {
    
    const getImplicitPerm = (resource: string, action: string) => {
      if (!currentRoleItem || !currentRoleItem.implicitPermissions) return null;
      return currentRoleItem.implicitPermissions.find(p => p.resource === resource && p.action === action) || null;
    };

    return (
      <div className="overflow-x-auto w-full">
        <table className="table-lines w-full table-fixed text-sm">
          <thead>
            <tr>
              <th className="w-[150px] text-left" style={{ textAlign: 'left' }}>Resource</th>
              {ACTIONS.map(a => <th key={a} className="text-center uppercase text-[var(--text-secondary)] text-xs tracking-wider" style={{ textAlign: 'center' }}>{a}</th>)}
            </tr>
          </thead>
          <tbody>
            {RESOURCES.map(res => (
              <tr key={res}>
                <td className="font-medium text-[var(--text-secondary)]">{res}</td>
                {ACTIONS.map(act => {
                  const isNA = !VALID_ACTIONS[res]?.includes(act);

                  if (isNA) {
                    return (
                      <td key={act} className="text-center p-1">
                        <div className="flex items-center justify-center h-8">
                          <span className="text-[10px] text-muted font-bold uppercase tracking-widest opacity-40">N/A</span>
                        </div>
                      </td>
                    );
                  }

                  if (isReadOnly && currentRoleItem) {
                    const local = currentRoleItem.localPermissions?.find(p => p.resource === res && p.action === act);
                    const inherited = getImplicitPerm(res, act);
                    return (
                      <td key={act} className="text-center">
                        <div className="flex flex-col items-center justify-center h-full min-h-[40px]">
                          {local ? (
                            <span 
                              className={`material-symbols-outlined text-[20px] ${local.effect === 'allow' ? 'text-[var(--success)]' : 'text-[var(--danger)]'}`}
                              title={`Explicitly ${local.effect}`}
                            >
                              {local.effect === 'allow' ? 'check_circle' : 'cancel'}
                            </span>
                          ) : inherited ? (
                            <span 
                              className={`material-symbols-outlined text-[20px] opacity-40 hover:opacity-100 transition-opacity cursor-help ${inherited.effect === 'allow' ? 'text-[var(--success)]' : 'text-[var(--danger)]'}`}
                              title={`Inherited ${inherited.effect} from ${inherited.sourceRole}`}
                            >
                              {inherited.effect === 'allow' ? 'check_circle' : 'cancel'}
                            </span>
                          ) : (
                            <span className="text-muted text-xs">-</span>
                          )}
                        </div>
                      </td>
                    );
                  }

                  // Editing state
                  const localVal = formPermissions[res]?.[act] || '';
                  const inheritedVal = getImplicitPerm(res, act);
                  
                  return (
                    <td key={act} className="text-center">
                      <div className="flex flex-col items-center gap-1 justify-center py-1">
                        <select 
                          className="input !py-0.5 !px-1 text-xs h-7 w-[80px] text-center"
                          value={localVal}
                          onChange={(e) => handlePermissionChange(res, act, e.target.value as any)}
                        >
                          <option value="">Unset</option>
                          <option value="allow">Allow</option>
                          <option value="deny">Deny</option>
                        </select>
                        {inheritedVal && !localVal && (
                          <span 
                            className={`material-symbols-outlined text-[16px] opacity-40 ${inheritedVal.effect === 'allow' ? 'text-[var(--success)]' : 'text-[var(--danger)]'}`}
                            title={`Inherited ${inheritedVal.effect} from ${inheritedVal.sourceRole}`}
                          >
                            {inheritedVal.effect === 'allow' ? 'check_circle' : 'cancel'}
                          </span>
                        )}
                      </div>
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  };

  return (
    <DetailsLayout
      header={
        <EntityHeader
          title="Roles & Permissions"
          subtitle="Manage access control policies and inheritance"
          onBack={() => router.push('/admin/users')}
          showPrint={false}
        />
      }
    >
      <div className="flex flex-col gap-6">
        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading !mb-0">
              <span className="material-symbols-outlined">security</span>
              Roles
            </h3>
            <button className="btn btn-primary btn-sm" onClick={startCreate}>+ Create Role</button>
          </div>

          {loading ? (
            <div className="p-6 text-center text-muted">Loading...</div>
          ) : (
            <div className="flex flex-col gap-6">
              {isCreating && (
                <div className="border border-[var(--border)] rounded p-4 bg-[var(--bg-secondary)]">
                  <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-4">
                      <span className="material-symbols-outlined text-muted">badge</span>
                      <input 
                        type="text" 
                        className="input font-medium text-lg w-64" 
                        placeholder="new-role-name" 
                        value={newRoleName}
                        onChange={e => setNewRoleName(e.target.value)}
                        autoFocus
                      />
                    </div>
                    <div className="flex gap-2">
                      <button className="btn btn-secondary btn-sm" onClick={cancel}>Cancel</button>
                      <button className="btn btn-primary btn-sm" onClick={save}>Save Role</button>
                    </div>
                  </div>
                  
                  <div className="mb-4">
                    <label className="label">Inherits From:</label>
                    <div className="flex flex-wrap gap-2 mt-1">
                      {getRoleNames().map(r => (
                        <label key={r} className="flex items-center gap-1 bg-[var(--bg-card)] px-2 py-1 rounded border border-[var(--border)] cursor-pointer hover:border-[var(--accent)]">
                          <input 
                            type="checkbox" 
                            checked={formInherits.includes(r)}
                            onChange={() => handleInheritsToggle(r)}
                          />
                          <span className="text-sm font-medium">{r}</span>
                        </label>
                      ))}
                    </div>
                  </div>

                  {renderMatrix(false)}
                </div>
              )}

              {roles.map(roleItem => (
                <div key={roleItem.role} className="border border-[var(--border)] rounded-xl overflow-hidden flex flex-col bg-white transition-colors">
                  <div 
                    className={`flex items-center justify-between px-5 py-3 hover:bg-[#f8f9fa] cursor-pointer select-none ${expandedRoles[roleItem.role] || editingRole === roleItem.role ? 'border-b border-[rgba(196,198,205,0.4)]' : ''}`}
                    onClick={() => toggleRole(roleItem.role)}
                  >
                    <div className="flex items-center gap-4">
                      <span className={`material-symbols-outlined text-[18px] transition-transform duration-200 text-[var(--accent)] ${expandedRoles[roleItem.role] || editingRole === roleItem.role ? 'rotate-90' : ''}`}>
                        chevron_right
                      </span>
                      <div className="font-bold text-sm text-[#041627] capitalize" style={{ fontFamily: 'Manrope, sans-serif' }}>{roleItem.role}</div>
                      {roleItem.inherits && roleItem.inherits.length > 0 && (
                        <div className="flex items-center gap-1 text-xs text-[var(--text-secondary)]">
                          Inherits: <span className="font-medium">{roleItem.inherits.join(', ')}</span>
                        </div>
                      )}
                    </div>
                    <div className="flex gap-2" onClick={e => e.stopPropagation()}>
                      {editingRole === roleItem.role ? (
                        <>
                          <button className="btn btn-secondary btn-sm" onClick={cancel}>Cancel</button>
                          <button className="btn btn-primary btn-sm" onClick={save}>Save Changes</button>
                        </>
                      ) : (
                        <>
                          <button className="btn btn-secondary btn-sm" onClick={() => startEdit(roleItem)}>Edit</button>
                          {roleItem.role !== 'admin' && roleItem.role !== 'viewer' && roleItem.role !== 'webhook' && roleItem.role !== 'agent' && (
                            <button className="btn btn-secondary btn-sm text-danger" onClick={() => deleteRole(roleItem.role)}>Delete</button>
                          )}
                        </>
                      )}
                    </div>
                  </div>

                  {(expandedRoles[roleItem.role] || editingRole === roleItem.role) && (
                    <div className="p-4">
                      {editingRole === roleItem.role ? (
                        <div className="flex flex-col gap-4">
                          <div>
                            <label className="label">Inherits From:</label>
                            <div className="flex flex-wrap gap-2 mt-1">
                              {getRoleNames().filter(r => r !== roleItem.role).map(r => (
                                <label key={r} className="flex items-center gap-1 bg-[var(--bg-card)] px-2 py-1 rounded border border-[var(--border)] cursor-pointer hover:border-[var(--accent)]">
                                  <input 
                                    type="checkbox" 
                                    checked={formInherits.includes(r)}
                                    onChange={() => handleInheritsToggle(r)}
                                  />
                                  <span className="text-sm font-medium">{r}</span>
                                </label>
                              ))}
                            </div>
                          </div>
                          {renderMatrix(false, roleItem)}
                        </div>
                      ) : (
                        renderMatrix(true, roleItem)
                      )}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </DetailsLayout>
  );
}

'use client';

import { useState, useEffect, useMemo, useCallback } from 'react';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import { useTranslations } from 'next-intl';
import JournalEntrySlideOver, { JournalEntry } from './journal-entries/JournalEntrySlideOver';
import CodesModal from './CodesModal';
import DataGrid from '@/components/DataGrid';
import type { ColDef } from 'ag-grid-community';

interface AccountOption {
  accountCode: string;
  name: string;
}

interface GlEntry {
  journalEntryId: string;
  entryNumber: string;
  entryDate: string;
  entryMemo: string | null;
  sourceType: string;
  sourceId: string | null;
  accountCode: string;
  accountName: string;
  partyType: string | null;
  partyId: string | null;
  debit: string;
  credit: string;
  lineMemo: string | null;
  createdBy: string | null;
  createdOn: string | null;
}

const PAGE_SIZE = 200;

export default function GeneralLedgerContent() {
  const t = useTranslations('gl.generalLedger');
  const tCodes = useTranslations('gl.codes');
  const tCommon = useTranslations('common');
  const tGrid = useTranslations('common.grid');

  function fmt(v: string | number | null | undefined) {
    if (!v) return tCommon('na');
    const n = typeof v === 'string' ? parseFloat(v) : v;
    if (!n || n === 0) return tCommon('na');
    return n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  const [accounts, setAccounts] = useState<AccountOption[]>([]);
  const [accountCode, setAccountCode] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [selectedEntry, setSelectedEntry] = useState<JournalEntry | null>(null);

  // Manual pagination state (so we control it from the header, not the DataGrid overlay)
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [rows, setRows] = useState<GlEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [isCodesOpen, setIsCodesOpen] = useState(false);

  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));

  useEffect(() => {
    api.glControllerGetAccounts({ format: 'flat' })
      .then(res => {
        const data = res.data || [];
        const leafAccounts = data.filter((a: unknown) => !(a as { isGroup: boolean }).isGroup);
        setAccounts(leafAccounts.map((a: unknown) => ({ accountCode: (a as { accountCode: string }).accountCode, name: (a as { name: string }).name })));
      })
      .catch((err) => reportError(err, 'GeneralLedgerPage'));
  }, []);

  // Reset page to 1 when filters change
  useEffect(() => { setPage(1); }, [accountCode, fromDate, toDate]);

  // Fetch GL data
  const fetchData = useCallback(() => {
    setLoading(true);
    const params = new URLSearchParams();
    if (accountCode) params.set('account', accountCode);
    if (fromDate) params.set('fromDate', fromDate);
    if (toDate) params.set('toDate', toDate);
    params.set('page', String(page));
    params.set('limit', String(PAGE_SIZE));
    const qs = params.toString() ? `?${params}` : '';
    api.glControllerGetGeneralLedger({ 
      account: accountCode, 
      fromDate: fromDate, 
      toDate: toDate, 
      page: page.toString(), 
      limit: PAGE_SIZE.toString() 
    })
      .then((res) => {
        const payload = res.data;
        setRows((payload as any).data as unknown as GlEntry[]);
        setTotal((payload as any).total || 0);
      })
      .catch((err) => reportError(err, 'GeneralLedgerContent'))
      .finally(() => setLoading(false));
  }, [accountCode, fromDate, toDate, page]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const columns = useMemo<ColDef[]>(() => [
    { 
      field: 'entryDate', 
      headerName: t('columns.date'), 
      width: 120,
      valueFormatter: (p: any) => p.value ? new Date(p.value).toLocaleDateString() : ''
    },
    { 
      field: 'entryNumber', 
      headerName: t('columns.entryNumber'), 
      width: 140, 
      pinned: 'left',
      cellStyle: { fontWeight: 'bold', color: 'var(--accent)', cursor: 'pointer' }
    },
    {
      field: 'accountCode',
      headerName: t('columns.customer'),
      width: 250,
      cellRenderer: (p: any) => {
        return (
          <span>
            <span className="font-mono text-gray-400 mr-2">{p.value}</span>
            {p.data.accountName}
          </span>
        );
      }
    },
    { 
      field: 'lineMemo', 
      headerName: t('columns.memo'), 
      flex: 1, 
      minWidth: 200,
      valueGetter: (p: any) => p.data.lineMemo || p.data.entryMemo || ''
    },
    { 
      field: 'debit', 
      headerName: t('columns.debit'), 
      width: 120,
      cellClass: 'text-right font-mono',
      valueFormatter: (p: any) => fmt(p.value)
    },
    { 
      field: 'credit', 
      headerName: t('columns.credit'), 
      width: 120,
      cellClass: 'text-right font-mono',
      valueFormatter: (p: any) => fmt(p.value)
    }
  ], [t, tCommon]);

  // We manage data externally, so we feed it directly to DataGrid via fetchAll + a dummy endpoint
  // Actually, we'll bypass DataGrid's own fetching by providing the data externally.
  // Since DataGrid always fetches, we'll use its renderHeader but handle data ourselves.

  return (
    <>
    <DataGrid<GlEntry>
      endpoint={`/api/gl/general-ledger?account=${accountCode}&fromDate=${fromDate}&toDate=${toDate}`}
      columns={columns}
      gridKey="gl-general-ledger"
      exportFileName="general-ledger"
      fetchAll={true}
      onRowClicked={(row) => {
        setSelectedEntry({
          journalEntryId: row.journalEntryId,
          entryNumber: row.entryNumber,
          entryDate: row.entryDate,
          memo: row.entryMemo,
          sourceType: row.sourceType || 'manual',
          sourceId: row.sourceId || null,
          createdBy: row.createdBy || null,
        });
      }}
      pageTitle={t('title')}
      headerFilters={
        <>
          <select
            value={accountCode}
            onChange={(e) => setAccountCode(e.target.value)}
            className="input text-xs h-9 border-gray-200 w-auto min-w-[200px] bg-white rounded-lg"
          >
            <option value="">{t('allAccounts')}</option>
            {accounts.map((a) => (
              <option key={a.accountCode} value={a.accountCode}>
                {a.accountCode} — {a.name}
              </option>
            ))}
          </select>

          <div className="flex items-center gap-3">
            <input
              type="date"
              value={fromDate}
              onChange={(e) => setFromDate(e.target.value)}
              className="input text-xs h-9 border-gray-200 bg-white px-3 text-gray-500 rounded-lg w-auto"
              title={t('fromDate')}
            />
            <span className="text-gray-300 font-bold">→</span>
            <input
              type="date"
              value={toDate}
              onChange={(e) => setToDate(e.target.value)}
              className="input text-xs h-9 border-gray-200 bg-white px-3 text-gray-500 rounded-lg w-auto"
              title={t('toDate')}
            />
          </div>
        </>
      }
      headerActions={
        <button
          onClick={() => setIsCodesOpen(true)}
          className="btn btn-secondary btn-sm whitespace-nowrap"
        >
          {/* eslint-disable-next-line i18next/no-literal-string */}
          <span className="material-symbols-outlined text-sm">visibility</span>
          {/* eslint-enable i18next/no-literal-string */}
          {tCodes('button')}
        </button>
      }
    />

      <JournalEntrySlideOver
        entry={selectedEntry}
        onClose={() => setSelectedEntry(null)}
      />

      <CodesModal 
        isOpen={isCodesOpen}
        onClose={() => setIsCodesOpen(false)}
      />
    </>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import SlideOver from '@/components/shared/SlideOver';
import { useTranslations } from 'next-intl';
import Link from 'next/link';

export interface JournalEntry {
  journalEntryId: string;
  entryNumber: string;
  entryDate: string;
  memo: string | null;
  sourceType: string;
  sourceId: string | null;
  createdBy: string | null;
}

export interface JournalLine {
  journalLineId: string;
  accountCode?: string;
  accountName?: string;
  partyType?: string | null;
  partyId?: string | null;
  partyName?: string | null;
  debit: string;
  credit: string;
  memo: string | null;
}

interface JournalEntrySlideOverProps {
  entry: JournalEntry | null;
  onClose: () => void;
}

export default function JournalEntrySlideOver({ entry, onClose }: JournalEntrySlideOverProps) {
  const t = useTranslations('gl.journalEntries');
  const tCommon = useTranslations('common');

  function fmt(v: string | number) {
    const n = typeof v === 'string' ? parseFloat(v) : v;
    if (!n || n === 0) return tCommon('na');
    return n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  const [lines, setLines] = useState<JournalLine[]>([]);
  const [loading, setLoading] = useState(false);

  const sourceLabel = (type: string) => {
    const labels: Record<string, string> = {
      sales_invoice: t('sourceSalesInvoice'),
      purchase_invoice: t('sourcePurchaseInvoice'),
      sales_credit_note: t('sourceSalesCreditNote'),
      manual: t('sourceManual'),
    };
    return labels[type] || type;
  };

  useEffect(() => {
    if (!entry) {
      setLines([]);
      return;
    }

    setLoading(true);
    api.glControllerGetJournalEntry(entry.journalEntryId)
      .then((res) => {
        const detail = res.data as any;
        setLines(detail.lines || []);
      })
      .catch((err) => reportError(err, 'JournalEntrySlideOver'))
      .finally(() => setLoading(false));
  }, [entry]);

  return (
    <SlideOver
      isOpen={!!entry}
      onClose={onClose}
      title={entry ? entry.entryNumber : t('title')}
      subtitle={entry ? `${new Date(entry.entryDate).toLocaleDateString()} · ${sourceLabel(entry.sourceType)}` : undefined}
      width="max-w-3xl"
    >
      {entry && (
        <div className="space-y-6">
          <div className="card space-y-5">
            <div className="flex flex-col gap-5 text-sm">
              <div>
                <span className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">{t('columns.memo')}</span>
                <span className="text-[#041627]">{entry.memo || tCommon('na')}</span>
              </div>
              <div>
                <span className="block text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">{t('sourceDocument')}</span>
                {entry.sourceId && (entry.sourceType === 'sales_invoice' || entry.sourceType === 'sales_credit_note') ? (
                  <Link 
                    href={`/sales-orders/${entry.sourceId}${entry.sourceType === 'sales_invoice' ? '#invoices-section' : ''}`} 
                    className="text-[var(--accent)] hover:underline"
                    onClick={onClose}
                  >
                    {sourceLabel(entry.sourceType)}
                  </Link>
                ) : (
                  <span className="text-[#041627]">{sourceLabel(entry.sourceType)}</span>
                )}
              </div>
            </div>
          </div>

          <div className="rounded-xl border border-gray-200 overflow-hidden bg-white">
            {loading ? (
              <div className="flex justify-center items-center py-12">
                {/* eslint-disable-next-line i18next/no-literal-string */}
                <span className="loading loading-spinner text-gray-400"></span>
              </div>
            ) : (
              <table className="w-full text-sm text-left">
                <thead className="bg-[#f8f9fa] border-b border-gray-200 text-[#041627] font-semibold text-xs uppercase tracking-wider">
                  <tr>
                    <th className="px-5 py-3">{t('columns.customer')}</th>
                    <th className="px-5 py-3">{t('columns.party')}</th>
                    <th className="px-5 py-3 text-right">{t('columns.debit')}</th>
                    <th className="px-5 py-3 text-right">{t('columns.credit')}</th>
                    <th className="px-5 py-3">{t('columns.memo')}</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {lines.map((l) => (
                    <tr key={l.journalLineId} className="hover:bg-gray-50/50 transition-colors">
                      <td className="px-5 py-3">
                        <div className="font-mono text-xs text-gray-500">{l.accountCode}</div>
                        <div className="font-semibold text-[#041627] mt-0.5">{l.accountName}</div>
                      </td>
                      <td className="px-5 py-3 text-xs">
                        {l.partyType && l.partyId ? (
                          <Link 
                            href={`/${l.partyType === 'customer' ? 'accounts' : 'suppliers'}/${l.partyId}`}
                            className="text-[var(--accent)] hover:underline"
                            onClick={onClose}
                          >
                            {l.partyName || (l.partyId ? `${l.partyType}: ${l.partyId.substring(0, 8)}...` : l.partyType)}
                          </Link>
                        ) : l.partyType ? (
                          <span className="text-gray-600">
                            {l.partyType}: {l.partyId?.substring(0, 8)}...
                          </span>
                        ) : tCommon('na')}
                      </td>
                      <td className="px-5 py-3 text-right font-mono font-medium text-[#041627]">
                        {fmt(l.debit)}
                      </td>
                      <td className="px-5 py-3 text-right font-mono font-medium text-[#041627]">
                        {fmt(l.credit)}
                      </td>
                      <td className="px-5 py-3 text-gray-500 text-xs">
                        {l.memo || tCommon('na')}
                      </td>
                    </tr>
                  ))}
                  {/* Totals Row */}
                  {lines.length > 0 && (
                    <tr className="bg-[#f8f9fa] border-t-2 border-gray-200">
                      <td colSpan={2} className="px-5 py-3 text-right font-bold text-[#041627] text-xs uppercase tracking-wider">
                        {t('total')}
                      </td>
                      <td className="px-5 py-3 text-right font-mono font-bold text-[#041627]">
                        {fmt(lines.reduce((s, l) => s + parseFloat(l.debit || '0'), 0))}
                      </td>
                      <td className="px-5 py-3 text-right font-mono font-bold text-[#041627]">
                        {fmt(lines.reduce((s, l) => s + parseFloat(l.credit || '0'), 0))}
                      </td>
                      <td></td>
                    </tr>
                  )}
                </tbody>
              </table>
            )}
            {!loading && lines.length === 0 && (
              <div className="p-8 text-center text-gray-500 text-sm">
                {t('noLines')}
              </div>
            )}
          </div>
        </div>
      )}
    </SlideOver>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import MasterDetailLayout from '@/components/shared/MasterDetailLayout';
import * as api from '@modbm/sdk';
import { reportError } from '@/lib/api';
import toast from 'react-hot-toast';

export default function BankMatchingView({ 
  reconciliation, 
  onUpdate 
}: { 
  reconciliation: any, 
  onUpdate: () => void 
}) {
  const [bankLines, setBankLines] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedLineId, setSelectedLineId] = useState<string | null>(null);
  const [confirming, setConfirming] = useState(false);

  useEffect(() => {
    fetchBankLines();
  }, [reconciliation.accountId]);

  const fetchBankLines = async () => {
    try {
      setLoading(true);
      const res = await api.bankStatementControllerGetLines({
        glAccountId: reconciliation.accountId,
        isReconciled: false,
      });
      setBankLines((res as any).data);
    } catch (e) {
      reportError(e, 'BankLines');
    } finally {
      setLoading(false);
    }
  };

  const confirmMatch = async (lineId: string) => {
    try {
      setConfirming(true);
      await api.bankStatementControllerConfirmMatch(lineId, {});
      toast.success('Match confirmed');
      await fetchBankLines();
      onUpdate();
      if (selectedLineId === lineId) setSelectedLineId(null);
    } catch (e) {
      reportError(e, 'ConfirmMatch');
      toast.error('Failed to confirm match');
    } finally {
      setConfirming(false);
    }
  };

  const selectedLine = bankLines.find(l => l.lineId === selectedLineId);
  const formatCurrency = (val: number | string) => new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(Number(val));

  const masterPane = (
    <div className="flex flex-col h-full overflow-y-auto bg-[var(--bg-primary)]">
      {loading ? (
        <div className="p-8 text-center text-[var(--text-secondary)]">Loading bank lines...</div>
      ) : bankLines.length === 0 ? (
        <div className="p-8 text-center flex flex-col items-center justify-center h-full">
          {/* eslint-disable-next-line i18next/no-literal-string */}
          <span className="material-symbols-outlined text-4xl text-[var(--text-muted)] mb-3">check_circle</span>
          <p className="text-[var(--text-secondary)] font-medium">All bank statement lines are matched!</p>
        </div>
      ) : (
        <div className="flex flex-col divide-y divide-[var(--border)]">
          {bankLines.map(line => {
            const isSuggested = !!line.matchedJournalLineId;
            const isSelected = selectedLineId === line.lineId;
            const isDeposit = Number(line.amount) > 0;
            
            return (
              <div 
                key={line.lineId}
                onClick={() => setSelectedLineId(line.lineId)}
                className={`p-4 cursor-pointer transition-all ${
                  isSelected 
                    ? 'bg-[#f8fbfd] border-l-4 border-l-[var(--brand-blue)]' 
                    : 'hover:bg-[var(--bg-card-hover)] border-l-4 border-l-transparent bg-[var(--bg-card)]'
                }`}
              >
                <div className="flex justify-between items-start mb-1.5">
                  <span className="text-xs font-bold text-[var(--text-muted)]">{line.date}</span>
                  <span className={`text-sm font-bold ${isDeposit ? 'text-[var(--success)]' : 'text-[var(--text-primary)]'}`}>
                    {formatCurrency(line.amount)}
                  </span>
                </div>
                <div className="text-sm text-[var(--text-primary)] font-medium line-clamp-2 mb-3 leading-snug">
                  {line.description}
                </div>
                
                {isSuggested ? (
                  <div className="inline-flex items-center gap-1.5 px-2 py-1 rounded-md bg-emerald-50 text-[var(--success)] border border-emerald-200">
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined text-[14px]">auto_awesome</span>
                    <span className="text-[10px] font-bold uppercase tracking-wider">Suggested Match</span>
                  </div>
                ) : (
                  <div className="inline-flex items-center gap-1.5 px-2 py-1 rounded-md bg-gray-100 text-[var(--text-muted)] border border-gray-200">
                    <span className="text-[10px] font-bold uppercase tracking-wider">Unmatched</span>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );

  const detailPane = (
    <div className="flex flex-col h-full bg-[#fafbfc]">
      {!selectedLine ? (
        <div className="flex flex-col items-center justify-center h-full text-[var(--text-muted)] p-8">
          {/* eslint-disable-next-line i18next/no-literal-string */}
          <span className="material-symbols-outlined text-5xl mb-4 opacity-50">account_balance</span>
          <p className="text-sm font-medium text-center">Select a bank line from the list to view details or apply a match.</p>
        </div>
      ) : (
        <div className="flex flex-col h-full">
          {/* Top Half: Bank Statement Line Details */}
          <div className="p-6 bg-[var(--bg-card)] border-b border-[var(--border)] shadow-sm z-10">
            <h3 className="text-xs font-bold uppercase tracking-wider text-[var(--text-muted)] mb-4">Bank Statement Line</h3>
            <div className="flex justify-between items-start">
              <div className="flex flex-col gap-1">
                <span className="text-2xl font-bold text-[var(--text-primary)]" style={{ fontFamily: 'Manrope, sans-serif' }}>
                  {formatCurrency(selectedLine.amount)}
                </span>
                <span className="text-sm text-[var(--text-secondary)]">{selectedLine.date}</span>
              </div>
              {Number(selectedLine.amount) > 0 ? (
                <span className="px-2.5 py-1 rounded-full bg-emerald-100 text-[var(--success)] text-xs font-bold">Deposit</span>
              ) : (
                <span className="px-2.5 py-1 rounded-full bg-gray-100 text-[var(--text-secondary)] text-xs font-bold">Withdrawal</span>
              )}
            </div>
            <div className="mt-4 p-3 bg-[#f8fbfd] rounded-lg border border-blue-100/50">
              <p className="text-sm text-[var(--brand-navy)] font-medium leading-relaxed">{selectedLine.description}</p>
            </div>
          </div>

          {/* Bottom Half: System Match or Fallback */}
          <div className="flex-1 overflow-y-auto p-6">
            {selectedLine.matchedJournalLine ? (
              <div className="flex flex-col animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="flex items-center gap-2 mb-4">
                  {/* eslint-disable-next-line i18next/no-literal-string */}
                  <span className="material-symbols-outlined text-[var(--success)]">check_circle</span>
                  <h3 className="text-sm font-bold text-[var(--text-primary)]">System Match Found</h3>
                </div>
                
                <div className="bg-white border-2 border-emerald-200 rounded-xl p-5 shadow-sm relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-50 rounded-bl-full -mr-4 -mt-4 opacity-50 pointer-events-none" />
                  
                  <div className="flex justify-between items-center mb-4 relative z-10">
                    <span className="text-xs font-bold uppercase tracking-wider text-[var(--text-muted)]">Journal Entry</span>
                    <span className="text-sm text-[var(--text-secondary)]">{selectedLine.matchedJournalLine.entryDate}</span>
                  </div>
                  
                  <p className="text-base font-medium text-[var(--text-primary)] mb-6 relative z-10">
                    {selectedLine.matchedJournalLine.memo || 'No memo provided'}
                  </p>
                  
                  <div className="flex justify-between items-end relative z-10 mb-6 pb-6 border-b border-gray-100">
                    <span className="text-sm text-[var(--text-muted)] font-medium">Ledger Amount</span>
                    <span className="text-xl font-bold text-[var(--text-primary)]">
                      {formatCurrency(Number(selectedLine.matchedJournalLine.debit) || -Number(selectedLine.matchedJournalLine.credit))}
                    </span>
                  </div>
                  
                  <button 
                    onClick={() => confirmMatch(selectedLine.lineId)}
                    disabled={confirming}
                    className="w-full py-3 bg-[var(--accent)] text-white font-bold rounded-lg hover:brightness-110 shadow-md hover:shadow-lg transition-all flex items-center justify-center gap-2 disabled:opacity-50"
                  >
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined text-[18px]">done_all</span>
                    {confirming ? 'Confirming...' : 'Confirm Match'}
                  </button>
                </div>
              </div>
            ) : (
              <div className="flex flex-col h-full animate-in fade-in slide-in-from-bottom-4 duration-300">
                <h3 className="text-xs font-bold uppercase tracking-wider text-[var(--text-muted)] mb-4">Reconciliation Actions</h3>
                
                <div className="flex-1 bg-white border border-[var(--border)] rounded-xl shadow-sm overflow-hidden flex flex-col">
                  <div className="flex border-b border-[var(--border)] bg-gray-50/50">
                    <button className="flex-1 py-3 text-sm font-bold border-b-2 border-[var(--brand-blue)] text-[var(--brand-blue)] transition-colors">
                      Find Match
                    </button>
                    <button className="flex-1 py-3 text-sm font-bold text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors border-b-2 border-transparent hover:bg-gray-50">
                      Create Entry
                    </button>
                  </div>
                  
                  <div className="flex-1 p-8 flex flex-col items-center justify-center text-center">
                    <div className="w-16 h-16 bg-[#f8fbfd] rounded-full flex items-center justify-center mb-4">
                      {/* eslint-disable-next-line i18next/no-literal-string */}
                      <span className="material-symbols-outlined text-3xl text-[var(--brand-blue)]">search</span>
                    </div>
                    <h4 className="text-base font-bold text-[var(--text-primary)] mb-2">No Automatic Match Found</h4>
                    <p className="text-sm text-[var(--text-secondary)] max-w-xs leading-relaxed">
                      Search for an existing transaction in your ledger, or create a new journal entry to reconcile this bank line.
                    </p>
                    <button className="mt-6 px-5 py-2 bg-white border border-[var(--border)] text-[var(--brand-blue)] font-bold rounded-lg hover:bg-gray-50 transition-colors shadow-sm text-sm">
                      Search Ledger
                    </button>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );

  return (
    <div className="h-full w-full">
      <MasterDetailLayout
        title=""
        isDetailOpen={!!selectedLineId}
        onCloseDetail={() => setSelectedLineId(null)}
        masterPane={masterPane}
        detailPane={detailPane}
        masterWidthClass="lg:w-[380px] shrink-0"
      />
    </div>
  );
}

