source:
'use client';

import { use, useMemo } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { calculateAvailableQuantity, PURCHASE_ORDER_STATE } from '@modbm/shared';
import ProductSearchInput from '@/components/shared/ProductSearchInput';
import ActivityTimeline from '@/components/shared/ActivityTimeline';
import { formatAmount } from '@/lib/currency';
import { calculateUomPriceAdjustment } from '@modbm/shared';
import type { ProductUom } from '@modbm/shared';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import PageNav from '@/components/shared/PageNav';
import LocationSelect from '@/components/shared/LocationSelect';
import { DataTable, MobileCardField, DataTableColumn } from '@/components/shared/DataTable';

import type { TaxCategory } from './types';
import { getTaxLabel } from './types';
import InvoicesSection from './InvoicesSection';
import AllocationsSection from './AllocationsSection';
import ReceptionsSection from './ReceptionsSection';
import ReturnsSection from './ReturnsSection';
import { usePurchaseOrder } from './usePurchaseOrder';

import StateBadge from '@/components/StateBadge';
import { ValidState } from '@/types/states';

function TaxLabel({ category }: { category: TaxCategory }) {
  if (!category) return null;
  return <>{getTaxLabel(category)}</>;
}

export default function OrderDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const router = useRouter();
  const tCommon = useTranslations('common');
  const tPurchase = useTranslations('purchaseOrders');
  const tToast = useTranslations('toast');

  const o = usePurchaseOrder(id);


  const { order, loading, error, saving, copying, latestAutoTransition,
    isHeaderEditable, isLinesEditable, visibleTransitions, subtotal, totalTax,
    editName, setEditName, editReferenceNumber, setEditReferenceNumber,
    editNotes, setEditNotes, editLocationId, setEditLocationId, headerDirty,
    taxCategories, activeTab, setActiveTab, inventoryData, inventoryLoading,
    invoices, setInvoicing,
    clearError, setError, saveHeader, changeState, copyOrder,
    updateLine, updateLineFields, removeLine, addLineFromProduct, addBlankLine,
    loadOrder, loadInvoices, loadAllocations, allocations, allocationsLoading,
  } = o;

  useDocumentTitle(order ? (order.name ? `${order.orderNumber} - ${order.name}` : order.orderNumber) : null);



  const sections = {
    details: { id: 'details-section', label: 'Details', show: true },
    allocations: { id: 'allocations-section', label: 'Allocations', show: true },
    receptions: { id: 'receptions-section', label: 'Receptions', show: true },
    invoices: { id: 'Invoices-section', label: 'Invoices', show: true },
    activity: { id: 'activity-section', label: 'Activity', show: true },
  };
  const visibleSections = Object.values(sections).filter(s => s.show);

  const lineColumns: DataTableColumn<any>[] = useMemo(() => [
    {
        header: tPurchase('columns.lineNumber'), width: 40,
        render: (line: any) => <span className="text-slate-500 font-medium">#{line.lineNumber}</span>,
        mobileCard: (line: any) => null
    },
    {
        header: tPurchase('columns.product'),
        render: (line: any) => (
            <div className="font-semibold text-sm">
                {line.productId && line.productId !== '00000000-0000-0000-0000-000000000000' ? (
                    <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                        {line.productNumber || line.productId?.substring(0, 8)}
                    </Link>
                ) : (
                    line.productNumber || line.productId?.substring(0, 8) || '—'
                )}
            </div>
        )
    },
    {
        header: tPurchase('columns.description'),
        render: (line: any) => (
            (!line.productId || line.productId === '00000000-0000-0000-0000-000000000000') && isLinesEditable ? (
                <input
                    className="input w-full text-sm h-8"
                    defaultValue={line.productDescription || ''}
                    key={`desc-${line.purchaseOrderLineId}-${line.productDescription}`}
                    onBlur={(e) => {
                        if (e.target.value !== (line.productDescription || '')) {
                            updateLine(line.purchaseOrderLineId, 'productDescription', e.target.value);
                        }
                    }}
                    placeholder="Custom description..."
                />
            ) : (
                <span className="text-sm">{line.productDescription || '—'}</span>
            )
        )
    },
    {
        header: tPurchase('columns.qty'), width: 90, align: 'right',
        render: (line: any) => (
            isLinesEditable ? (
                <input
                    className="input text-right w-full h-8 text-sm"
                    type="number"
                    min="0"
                    step="1"
                    defaultValue={line.quantity}
                    key={`qty-${line.purchaseOrderLineId}-${line.quantity}`}
                    onBlur={(e) => {
                        if (e.target.value !== line.quantity) {
                            updateLine(line.purchaseOrderLineId, 'quantity', e.target.value);
                        }
                    }}
                />
            ) : <span className="text-sm tabular-nums">{line.quantity}</span>
        ),
        mobileCard: (line: any, defaultRender: any) => <MobileCardField label={tPurchase('columns.qty')} value={
            isLinesEditable ? defaultRender : <span className="text-sm">{line.quantity} {line.unitOfMeasure || line.baseUom || 'EA'}</span>
        } />
    },
    {
        header: tPurchase('columns.uom'), width: 80, align: 'right',
        render: (line: any) => {
            if (!isLinesEditable) return <span className="text-sm tabular-nums">{line.unitOfMeasure || line.baseUom || 'EA'}</span>;
            const uoms: ProductUom[] = line.productUoms || [];
            const defaultUom = line.baseUom || 'EA';
            const selectOptions = uoms.length > 0 ? uoms : [{ uomCode: defaultUom, ratio: 1 }];
            return (
                <select
                    className="input w-full h-8 text-sm text-right"
                    value={line.unitOfMeasure || defaultUom}
                    onChange={(e) => {
                        const newVal = e.target.value;
                        const oldVal = line.unitOfMeasure || defaultUom;
                        if (newVal !== oldVal) {
                            const oldO = selectOptions.find(o => o.uomCode === oldVal);
                            const oldRatio = typeof oldO?.ratio === 'string' ? parseFloat(oldO.ratio) : (oldO?.ratio || 1);
                            const newO = selectOptions.find(o => o.uomCode === newVal);
                            const newRatio = typeof newO?.ratio === 'string' ? parseFloat(newO.ratio) : (newO?.ratio || 1);
                            const newPrice = calculateUomPriceAdjustment(line.pricePerUnit || 0, oldRatio, newRatio);
                            updateLineFields(line.purchaseOrderLineId, {
                                unitOfMeasure: newVal,
                                pricePerUnit: isNaN(newPrice) ? '0.00' : newPrice.toFixed(2)
                            });
                        }
                    }}
                >
                    {selectOptions.map(o => (
                        <option key={o.uomCode} value={o.uomCode}>{o.uomCode}</option>
                    ))}
                </select>
            );
        },
        mobileCard: () => null
    },
    {
        header: tPurchase('columns.unitPrice'), width: 110, align: 'right',
        render: (line: any) => (
            isLinesEditable ? (
                <input
                    className="input text-right w-full h-8 text-sm tabular-nums"
                    type="number"
                    min="0"
                    step="0.01"
                    defaultValue={parseFloat(line.pricePerUnit || '0').toFixed(2)}
                    key={`price-${line.purchaseOrderLineId}-${line.pricePerUnit}`}
                    onBlur={(e) => {
                        const val = parseFloat(e.target.value);
                        const formatted = isNaN(val) ? '0.00' : val.toFixed(2);
                        e.target.value = formatted;
                        if (formatted !== parseFloat(line.pricePerUnit || '0').toFixed(2)) {
                            updateLine(line.purchaseOrderLineId, 'pricePerUnit', formatted);
                        }
                    }}
                />
            ) : <span className="text-sm tabular-nums">{formatAmount(parseFloat(line.pricePerUnit || '0'), order?.currencyCode || 'EUR')}</span>
        ),
        mobileCard: (line: any, defaultRender: any) => <MobileCardField label={tPurchase('columns.unitPrice')} value={defaultRender} />
    },
    {
        header: tPurchase('columns.discountPct' ), width: 80, align: 'right',
        render: (line: any) => (
            isLinesEditable ? (
                <input
                    className="input text-right w-full h-8 text-sm tabular-nums"
                    type="number"
                    min="0"
                    max="100"
                    step="0.1"
                    defaultValue={line.discountPercentage}
                    key={`disc-${line.purchaseOrderLineId}-${line.discountPercentage}`}
                    onBlur={(e) => {
                        if (e.target.value !== line.discountPercentage) {
                            updateLine(line.purchaseOrderLineId, 'discountPercentage', e.target.value);
                        }
                    }}
                />
            ) : <span className="text-sm tabular-nums">{parseFloat(line.discountPercentage || '0').toFixed(1)}%</span>
        ),
        mobileCard: (line: any, defaultRender: any) => (
            isLinesEditable ? (
                <MobileCardField label={tPurchase('columns.discountPct')} value={defaultRender} />
            ) : null
        )
    },
    {
        header: tPurchase('columns.tax'), width: 110, align: 'right',
        render: (line: any) => (
            isLinesEditable ? (
                <select
                    className="input w-full h-8 text-sm text-right"
                    value={line.taxCategoryId || ''}
                    onChange={(e) => updateLine(line.purchaseOrderLineId, 'taxCategoryId', e.target.value)}
                >
                    {taxCategories.map((c) => (
                        <option key={c.taxCategoryId} value={c.taxCategoryId}>
                            <TaxLabel category={c} />
                        </option>
                    ))}
                </select>
            ) : (
                <span className="text-sm tabular-nums text-right block">
                    {(() => {
                        const c = taxCategories.find((cat) => cat.taxCategoryId === line.taxCategoryId);
                        if (c) {
                            const pct = parseFloat(c.rate || '0');
                            const formattedPct = pct % 1 === 0 ? pct.toFixed(0) : pct.toString();
                            return <span title={`Tax Category: ${c.title}`} style={{ cursor: 'help', borderBottom: '1px dotted var(--text-muted)' }}>{formattedPct}%</span>;
                        }
                        const amt = parseFloat(line.amount || '0');
                        const tax = parseFloat(line.tax || '0');
                        if (amt > 0 && tax > 0) {
                            const pct = (tax / amt) * 100;
                            return <span title="Tax Category: Custom" style={{ cursor: 'help', borderBottom: '1px dotted var(--text-muted)' }}>{`${pct % 1 === 0 ? pct.toFixed(0) : pct.toFixed(1)}%`}</span>;
                        }
                        if (amt > 0 && tax === 0) return <span title={tCommon('taxLabels.exempt')} style={{ cursor: 'help', borderBottom: '1px dotted var(--text-muted)' }}>0%</span>;
                        return '—';
                    })()}
                </span>
            )
        ),
        mobileCard: (line: any, defaultRender: any) => <MobileCardField label={tPurchase('columns.tax')} value={defaultRender} />
    },
    {
        header: tPurchase('columns.amount'), width: 110, align: 'right',
        render: (line: any) => (
            <span className="font-bold tabular-nums">
                {formatAmount(parseFloat(line.amount || '0'), order?.currencyCode || 'EUR')}
            </span>
        ),
        mobileCard: (line: any, defaultRender: any) => <MobileCardField label={tPurchase('columns.amount')} value={
            <span className="font-bold text-[var(--accent)] text-base">{formatAmount(parseFloat(line.amount || '0'), order?.currencyCode || 'EUR')}</span>
        } />
    },
    ...(isLinesEditable ? [{
        header: '', width: 50,
        render: (line: any) => (
            <button
                className="btn btn-danger btn-sm"
                onClick={() => removeLine(line.purchaseOrderLineId)}
                title="Remove line"
            >
                <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} />
            </button>
        ),
        mobileCard: (line: any) => (
            <div className="flex justify-end mt-2">
                <button
                    className="btn btn-danger btn-sm"
                    onClick={() => removeLine(line.purchaseOrderLineId)}
                >
                    <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} /> {tCommon('buttons.remove')}
                </button>
            </div>
        )
    }] : [])
  ], [tPurchase, isLinesEditable, order?.currencyCode, taxCategories, updateLine, removeLine, updateLineFields, tCommon]);

  if (loading) {
    return (
      <>
        <div className="flex items-center justify-center flex-1">
          <p style={{ color: 'var(--text-muted)' }}>{tCommon('loading')}</p>
        </div>
      </>
    );
  }

  if (!order) {
    return (
      <>
        <div className="flex flex-col items-center justify-center flex-1">
          <p className="text-lg mb-2" style={{ color: 'var(--danger)' }}>
            {error || tPurchase('orderNotFound')}
          </p>
          <button className="btn btn-secondary" onClick={() => router.push('/purchase-orders')}>
            {tPurchase('backToOrders')}
          </button>
        </div>
      </>
    );
  }

  return (
    <>
      <DetailsLayout
        header={
          <EntityHeader
            title={order.orderNumber}
            subtitle={order.name || tPurchase('untitledOrder')}
            onBack={() => {
              if (window.history.length > 1) {
                router.back();
              } else {
                router.push('/purchase-orders');
              }
            }}
            isSaving={saving}
            badges={<StateBadge state={order.stateCode as ValidState} />}
            nav={<PageNav sections={visibleSections} />}
            actions={
              <>

                {visibleTransitions.map((t) => (
                  <button
                    key={t.state}
                    className={`btn btn-sm ${t.isDanger ? 'btn-danger' : t.isBack ? 'btn-secondary' : 'btn-primary'}`}
                    onClick={() => changeState(t.state)}
                  >
                    {t.icon === 'close' ? (
                      <>
                        {/* eslint-disable-next-line i18next/no-literal-string */}
                        <span className="material-symbols-outlined mr-1" style={{ fontSize: 16 }}>close</span>
                        {/* eslint-enable i18next/no-literal-string */}
                      </>
                    ) : (
                      t.icon
                    )}
                    {t.label}
                  </button>
                ))}
              </>
            }
          />
        }
      >
      <div className="flex flex-col gap-3">

      {error && (
        <div
          className="px-4 py-3 rounded-lg text-sm"
          style={{
            background: 'rgba(239, 68, 68, 0.1)',
            border: '1px solid rgba(239, 68, 68, 0.3)',
            color: '#f87171',
          }}
        >
          {error}
          <button className="ml-3 text-xs underline" onClick={clearError}>{tCommon('dismiss')}</button>
        </div>
      )}

          {/* Order info card */}
          <div id="details-section" className="card">
            <div className="flex justify-between items-center mb-4">
              <h3 className="section-heading">
                {/* eslint-disable-next-line i18next/no-literal-string */}
                <span className="material-symbols-outlined">receipt_long</span>
                {tPurchase('orderDetails')}
              </h3>
              <button
                className="btn btn-secondary btn-sm"
                onClick={copyOrder}
                disabled={copying}
              >
                {copying ? tCommon('copying') : tPurchase('buttons.copyOrder')}
              </button>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tPurchase('labels.supplier')}
                    {order.currencyCode && (
                      <span
                        style={{
                          marginLeft: 8,
                          padding: '1px 6px',
                          borderRadius: 4,
                          background: 'rgba(59,130,246,0.15)',
                          color: 'var(--accent)',
                          fontWeight: 600,
                          fontSize: 10,
                          letterSpacing: '0.04em',
                        }}
                      >
                        {order.currencyCode}
                      </span>
                    )}
                  </label>
                  <div className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                    {order.vendorId ? (
                      <Link href={`/suppliers/${order.vendorId}`} className="text-[var(--accent)] hover:underline">
                        {order.vendorName || order.vendorId}
                      </Link>
                    ) : (
                      order.vendorName || '—'
                    )}
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tPurchase('labels.referenceNumber')}
                  </label>
                  <input
                    className="input"
                    value={editReferenceNumber}
                    onChange={(e) => setEditReferenceNumber(e.target.value)}
                    onBlur={saveHeader}
                    disabled={!isHeaderEditable}
                    placeholder={tPurchase('placeholders.referenceNumber')}
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tPurchase('labels.orderName')}
                  </label>
                  <input
                    className="input"
                    value={editName}
                    onChange={(e) => setEditName(e.target.value)}
                    onBlur={saveHeader}
                    disabled={!isHeaderEditable}
                    placeholder={tPurchase('placeholders.orderName')}
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tPurchase('labels.created')}
                  </label>
                  <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                    {new Date(order.createdOn).toLocaleString()} {tCommon('by')} {order.createdBy || '—'}
                  </p>
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tPurchase('labels.location')}
                  </label>
                  {isHeaderEditable && order.stateCode === PURCHASE_ORDER_STATE.DRAFT ? (
                    <LocationSelect
                      value={editLocationId || ''}
                      onChange={(loc) => setEditLocationId(loc)}
                      className="text-sm"
                    />
                  ) : (
                    <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                      {order.locationName || order.deliveryLocationId || '—'}
                    </p>
                  )}
                </div>
                <div className="hidden lg:block">
                   {/* notes pushed to full width if needed, or matched next column */}
                </div>
                <div className="lg:col-span-2">
                  <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                    {tCommon('notesCardHeading')}
                  </label>
                  <input
                    className="input w-full"
                    value={editNotes}
                    onChange={(e) => setEditNotes(e.target.value)}
                    onBlur={saveHeader}
                    disabled={!isHeaderEditable}
                    placeholder={tCommon('notesCardPlaceholder')}
                  />
                </div>
              </div>
          </div>

        {/* Line items / Availability tabs */}
        <div id="lines-section" className="card">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 mb-4">
            <div className="flex overflow-x-auto w-full lg:w-auto pb-1 lg:pb-0">
              <div className="flex gap-0 min-w-max">
                <button
                className="text-xs font-medium px-3 py-1.5 rounded-l-lg"
                style={{
                  color: activeTab === 'lines' ? 'var(--accent)' : 'var(--text-muted)',
                  background: activeTab === 'lines' ? 'rgba(59,130,246,0.1)' : 'transparent',
                  border: '1px solid',
                  borderColor: activeTab === 'lines' ? 'rgba(59,130,246,0.3)' : 'var(--border)',
                  cursor: 'pointer',
                }}
                onClick={() => setActiveTab('lines')}
              >
                {tPurchase('lineItems')}
              </button>
              <button
                className={`text-xs font-medium px-3 py-1.5 ${order.stateCode !== PURCHASE_ORDER_STATE.DRAFT ? '' : 'rounded-r-lg'}`}
                style={{
                  color: activeTab === 'availability' ? 'var(--accent)' : 'var(--text-muted)',
                  background: activeTab === 'availability' ? 'rgba(59,130,246,0.1)' : 'transparent',
                  border: '1px solid',
                  borderColor: activeTab === 'availability' ? 'rgba(59,130,246,0.3)' : 'var(--border)',
                  borderLeft: activeTab === 'availability' ? '1px solid rgba(59,130,246,0.3)' : 'none',
                  cursor: 'pointer',
                }}
                onClick={() => setActiveTab('availability')}
              >
                {tPurchase('availability')}
              </button>
              {order.stateCode !== PURCHASE_ORDER_STATE.DRAFT && (
                <button
                  className="text-xs font-medium px-3 py-1.5 rounded-r-lg"
                  style={{
                    color: activeTab === 'status' ? 'var(--accent)' : 'var(--text-muted)',
                    background: activeTab === 'status' ? 'rgba(59,130,246,0.1)' : 'transparent',
                    border: '1px solid',
                    borderColor: activeTab === 'status' ? 'rgba(59,130,246,0.3)' : 'var(--border)',
                    borderLeft: activeTab === 'status' ? '1px solid rgba(59,130,246,0.3)' : 'none',
                    cursor: 'pointer',
                  }}
                  onClick={() => setActiveTab('status')}
                >
                  {tPurchase('statusTab')}
                </button>
              )}
              </div>
            </div>
            {isLinesEditable && activeTab === 'lines' && (
              <div className="flex flex-wrap items-center gap-2 w-full lg:w-auto justify-start lg:justify-end">
                <div className="flex-1 min-w-[200px] max-w-sm">
                  <ProductSearchInput
                    onSelect={addLineFromProduct}
                    placeholder="Add product… (search)"
                    style={{ width: '100%' }}
                  />
                </div>
                <button
                  className="btn btn-secondary btn-sm whitespace-nowrap"
                  onClick={addBlankLine}
                  disabled={saving}
                >
                  + {tPurchase('buttons.customLine')}
                </button>
              </div>
            )}
          </div>

          {activeTab === 'lines' ? (
            <DataTable
              data={order.lines}
              keyExtractor={(line) => line.purchaseOrderLineId}
              columns={lineColumns}
              mobileCard={(line: any) => {
                const isAmountCol = (colHeader: any) => colHeader === tPurchase('columns.amount');
                const actionCol = lineColumns.length > 9 ? lineColumns[9].render?.(line, 0) : null;
                return (
                  <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col">
                    <div className="flex justify-between items-start gap-2 mb-2">
                      <div className="font-semibold text-sm text-[var(--accent)]">
                        {lineColumns[1].render?.(line, 0)}
                      </div>
                      <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">#{line.lineNumber}</div>
                    </div>
                    <div className="text-sm text-slate-600 font-medium mb-3 [&_.input]:w-full [&_.input]:text-sm [&_.input]:h-8 [&_.input]:!py-1">
                      {lineColumns[2].render?.(line, 0)}
                    </div>
                    <div className="flex flex-col gap-0 border-t border-slate-100 pt-1">
                      {[3, 4, 5, 6, 7, 8].map(colIdx => {
                        const col = lineColumns[colIdx];
                        return (
                          <MobileCardField
                            key={colIdx}
                            label={col.header}
                            value={
                              <div className={isAmountCol(col.header) ? 'font-bold text-[var(--accent)] text-base' : '[&_.input]:text-sm [&_.input]:h-8 [&_.input]:!py-1 [&_.input]:w-24 [&_select.input]:w-32'}>
                                {col.render?.(line, 0)}
                              </div>
                            }
                          />
                        );
                      })}
                      {actionCol && (
                        <div className="flex justify-end mt-2">
                          {actionCol}
                        </div>
                      )}
                    </div>
                  </div>
                );
              }}
              emptyMessage={tPurchase('noLineItems')}
              footer={
                order.lines.length > 0 ? (() => {
                  const taxPct = subtotal > 0 ? (totalTax / subtotal) * 100 : 0;
                  return (
                    <>
                      <tr className="hidden lg:table-row" style={{ borderTop: '2px solid var(--border)' }}>
                        <td colSpan={8} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                          {tCommon('subtotal')}
                        </td>
                        <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                          {formatAmount(subtotal, order.currencyCode || 'EUR')}
                        </td>
                        {isLinesEditable && <td></td>}
                      </tr>
                      <tr className="hidden lg:table-row">
                        <td colSpan={8} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                          {tCommon('tax')}{taxPct > 0 ? ` (${taxPct % 1 === 0 ? taxPct.toFixed(0) : taxPct.toFixed(1)}%)` : ''}
                        </td>
                        <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                          {formatAmount(totalTax, order.currencyCode || 'EUR')}
                        </td>
                        {isLinesEditable && <td></td>}
                      </tr>
                      <tr className="hidden lg:table-row" style={{ backgroundColor: 'rgba(59,130,246,0.02)' }}>
                        <td colSpan={8} style={{ textAlign: 'right', fontWeight: 700, fontSize: 13, color: 'var(--text-primary)' }}>
                          {tCommon('total')}
                        </td>
                        <td style={{ textAlign: 'right', fontWeight: 800, fontSize: 14, color: 'var(--accent)', fontVariantNumeric: 'tabular-nums' }}>
                          {formatAmount(subtotal + totalTax, order.currencyCode || 'EUR')}
                        </td>
                        {isLinesEditable && <td></td>}
                      </tr>
                      
                      {/* Mobile summary */}
                      <tr className="lg:hidden">
                          <td className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tCommon('subtotal')}</td>
                          <td className="py-1 text-sm font-semibold text-right tabular-nums">{formatAmount(subtotal, order.currencyCode || 'EUR')}</td>
                      </tr>
                      <tr className="lg:hidden">
                          <td className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tCommon('tax')}</td>
                          <td className="py-1 text-sm font-semibold text-right tabular-nums">{formatAmount(totalTax, order.currencyCode || 'EUR')}</td>
                      </tr>
                      <tr className="lg:hidden">
                          <td className="py-2 text-sm font-bold text-[var(--accent)] text-right pr-4">{tCommon('total')}</td>
                          <td className="py-2 text-base font-bold text-[var(--accent)] text-right tabular-nums">{formatAmount(subtotal + totalTax, order.currencyCode || 'EUR')}</td>
                      </tr>
                    </>
                  );
                })() : null
              }
            />
          ) : activeTab === 'availability' ? (
            /* Availability tab */
            inventoryLoading ? (
              <p className="text-sm" style={{ color: 'var(--text-muted)', padding: '20px 0', textAlign: 'center' }}>{tPurchase('loadingInventory')}</p>
            ) : (
              <DataTable
                data={order.lines}
                keyExtractor={(line) => line.purchaseOrderLineId}
                columns={[
                  { header: tPurchase('columns.lineNumber'), width: 40 },
                  { header: tPurchase('columns.product') },
                  { header: tPurchase('columns.description') },
                  { header: tPurchase('columns.thisOrder'), width: 90, align: 'right' },
                  { header: tPurchase('columns.location'), width: 100, align: 'right' },
                  { header: tPurchase('columns.onHand'), width: 90, align: 'right' },
                  { header: tPurchase('columns.committed'), width: 90, align: 'right' },
                  { header: tPurchase('columns.ordered'), width: 90, align: 'right' },
                  { header: tPurchase('columns.reserved'), width: 90, align: 'right' },
                  { header: tPurchase('columns.available'), width: 90, align: 'right' },
                  { header: tPurchase('columns.status'), width: 70, align: 'center' }
                ]}
                emptyMessage={tPurchase('noLineItemsShort')}
                renderCustomRow={(line) => {
                    const lineInventory = inventoryData.filter(
                      (inv) => inv.productId === line.productId,
                    );
                    const totalAvail = lineInventory.reduce(
                      (sum, inv) => sum + calculateAvailableQuantity(inv.quantityOnHand, inv.quantityCommitted, inv.quantityReserved), 0,
                    );
                    const orderedQty = parseFloat(line.quantity || '0');
                    const canFulfil = totalAvail >= orderedQty;

                    if (lineInventory.length === 0) {
                      return (
                        <tr key={line.purchaseOrderLineId}>
                          <td style={{ color: 'var(--text-muted)' }}>{line.lineNumber}</td>
                          <td style={{ fontWeight: 600, fontSize: 12 }}>
                            {line.productId && line.productId !== '00000000-0000-0000-0000-000000000000' ? (
                              <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                {line.productNumber || line.productId?.substring(0, 8)}
                              </Link>
                            ) : (
                              line.productNumber || line.productId?.substring(0, 8) || '—'
                            )}
                          </td>
                          <td>{line.productDescription || '—'}</td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{line.quantity}</td>
                          <td colSpan={6} style={{ textAlign: 'center', color: 'var(--text-muted)', fontSize: 12 }}>
                            {tPurchase('noInventoryData')}
                          </td>
                          <td style={{ textAlign: 'center' }}>
                            <span style={{ color: '#f59e0b', fontWeight: 700, fontSize: 11 }}>⚠</span>
                          </td>
                        </tr>
                      );
                    }

                    return lineInventory.map((inv, idx) => {
                      const avail = calculateAvailableQuantity(inv.quantityOnHand, inv.quantityCommitted, inv.quantityReserved);
                      return (
                        <tr key={`${line.purchaseOrderLineId}-${inv.inventoryLevelId}`}>
                          {idx === 0 && (
                            <>
                              <td style={{ color: 'var(--text-muted)' }} rowSpan={lineInventory.length}>{line.lineNumber}</td>
                              <td style={{ fontWeight: 600, fontSize: 12 }} rowSpan={lineInventory.length}>
                                {line.productId && line.productId !== '00000000-0000-0000-0000-000000000000' ? (
                                  <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                    {line.productNumber || line.productId?.substring(0, 8)}
                                  </Link>
                                ) : (
                                  line.productNumber || line.productId?.substring(0, 8) || '—'
                                )}
                              </td>
                              <td rowSpan={lineInventory.length}>{line.productDescription || '—'}</td>
                              <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }} rowSpan={lineInventory.length}>
                                {line.quantity}
                              </td>
                            </>
                          )}
                          <td style={{ textAlign: 'right', fontSize: 12 }}>{inv.locationName || inv.locationNo}</td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                            {parseFloat(inv.quantityOnHand || '0')}
                          </td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                            {parseFloat(inv.quantityCommitted || '0')}
                          </td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                            {parseFloat(inv.quantityOnOrder || '0')}
                          </td>
                          <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                            {parseFloat(inv.quantityReserved || '0')}
                          </td>
                          <td style={{
                            textAlign: 'right',
                            fontVariantNumeric: 'tabular-nums',
                            fontWeight: 600,
                            color: avail > 0 ? '#4ade80' : '#ef4444',
                          }}>
                            {avail}
                          </td>
                          {idx === 0 && (
                            <td style={{ textAlign: 'center' }} rowSpan={lineInventory.length}>
                              <span style={{
                                color: canFulfil ? '#4ade80' : '#ef4444',
                                fontWeight: 700,
                                fontSize: 11,
                              }}>
                                {canFulfil ? '✓' : '✗'}
                              </span>
                            </td>
                          )}
                        </tr>
                      );
                    });
                }}
                mobileCard={(line) => {
                    const lineInventory = inventoryData.filter(
                      (inv) => inv.productId === line.productId,
                    );
                    const totalAvail = lineInventory.reduce(
                      (sum, inv) => sum + calculateAvailableQuantity(inv.quantityOnHand, inv.quantityCommitted, inv.quantityReserved), 0,
                    );
                    const orderedQty = parseFloat(line.quantity || '0');
                    const canFulfil = totalAvail >= orderedQty;

                    return (
                        <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col">
                            <div className="flex justify-between items-start gap-2 mb-2">
                                <div className="font-semibold text-sm text-[var(--accent)]">
                                    {line.productNumber || line.productId?.substring(0, 8) || '—'}
                                </div>
                                <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">#{line.lineNumber}</div>
                            </div>
                            <div className="text-sm text-slate-600 font-medium mb-3">
                                {line.productDescription || '—'}
                            </div>
                            
                            {lineInventory.length === 0 ? (
                                <div className="text-sm text-amber-600 italic text-center py-2 bg-amber-50 rounded border border-amber-100">{tPurchase('noInventoryData')} ⚠</div>
                            ) : (
                                <>
                                    <div className="flex justify-between items-center py-2 border-t border-slate-100">
                                        <span className="text-xs font-medium text-slate-500">{tPurchase('columns.thisOrder')}</span>
                                        <span className="text-sm font-semibold">{line.quantity}</span>
                                    </div>
                                    
                                    <div className="mt-3 flex flex-col gap-2">
                                        <span className="text-xs font-medium text-slate-500">{tPurchase('columns.location')}:</span>
                                        {lineInventory.map((inv) => {
                                            const avail = calculateAvailableQuantity(inv.quantityOnHand, inv.quantityCommitted, inv.quantityReserved);
                                            return (
                                                <div key={inv.inventoryLevelId} className="bg-slate-50 rounded p-2 text-xs flex flex-col gap-1 border border-slate-100">
                                                    <div className="flex justify-between font-medium">
                                                        <span>{inv.locationName || inv.locationNo}</span>
                                                        <span className={avail > 0 ? 'text-emerald-600' : 'text-rose-600'}>{avail} avail</span>
                                                    </div>
                                                    <div className="flex justify-between text-slate-500">
                                                        <span>{parseFloat(inv.quantityOnHand || '0')} on hand</span>
                                                        <span>{parseFloat(inv.quantityCommitted || '0')} cmt / {parseFloat(inv.quantityOnOrder || '0')} in</span>
                                                    </div>
                                                </div>
                                            );
                                        })}
                                    </div>
                                </>
                            )}
                        </div>
                    );
                }}
              />
            )
          ) : activeTab === 'status' ? (
            /* Status / Bill Summary tab */
            <div className="overflow-x-auto">
              <DataTable
                  data={order.lines || []}
                  keyExtractor={(line) => line.purchaseOrderLineId}
                  columns={[
                      { header: tPurchase('columns.lineNumber'), width: 40 },
                      { header: tPurchase('columns.product') },
                      { header: tPurchase('columns.description') },
                      { header: tPurchase('columns.ordered'), align: 'right' },
                      { header: tPurchase('allocated'), align: 'right' },
                      { header: tPurchase('columns.received'), align: 'right' },
                      { header: tPurchase('columns.billed'), align: 'right' },
                      { header: tPurchase('columns.remaining'), align: 'right' }
                  ]}
                  emptyMessage={tPurchase('noLineItemsShort')}
                  renderCustomRow={(line) => {
                      const ordered = parseFloat(line.quantity || '0');
                      const received = parseFloat(line.quantityReceived || '0');
                      const allocated = allocations.reduce((sum, alloc) => {
                          return sum + (alloc.purchaseOrderLineId === line.purchaseOrderLineId ? parseFloat(alloc.quantity) : 0);
                      }, 0);
                      const billed = invoices.reduce((sum, inv) => {
                          const invLine = inv.lines?.find((il: any) => il.purchaseOrderLineId === line.purchaseOrderLineId);
                          return sum + (invLine ? parseFloat(invLine.quantityInvoiced) : 0);
                      }, 0);
                      const remaining = Math.max(0, ordered - billed);
                      return (
                          <tr key={line.purchaseOrderLineId}>
                              <td style={{ color: 'var(--text-muted)' }}>{line.lineNumber}</td>
                              <td style={{ fontWeight: 600, fontSize: 12 }}>
                                  {line.productNumber || line.productId?.substring(0, 8) || '—'}
                              </td>
                              <td>{line.productDescription || '—'}</td>
                              <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{ordered}</td>
                              <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: allocated > 0 ? 'var(--badge-shipped)' : undefined, fontWeight: allocated > 0 ? 600 : 400 }}>{allocated}</td>
                              <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: received >= ordered && ordered > 0 ? 'var(--badge-shipped)' : undefined, fontWeight: received >= ordered && ordered > 0 ? 600 : 400 }}>{received}</td>
                              <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: billed >= received && received > 0 ? 'var(--badge-shipped)' : undefined, fontWeight: billed >= received && received > 0 ? 600 : 400 }}>{billed}</td>
                              <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: remaining === 0 ? 'var(--text-muted)' : undefined }}>{remaining}</td>
                          </tr>
                      );
                  }}
                  mobileCard={(line) => {
                      const ordered = parseFloat(line.quantity || '0');
                      const received = parseFloat(line.quantityReceived || '0');
                      const allocated = allocations.reduce((sum, alloc) => {
                          return sum + (alloc.purchaseOrderLineId === line.purchaseOrderLineId ? parseFloat(alloc.quantity) : 0);
                      }, 0);
                      const billed = invoices.reduce((sum, inv) => {
                          const invLine = inv.lines?.find((il: any) => il.purchaseOrderLineId === line.purchaseOrderLineId);
                          return sum + (invLine ? parseFloat(invLine.quantityInvoiced) : 0);
                      }, 0);
                      const remaining = Math.max(0, ordered - billed);

                      return (
                          <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col">
                              <div className="flex justify-between items-start gap-2 mb-2">
                                  <div className="font-semibold text-sm text-[var(--accent)]">
                                      {line.productNumber || line.productId?.substring(0, 8) || '—'}
                                  </div>
                                  <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">#{line.lineNumber}</div>
                              </div>
                              <div className="text-sm text-slate-600 font-medium mb-3">
                                  {line.productDescription || '—'}
                              </div>
                              
                              <div className="flex flex-col gap-0 border-t border-slate-100 pt-1">
                                  <MobileCardField label={tPurchase('columns.ordered')} value={
                                      <span className="font-semibold">{ordered}</span>
                                  } />
                                  <MobileCardField label={tPurchase('allocated')} value={
                                      <span className={allocated > 0 ? 'font-semibold text-emerald-600' : ''}>{allocated}</span>
                                  } />
                                  <MobileCardField label={tPurchase('columns.received')} value={
                                      <span className={received >= ordered && ordered > 0 ? 'font-semibold text-emerald-600' : ''}>{received}</span>
                                  } />
                                  <MobileCardField label={tPurchase('columns.billed')} value={
                                      <span className={billed >= received && received > 0 ? 'font-semibold text-emerald-600' : ''}>{billed}</span>
                                  } />
                                  <MobileCardField label={tPurchase('columns.remaining')} value={
                                      <span className={remaining === 0 ? 'text-slate-400' : 'font-semibold text-amber-600'}>{remaining}</span>
                                  } />
                              </div>
                          </div>
                      );
                  }}
              />
            </div>
          ) : null}
        </div>

        <AllocationsSection 
          orderId={id} 
          allocations={allocations} 
          loading={allocationsLoading} 
          onAllocationsChanged={loadAllocations} 
        />

        <ReceptionsSection orderId={id} />

        <ReturnsSection
          orderId={id}
          orderState={order.stateCode}
          orderLines={order.lines}
          events={order.events}
          currencyCode={order.currencyCode}
        />

        <InvoicesSection
          orderId={id}
          order={order}
          Invoices={invoices}
          taxCategories={taxCategories}
          setError={setError}
          loadInvoices={loadInvoices}
          loadOrder={loadOrder}
        />

        {/* Audit timeline */}
        <div id="activity-section" className="card">
          <ActivityTimeline events={order.events || []} />
        </div>
      </div>
      </DetailsLayout>

      {/* Global Toast Notification for Auto-Transitions */}
      <div
        className={`fixed bottom-6 right-6 rounded-lg p-4 max-w-[400px] z-[60] flex flex-col gap-1 pointer-events-none shadow-lg border border-[var(--border)] transition-all duration-300 ease-out ${latestAutoTransition ? 'translate-y-0 opacity-100' : 'translate-y-full opacity-0'
          }`}
        style={{ background: 'var(--bg-card)' }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span style={{ fontSize: 16 }}>⚡</span>
          <strong style={{ fontSize: 13, color: 'var(--text-primary)' }}>
            {tToast('orderStateUpdated')}
          </strong>
        </div>
        <p style={{ fontSize: 12, color: 'var(--text-secondary)', margin: 0, lineHeight: 1.4 }}>
          {latestAutoTransition && (
            tToast('orderMovedToReason', {
              state: tCommon(`states.${latestAutoTransition.to}` as never),
              reason: latestAutoTransition.reason.toLowerCase()
            })
          )}
        </p>
      </div>
    </>
  );
}

'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import SlideOver from '@/components/shared/SlideOver';
import { MobileCardField } from '@/components/shared/DataTable';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import { useTranslations } from 'next-intl';
import { MATCH_STATUS, PUTAWAY_STATUS } from '@modbm/shared';
import { toast } from 'react-hot-toast';
import { getErrorMessage } from '@modbm/shared';

interface AllocationSlideOverProps {
  isOpen: boolean;
  onClose: () => void;
  grLines: any[];
  onRefresh: () => void;
}

/**
 * Per-line state: tracks the fetched PO candidates and which POs are expanded.
 */
interface LineState {
  pendingLines: any[];
  loading: boolean;
  expandedPOs: Set<string>;
  allocated: boolean; // true once successfully allocated
}

export default function AllocationSlideOver({ isOpen, onClose, grLines, onRefresh }: AllocationSlideOverProps) {
  const t = useTranslations('goodsReceived');
  const [lineStates, setLineStates] = useState<Map<string, LineState>>(new Map());
  const [activeLineId, setActiveLineId] = useState<string | null>(null);
  const [localLines, setLocalLines] = useState<any[]>([]);
  // Track which line IDs have already been fetched to avoid the stale-closure race condition
  const fetchedRef = useRef<Set<string>>(new Set());

  // Initialize localLines when the slide-over opens
  useEffect(() => {
    if (isOpen) {
      // Only take lines that are currently unmatched AND not quarantined
      // ADV-086: Quarantined items must be cleared before matching
      const initialUnmatched = grLines.filter((l) => l.matchStatus !== MATCH_STATUS.MATCHED && l.putawayStatus !== PUTAWAY_STATUS.QUARANTINED);
      setLocalLines(initialUnmatched);
      if (initialUnmatched.length > 0) {
        setActiveLineId(initialUnmatched[0].goodsReceivedLineId);
      }
    } else {
      setLocalLines([]);
      setActiveLineId(null);
      setLineStates(new Map());
      fetchedRef.current = new Set();
    }
    // Intentionally only reacting to isOpen to prevent background grid refreshes from resetting the view
  }, [isOpen]);

  // We consider all localLines as our queue. Some might have been marked allocated via lineStates.
  const unmatchedLines = localLines;

  // Fetch pending POs for each line when localLines changes (we only fetch for those missing from lineStates)
  useEffect(() => {
    if (!isOpen || unmatchedLines.length === 0) return;

    for (const line of unmatchedLines) {
      // Skip if we already kicked off a fetch for this line
      if (fetchedRef.current.has(line.goodsReceivedLineId)) continue;
      fetchedRef.current.add(line.goodsReceivedLineId);

      // Initialize state for this line (loading placeholder)
      setLineStates((prev) => {
        const next = new Map(prev);
        next.set(line.goodsReceivedLineId, {
          pendingLines: [],
          loading: true,
          expandedPOs: new Set(),
          allocated: false,
        });
        return next;
      });

      api.purchaseOrdersControllerFindPendingLines({ 
        productId: line.productId, 
        vendorId: line.vendorId 
      })
        .then((data: any) => {
          const lines = Array.isArray(data) ? data : data.data || [];
          const poIds = [...new Set(lines.map((l: any) => l.purchaseOrderId))] as string[];

          setLineStates((prev) => {
            const next = new Map(prev);
            next.set(line.goodsReceivedLineId, {
              pendingLines: lines,
              loading: false,
              expandedPOs: new Set(poIds.length <= 3 ? poIds : poIds.length > 0 ? [poIds[0]] : []),
              allocated: false,
            });
            return next;
          });
        })
        .catch((err: any) => {
          reportError(err, 'AllocationSlideOver.pendingPOs');
          setLineStates((prev) => {
            const next = new Map(prev);
            next.set(line.goodsReceivedLineId, {
              pendingLines: [],
              loading: false,
              expandedPOs: new Set(),
              allocated: false,
            });
            return next;
          });
        });
    }
  }, [isOpen, unmatchedLines]);

  const toggleExpand = useCallback((lineId: string, poId: string) => {
    setLineStates((prev) => {
      const next = new Map(prev);
      const state = next.get(lineId);
      if (!state) return prev;
      const expanded = new Set(state.expandedPOs);
      if (expanded.has(poId)) expanded.delete(poId);
      else expanded.add(poId);
      next.set(lineId, { ...state, expandedPOs: expanded });
      return next;
    });
  }, []);

  const markAllocated = useCallback((lineId: string, allocatedQty: string, splitLine?: any) => {
    setLineStates((prev) => {
      const next = new Map(prev);
      const state = next.get(lineId);
      if (!state) return prev;
      next.set(lineId, { ...state, allocated: true });
      return next;
    });

    setLocalLines((prev) => {
      const idx = prev.findIndex(l => l.goodsReceivedLineId === lineId);
      if (idx === -1) return prev;

      const next = [...prev];
      // Update original line quantity to what was actually allocated
      next[idx] = { ...next[idx], quantityReceived: allocatedQty };

      let newActiveId = null;

      if (splitLine) {
        // Insert the split line right after the current line
        next.splice(idx + 1, 0, splitLine);
        // The split line becomes the new active line
        newActiveId = splitLine.goodsReceivedLineId;
      } else if (idx < next.length - 1) {
        // Auto-advance to the next line in the queue
        newActiveId = next[idx + 1].goodsReceivedLineId;
      }

      if (newActiveId) {
        setActiveLineId(newActiveId);
      }

      return next;
    });
  }, []);

  const handleAllocate = useCallback(async (grLine: any, poLine: any, qtyStr: string) => {
    const originalQuantity = parseFloat(grLine.quantityReceived || '0');
    const qty = parseFloat(qtyStr);
    if (isNaN(qty) || qty <= 0 || qty > originalQuantity) {
      toast.error(t('allocation.quantityValidationError', { max: originalQuantity }));
      return;
    }

    const hasLocationMismatch = poLine.deliveryLocationId && grLine.locationId && poLine.deliveryLocationId !== grLine.locationId;
    if (hasLocationMismatch) {
      if (!confirm(`Location Mismatch: This PO was destined for ${poLine.locationName || 'another location'}, but the goods were received here. Are you sure you want to proceed?`)) {
        return;
      }
    }

    try {
      const result = await api.goodsReceivedControllerResolveAllocation(grLine.goodsReceivedLineId, {
        purchaseOrderLineId: poLine.purchaseOrderLineId,
        allocatedQuantity: qtyStr,
      });
      // The API returns { success: true, splitLine: { ... } } if a split occurred
      const splitLineData = result?.data?.splitLine;
      
      let splitLine = null;
      if (splitLineData) {
        // Construct the new line using details from the original line
        splitLine = {
          ...grLine,
          goodsReceivedLineId: splitLineData.goodsReceivedLineId,
          quantityReceived: splitLineData.quantityReceived,
          matchStatus: splitLineData.matchStatus,
        };
      }

      markAllocated(grLine.goodsReceivedLineId, qtyStr, splitLine);
      onRefresh();
    } catch (err: unknown) {
      toast.error(getErrorMessage(err) || t('allocation.matchError'));
    }
  }, [onRefresh, markAllocated, t]);

  if (!isOpen || unmatchedLines.length === 0) return null;

  return (
    <SlideOver isOpen={isOpen} onClose={onClose} title={`Match Received Goods (${unmatchedLines.length} line${unmatchedLines.length > 1 ? 's' : ''})`} width="max-w-4xl">
      <div className="flex flex-col gap-6">

        {/* Summary Table */}
        <div className="card mb-0">
          <div className="hidden lg:block overflow-x-auto w-full">
            <table className="table-lines w-full">
              <thead>
                <tr>
                  <th>{t('columns.receiptNo')}</th>
                  <th>{t('columns.product')}</th>
                  <th>{t('columns.supplier')}</th>
                  <th style={{ textAlign: 'right' }}>{t('columns.receivedQty', { fallback: 'Received Qty' })}</th>
                  <th style={{ width: 90, textAlign: 'center' }}>{t('columns.status', { fallback: 'Status' })}</th>
                </tr>
              </thead>
              <tbody>
                {unmatchedLines.map((line) => {
                  const state = lineStates.get(line.goodsReceivedLineId);
                  const isActive = activeLineId === line.goodsReceivedLineId;
                  return (
                    <tr 
                      key={line.goodsReceivedLineId}
                      onClick={() => setActiveLineId(line.goodsReceivedLineId)}
                      className={`cursor-pointer transition-colors ${isActive ? 'bg-[var(--bg-card-hover)] border-l-2 border-[var(--accent)]' : 'hover:bg-[var(--bg-card-hover)]/50 border-l-2 border-transparent'}`}
                    >
                      <td className="font-medium text-[var(--text-primary)]">{line.receiptNumber}</td>
                      <td>
                        <div className="font-semibold text-[var(--accent)]">{line.productNumber}</div>
                        <div className="text-xs text-[var(--text-muted)] mt-0.5">{line.productName}</div>
                      </td>
                      <td className="text-[var(--text-primary)]">{line.vendorName}</td>
                      <td className="text-right font-bold text-[var(--text-primary)] tabular-nums">
                        {parseFloat(line.quantityReceived || '0')}
                      </td>
                      <td className="text-center">
                        {state?.allocated ? (
                          <span className="badge badge-success">{t('status.allocated')}</span>
                        ) : (
                          <span className="text-xs text-[var(--text-muted)]">{t('status.pending')}</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          <div className="lg:hidden flex flex-col w-full gap-2 pt-2">
            {unmatchedLines.map((line) => {
              const state = lineStates.get(line.goodsReceivedLineId);
              const isActive = activeLineId === line.goodsReceivedLineId;
              return (
                <div
                  key={line.goodsReceivedLineId}
                  className={`transition-colors rounded-lg border p-3 flex flex-col shadow-sm ${isActive ? 'bg-[var(--bg-card-hover)] border-[var(--accent)]' : 'bg-[var(--bg-card)] border-[var(--border)]'}`}
                >
                  <div className="flex justify-between items-start gap-2 mb-2 cursor-pointer" onClick={() => setActiveLineId(line.goodsReceivedLineId)}>
                    <div className="font-semibold text-sm text-[var(--accent)]">
                      {line.productNumber || '—'}
                    </div>
                    <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">
                      {line.receiptNumber}
                    </div>
                  </div>
                  <div className="text-sm text-[var(--text-primary)] font-medium mb-3 cursor-pointer" onClick={() => setActiveLineId(line.goodsReceivedLineId)}>
                    {line.productName || '—'}
                  </div>
                  <div className="flex flex-col gap-1 border-t border-[var(--border)] pt-2 cursor-pointer" onClick={() => setActiveLineId(line.goodsReceivedLineId)}>
                    <MobileCardField label={t('columns.supplier')} value={line.vendorName} />
                    <MobileCardField label={t('columns.receivedQty', { fallback: 'Received Qty' })} value={
                      <span className="font-bold tabular-nums">{parseFloat(line.quantityReceived || '0')}</span>
                    } />
                    <MobileCardField label={t('columns.status', { fallback: 'Status' })} value={
                      state?.allocated ? (
                        <span className="badge badge-success">{t('status.allocated')}</span>
                      ) : (
                        <span className="text-xs text-[var(--text-muted)]">{t('status.pending')}</span>
                      )
                    } />
                  </div>
                  {isActive && state && !state.allocated && (
                    <div className="mt-4 pt-4 border-t border-[rgba(196,198,205,0.4)]">
                      <h4 className="text-xs font-bold mb-3 uppercase tracking-wider text-[var(--text-secondary)]">Eligible POs</h4>
                      <POCandidatesList grLine={line} state={state} toggleExpand={toggleExpand} handleAllocate={handleAllocate} />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {/* Per-line PO candidates */}
        <div className="hidden lg:block">
          {unmatchedLines.map((grLine) => {
            if (grLine.goodsReceivedLineId !== activeLineId) return null;
            
            const state = lineStates.get(grLine.goodsReceivedLineId);
            if (!state || state.allocated) return null;

            const originalQuantity = parseFloat(grLine.quantityReceived || '0');

            return (
              <div key={grLine.goodsReceivedLineId}>
                {/* Section header */}
                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-2 mb-4 p-3 bg-[var(--bg-card)] rounded-lg border border-[var(--border)] lg:border-none lg:p-0 lg:bg-transparent">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="font-bold text-[var(--accent)]">{grLine.productNumber}</span>
                    <span className="hidden lg:inline text-[var(--text-muted)]">—</span>
                    <span className="text-sm text-[var(--text-primary)] w-full lg:w-auto">{grLine.productName}</span>
                  </div>
                  
                  <div className="flex flex-wrap items-center justify-between lg:justify-end gap-4 mt-2 lg:mt-0 pt-2 lg:pt-0 border-t border-[var(--border)] lg:border-none w-full lg:w-auto">
                    <span className="text-xs text-[var(--text-secondary)]">
                      {t('allocation.receivedAt')} <span className="font-medium text-[var(--text-primary)]">{grLine.locationName || t('allocation.unknown')}</span>
                    </span>
                    <span className="text-xs font-semibold px-2 py-1 bg-[var(--bg-secondary)] rounded-md text-[var(--text-primary)] tabular-nums shrink-0">
                      {t('allocation.qty')} {originalQuantity}
                    </span>
                  </div>
                </div>

                <POCandidatesList grLine={grLine} state={state} toggleExpand={toggleExpand} handleAllocate={handleAllocate} />
              </div>
            );
          })}
        </div>

      </div>
    </SlideOver>
  );
}

function POCandidatesList({
  grLine,
  state,
  toggleExpand,
  handleAllocate
}: {
  grLine: any;
  state: any;
  toggleExpand: (lineId: string, poId: string) => void;
  handleAllocate: (grLine: any, poLine: any, qtyStr: string) => void;
}) {
  const t = useTranslations('goodsReceived');
  const originalQuantity = parseFloat(grLine.quantityReceived || '0');

  // Group pending lines by PO
  const poGroups = new Map<string, any>();
  for (const line of state.pendingLines) {
    if (!poGroups.has(line.purchaseOrderId)) {
      poGroups.set(line.purchaseOrderId, {
        purchaseOrderId: line.purchaseOrderId,
        orderNumber: line.orderNumber,
        locationName: line.locationName,
        lines: [],
      });
    }
    poGroups.get(line.purchaseOrderId)!.lines.push(line);
  }
  const groups = Array.from(poGroups.values());

  if (state.loading) {
    return (
      <div className="p-6 text-center text-[var(--text-muted)] border border-[var(--border)] rounded-md bg-[var(--bg-card)]">
        {t('allocation.loadingEligible')}
      </div>
    );
  }

  if (groups.length === 0) {
    return (
      <div className="p-6 text-center text-[var(--text-muted)] border border-[var(--border)] rounded-md bg-[var(--bg-card)]">
        {t('allocation.noPendingPOs')}
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-2">
      {groups.map((group) => {
        const isExpanded = state.expandedPOs.has(group.purchaseOrderId);
        return (
          <div key={group.purchaseOrderId} style={{ borderRadius: 8, border: '1px solid var(--border)', overflow: 'hidden', background: 'var(--bg-card)' }}>
            {/* Card Header */}
            <button
              onClick={() => toggleExpand(grLine.goodsReceivedLineId, group.purchaseOrderId)}
              style={{ width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 16px', background: 'none', border: 'none', cursor: 'pointer', textAlign: 'left' }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                {/* eslint-disable-next-line i18next/no-literal-string */}
                <span className="material-symbols-outlined" style={{ fontSize: 18, transition: 'transform 0.15s', transform: isExpanded ? 'rotate(90deg)' : 'rotate(0deg)', color: 'var(--text-muted)' }}>
                  chevron_right
                </span>
                <span style={{ fontWeight: 700, color: 'var(--accent)', fontSize: 14 }}>
                  {group.orderNumber}
                </span>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                {grLine.locationName && group.locationName && grLine.locationName !== group.locationName && (
                  <span className="badge badge-sm badge-warning">{t('allocation.locationMismatch')}</span>
                )}
                <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>
                  {t('allocation.destination')} <span className="font-medium text-[var(--text-primary)]">{group.locationName || t('allocation.unknown')}</span>
                </div>
              </div>
            </button>

            {/* Expanded Lines */}
            {isExpanded && (
              <div style={{ borderTop: '1px solid var(--border)' }}>
                <div className="hidden lg:block overflow-x-auto">
                  <table className="table-lines w-full">
                    <thead>
                      <tr>
                        <th>{t('columns.ordered', { fallback: 'Ordered' })}</th>
                        <th>{t('columns.received', { fallback: 'Received' })}</th>
                        <th>{t('columns.remaining', { fallback: 'Remaining' })}</th>
                        <th style={{ width: 160, textAlign: 'center' }}>{t('columns.allocate', { fallback: 'Allocate' })}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {group.lines.map((poLine: any) => (
                        <POLineRow
                          key={poLine.purchaseOrderLineId}
                          line={poLine}
                          originalQuantity={originalQuantity}
                          onAllocate={(qty) => handleAllocate(grLine, poLine, qty)}
                        />
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="lg:hidden flex flex-col w-full divide-y divide-[var(--border)]">
                  {group.lines.map((poLine: any) => (
                    <POLineMobileCard
                      key={poLine.purchaseOrderLineId}
                      line={poLine}
                      originalQuantity={originalQuantity}
                      onAllocate={(qty) => handleAllocate(grLine, poLine, qty)}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function POLineRow({ line, originalQuantity, onAllocate }: { line: any; originalQuantity: number; onAllocate: (qty: string) => void }) {
  const t = useTranslations('goodsReceived');
  const ordered = parseFloat(line.quantity || '0');
  const received = parseFloat(line.quantityReceived || '0');
  const remaining = Math.max(0, ordered - received);

  const suggestedQty = Math.min(originalQuantity, remaining);
  const [qty, setQty] = useState(suggestedQty > 0 ? suggestedQty.toString() : originalQuantity.toString());
  const [isAllocating, setIsAllocating] = useState(false);

  return (
    <tr>
      <td className="tabular-nums">{ordered}</td>
      <td className="tabular-nums text-[var(--text-primary)]">{received}</td>
      <td className="tabular-nums font-bold text-[var(--text-primary)]">{remaining}</td>
      <td className="text-right">
        <div className="flex items-center justify-end gap-1">
          <input
            type="number"
            step="0.01"
            min="0.01"
            max={originalQuantity}
            className="input text-right"
            style={{ width: '70px', padding: '2px 4px', height: '26px', fontSize: '12px' }}
            value={qty}
            onChange={(e) => setQty(e.target.value)}
          />
          <button
            onClick={async () => {
              setIsAllocating(true);
              await onAllocate(qty);
              setIsAllocating(false);
            }}
            disabled={isAllocating || !qty}
            className="btn btn-primary btn-sm"
            style={{ padding: '2px 8px', height: '26px', fontSize: '11px' }}
          >
            {isAllocating ? t('allocation.allocating') : t('allocation.match')}
          </button>
        </div>
      </td>
    </tr>
  );
}

function POLineMobileCard({ line, originalQuantity, onAllocate }: { line: any; originalQuantity: number; onAllocate: (qty: string) => void }) {
  const t = useTranslations('goodsReceived');
  const ordered = parseFloat(line.quantity || '0');
  const received = parseFloat(line.quantityReceived || '0');
  const remaining = Math.max(0, ordered - received);

  const suggestedQty = Math.min(originalQuantity, remaining);
  const [qty, setQty] = useState(suggestedQty > 0 ? suggestedQty.toString() : originalQuantity.toString());
  const [isAllocating, setIsAllocating] = useState(false);

  return (
    <div className="flex flex-col gap-2 p-4 bg-[var(--bg-secondary)]">
      <div className="flex items-center justify-between gap-4">
        <MobileCardField className="flex-1 border-0 py-0" label={t('columns.ordered', { fallback: 'Ordered' })} value={ordered} />
        <MobileCardField className="flex-1 border-0 py-0" label={t('columns.received', { fallback: 'Received' })} value={received} />
      </div>
      <div className="flex flex-col gap-2 border-t border-[var(--border)] pt-3 mt-1">
        <div className="flex items-center justify-between">
          <span className="text-xs font-medium text-slate-500">{t('columns.remaining', { fallback: 'Remaining' })}</span>
          <span className="text-sm font-bold text-[var(--text-primary)] tabular-nums">{remaining}</span>
        </div>
        <div className="flex items-center justify-end gap-2 mt-2">
          <input
            type="number"
            step="0.01"
            min="0.01"
            max={originalQuantity}
            className="input text-right"
            style={{ width: '80px', padding: '6px 8px', height: '32px', fontSize: '13px' }}
            value={qty}
            onChange={(e) => setQty(e.target.value)}
          />
          <button
            onClick={async () => {
              setIsAllocating(true);
              await onAllocate(qty);
              setIsAllocating(false);
            }}
            disabled={isAllocating || !qty}
            className="btn btn-primary"
            style={{ padding: '6px 16px', height: '32px', fontSize: '13px' }}
          >
            {isAllocating ? t('allocation.allocating') : t('allocation.match')}
          </button>
        </div>
      </div>
    </div>
  );
}

