'use client';

import { useState, Suspense } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import * as api from '@modbm/sdk';
import { toast } from 'react-hot-toast';
import ProductSearchInput from '@/components/shared/ProductSearchInput';
import type { Product } from '@/components/shared/ProductSearchInput';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import { MobileCardField } from '@/components/shared/DataTable';

import React from 'react';
import LocationSelect from '@/components/shared/LocationSelect';
import SupplierSelect from '@/components/shared/SupplierSelect';
import { useTranslations } from 'next-intl';
import { formatAmount } from '@/lib/currency';
import { getErrorMessage } from '@modbm/shared';

interface DraftLine {
  id: string;
  productId: string;
  productNumber?: string;
  productName: string;
  quantityReceived: number;
}

interface CompletedLine {
  goodsReceivedLineId: string;
  productId: string;
  productNumber: string;
  productName: string;
  quantityReceived: string;
  matchStatus: string;
  orderNumber?: string;
  purchaseOrderId?: string;
}

function ReceivingFlow() {
  const t = useTranslations('goodsReceived');
  const tCommon = useTranslations('common');
  useDocumentTitle(t('flow.title'));
  const router = useRouter();

  // Header state
  const [vendorId, setVendorId] = useState<string | null>(null);
  const [locationId, setLocationId] = useState<string | null>(null);
  const [packingSlipNumber, setPackingSlipNumber] = useState<string>('');
  const [notes, setNotes] = useState<string>('');

  // Draft state
  const [draftLines, setDraftLines] = useState<DraftLine[]>([]);
  const [qtyToReceive, setQtyToReceive] = useState<string>('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);

  // Flow state
  const [saving, setSaving] = useState(false);
  const [completed, setCompleted] = useState(false);
  const [completedLines, setCompletedLines] = useState<CompletedLine[]>([]);

  const handleProductSelect = (product: Product) => {
    setSelectedProduct(product);
    setQtyToReceive('1');
  };

  const addToDraft = () => {
    if (!selectedProduct) return;
    const qty = Number(qtyToReceive);
    if (qty <= 0) {
      toast.error(t('toast.qtyReq'));
      return;
    }

    // Check if product already in draft — if so, add to existing quantity
    const existing = draftLines.find((l) => l.productId === selectedProduct.productId);
    if (existing) {
      setDraftLines(
        draftLines.map((l) =>
          l.productId === selectedProduct.productId
            ? { ...l, quantityReceived: l.quantityReceived + qty }
            : l,
        ),
      );
    } else {
      setDraftLines([
        ...draftLines,
        {
          id: Math.random().toString(36).substring(7),
          productId: selectedProduct.productId,
          productNumber: selectedProduct.productNumber,
          productName: selectedProduct.name,
          quantityReceived: qty,
        },
      ]);
    }

    setSelectedProduct(null);
    setQtyToReceive('');
  };

  const removeDraftLine = (id: string) => {
    setDraftLines(draftLines.filter((l) => l.id !== id));
  };

  const commitReception = async () => {
    if (draftLines.length === 0) return;
    if (!vendorId) {
      toast.error(t('toast.selectSupplier'));
      return;
    }
    if (!locationId) {
      toast.error(t('toast.selectLocation'));
      return;
    }
    setSaving(true);

    const payload = {
      vendorId,
      locationId,
      packingSlipNumber: packingSlipNumber || undefined,
      notes: notes || undefined,
      lines: draftLines.map((l) => ({
        productId: l.productId,
        quantityReceived: String(l.quantityReceived),
      })),
    };

    try {
      const result = await api.goodsReceivedControllerCreate(payload);
      const returnedLines = (result.data as any)?.lines || [];
      const mapped: CompletedLine[] = returnedLines.map((l: any) => ({
        goodsReceivedLineId: l.goodsReceivedLineId,
        productId: l.productId,
        productNumber: l.productNumber || l.productId.substring(0, 8),
        productName: l.productName || l.productDescription || '',
        quantityReceived: l.quantityReceived,
        matchStatus: l.matchStatus || 'unmatched',
        orderNumber: l.orderNumber,
        purchaseOrderId: l.purchaseOrderId,
      }));

      setCompletedLines(mapped);
      toast.success(t('toast.confirmed'));
      setCompleted(true);
    } catch (err: unknown) {
      toast.error(getErrorMessage(err) || t('toast.failed'));
    } finally {
      setSaving(false);
    }
  };

  // ── Match status badge ──────────────────────────────────────────────
  const MatchStatusBadge = ({ status }: { status: string }) => {
    const styles: Record<string, { bg: string; color: string; label: string }> = {
      matched: { bg: 'rgba(16,185,129,0.12)', color: '#059669', label: t('matchStatus.matched') },
      unmatched: { bg: 'rgba(239,68,68,0.12)', color: '#dc2626', label: t('matchStatus.unmatched') },
      ambiguous: { bg: 'rgba(245,158,11,0.12)', color: '#d97706', label: t('matchStatus.ambiguous') },
    };
    const s = styles[status] || styles.unmatched;
    return (
      <span
        style={{
          display: 'inline-block',
          padding: '2px 8px',
          borderRadius: 6,
          fontSize: 11,
          fontWeight: 600,
          background: s.bg,
          color: s.color,
          letterSpacing: '0.02em',
        }}
      >
        {s.label}
      </span>
    );
  };

  // ── Completed screen ────────────────────────────────────────────────
  if (completed) {
    return (
      <DetailsLayout
        header={
          <EntityHeader
            title={t('completed.title')}
            actions={
              <div className="flex flex-wrap gap-2 w-full lg:w-auto">
                <button className="btn btn-secondary" onClick={() => router.push('/receiving')}>
                  {t('completed.backToList')}
                </button>
                <button
                  className="btn btn-primary w-full lg:w-auto"
                  onClick={() => {
                    setCompleted(false);
                    setDraftLines([]);
                    setSelectedProduct(null);
                    setCompletedLines([]);
                    setVendorId(null);
                    setPackingSlipNumber('');
                    setNotes('');
                  }}
                >
                  {t('completed.newReception')}
                </button>
              </div>
            }
            showPrint={false}
          />
        }
      >
        <div className="flex flex-col gap-6">
          <div className="card flex flex-col gap-4">
            {(notes || packingSlipNumber) && (
              <div className="mb-4 flex gap-8 text-sm">
                {packingSlipNumber && (
                  <div>
                    <strong style={{ color: 'var(--text-muted)', display: 'block', marginBottom: 2 }}>
                      {t('labels.packingSlip')}:
                    </strong>
                    {packingSlipNumber}
                  </div>
                )}
                {notes && (
                  <div>
                    <strong style={{ color: 'var(--text-muted)', display: 'block', marginBottom: 2 }}>
                      {tCommon('columns.notes')}:
                    </strong>
                    {notes}
                  </div>
                )}
              </div>
            )}

            <div className="hidden lg:block overflow-x-auto w-full">
              <table className="table-lines">
                <thead>
                  <tr>
                    <th>{tCommon('columns.product')}</th>
                    <th>{tCommon('columns.description')}</th>
                    <th style={{ width: 100, textAlign: 'right' }}>{tCommon('columns.received')}</th>
                    <th style={{ width: 120 }}>{t('columns.matchStatus')}</th>
                    <th style={{ width: 160 }}>{tCommon('columns.purchaseOrder')}</th>
                  </tr>
                </thead>
                <tbody>
                  {completedLines.map((line) => (
                    <tr key={line.goodsReceivedLineId}>
                      <td style={{ fontWeight: 600, fontSize: 12 }}>{line.productNumber || '—'}</td>
                      <td style={{ fontSize: 13 }}>{line.productName || '—'}</td>
                      <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontSize: 13 }}>
                        {line.quantityReceived}
                      </td>
                      <td>
                        <MatchStatusBadge status={line.matchStatus} />
                      </td>
                      <td>
                        {line.orderNumber && line.purchaseOrderId ? (
                          <Link href={`/purchase-orders/${line.purchaseOrderId}`} style={{ fontWeight: 500, fontSize: 13, color: 'var(--accent)', textDecoration: 'none' }}>
                            {line.orderNumber}
                          </Link>
                        ) : line.orderNumber ? (
                          <span style={{ fontWeight: 500, fontSize: 13, color: 'var(--accent)' }}>
                            {line.orderNumber}
                          </span>
                        ) : (
                          <span style={{ color: 'var(--text-muted)', fontSize: 12 }}>—</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            <div className="lg:hidden flex flex-col gap-3 w-full">
              {completedLines.map((line, idx) => (
                <div key={line.goodsReceivedLineId} className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col shadow-sm">
                  <div className="flex justify-between items-start gap-2 mb-2">
                    <div className="font-semibold text-sm text-[var(--accent)]">
                      {line.productNumber || '—'}
                    </div>
                    <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">#{idx + 1}</div>
                  </div>
                  <div className="text-sm text-slate-600 font-medium mb-3">
                    {line.productName || '—'}
                  </div>
                  <div className="flex flex-col gap-1 border-t border-slate-100 pt-2">
                    <MobileCardField label={tCommon('columns.received')} value={line.quantityReceived} />
                    <MobileCardField label={t('columns.matchStatus')} value={<MatchStatusBadge status={line.matchStatus} />} />
                    <MobileCardField label={tCommon('columns.purchaseOrder')} value={line.orderNumber && line.purchaseOrderId ? (
                      <Link href={`/purchase-orders/${line.purchaseOrderId}`} style={{ fontWeight: 500, color: 'var(--accent)', textDecoration: 'none' }}>{line.orderNumber}</Link>
                    ) : line.orderNumber ? (
                      <span style={{ fontWeight: 500, color: 'var(--accent)' }}>{line.orderNumber}</span>
                    ) : (
                      <span style={{ color: 'var(--text-muted)' }}>—</span>
                    )} />
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </DetailsLayout>
    );
  }

  // ── Main flow ───────────────────────────────────────────────────────
  return (
    <DetailsLayout
      header={
        <EntityHeader
          title={t('flow.title')}
          subtitle={t('flow.subtitle')}
          isSaving={saving}
          actions={
            <button
              className="btn btn-primary w-full lg:w-auto"
              onClick={commitReception}
              disabled={draftLines.length === 0 || saving || !vendorId || !locationId}
            >
              {t('flow.confirmReception')}
            </button>
          }
          showPrint={false}
        />
      }
    >
      <div className="flex flex-col gap-6">
        {/* Package Header */}
        <div className="card flex flex-col gap-4" style={{ height: 'fit-content' }}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            <div>
              <label className="block mb-1 text-xs font-semibold" style={{ color: 'var(--text-muted)' }}>
                {t('labels.supplier')} *
              </label>
              <SupplierSelect
                value={vendorId}
                onChange={(s) => setVendorId(s?.vendorId || null)}
                placeholder={t('placeholders.selectSupplier')}
                required
              />
            </div>
            <div>
              <label className="block mb-1 text-xs font-semibold" style={{ color: 'var(--text-muted)' }}>
                {t('labels.location')} *
              </label>
              <LocationSelect
                value={locationId}
                onChange={setLocationId}
                placeholder={t('placeholders.selectLocation')}
                required
              />
            </div>
            <div>
              <label className="block mb-1 text-xs font-semibold" style={{ color: 'var(--text-muted)' }}>
                {t('labels.packingSlip')}
              </label>
              <input
                className="input"
                placeholder={t('placeholders.packingSlip')}
                value={packingSlipNumber}
                onChange={(e) => setPackingSlipNumber(e.target.value)}
              />
            </div>
            <div>
              <label className="block mb-1 text-xs font-semibold" style={{ color: 'var(--text-muted)' }}>
                {tCommon('columns.notes')}
              </label>
              <input
                className="input"
                placeholder={t('placeholders.notes')}
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
              />
            </div>
          </div>

          {/* Product scanner */}
          <h3 className="section-heading mb-0 mt-2">{t('flow.scanProduct')}</h3>

          <div className="flex flex-col lg:flex-row lg:items-end gap-3">
            {!selectedProduct ? (
              <div className="flex-1 w-full">
                <ProductSearchInput
                  onSelect={handleProductSelect}
                  placeholder={t('placeholders.searchProduct')}
                />
              </div>
            ) : (
              <div className="flex-1 flex flex-col w-full">
                <label className="block mb-1 text-xs font-medium" style={{ color: 'var(--text-muted)' }}>
                  {t('flow.selectedProduct', { fallback: 'Selected Product' })}
                </label>
                <div
                  className="text-sm px-3 flex items-center w-full border rounded outline-none"
                  style={{
                    background: 'var(--bg-card)',
                    color: 'var(--text-primary)',
                    borderColor: 'var(--border)',
                    height: '38px',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis'
                  }}
                  title={`${selectedProduct.productNumber} — ${selectedProduct.name}`}
                >
                  <span style={{ fontWeight: 600, marginRight: 8, color: 'var(--accent)' }}>{selectedProduct.productNumber}</span>
                  <span style={{ color: 'var(--text-muted)', overflow: 'hidden', textOverflow: 'ellipsis' }}>{selectedProduct.name}</span>
                </div>
              </div>
            )}

            {selectedProduct && (
              <div className="flex items-end gap-3 w-full lg:w-auto">
                <div className="flex-1 lg:w-[100px]">
                  <label className="block mb-1 text-xs font-medium" style={{ color: 'var(--text-muted)' }}>
                    {tCommon('columns.qty')}
                  </label>
                  <input
                    type="number"
                    min="0"
                    step="any"
                    className="input w-full"
                    value={qtyToReceive}
                    onChange={(e) => setQtyToReceive(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') addToDraft();
                    }}
                  />
                </div>
                <div className="flex gap-2 shrink-0">
                  <button className="btn btn-primary flex-1 lg:flex-none" onClick={addToDraft}>
                    {tCommon('add')}
                  </button>
                  <button
                    className="btn btn-secondary flex-1 lg:flex-none"
                    onClick={() => {
                      setSelectedProduct(null);
                      setQtyToReceive('');
                    }}
                  >
                    {tCommon('cancel')}
                  </button>
                </div>
              </div>
            )}
          </div>


        </div>

        {/* Draft Cart */}
        <div className="card flex flex-col gap-4" style={{ height: 'fit-content' }}>
          <h3 className="section-heading">{t('flow.itemsReceived')}</h3>

          {draftLines.length === 0 ? (
            <p style={{ color: 'var(--text-muted)', fontSize: 14 }}>{t('flow.noItems')}</p>
          ) : (
            <>
              <div className="hidden lg:block overflow-x-auto w-full">
                <table className="table-lines">
                  <thead>
                    <tr>
                      <th>{tCommon('columns.product')}</th>
                      <th>{tCommon('columns.description')}</th>
                      <th style={{ width: 100, textAlign: 'right' }}>{tCommon('columns.qty')}</th>
                      <th style={{ width: 80 }}></th>
                    </tr>
                  </thead>
                  <tbody>
                    {draftLines.map((line) => (
                      <tr key={line.id}>
                        <td style={{ fontWeight: 600, fontSize: 12 }}>{line.productNumber || '—'}</td>
                        <td style={{ fontSize: 13 }}>{line.productName || '—'}</td>
                        <td
                          style={{
                            textAlign: 'right',
                            fontVariantNumeric: 'tabular-nums',
                            fontSize: 13,
                          }}
                        >
                          {line.quantityReceived}
                        </td>
                        <td style={{ textAlign: 'right' }}>
                          <button
                            className="btn btn-secondary btn-sm"
                            style={{ color: 'var(--danger)', borderColor: 'var(--danger)' }}
                            onClick={() => removeDraftLine(line.id)}
                          >
                            {/* eslint-disable-next-line i18next/no-literal-string */}
                            ✕
                            {/* eslint-enable i18next/no-literal-string */}
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <div className="lg:hidden flex flex-col gap-3 w-full">
                {draftLines.map((line, idx) => (
                  <div key={line.id} className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col shadow-sm">
                    <div className="flex justify-between items-start gap-2 mb-2">
                      <div className="font-semibold text-sm text-[var(--accent)]">
                        {line.productNumber || '—'}
                      </div>
                      <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">#{idx + 1}</div>
                    </div>
                    <div className="text-sm text-slate-600 font-medium mb-3">
                      {line.productName || '—'}
                    </div>
                    <div className="flex flex-col gap-1 border-t border-slate-100 pt-2">
                      <MobileCardField label={tCommon('columns.qty')} value={line.quantityReceived} />
                      <div className="flex justify-end pt-2 mt-1 border-t border-slate-50">
                        <button
                          className="btn btn-secondary btn-sm"
                          style={{ color: 'var(--danger)', borderColor: 'var(--danger)' }}
                          onClick={() => removeDraftLine(line.id)}
                        >
                          {/* eslint-disable-next-line i18next/no-literal-string */}
                          ✕
                          {/* eslint-enable i18next/no-literal-string */}
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      </div>

      <style jsx>{`
        .table-lines {
          width: 100%;
          border-collapse: collapse;
          margin-bottom: 0;
        }
        .table-lines th {
          text-align: left;
          padding: 10px 12px;
          font-size: 11px;
          font-weight: 700;
          text-transform: uppercase;
          letter-spacing: 0.05em;
          color: var(--text-muted);
          border-bottom: 2px solid var(--border);
        }
        .table-lines td {
          padding: 12px;
          font-size: 13px;
          border-bottom: 1px solid var(--border);
          vertical-align: middle;
        }
      `}</style>
    </DetailsLayout>
  );
}

export default function ReceivingPage() {
  const tCommon = useTranslations('common');
  return (
    <Suspense fallback={<p style={{ padding: 20 }}>{tCommon('loading')}</p>}>
      <ReceivingFlow />
    </Suspense>
  );
}

'use client';

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import { useSettings } from '@/components/SettingsProvider';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import toast from 'react-hot-toast';
import DataGrid from '@/components/DataGrid';
import Link from 'next/link';
import POAllocationCell from './POAllocationCell';
import AllocationSlideOver from './AllocationSlideOver';
import { GOODS_RECEIVED_STATE, PUTAWAY_STATUS, MATCH_STATUS } from '@modbm/shared';
import { getErrorMessage } from '@modbm/shared';

function FilterDropdown({ locations, selectedLocationId, setSelectedLocationId, days, setDays, t, tCommon, defaultLocId }: any) {
    const [open, setOpen] = useState(false);
    const ref = React.useRef<HTMLDivElement>(null);
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (ref.current && !ref.current.contains(event.target as Node)) {
                setOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const isActive = selectedLocationId !== defaultLocId || days !== '90';

    return (
        <div className="sm:relative" ref={ref}>
            <button 
                onClick={() => setOpen(!open)}
                className={`flex items-center justify-center h-10 w-10 rounded-lg transition-all ${isActive ? 'bg-[var(--accent)] text-white border-[var(--accent)]' : 'bg-white lg:bg-transparent border border-[var(--border)] lg:border-none text-[var(--text-secondary)] hover:bg-[var(--bg-card-hover)]'}`}
                title="Filters"
            >
                <span className="material-symbols-outlined text-[20px]">filter_list</span>
            </button>
            {open && (
                <div className="absolute left-0 right-0 sm:left-auto sm:right-0 top-full mt-2 w-full sm:w-64 bg-white shadow-[0_4px_24px_rgba(0,0,0,0.12)] rounded-xl border border-[var(--border)] p-4 z-50 flex flex-col gap-4">
                    <div className="flex flex-col gap-1.5">
                        <label className="text-xs font-bold text-[var(--text-muted)] uppercase tracking-wider">{tCommon('columns.location')}</label>
                        <select
                            value={selectedLocationId}
                            onChange={(e) => setSelectedLocationId(e.target.value)}
                            className="input text-sm w-full"
                        >
                            <option value="">{t('buttons.allLocations')}</option>
                            {locations.map((loc: any) => (
                                <option key={loc.locationId} value={loc.locationId}>
                                    {loc.code} - {loc.name}
                                </option>
                            ))}
                        </select>
                    </div>
                    <div className="flex flex-col gap-1.5">
                        <label className="text-xs font-bold text-[var(--text-muted)] uppercase tracking-wider">{tCommon('columns.date')}</label>
                        <select
                            value={days}
                            onChange={(e) => setDays(e.target.value)}
                            className="input text-sm w-full"
                        >
                            <option value="30">{tCommon('filters.last30Days')}</option>
                            <option value="90">{tCommon('filters.last90Days')}</option>
                            <option value="365">{tCommon('filters.last1Year')}</option>
                            <option value="0">{tCommon('filters.allTime')}</option>
                        </select>
                    </div>
                </div>
            )}
        </div>
    );
}

export default function GoodsReceivedListPage() {
    const t = useTranslations('goodsReceived');
    const tCommon = useTranslations('common');
    useDocumentTitle(t('title'));
    const { app } = useSettings();
    const [days, setDays] = useState('90');
    const [refreshKey, setRefreshKey] = useState(0);

    const [locations, setLocations] = useState<any[]>([]);
    const [selectedLocationId, setSelectedLocationId] = useState<string>('');

    useEffect(() => {
        api.inventoryControllerFindAllLocations({} )
            .then((response) => {
                const locs = response.data || [];
                setLocations(locs);
                // For receiving, we default to the app default but allow "All" (which is empty string)
                const defaultLocId = app?.defaultFulfillmentLocationId || (locs.length > 0 ? locs[0].locationId : '');
                setSelectedLocationId(defaultLocId);
            })
            .catch((err: unknown) => reportError(err, 'GoodsReceivedListPage.loadLocations'));
    }, [app?.defaultFulfillmentLocationId]);

    const [slideOverOpen, setSlideOverOpen] = useState(false);
    const [selectedRows, setSelectedRows] = useState<any[]>([]);

    const handleAllocate = useCallback(() => {
        if (selectedRows.length === 0) return;
        setSlideOverOpen(true);
    }, [selectedRows]);

    const handleSlideOverClose = useCallback(() => {
        setSlideOverOpen(false);
    }, []);

    const triggerRefresh = useCallback(() => setRefreshKey(k => k + 1), []);

    const handleToggleQuarantine = useCallback(async () => {
        if (selectedRows.length === 0) return;
        
        try {
            const reason = window.prompt('Reason for quarantine', '') || undefined;

            // Toggle for all selected that are not completed
            const eligible = selectedRows.filter(r => r.putawayStatus !== PUTAWAY_STATUS.COMPLETED);
            const errors: string[] = [];
            for (const row of eligible) {
                try {
                    if (reason) {
                        await api.inventoryControllerToggleQuarantine(row.goodsReceivedLineId, { reason } as unknown as import('@modbm/sdk').ToggleQuarantineDto);
                        toast.success('Line quarantined successfully');
                    }
                } catch (err: unknown) {
                    errors.push(getErrorMessage(err) || `Failed for ${row.receiptNumber}`);
                }
            }
            if (errors.length > 0) {
                alert(`Quarantine errors:\n${errors.join('\n')}`);
            }
            triggerRefresh();
        } catch (err: unknown) {
            alert(getErrorMessage(err) || 'Failed to toggle quarantine');
        }
    }, [selectedRows, triggerRefresh]);

    const handleCancelReceipt = useCallback(async () => {
        const uniqueReceiptIds = [...new Set(selectedRows.map((r) => r.goodsReceivedId))];
        if (uniqueReceiptIds.length !== 1) {
            alert('Please select lines from exactly one receipt to cancel.');
            return;
        }

        const receiptId = uniqueReceiptIds[0];
        const receiptNumber = selectedRows.find(r => r.goodsReceivedId === receiptId)?.receiptNumber;

        if (!window.confirm(`Are you sure you want to cancel the ENTIRE receipt ${receiptNumber}? This cannot be undone.`)) {
            return;
        }

        try {
            await api.goodsReceivedControllerCancelReception(receiptId, {});
            triggerRefresh();
            setSelectedRows([]);
        } catch (err: unknown) {
            alert(getErrorMessage(err) || 'Failed to cancel receipt');
        }
    }, [selectedRows, triggerRefresh]);

    const gridEndpoint = `/api/goods-received/lines?days=${days}&limit=0${selectedLocationId ? `&locationId=${selectedLocationId}` : ''}`;

    const gridColumns: any[] = useMemo(() => [
        {
            field: 'receiptNumber',
            headerName: t('columns.receiptNo'),
            width: 140,
            checkboxSelection: true,
            headerCheckboxSelection: true,
        },
        { field: 'goodsReceivedLineId', headerName: tCommon('columns.id'), hide: true },
        {
            field: 'putawayStatus',
            headerName: 'Putaway Status',
            width: 140,
            valueFormatter: (p: import("ag-grid-community").ICellRendererParams<any>) => {
                if (!p.value) return '';
                if (p.data?.stateCode === GOODS_RECEIVED_STATE.CANCELLED) return 'Cancelled';
                if (p.value === PUTAWAY_STATUS.COMPLETED) return 'Completed';
                if (p.value === PUTAWAY_STATUS.QUARANTINED) return 'Quarantined';
                if (p.value === PUTAWAY_STATUS.PENDING_PUTAWAY) return 'Pending';
                if (p.value === PUTAWAY_STATUS.AWAITING_MATCHING) return 'Awaiting Match';
                return p.value;
            }
        },
        { field: 'createdOn', headerName: tCommon('columns.date'), width: 110, valueFormatter: (p: import("ag-grid-community").ICellRendererParams<any>) => p.value ? new Date(p.value).toLocaleDateString() : '' },
        { field: 'vendorName', headerName: t('columns.supplier'), width: 160 },
        { field: 'locationName', headerName: tCommon('columns.location', { defaultValue: 'Location' }), width: 140 },
        { 
            field: 'productNumber', 
            headerName: tCommon('columns.product'), 
            width: 240,
            cellRenderer: (p: import("ag-grid-community").ICellRendererParams<any>) => {
                if (!p.data) return null;
                return (
                    <div style={{ lineHeight: '1.2', padding: '4px 0' }}>
                        <div style={{ fontWeight: 600, color: 'var(--accent)' }}>{p.data.productNumber}</div>
                        <div style={{ fontSize: 11, color: 'var(--text-muted)' }}>{p.data.productName}</div>
                    </div>
                );
            }
        },

        { 
            field: 'quantityReceived', 
            headerName: tCommon('columns.quantity'), 
            width: 90,
            cellStyle: { textAlign: 'right', fontVariantNumeric: 'tabular-nums' }
        },
        {
            field: 'orderNumber',
            headerName: 'PO Match',
            width: 220,
            cellRenderer: (p: import("ag-grid-community").ICellRendererParams<any>) => <POAllocationCell data={p.data} />
        },

        { field: 'packingSlipNumber', headerName: t('columns.packingSlip'), width: 140 },
        { field: 'notes', headerName: tCommon('columns.notes'), flex: 1, minWidth: 200 }
    ], [t, tCommon]);

    // Count unmatched (and not quarantined) in selection — quarantined items cannot be matched
    const matchableCount = selectedRows.filter((r) => r.matchStatus !== MATCH_STATUS.MATCHED && r.putawayStatus !== PUTAWAY_STATUS.QUARANTINED).length;
    const hasQuarantinedSelected = selectedRows.some((r) => r.putawayStatus === PUTAWAY_STATUS.QUARANTINED);

    return (
        <>
            <DataGrid 
                refreshTrigger={refreshKey}
                endpoint={gridEndpoint} 
                columns={gridColumns} 
                gridKey="goods-received-lines-list"
                defaultSortModel={[
                    { colId: 'putawayStatus', sort: 'asc' },
                    { colId: 'createdOn', sort: 'desc' }
                ]}
                fetchAll
                rowIdField="goodsReceivedLineId"
                rowSelection="multiple"
                onSelectionChanged={setSelectedRows}
                pageTitle={t('title')}
                headerFilters={
                    <FilterDropdown 
                        locations={locations}
                        selectedLocationId={selectedLocationId}
                        setSelectedLocationId={setSelectedLocationId}
                        days={days}
                        setDays={setDays}
                        t={t}
                        tCommon={tCommon}
                        defaultLocId={app?.defaultFulfillmentLocationId || ''}
                    />
                }
                headerActions={
                    <div className="flex lg:hidden flex-wrap items-center justify-start gap-3 w-full">
                        <Link href="/receiving/new" className="px-4 py-2 text-sm font-bold rounded-lg transition-all bg-[#006b5c] text-white hover:brightness-110 whitespace-nowrap">
                            {t('buttons.newReception')}
                        </Link>
                        <button
                            onClick={handleToggleQuarantine}
                            disabled={selectedRows.filter(r => r.putawayStatus !== PUTAWAY_STATUS.COMPLETED).length === 0}
                            className="px-4 py-2 text-sm font-bold rounded-lg transition-all border border-[var(--border)] text-[var(--text-secondary)] hover:bg-[var(--bg-card-hover)] disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
                        >
                            {t('buttons.quarantine')}
                        </button>
                        <button
                            onClick={handleCancelReceipt}
                            disabled={[...new Set(selectedRows.map(r => r.goodsReceivedId))].length !== 1 || selectedRows.some(r => r.putawayStatus === PUTAWAY_STATUS.COMPLETED)}
                            className="px-4 py-2 text-sm font-bold rounded-lg transition-all border border-[var(--border)] text-[var(--text-secondary)] hover:bg-[var(--bg-card-hover)] disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
                            title={t('buttons.cancelReceiptTooltip')}
                        >
                            {t('buttons.cancel')}
                        </button>
                        <button
                            onClick={handleAllocate}
                            disabled={matchableCount === 0}
                            title={hasQuarantinedSelected ? 'Quarantined items must be cleared before matching' : undefined}
                            className="px-4 py-2 text-sm font-bold rounded-lg transition-all bg-[var(--accent)] text-white hover:brightness-110 disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
                        >
                            {matchableCount > 0 ? t('buttons.matchCount', { count: matchableCount }) : t('buttons.match')}
                        </button>
                    </div>
                }
                secondaryHeader={
                    <div className="flex flex-wrap items-center justify-end gap-3 w-full pt-3">
                        <Link href="/receiving/new" className="px-4 py-2 text-sm font-bold rounded-lg transition-all bg-[#006b5c] text-white hover:brightness-110 whitespace-nowrap">
                            {t('buttons.newReception')}
                        </Link>
                        <div className="h-5 w-px bg-[rgba(196,198,205,0.4)] shrink-0"></div>
                        <button
                            onClick={handleToggleQuarantine}
                            disabled={selectedRows.filter(r => r.putawayStatus !== PUTAWAY_STATUS.COMPLETED).length === 0}
                            className="px-4 py-2 text-sm font-bold rounded-lg transition-all border border-[var(--border)] text-[var(--text-secondary)] hover:bg-[var(--bg-card-hover)] disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
                        >
                            {t('buttons.quarantine')}
                        </button>
                        <button
                            onClick={handleCancelReceipt}
                            disabled={[...new Set(selectedRows.map(r => r.goodsReceivedId))].length !== 1 || selectedRows.some(r => r.putawayStatus === PUTAWAY_STATUS.COMPLETED)}
                            className="px-4 py-2 text-sm font-bold rounded-lg transition-all border border-[var(--border)] text-[var(--text-secondary)] hover:bg-[var(--bg-card-hover)] disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
                            title={t('buttons.cancelReceiptTooltip')}
                        >
                            {t('buttons.cancel')}
                        </button>
                        <div className="h-5 w-px bg-[rgba(196,198,205,0.4)] shrink-0"></div>
                        <button
                            onClick={handleAllocate}
                            disabled={matchableCount === 0}
                            title={hasQuarantinedSelected ? 'Quarantined items must be cleared before matching' : undefined}
                            className="px-4 py-2 text-sm font-bold rounded-lg transition-all bg-[var(--accent)] text-white hover:brightness-110 disabled:opacity-50 disabled:cursor-not-allowed whitespace-nowrap"
                        >
                            {matchableCount > 0 ? t('buttons.matchCount', { count: matchableCount }) : t('buttons.match')}
                        </button>
                    </div>
                }
            />
            
            <AllocationSlideOver 
                isOpen={slideOverOpen} 
                onClose={handleSlideOverClose} 
                grLines={selectedRows} 
                onRefresh={triggerRefresh} 
            />
        </>
    );
}

'use client';

import React from 'react';
import { useRouter } from 'next/navigation';
import { useTranslations } from 'next-intl';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import StateBadge from '@/components/StateBadge';
import { formatAmount } from '@/lib/currency';
import { ValidState } from '@/types/states';
import Link from 'next/link';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import { useSalesInvoice } from './useSalesInvoice';
import MobileLineItemCard from '@/components/shared/MobileLineItemCard';

export default function InvoiceDetailContent({ id }: { id: string }) {
  const router = useRouter();
  const tCommon = useTranslations('common');
  const t = useTranslations('salesInvoices');
  const { invoice, loading, error } = useSalesInvoice(id);

  useDocumentTitle(invoice ? `Invoice ${invoice.invoiceNumber}` : t('loading'));

  if (loading) return <div className="p-8">{t('loadingEllipsis')}</div>;
  if (error) return <div className="p-8 text-red-500">{t('errorLoading', { message: error.message })}</div>;
  if (!invoice) return <div className="p-8 text-red-500">{t('notFound')}</div>;

  return (
    <DetailsLayout
      header={
        <EntityHeader
          title={invoice.invoiceNumber}
          subtitle={`Customer: ${invoice.customerName}`}
          onBack={() => router.push('/sales-invoices')}
          badges={<StateBadge state={invoice.stateCode as ValidState} />}
          actions={null}
        />
      }
    >
      <div className="flex flex-col gap-3">
        <div className="card">
          <h3 className="section-heading flex items-center gap-2 mb-4">
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined shrink-0">receipt_long</span>
            {/* eslint-enable i18next/no-literal-string */}
            <span>{t('invoiceDetails')}</span>
          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium mb-1" style={{ color: 'var(--text-muted)' }}>
                {t('customer')}
              </label>
              <div className="text-sm">
                {invoice.customerId ? (
                  <Link 
                    href={`/customers/${invoice.customerId}`} 
                    className="text-[var(--accent)] hover:underline font-medium"
                  >
                    {invoice.customerName || t('unknownCustomer')}
                  </Link>
                ) : (
                  invoice.customerName || t('unknownCustomer')
                )}
              </div>
            </div>
            <div>
              <label className="block text-xs font-medium mb-1" style={{ color: 'var(--text-muted)' }}>
                {t('orderNo')}
              </label>
              <div className="text-sm">
                {invoice.salesOrderId ? (
                  <Link
                    href={`/sales-orders/${invoice.salesOrderId}`}
                    className="text-[var(--accent)] hover:underline font-medium"
                  >
                    {invoice.orderNumber}
                  </Link>
                ) : (
                  invoice.orderNumber || '—'
                )}
              </div>
            </div>
            <div>
              <label className="block text-xs font-medium mb-1" style={{ color: 'var(--text-muted)' }}>
                {tCommon('columns.currency')}
              </label>
              <div className="text-sm">{invoice.currencyCode}</div>
            </div>
            <div>
              <label className="block text-xs font-medium mb-1" style={{ color: 'var(--text-muted)' }}>
                {t('date')}
              </label>
              <div className="text-sm">{new Date(invoice.createdOn).toLocaleDateString()}</div>
            </div>
            <div className="col-span-2 mt-2">
              <label className="block text-xs font-medium mb-1" style={{ color: 'var(--text-muted)' }}>
                {tCommon('notesCardHeading')}
              </label>
              {invoice.notes ? (
                <div className="text-sm bg-gray-50 p-3 rounded">{invoice.notes}</div>
              ) : (
                <div className="text-sm" style={{ color: 'var(--text-muted)' }}>—</div>
              )}
            </div>
          </div>
        </div>

        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading flex items-center gap-2">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined shrink-0">list</span>
              {/* eslint-enable i18next/no-literal-string */}
              <span>{t('lineItems')}</span>
            </h3>
          </div>
          {/* Desktop Table */}
          <div className="hidden sm:block overflow-x-auto">
            <table className="table-lines min-w-[600px]">
              <thead>
              <tr>
                <th style={{ width: 40 }}>#</th>
                <th style={{ width: 150 }}>{t('columns.product')}</th>
                <th>{t('columns.description')}</th>
                <th style={{ width: 90, textAlign: 'right' }}>{t('columns.qty')}</th>
                <th style={{ width: 110, textAlign: 'right' }}>{t('columns.price')}</th>
                <th style={{ width: 110, textAlign: 'right' }}>{t('columns.amount')}</th>
              </tr>
            </thead>
            <tbody>
              {invoice.lines?.map((line, idx) => (
                <tr key={line.lineId}>
                  <td style={{ color: 'var(--text-muted)' }}>{idx + 1}</td>
                  <td>
                    <div className="font-semibold" style={{ color: 'var(--accent)' }}>
                      {line.productNumber}
                    </div>
                  </td>
                  <td>{line.description || '—'}</td>
                  <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                    {parseFloat(line.quantityInvoiced)}
                  </td>
                  <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                    {formatAmount(parseFloat(line.pricePerUnit), invoice.currencyCode)}
                  </td>
                  <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                    {formatAmount(parseFloat(line.amount), invoice.currencyCode)}
                  </td>
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr style={{ borderTop: '2px solid var(--border)' }}>
                <td colSpan={5} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                  {tCommon('subtotal')}
                </td>
                <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                  {formatAmount(parseFloat(invoice.totalAmount) - parseFloat(invoice.taxAmount), invoice.currencyCode)}
                </td>
              </tr>
              <tr>
                <td colSpan={5} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                  {tCommon('tax')}
                </td>
                <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                  {formatAmount(parseFloat(invoice.taxAmount), invoice.currencyCode)}
                </td>
              </tr>
              <tr style={{ backgroundColor: 'rgba(59,130,246,0.02)' }}>
                <td colSpan={5} style={{ textAlign: 'right', fontWeight: 700, fontSize: 13, color: 'var(--text-primary)' }}>
                  {tCommon('total')}
                </td>
                <td style={{ textAlign: 'right', fontWeight: 800, fontSize: 14, color: 'var(--accent)', fontVariantNumeric: 'tabular-nums' }}>
                  {formatAmount(parseFloat(invoice.totalAmount), invoice.currencyCode)}
                </td>
              </tr>
            </tfoot>
          </table>
          </div>

          {/* Mobile Cards */}
          <div className="flex flex-col lg:hidden mt-2">
            {invoice.lines?.map((line, idx) => (
              <MobileLineItemCard
                key={line.lineId}
                title={line.productNumber}
                subtitle={line.description || '—'}
                topRightBadge={`#${idx + 1}`}
                details={[
                  {
                    label: t('columns.qty'),
                    value: parseFloat(line.quantityInvoiced)
                  },
                  {
                    label: t('columns.price'),
                    value: formatAmount(parseFloat(line.pricePerUnit), invoice.currencyCode)
                  },
                  {
                    label: t('columns.amount'),
                    value: formatAmount(parseFloat(line.amount), invoice.currencyCode),
                    isHighlighted: true
                  }
                ]}
              />
            ))}
            {(!invoice.lines || invoice.lines.length === 0) && (
              <div className="text-center text-sm text-[var(--text-muted)] py-4 border border-[var(--border)] rounded-lg">
                {tCommon('orderReadView.noLineItems')}
              </div>
            )}
            
            {/* Mobile Summary */}
            <div className="mt-2 bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4">
              <table className="w-full text-sm">
                <tbody>
                  <tr>
                    <td className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tCommon('subtotal')}</td>
                    <td className="py-1 text-sm font-semibold text-right tabular-nums">
                      {formatAmount(parseFloat(invoice.totalAmount) - parseFloat(invoice.taxAmount), invoice.currencyCode)}
                    </td>
                  </tr>
                  <tr>
                    <td className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tCommon('tax')}</td>
                    <td className="py-1 text-sm font-semibold text-right tabular-nums">
                      {formatAmount(parseFloat(invoice.taxAmount), invoice.currencyCode)}
                    </td>
                  </tr>
                  <tr>
                    <td className="py-2 text-sm font-bold text-[var(--accent)] text-right pr-4">{tCommon('total')}</td>
                    <td className="py-2 text-base font-bold text-[var(--accent)] text-right tabular-nums">
                      {formatAmount(parseFloat(invoice.totalAmount), invoice.currencyCode)}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </div>

        {/* Payment Allocations Card */}
        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading flex items-center gap-2">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined shrink-0">payments</span>
              {/* eslint-enable i18next/no-literal-string */}
              <span>{t('paymentAllocations')}</span>
            </h3>
          </div>
          <div className="overflow-x-auto -mx-5 sm:mx-0 px-5 sm:px-0">
            <p className="text-sm" style={{ color: 'var(--text-muted)' }}>
              {t('paymentAllocationsDesc')}
            </p>
          </div>
        </div>
      </div>
    </DetailsLayout>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import StateBadge from '@/components/StateBadge';
import { ValidState } from '@/types/states';
import { DataTable, MobileCardField } from '@/components/shared/DataTable';
import * as api from '@modbm/sdk';
import Link from 'next/link';

/**
 * FulfillmentSection — Combined read-only picking + shipping status
 * for the Sales Order detail page. Single table showing the full
 * fulfillment pipeline per line: Ordered → Picked → Shipped → Available.
 */

interface ShippingLine {
    salesOrderLineId: string;
    lineNumber: number;
    productId: string;
    productNumber: string;
    productDescription: string;
    isPhysical: boolean;
    quantity: string;
    quantityPicked: string;
    quantityShipped: string;
    availableToShip: string;
}

interface ShipmentSummary {
    shipmentId: string;
    shipmentNumber: string;
    stateCode: string;
    notes: string | null;
    trackingNumber: string | null;
    createdOn: string;
    lineCount: number;
}

interface ShippingContext {
    lines: ShippingLine[];
    shipments: ShipmentSummary[];
}

interface PickingSummaryLine {
    salesOrderLineId: string;
    lineNumber: number;
    productId: string;
    productNumber: string;
    productDescription: string;
    quantity: string;
    quantityPicked: string;
    remaining: string;
    isFullyPicked: boolean;
    isPhysical: boolean;
    onHand: string;
}

interface PickingSummary {
    totalLines: number;
    fullyPickedLines: number;
    isFullyPicked: boolean;
    lines: PickingSummaryLine[];
}

interface Props {
    orderId: string;
    pickingSummary: PickingSummary | null;
}

export default function FulfillmentSection({ orderId, pickingSummary }: Props) {
    const t = useTranslations('fulfillment');
    const tCommon = useTranslations('common');

    const [shippingCtx, setShippingCtx] = useState<ShippingContext | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        setLoading(true);
        api.orderPickingControllerGetShippingContext(orderId)
            .then((res) => setShippingCtx(res.data as unknown as ShippingContext))
            .catch(() => setShippingCtx(null))
            .finally(() => setLoading(false));
    }, [orderId]);

    const pickingMap = new Map(
        (pickingSummary?.lines ?? []).map(l => [l.salesOrderLineId, l])
    );

    const physicalLines = (shippingCtx?.lines ?? []).filter(l => l.isPhysical);

    return (
        <div id="fulfillment-section" className="card">
            <div className="flex items-center justify-between mb-4">
                <h3 className="section-heading">
                    {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined">local_shipping</span>
            {/* eslint-enable i18next/no-literal-string */}
                    {t('title')}
                </h3>
            </div>

            {loading ? (
                <div className="text-center py-6 text-sm" style={{ color: 'var(--text-muted)' }}>
                    {tCommon('loading')}
                </div>
            ) : !shippingCtx ? (
                <div className="text-center py-6 text-sm" style={{ color: 'var(--text-muted)' }}>
                    {t('noData')}
                </div>
            ) : (
                <>
                    <DataTable
                        data={physicalLines}
                        keyExtractor={(line) => line.salesOrderLineId}
                        columns={[
                            { header: t('columns.product') },
                            { header: t('columns.ordered'), align: 'right' },
                            { header: t('columns.picked'), align: 'right' },
                            { header: t('columns.onHand'), align: 'right' },
                            { header: t('columns.shipped'), align: 'right' },
                            { header: t('columns.readyToShip'), align: 'right' }
                        ]}
                        emptyMessage={t('noPhysicalLines')}
                        renderCustomRow={(line: any, idx: number) => {
                            const ordered = parseFloat(line.quantity);
                            const picked = parseFloat(line.quantityPicked);
                            const shipped = parseFloat(line.quantityShipped);
                            const available = parseFloat(line.availableToShip);
                            const pickLine = pickingMap.get(line.salesOrderLineId);
                            const onHand = pickLine ? parseFloat(pickLine.onHand) : null;
                            const isPicked = picked >= ordered;
                            const isShipped = shipped >= ordered;

                            return (
                                <tr key={line.salesOrderLineId} className={isShipped ? 'opacity-50' : ''}>
                                    <td>
                                        <div className="font-bold text-sm">
                                            {line.productId ? (
                                                <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                                    {line.productNumber}
                                                </Link>
                                            ) : line.productNumber}
                                        </div>
                                        <div className="text-xs text-[var(--text-muted)] truncate max-w-[250px]">{line.productDescription}</div>
                                    </td>
                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                        {ordered.toLocaleString()}
                                    </td>
                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                        <span className={isPicked ? 'text-[var(--success)]' : picked > 0 ? 'text-[var(--warning)]' : ''}>
                                            {picked.toLocaleString()}
                                        </span>
                                    </td>
                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: 'var(--text-muted)' }}>
                                        {onHand !== null ? onHand.toLocaleString() : '—'}
                                    </td>
                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                        <span className={isShipped ? 'text-[var(--success)]' : shipped > 0 ? 'text-[var(--warning)]' : ''}>
                                            {shipped.toLocaleString()}
                                        </span>
                                    </td>
                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                        <span className={available > 0 ? 'font-semibold text-[var(--accent)]' : 'text-[var(--text-muted)]'}>
                                            {available.toLocaleString()}
                                        </span>
                                    </td>
                                </tr>
                            );
                        }}
                        mobileCard={(line: any) => {
                            const ordered = parseFloat(line.quantity);
                            const picked = parseFloat(line.quantityPicked);
                            const shipped = parseFloat(line.quantityShipped);
                            const available = parseFloat(line.availableToShip);
                            const pickLine = pickingMap.get(line.salesOrderLineId);
                            const onHand = pickLine ? parseFloat(pickLine.onHand) : null;
                            const isPicked = picked >= ordered;
                            const isShipped = shipped >= ordered;

                            return (
                                <div className={`bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col ${isShipped ? 'opacity-60' : ''}`}>
                                    <div className="flex justify-between items-start gap-2 mb-2">
                                        <div className="font-semibold text-sm text-[var(--accent)]">
                                            {line.productId ? (
                                                <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                                    {line.productNumber}
                                                </Link>
                                            ) : line.productNumber}
                                        </div>
                                    </div>
                                    <div className="text-sm text-slate-600 font-medium mb-3">
                                        {line.productDescription}
                                    </div>
                                    <div className="flex flex-col gap-0 border-t border-slate-100 pt-1">
                                        <MobileCardField label={t('columns.ordered')} value={
                                            <span className="font-semibold">{ordered.toLocaleString()}</span>
                                        } />
                                        <MobileCardField label={t('columns.picked')} value={
                                            <span className={isPicked ? 'text-[var(--success)] font-semibold' : picked > 0 ? 'text-[var(--warning)] font-semibold' : ''}>
                                                {picked.toLocaleString()}
                                            </span>
                                        } />
                                        <MobileCardField label={t('columns.onHand')} value={
                                            <span className="text-[var(--text-muted)]">
                                                {onHand !== null ? onHand.toLocaleString() : '—'}
                                            </span>
                                        } />
                                        <MobileCardField label={t('columns.shipped')} value={
                                            <span className={isShipped ? 'text-[var(--success)] font-semibold' : shipped > 0 ? 'text-[var(--warning)] font-semibold' : ''}>
                                                {shipped.toLocaleString()}
                                            </span>
                                        } />
                                        <MobileCardField label={t('columns.readyToShip')} value={
                                            <span className={available > 0 ? 'font-semibold text-[var(--accent)]' : 'text-[var(--text-muted)]'}>
                                                {available.toLocaleString()}
                                            </span>
                                        } />
                                    </div>
                                </div>
                            );
                        }}
                    />

                </>
            )}
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { useTranslations } from 'next-intl';
import * as api from '@modbm/sdk';
import Link from 'next/link';
import { SALES_ORDER_STATE } from '@modbm/shared';
import { formatLocationDisplay } from '@/lib/formatters';

interface OrderDetailsCardProps {
    order: any;
    isOrderDetailsEditable: boolean;
    editName: string;
    setEditName: (val: string) => void;
    editPO: string;
    setEditPO: (val: string) => void;
    editFulfillmentLocationId: string;
    setEditFulfillmentLocationId: (val: string) => void;
    editNotes: string;
    setEditNotes: (val: string) => void;
    saveHeader: () => void;
    locations: any[];
    copyOrder: () => void;
    copying: boolean;
    onQuoteClick: () => void;
    reportError: (err: unknown, context: string) => void;
    setError: (err: string) => void;
}

export default function OrderDetailsCard({
    order,
    isOrderDetailsEditable,
    editName,
    setEditName,
    editPO,
    setEditPO,
    editFulfillmentLocationId,
    setEditFulfillmentLocationId,
    editNotes,
    setEditNotes,
    saveHeader,
    locations,
    copyOrder,
    copying,
    onQuoteClick,
    reportError,
    setError
}: OrderDetailsCardProps) {
    const tSales = useTranslations('salesOrders');
    const tCommon = useTranslations('common');
    const [menuOpen, setMenuOpen] = useState(false);

    return (
        <div className="card">
            <div className="flex items-center justify-between gap-4 mb-4">
                <h2 className="section-heading mb-0">
                    <span className="material-symbols-outlined">receipt_long</span>
                    {tSales('orderDetails')}
                </h2>
                <div className="relative">
                    <button
                        className="btn btn-secondary btn-sm px-2"
                        onClick={() => setMenuOpen(!menuOpen)}
                    >
                        <span className="material-symbols-outlined" style={{ fontSize: 20 }}>more_vert</span>
                    </button>
                    {menuOpen && (
                        <>
                            <div className="fixed inset-0 z-40" onClick={() => setMenuOpen(false)} />
                            <div 
                                className="absolute right-0 top-full mt-1 bg-[var(--bg-card)] border border-[var(--border)] rounded-md shadow-lg p-1 z-50 min-w-[150px] flex flex-col gap-1"
                                onClick={() => setMenuOpen(false)}
                            >
                                {(order.stateCode === SALES_ORDER_STATE.DRAFT || order.stateCode === SALES_ORDER_STATE.QUOTED) && (
                                    <button
                                        className="text-sm px-3 py-2 text-left hover:bg-[var(--bg-secondary)] rounded-md w-full transition-colors"
                                        onClick={onQuoteClick}
                                    >
                                        {tSales('buttons.createQuote')}
                                    </button>
                                )}
                                {(order.stateCode !== SALES_ORDER_STATE.DRAFT && order.stateCode !== SALES_ORDER_STATE.QUOTED) && (
                                    <button
                                        className="text-sm px-3 py-2 text-left hover:bg-[var(--bg-secondary)] rounded-md w-full transition-colors"
                                        onClick={async () => {
                                            try {
                                                const response = await api.reportsControllerRunHook('sales-order-confirmation', {}, { id: order.salesOrderId!, context: 'sales-order' });
                                                const blob = response.data ;
                                                const url = URL.createObjectURL(blob);
                                                window.open(url, '_blank');
                                            } catch (err) {
                                                reportError(err, 'OrderDetailPage:generateConfirmation');
                                                setError(err instanceof Error ? err.message : tCommon('errors.failedToGenerateReport'));
                                            }
                                        }}
                                    >
                                        {tSales('buttons.confirmationPdf')}
                                    </button>
                                )}
                                {(order.stateCode === SALES_ORDER_STATE.CONFIRMED || order.stateCode === SALES_ORDER_STATE.PICKING) && (
                                    <button
                                        className="text-sm px-3 py-2 text-left hover:bg-[var(--bg-secondary)] rounded-md w-full transition-colors"
                                        onClick={async () => {
                                            try {
                                                const response = await api.reportsControllerRunHook('pro-forma-invoice', {}, { id: order.salesOrderId!, context: 'sales-order' });
                                                const blob = response.data ;
                                                const url = URL.createObjectURL(blob);
                                                window.open(url, '_blank');
                                            } catch (err) {
                                                reportError(err, 'OrderDetailPage:generateProForma');
                                                setError(err instanceof Error ? err.message : tCommon('errors.failedToGenerateReport'));
                                            }
                                        }}
                                    >
                                        {tSales('buttons.proFormaInvoice')}
                                    </button>
                                )}
                                <button
                                    className="text-sm px-3 py-2 text-left hover:bg-[var(--bg-secondary)] rounded-md w-full transition-colors"
                                    onClick={copyOrder}
                                    disabled={copying}
                                >
                                    {copying ? tCommon('copying') : tSales('buttons.copyOrder')}
                                </button>
                            </div>
                        </>
                    )}
                </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="min-w-0">
                    <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                        {tSales('labels.customer')}
                        {order.currencyCode && (
                            <span
                                style={{
                                    marginLeft: 8,
                                    padding: '1px 6px',
                                    borderRadius: 4,
                                    background: 'rgba(59,130,246,0.15)',
                                    color: 'var(--accent)',
                                    fontWeight: 600,
                                    fontSize: 10,
                                    letterSpacing: '0.04em',
                                }}
                            >
                                {order.currencyCode}
                            </span>
                        )}
                    </label>
                    <p className="text-sm truncate" style={{ fontWeight: 500, paddingTop: 6 }}>
                        {order.customerName || order.customerId ? (
                            <Link 
                                href={`/customers/${order.customerId}`} 
                                style={{ color: 'var(--accent)', textDecoration: 'none' }}
                                className="hover:underline"
                            >
                                {order.customerName || <span style={{ fontStyle: 'italic' }}>{tSales('unnamedCustomer')}</span>}
                            </Link>
                        ) : (
                            '—'
                        )}
                    </p>
                </div>
                <div className="min-w-0">
                    <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                        {tSales('labels.created')}
                    </label>
                    <p className="text-sm truncate" style={{ fontWeight: 500, paddingTop: 6 }}>
                        {new Date(order.createdOn).toLocaleString()} {tCommon('by')} {order.createdBy || '—'}
                    </p>
                </div>
                <div className="min-w-0">
                    <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                        {tSales('labels.orderName')}
                    </label>
                    <input
                        className="input w-full"
                        disabled={!isOrderDetailsEditable}
                        value={editName}
                        onChange={(e) => setEditName(e.target.value)}
                        onBlur={saveHeader}
                        placeholder={tSales('placeholders.orderName')}
                    />
                </div>
                <div className="min-w-0">
                    <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                        {tSales('labels.customerPO')}
                    </label>
                    <input
                        className="input w-full"
                        disabled={!isOrderDetailsEditable}
                        value={editPO}
                        onChange={(e) => setEditPO(e.target.value)}
                        onBlur={saveHeader}
                        placeholder={tSales('placeholders.customerPO')}
                    />
                </div>
                <div className="min-w-0 md:col-span-2 lg:col-span-1">
                    <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                        {tSales('labels.fulfillmentLocation')}
                    </label>
                    <select
                        className="input w-full"
                        disabled={!isOrderDetailsEditable}
                        value={editFulfillmentLocationId}
                        onChange={(e) => setEditFulfillmentLocationId(e.target.value)}
                        onBlur={saveHeader}
                    >
                        {(locations || []).map((loc: { locationId: string; name: string; code?: string }) => (
                            <option key={loc.locationId} value={loc.locationId}>
                                {formatLocationDisplay(loc)}
                            </option>
                        ))}
                    </select>
                </div>
                <div className="min-w-0 col-span-1 md:col-span-2">
                    <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                        {tCommon('notesCardHeading')}
                    </label>
                    <input
                        className="input w-full"
                        disabled={!isOrderDetailsEditable}
                        value={editNotes}
                        onChange={(e) => setEditNotes(e.target.value)}
                        onBlur={saveHeader}
                        placeholder={tCommon('notesCardPlaceholder')}
                    />
                </div>
            </div>
        </div>
    );
}

'use client';

import { useTranslations } from 'next-intl';
import StateBadge from '@/components/StateBadge';
import { ValidState } from '@/types/states';
import Link from 'next/link';
import { DataTable, MobileCardField } from '@/components/shared/DataTable';

/**
 * PickingStatusSection — Read-only picking status for the Sales Order detail page.
 * Shows picking progress per line (ordered, picked, remaining, on-hand).
 */

interface PickingSummaryLine {
    salesOrderLineId: string;
    lineNumber: number;
    productId: string;
    productNumber: string;
    productDescription: string;
    quantity: string;
    quantityPicked: string;
    quantityShipped: string;
    remaining: string;
    isFullyPicked: boolean;
    isPhysical: boolean;
    onHand: string;
}

interface PickingSummary {
    totalLines: number;
    fullyPickedLines: number;
    isFullyPicked: boolean;
    lines: PickingSummaryLine[];
}

interface Props {
    pickingSummary: PickingSummary | null;
}

export default function PickingStatusSection({ pickingSummary }: Props) {
    const tPicking = useTranslations('picking');
    const tCommon = useTranslations('common');

    if (!pickingSummary) {
        return (
            <div className="text-center py-6 text-sm" style={{ color: 'var(--text-muted)' }}>
                {tCommon('loading')}
            </div>
        );
    }

    const physicalLines = pickingSummary.lines.filter(l => l.isPhysical);
    const fullyPicked = physicalLines.filter(l => l.isFullyPicked).length;

    return (
        <div id="picking-section" className="card">
            <div className="flex items-center justify-between mb-4">
                <h3 className="section-heading">
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined">inventory</span>
                    {/* eslint-enable i18next/no-literal-string */}
                    {tPicking('title')}
                </h3>
                <div className="flex items-center gap-2">
                    <span className="bg-[var(--accent)] text-white text-xs font-bold px-2 py-0.5 rounded-full">
                        {fullyPicked} / {physicalLines.length}
                    </span>
                    {pickingSummary.isFullyPicked && (
                        <span className="text-xs font-bold text-[var(--success)]">
                            {/* eslint-disable-next-line i18next/no-literal-string */}
                            <span className="material-symbols-outlined text-sm align-middle mr-0.5">check_circle</span>
                            {/* eslint-enable i18next/no-literal-string */}
                            {tPicking('statuses.done')}
                        </span>
                    )}
                </div>
            </div>

            <DataTable
                data={physicalLines}
                keyExtractor={(line) => line.salesOrderLineId}
                columns={[
                    { header: tPicking('columns.product') },
                    { header: tPicking('columns.ordered'), align: 'right' },
                    { header: tPicking('columns.picked'), align: 'right' },
                    { header: tPicking('columns.remaining'), align: 'right' },
                    { header: tPicking('columns.onHand'), align: 'right' },
                    { header: tPicking('columns.status'), align: 'center' }
                ]}
                emptyMessage={tPicking('noPhysicalLines')}
                renderCustomRow={(line) => {
                    const remaining = parseFloat(line.remaining);
                    return (
                        <tr key={line.salesOrderLineId} className={line.isFullyPicked ? 'opacity-60' : ''}>
                            <td>
                                <div className="font-bold text-sm">
                                    {line.productId ? (
                                        <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                            {line.productNumber}
                                        </Link>
                                    ) : line.productNumber}
                                </div>
                                <div className="text-xs text-[var(--text-muted)] truncate max-w-[250px]">{line.productDescription}</div>
                            </td>
                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                {parseFloat(line.quantity).toLocaleString()}
                            </td>
                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                {parseFloat(line.quantityPicked).toLocaleString()}
                            </td>
                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                <span className={remaining > 0 ? 'font-semibold text-[var(--warning)]' : 'text-[var(--text-muted)]'}>
                                    {remaining.toLocaleString()}
                                </span>
                            </td>
                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                {parseFloat(line.onHand).toLocaleString()}
                            </td>
                            <td style={{ textAlign: 'center' }}>
                                {line.isFullyPicked ? (
                                    <>
                                        {/* eslint-disable-next-line i18next/no-literal-string */}
                                        <span className="material-symbols-outlined text-[var(--success)] text-base" style={{ fontVariationSettings: "'FILL' 1" }}>check_circle</span>
                                        {/* eslint-enable i18next/no-literal-string */}
                                    </>
                                ) : remaining > 0 ? (
                                    <>
                                        {/* eslint-disable-next-line i18next/no-literal-string */}
                                        <span className="material-symbols-outlined text-[var(--warning)] text-base">pending</span>
                                        {/* eslint-enable i18next/no-literal-string */}
                                    </>
                                ) : null}
                            </td>
                        </tr>
                    );
                }}
                mobileCard={(line) => {
                    const remaining = parseFloat(line.remaining);
                    return (
                        <div className={`bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col ${line.isFullyPicked ? 'opacity-60' : ''}`}>
                            <div className="flex justify-between items-start gap-2 mb-2">
                                <div className="font-semibold text-sm text-[var(--accent)]">
                                    {line.productId ? (
                                        <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                            {line.productNumber}
                                        </Link>
                                    ) : line.productNumber}
                                </div>
                                <div>
                                    {line.isFullyPicked ? (
                                        <span className="material-symbols-outlined text-[var(--success)] text-base" style={{ fontVariationSettings: "'FILL' 1" }}>check_circle</span>
                                    ) : remaining > 0 ? (
                                        <span className="material-symbols-outlined text-[var(--warning)] text-base">pending</span>
                                    ) : null}
                                </div>
                            </div>
                            <div className="text-sm text-slate-600 font-medium mb-3">
                                {line.productDescription}
                            </div>

                            <div className="flex flex-col gap-0 border-t border-slate-100 pt-1">
                                <MobileCardField label={tPicking('columns.ordered')} value={
                                    <span className="font-semibold">{parseFloat(line.quantity).toLocaleString()}</span>
                                } />
                                <MobileCardField label={tPicking('columns.picked')} value={
                                    <span>{parseFloat(line.quantityPicked).toLocaleString()}</span>
                                } />
                                <MobileCardField label={tPicking('columns.remaining')} value={
                                    <span className={remaining > 0 ? 'font-semibold text-[var(--warning)]' : 'text-[var(--text-muted)]'}>
                                        {remaining.toLocaleString()}
                                    </span>
                                } />
                                <MobileCardField label={tPicking('columns.onHand')} value={
                                    <span>{parseFloat(line.onHand).toLocaleString()}</span>
                                } />
                            </div>
                        </div>
                    );
                }}
            />
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import * as api from '@modbm/sdk';
import { getErrorMessage } from '@modbm/shared';


interface Macro {
  macroId: string;
  name: string;
  macroType: string;
  content: string;
}

interface QuoteGenerationDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onGenerate: (text: string) => Promise<void>;
}

export default function QuoteGenerationDialog({ isOpen, onClose, onGenerate }: QuoteGenerationDialogProps) {
  const t = useTranslations('salesOrders');
  const tCommon = useTranslations('common');
  const tSettings = useTranslations('admin.settings');

  const [macros, setMacros] = useState<Macro[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [selectedMacroId, setSelectedMacroId] = useState<string>('');
  const [customText, setCustomText] = useState('');
  const [generating, setGenerating] = useState(false);

  useEffect(() => {
    if (isOpen) {
      loadMacros();
      setSelectedMacroId('');
      setCustomText('');
      setError(null);
    }
  }, [isOpen]);

  const loadMacros = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await api.macrosControllerFindAll({ macroType: 'text_template' } );
      const data = res.data;
      const textMacros = data.filter((m: any) => m.macroType === 'text_template');
      setMacros(textMacros);
    } catch (err: unknown) {
      setError(getErrorMessage(err) || 'Failed to load macros');
    } finally {
      setLoading(false);
    }
  };

  const handleMacroChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const id = e.target.value;
    setSelectedMacroId(id);
    const macro = macros.find(m => m.macroId === id);
    if (macro) {
      setCustomText(macro.content);
    }
  };

  const handleGenerate = async () => {
    setGenerating(true);
    setError(null);
    try {
      await onGenerate(customText);
      onClose();
    } catch (err: unknown) {
      setError(getErrorMessage(err) || 'Failed to generate quote');
    } finally {
      setGenerating(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-md flex flex-col overflow-hidden">
        <div className="px-6 py-4 border-b border-gray-200 flex justify-between items-center bg-gray-50">
          <h2 className="text-xl font-bold text-gray-900">{t('generateQuoteTitle')}</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined">close</span>
            {/* eslint-enable i18next/no-literal-string */}
          </button>
        </div>
        
        <div className="p-6 flex flex-col gap-4">
          {error && (
            <div className="p-3 rounded bg-red-50 text-red-700 text-sm border border-red-200">
              {error}
            </div>
          )}

          <div>
            <label className="block text-sm font-medium mb-1 text-gray-700">
              {t('labels.quoteMacro')}
            </label>
            {loading ? (
              <div className="text-sm text-gray-500">{tCommon('loading')}</div>
            ) : (
              <select
                className="input w-full"
                value={selectedMacroId}
                onChange={handleMacroChange}
              >
                <option value="">{t('placeholders.selectMacro')}</option>
                {macros.map(m => (
                  <option key={m.macroId} value={m.macroId}>
                    {m.name}
                  </option>
                ))}
              </select>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium mb-1 text-gray-700">
              {t('labels.quoteText')}
            </label>
            <textarea
              className="input w-full font-sans text-sm"
              rows={6}
              value={customText}
              onChange={(e) => setCustomText(e.target.value)}
              placeholder={t('placeholders.quoteText') || 'Enter text to display on the quote PDF...'}
            />
          </div>

          <div className="flex justify-end gap-2 mt-4 pt-4 border-t border-gray-100">
            <button
              className="btn btn-secondary"
              onClick={onClose}
              disabled={generating}
            >
              {tCommon('cancel')}
            </button>
            <button
              className="btn btn-primary flex items-center gap-2"
              onClick={handleGenerate}
              disabled={generating}
            >
              {generating && (
                <>
                  {/* eslint-disable-next-line i18next/no-literal-string */}
                  <span className="material-symbols-outlined animate-spin text-sm">progress_activity</span>
                  {/* eslint-enable i18next/no-literal-string */}
                </>
              )}
              {t('buttons.generate')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useTranslations } from 'next-intl';
import { useEffect, useState } from 'react';
import { DataTable, MobileCardField } from '@/components/shared/DataTable';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import { formatAmount } from '@/lib/currency';
import { computeLinePrice, computeReturnCreditSummary } from '@modbm/shared';
import { formatLocationDisplay } from '@/lib/formatters';

import type { OrderDetail, OrderReturn, TaxCategory } from './types';
import {
    RETURN_STATE,
    RETURN_TRANSITIONS,
    RETURN_LIFECYCLE,
    SALES_ORDER_STATE,
    isBackTransition as sharedIsBackTransition,
} from '@modbm/shared';
import StateBadge, { StateName } from '@/components/StateBadge';
import { ValidState } from '@/types/states';
import { useSettings } from '@/components/SettingsProvider';

function PurchaseReturnStateBadge({ state }: { state: ValidState }) {
    const t = useTranslations('common.states');
    return <span className={`badge badge-${state}`}>{t(state)}</span>;
}

interface NewReturnLine {
    salesOrderLineId: string;
    quantityReturned: string;
    reason: string;
    returnFee: string;
    feeMode: 'absolute' | 'percentage';
    originalAmount: number;
}

interface ReturnsSectionProps {
    orderId: string;
    order: OrderDetail;
    returns: OrderReturn[];
    returnsLoading: boolean;
    showCreateReturn: boolean;
    setShowCreateReturn: (v: boolean) => void;
    setError: (msg: string) => void;
    loadReturns: () => Promise<void>;
    loadOrder: (autoTransitions?: any[], showSpinner?: boolean) => Promise<void>;
    pickingSummary?: any;
    taxCategories: TaxCategory[];
    locations: { locationId: string; name: string; code?: string }[];
}

export default function ReturnsSection({
    orderId, order, returns, returnsLoading,
    showCreateReturn, setShowCreateReturn,
    setError, loadReturns, loadOrder, pickingSummary, taxCategories, locations,
}: ReturnsSectionProps) {
  const { baseCurrency } = useSettings();
    const t = useTranslations();
    const tCommon = useTranslations('common');
    const tSales = useTranslations('salesOrders');
    const tConfirm = useTranslations('confirm');

    // Local state
    const [saving, setSaving] = useState(false);
    const [returnLocations, setReturnLocations] = useState<Record<string, string>>({});
    const [newReturnNotes, setNewReturnNotes] = useState('');
    const [newReturnLines, setNewReturnLines] = useState<NewReturnLine[]>(() =>
        order.lines.map((l) => ({
            salesOrderLineId: l.salesOrderLineId,
            quantityReturned: '',
            reason: '',
            returnFee: '0',
            feeMode: 'absolute' as const,
            originalAmount: parseFloat(l.amount || '0'),
        })),
    );

    const handleCancel = () => {
        setShowCreateReturn(false);
        setNewReturnLines(
            order.lines.map((l) => ({
                salesOrderLineId: l.salesOrderLineId,
                quantityReturned: '',
                reason: '',
                returnFee: '0',
                feeMode: 'absolute' as const,
                originalAmount: parseFloat(l.amount || '0'),
            })),
        );
        setNewReturnNotes('');
    };

    const handleSave = async () => {
        setSaving(true);
        setError('');
        try {
            const lines = newReturnLines
                .filter((l) => l.quantityReturned && parseFloat(l.quantityReturned) > 0)
                .map((l) => ({
                    salesOrderLineId: l.salesOrderLineId,
                    quantityReturned: l.quantityReturned,
                    reason: l.reason || undefined,
                    returnFee: l.returnFee || '0',
                }));
            await api.orderReturnsControllerCreateReturn(orderId, {
                notes: newReturnNotes || undefined,
                lines: lines ,
            });
            handleCancel();
            await loadReturns();
            await loadOrder(undefined, false);
        } catch (err) {
            setError(err instanceof Error ? err.message : tCommon('errors.failedToCreateReturn'));
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="card">
            <div className="flex items-center justify-between mb-2">
                <h3 className="section-heading">
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined">assignment_return</span>
                    {tSales('returnsHeading')}
                </h3>
                {!showCreateReturn && [
                    SALES_ORDER_STATE.PICKING,
                    SALES_ORDER_STATE.SHIPPED, 
                    SALES_ORDER_STATE.INVOICED, 
                    SALES_ORDER_STATE.LEGACY
                ].includes(order.stateCode as any) && (
                    <button
                        className="btn btn-secondary btn-sm"
                        onClick={() => setShowCreateReturn(true)}
                    >
                        {tSales('buttons.createReturn')}
                    </button>
                )}
            </div>

            {/* Create return form */}
            {showCreateReturn && (
                <div style={{ marginBottom: 16, padding: 16, borderRadius: 8, background: 'rgba(59, 130, 246, 0.05)', border: '1px solid rgba(59, 130, 246, 0.2)' }}>
                    <div className="flex items-center justify-between mb-3">
                        <strong style={{ fontSize: 13, display: 'flex', alignItems: 'center', gap: 6 }}>
                            {/* eslint-disable-next-line i18next/no-literal-string */}
                            <span className="material-symbols-outlined text-[16px]">assignment_return</span>
                            {tSales('newReturn')}
                        </strong>
                        <button
                            style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: 16 }}
                            onClick={handleCancel}
                        >
                            {/* eslint-disable-next-line i18next/no-literal-string */}
                            <span aria-hidden>✕</span>
                        </button>
                    </div>

                    <div style={{ marginBottom: 12 }}>
                        <input
                            className="input w-full"
                            value={newReturnNotes}
                            onChange={(e) => setNewReturnNotes(e.target.value)}
                            placeholder={tSales('placeholders.returnNotes')}
                        />
                    </div>

                    <DataTable
                        data={order.lines}
                        keyExtractor={(line: any) => line.salesOrderLineId}
                        columns={[
                            { header: tSales('columns.lineNumber'), width: 40 },
                            { header: tSales('columns.product') },
                            { header: tSales('columns.description') },
                            { header: tSales('columns.shipped'), width: 90, align: 'right' },
                            { header: tSales('columns.returnQty'), width: 100, align: 'right' },
                            { header: tSales('columns.reason'), width: 180 },
                            { header: tSales('columns.fee'), width: 140, align: 'right' }
                        ]}
                        renderCustomRow={(line: any, idx: number) => {
                            const rl = newReturnLines[idx];
                            if (!rl) return null;
                            const pLine = pickingSummary?.lines?.find((pl: any) => pl.salesOrderLineId === line.salesOrderLineId);
                            const shippedQty = pLine && pLine.quantityShipped != null ? parseFloat(pLine.quantityShipped) : 0;
                            return (
                                <tr key={line.salesOrderLineId}>
                                    <td style={{ color: 'var(--text-muted)' }}>{line.lineNumber}</td>
                                    <td style={{ fontWeight: 600, fontSize: 12 }}>
                                        {line.productNumber || line.productId?.substring(0, 8) || '—'}
                                    </td>
                                    <td>{line.productDescription || '—'}</td>
                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                        {shippedQty}
                                    </td>
                                    <td style={{ textAlign: 'right' }}>
                                        <input
                                            className="input"
                                            type="number"
                                            min="0"
                                            max={shippedQty || line.quantity}
                                            step="1"
                                            style={{
                                                width: 70, padding: '2px 6px', borderRadius: 4,
                                                border: '1px solid var(--border)', background: 'var(--surface)',
                                                color: 'var(--text)', fontSize: 13, textAlign: 'right',
                                            }}
                                            value={rl.quantityReturned}
                                            onChange={(e) => {
                                                const updated = [...newReturnLines];
                                                updated[idx] = { ...rl, quantityReturned: e.target.value };
                                                setNewReturnLines(updated);
                                            }}
                                            placeholder={tSales('placeholders.zero')}
                                        />
                                    </td>
                                    <td>
                                        <input
                                            className="input"
                                            style={{ width: '100%' }}
                                            value={rl.reason}
                                            onChange={(e) => {
                                                const updated = [...newReturnLines];
                                                updated[idx] = { ...rl, reason: e.target.value };
                                                setNewReturnLines(updated);
                                            }}
                                            placeholder={tSales('placeholders.reason')}
                                        />
                                    </td>
                                    <td style={{ textAlign: 'right' }}>
                                        <div className="flex items-center gap-1 justify-end">
                                            <select
                                                className="input"
                                                style={{ width: 50, fontSize: 11, padding: '4px 6px' }}
                                                value={rl.feeMode}
                                                onChange={(e) => {
                                                    const updated = [...newReturnLines];
                                                    const mode = e.target.value as 'absolute' | 'percentage';
                                                    if (mode === 'percentage' && rl.feeMode === 'absolute') {
                                                        const pct = rl.originalAmount > 0
                                                            ? ((parseFloat(rl.returnFee || '0') / rl.originalAmount) * 100).toFixed(1)
                                                            : '0';
                                                        updated[idx] = { ...rl, feeMode: mode, returnFee: pct };
                                                    } else if (mode === 'absolute' && rl.feeMode === 'percentage') {
                                                        const abs = (rl.originalAmount * parseFloat(rl.returnFee || '0') / 100).toFixed(2);
                                                        updated[idx] = { ...rl, feeMode: mode, returnFee: abs };
                                                    }
                                                    setNewReturnLines(updated);
                                                }}
                                            >
                                                <option value="absolute">$</option>
                                                <option value="percentage">%</option>
                                            </select>
                                            <input
                                                className="input"
                                                type="number"
                                                min="0"
                                                step="0.01"
                                                style={{ width: 80, textAlign: 'right' }}
                                                value={rl.returnFee}
                                                onChange={(e) => {
                                                    const updated = [...newReturnLines];
                                                    updated[idx] = { ...rl, returnFee: e.target.value };
                                                    setNewReturnLines(updated);
                                                }}
                                                onBlur={() => {
                                                    if (rl.feeMode === 'percentage') {
                                                        const updated = [...newReturnLines];
                                                        const abs = (rl.originalAmount * parseFloat(rl.returnFee || '0') / 100).toFixed(2);
                                                        updated[idx] = { ...rl, feeMode: 'absolute', returnFee: abs };
                                                        setNewReturnLines(updated);
                                                    }
                                                }}
                                            />
                                        </div>
                                    </td>
                                </tr>
                            );
                        }}
                        mobileCard={(line: any, idx: number) => {
                            const rl = newReturnLines[idx];
                            if (!rl) return null;
                            const pLine = pickingSummary?.lines?.find((pl: any) => pl.salesOrderLineId === line.salesOrderLineId);
                            const shippedQty = pLine && pLine.quantityShipped != null ? parseFloat(pLine.quantityShipped) : 0;
                            return (
                                <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col">
                                    <div className="flex justify-between items-start gap-2 mb-2">
                                        <div className="font-semibold text-sm text-[var(--accent)]">
                                            {line.productNumber || line.productId?.substring(0, 8) || '—'}
                                        </div>
                                        <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">#{line.lineNumber}</div>
                                    </div>
                                    <div className="text-sm text-slate-600 font-medium mb-3">
                                        {line.productDescription || '—'}
                                    </div>
                                    
                                    <div className="flex flex-col gap-0 border-t border-slate-100 pt-1">
                                        <MobileCardField label={tSales('columns.shipped')} value={
                                            <span>{shippedQty}</span>
                                        } />
                                        
                                        <div className="flex justify-between items-center py-2">
                                            <span className="text-xs font-medium text-slate-500">{tSales('columns.returnQty')}</span>
                                            <input
                                                className="input"
                                                type="number"
                                                min="0"
                                                max={shippedQty || line.quantity}
                                                step="1"
                                                style={{
                                                    width: 70, padding: '2px 6px', borderRadius: 4,
                                                    border: '1px solid var(--border)', background: 'var(--surface)',
                                                    color: 'var(--text)', fontSize: 13, textAlign: 'right',
                                                }}
                                                value={rl.quantityReturned}
                                                onChange={(e) => {
                                                    const updated = [...newReturnLines];
                                                    updated[idx] = { ...rl, quantityReturned: e.target.value };
                                                    setNewReturnLines(updated);
                                                }}
                                                placeholder={tSales('placeholders.zero')}
                                            />
                                        </div>
                                        
                                        <div className="flex flex-col gap-1 py-2">
                                            <span className="text-xs font-medium text-slate-500">{tSales('columns.reason')}</span>
                                            <input
                                                className="input"
                                                style={{ width: '100%' }}
                                                value={rl.reason}
                                                onChange={(e) => {
                                                    const updated = [...newReturnLines];
                                                    updated[idx] = { ...rl, reason: e.target.value };
                                                    setNewReturnLines(updated);
                                                }}
                                                placeholder={tSales('placeholders.reason')}
                                            />
                                        </div>
                                        
                                        <div className="flex justify-between items-center py-2 border-t border-slate-100 mt-1">
                                            <span className="text-xs font-medium text-slate-500">{tSales('columns.fee')}</span>
                                            <div className="flex items-center gap-1 justify-end">
                                                <select
                                                    className="input"
                                                    style={{ width: 50, fontSize: 11, padding: '4px 6px' }}
                                                    value={rl.feeMode}
                                                    onChange={(e) => {
                                                        const updated = [...newReturnLines];
                                                        const mode = e.target.value as 'absolute' | 'percentage';
                                                        if (mode === 'percentage' && rl.feeMode === 'absolute') {
                                                            const pct = rl.originalAmount > 0
                                                                ? ((parseFloat(rl.returnFee || '0') / rl.originalAmount) * 100).toFixed(1)
                                                                : '0';
                                                            updated[idx] = { ...rl, feeMode: mode, returnFee: pct };
                                                        } else if (mode === 'absolute' && rl.feeMode === 'percentage') {
                                                            const abs = (rl.originalAmount * parseFloat(rl.returnFee || '0') / 100).toFixed(2);
                                                            updated[idx] = { ...rl, feeMode: mode, returnFee: abs };
                                                        }
                                                        setNewReturnLines(updated);
                                                    }}
                                                >
                                                    <option value="absolute">$</option>
                                                    <option value="percentage">%</option>
                                                </select>
                                                <input
                                                    className="input"
                                                    type="number"
                                                    min="0"
                                                    step="0.01"
                                                    style={{ width: 80, textAlign: 'right' }}
                                                    value={rl.returnFee}
                                                    onChange={(e) => {
                                                        const updated = [...newReturnLines];
                                                        updated[idx] = { ...rl, returnFee: e.target.value };
                                                        setNewReturnLines(updated);
                                                    }}
                                                    onBlur={() => {
                                                        if (rl.feeMode === 'percentage') {
                                                            const updated = [...newReturnLines];
                                                            const abs = (rl.originalAmount * parseFloat(rl.returnFee || '0') / 100).toFixed(2);
                                                            updated[idx] = { ...rl, feeMode: 'absolute', returnFee: abs };
                                                            setNewReturnLines(updated);
                                                        }
                                                    }}
                                                />
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            );
                        }}
                        footer={(() => {
                            const activeFLines = newReturnLines.filter(l => l.quantityReturned && parseFloat(l.quantityReturned) > 0);
                            if (activeFLines.length === 0) return null;
                            const cc = order.currencyCode || 'AUD';
                            const summary = computeReturnCreditSummary(
                                activeFLines.map((rl) => {
                                    const origLine = order.lines.find(l => l.salesOrderLineId === rl.salesOrderLineId);
                                    const taxCat = taxCategories.find(c => c.taxCategoryId === origLine?.taxCategoryId);
                                    return {
                                        quantity: parseFloat(rl.quantityReturned || '0'),
                                        pricePerUnit: parseFloat(origLine?.pricePerUnit || '0'),
                                        discountPercentage: parseFloat(origLine?.discountPercentage || '0'),
                                        taxRate: parseFloat(taxCat?.rate || '0'),
                                        returnFee: parseFloat(rl.returnFee || '0'),
                                    };
                                }),
                            );
                            const { subtotal, totalTax, totalFees, netCredit } = summary;
                            return (
                                <>
                                    <tr className="hidden lg:table-row" style={{ borderTop: '2px solid var(--border)' }}>
                                        <td colSpan={5} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                            {tSales('returns.totalCredit')}
                                        </td>
                                        <td></td>
                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                            {formatAmount(subtotal, cc)}
                                        </td>
                                    </tr>
                                    <tr className="hidden lg:table-row">
                                        <td colSpan={5} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                            {tSales('columns.tax')}
                                        </td>
                                        <td></td>
                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                            {formatAmount(totalTax, cc)}
                                        </td>
                                    </tr>
                                    <tr className="hidden lg:table-row">
                                        <td colSpan={5} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                            {tSales('returns.totalFees')}
                                        </td>
                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                            {totalFees > 0 ? `−${formatAmount(totalFees, cc)}` : formatAmount(0, cc)}
                                        </td>
                                        <td></td>
                                    </tr>
                                    <tr className="hidden lg:table-row">
                                        <td colSpan={5} style={{ textAlign: 'right', fontWeight: 700, fontSize: 13 }}>
                                            {tSales('returns.netCredit')}
                                        </td>
                                        <td></td>
                                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 700, fontSize: 13 }}>
                                            {formatAmount(netCredit, cc)}
                                        </td>
                                    </tr>
                                    
                                    <tr className="lg:hidden">
                                        <td colSpan={6} className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tSales('returns.totalCredit')}</td>
                                        <td className="py-1 text-sm font-semibold text-right tabular-nums">{formatAmount(subtotal, cc)}</td>
                                    </tr>
                                    <tr className="lg:hidden">
                                        <td colSpan={6} className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tSales('columns.tax')}</td>
                                        <td className="py-1 text-sm font-semibold text-right tabular-nums">{formatAmount(totalTax, cc)}</td>
                                    </tr>
                                    <tr className="lg:hidden">
                                        <td colSpan={6} className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tSales('returns.totalFees')}</td>
                                        <td className="py-1 text-sm font-semibold text-right tabular-nums">{totalFees > 0 ? `−${formatAmount(totalFees, cc)}` : formatAmount(0, cc)}</td>
                                    </tr>
                                    <tr className="lg:hidden">
                                        <td colSpan={6} className="py-2 text-sm font-bold text-[var(--accent)] text-right pr-4">{tSales('returns.netCredit')}</td>
                                        <td className="py-2 text-base font-bold text-[var(--accent)] text-right tabular-nums">{formatAmount(netCredit, cc)}</td>
                                    </tr>
                                </>
                            );
                        })()}
                    />

                    <div className="flex items-center gap-2">
                        <button
                            className="btn btn-primary btn-sm"
                            disabled={saving || newReturnLines.every((l) => !l.quantityReturned || parseFloat(l.quantityReturned) <= 0)}
                            onClick={handleSave}
                        >
                            {tSales('buttons.saveReturn')}
                        </button>
                        <button className="btn btn-secondary btn-sm" onClick={handleCancel}>
                            {tCommon('cancel')}
                        </button>
                    </div>
                </div>
            )}

            {/* Existing returns list */}
            {returnsLoading ? (
                <p className="text-sm" style={{ color: 'var(--text-muted)' }}>{tSales('loadingReturns')}</p>
            ) : returns.length === 0 && !showCreateReturn ? (
                <div className="text-center py-6 text-sm" style={{ color: 'var(--text-muted)' }}>
                    {tSales('noReturns')}
                </div>
            ) : (
                <div className="space-y-3">
                    {returns.map((ret) => {
                        let allowedRetTransitions = RETURN_TRANSITIONS[ret.stateCode] || [];
                        if (ret.stateCode === RETURN_STATE.CONFIRMED || ret.stateCode === RETURN_STATE.PARTIALLY_RECEIVED) {
                            allowedRetTransitions = allowedRetTransitions.filter((s: string) => s !== RETURN_STATE.RECEIVED && s !== RETURN_STATE.PARTIALLY_RECEIVED);
                        }
                        const isRetEditable = ret.stateCode === RETURN_STATE.DRAFT;
                        return (
                            <div
                                key={ret.returnId}
                                style={{
                                    padding: 14,
                                    borderRadius: 8,
                                    border: '1px solid var(--border)',
                                    background: 'var(--bg-card, #fff)',
                                }}
                            >
                                <div className="flex items-center justify-between mb-3">
                                    <div className="flex items-center gap-3">
                                        <span style={{ fontWeight: 700, fontSize: 13 }}>{ret.returnNumber}</span>
                                        <PurchaseReturnStateBadge state={ret.stateCode as ValidState} />
                                        <span className="text-xs" style={{ color: 'var(--text-muted)' }}>
                                            {new Date(ret.createdOn).toLocaleString()}
                                            {ret.createdBy && ` ${tCommon('by')} ${ret.createdBy}`}
                                        </span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <div className="flex gap-2">
                                        {allowedRetTransitions.map((s: string) => (
                                            <button
                                                key={s}
                                                className={`btn btn-sm ${s === 'cancelled' ? 'btn-danger' : 'btn-primary'}`}
                                                onClick={async () => {
                                                    if (s === RETURN_STATE.PROCESSED) {
                                                        if (!confirm(tConfirm('processReturn'))) return;
                                                    }
                                                    try {
                                                        await api.orderReturnsControllerChangeReturnState(orderId, ret.returnId, {
                                                            stateCode: s
                                                        });
                                                        await loadReturns();
                                                        await loadOrder(undefined, false);
                                                    } catch (err) {
                                                        setError(err instanceof Error ? err.message : tCommon('errors.failedToChangeReturnState'));
                                                    }
                                                }}
                                            >
                                                → <StateName state={s as ValidState} />
                                            </button>
                                        ))}
                                        <button
                                            className="btn btn-secondary btn-sm"
                                            onClick={async () => {
                                                try {
                                                    const response = await api.reportsControllerRunHook('return-slip', {}, { id: ret.returnId, context: 'sales-return' });
                                                    const blob = response.data ;
                                                    const url = URL.createObjectURL(blob);
                                                    window.open(url, '_blank');
                                                } catch (err) {
                                                    setError(err instanceof Error ? err.message : tCommon('errors.failedToGenerateReport'));
                                                }
                                            }}
                                        >
                                            {tSales('buttons.returnSlip')}
                                        </button>
                                        {ret.stateCode === RETURN_STATE.PROCESSED && (
                                            <button
                                                className="btn btn-secondary btn-sm"
                                                onClick={async () => {
                                                    try {
                                                        const response = await api.reportsControllerRunHook('sales-return-credit', {}, { id: ret.returnId, context: 'sales-return' });
                                                        const blob = response.data ;
                                                        const url = URL.createObjectURL(blob);
                                                        window.open(url, '_blank');
                                                    } catch (err) {
                                                        // Fallback to existing error setter
                                                        setError(err instanceof Error ? err.message : tCommon('errors.failedToGenerateReport'));
                                                    }
                                                }}
                                            >
                                                {tSales('buttons.salesCredit')}
                                            </button>
                                        )}
                                        </div>
                                    </div>
                                </div>

                                {ret.notes && (
                                    <p className="text-xs mb-2" style={{ color: 'var(--text-secondary)' }}>
                                        {ret.notes}
                                    </p>
                                )}

                                {ret.creditNoteNumber && (
                                    <div className="flex items-center gap-2 mb-2 text-xs" style={{ color: 'var(--text-secondary)' }}>
                                        {/* eslint-disable-next-line i18next/no-literal-string */}
                        <span className="material-symbols-outlined" style={{ fontSize: 14 }}>receipt_long</span>
                        {/* eslint-enable i18next/no-literal-string */}
                                        <span style={{ fontWeight: 600 }}>{tSales('returns.creditNote')}:</span>
                                        <span>{ret.creditNoteNumber}</span>
                                    </div>
                                )}

                                <DataTable
                                    data={ret.lines}
                                    keyExtractor={(rl: any) => rl.returnLineId}
                                    columns={[
                                        { header: tSales('columns.product'), width: 150 },
                                        { header: tSales('columns.description') },
                                        { header: tSales('columns.returnQty'), width: 90, align: 'right' },
                                        { header: tSales('columns.unitPrice'), align: 'right' },
                                        { header: tSales('columns.discountPct'), align: 'right' },
                                        { header: tSales('columns.tax'), align: 'right' },
                                        { header: tSales('columns.reason'), width: 180 },
                                        { header: tSales('columns.fee'), width: 100, align: 'right' },
                                        { header: tSales('columns.amount'), width: 100, align: 'right' },
                                        ...(isRetEditable ? [{ header: '', width: 50 }] : [])
                                    ]}
                                    renderCustomRow={(rl: any) => {
                                        const origLine = order.lines.find((l) => l.salesOrderLineId === rl.salesOrderLineId);
                                        const disc = parseFloat(origLine?.discountPercentage || '0');
                                        const taxCat = taxCategories.find(c => c.taxCategoryId === origLine?.taxCategoryId);
                                        const taxRate = parseFloat(taxCat?.rate || '0');
                                        const cc = order.currencyCode || baseCurrency;
                                        const pricing = computeLinePrice({
                                            quantity: parseFloat(rl.quantityReturned || '0'),
                                            pricePerUnit: parseFloat(origLine?.pricePerUnit || '0'),
                                            discountPercentage: disc,
                                            taxRate: taxRate,
                                        });
                                        return (
                                            <tr key={rl.returnLineId}>
                                                <td>
                                                    <span style={{ fontWeight: 600, fontSize: 12 }}>
                                                        {origLine?.productNumber || origLine?.productId?.substring(0, 8) || '—'}
                                                    </span>
                                                </td>
                                                <td>
                                                    <span style={{ fontSize: 12, color: 'var(--text-secondary)' }}>
                                                        {origLine?.productDescription || '—'}
                                                    </span>
                                                </td>
                                                <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                                    {isRetEditable ? (
                                                        <input
                                                            className="input"
                                                            type="number"
                                                            min="1"
                                                            step="1"
                                                            style={{ width: '100%', textAlign: 'right' }}
                                                            defaultValue={rl.quantityReturned}
                                                            key={`retqty-${rl.returnLineId}-${rl.quantityReturned}`}
                                                            onBlur={async (e) => {
                                                                if (e.target.value !== rl.quantityReturned) {
                                                                    try {
                                                                        await api.orderReturnsControllerUpdateReturnLine(
                                                                            orderId,
                                                                            ret.returnId,
                                                                            rl.returnLineId,
                                                                            { quantityReturned: e.target.value }
                                                                        );
                                                                        await loadReturns();
                                                                    } catch (err) {
                                                                        setError(err instanceof Error ? err.message : tCommon('errors.failedToUpdateReturnLine'));
                                                                    }
                                                                }
                                                            }}
                                                        />
                                                    ) : (
                                                        rl.quantityReturned
                                                    )}
                                                </td>
                                                <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                                    {formatAmount(parseFloat(origLine?.pricePerUnit || '0'), cc)}
                                                </td>
                                                <td style={{ textAlign: 'right', color: disc > 0 ? 'inherit' : 'var(--text-muted)' }}>
                                                    {disc.toFixed(1)}%
                                                </td>
                                                <td style={{ textAlign: 'right', color: taxRate > 0 ? 'inherit' : 'var(--text-muted)' }}>
                                                    {taxRate.toFixed(1)}%
                                                </td>
                                                <td>
                                                    {isRetEditable ? (
                                                        <input
                                                            className="input"
                                                            style={{ width: '100%' }}
                                                            defaultValue={rl.reason || ''}
                                                            key={`retrsn-${rl.returnLineId}-${rl.reason}`}
                                                            onBlur={async (e) => {
                                                                if (e.target.value !== (rl.reason || '')) {
                                                                    try {
                                                                        await api.orderReturnsControllerUpdateReturnLine(
                                                                            orderId,
                                                                            ret.returnId,
                                                                            rl.returnLineId,
                                                                            { reason: e.target.value }
                                                                        );
                                                                        await loadReturns();
                                                                    } catch (err) {
                                                                        setError(err instanceof Error ? err.message : tCommon('errors.failedToUpdateReturnLine'));
                                                                    }
                                                                }
                                                            }}
                                                            placeholder={tSales('placeholders.reason')}
                                                        />
                                                    ) : (
                                                        <span style={{ fontSize: 12 }}>{rl.reason || '—'}</span>
                                                    )}
                                                </td>
                                                <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                                    {isRetEditable ? (
                                                        <input
                                                            className="input"
                                                            type="number"
                                                            min="0"
                                                            step="0.01"
                                                            style={{ width: '100%', textAlign: 'right' }}
                                                            defaultValue={parseFloat(rl.returnFee || '0').toFixed(2)}
                                                            key={`retfee-${rl.returnLineId}-${rl.returnFee}`}
                                                            onBlur={async (e) => {
                                                                const val = parseFloat(e.target.value);
                                                                const formatted = isNaN(val) ? '0.00' : val.toFixed(2);
                                                                if (formatted !== parseFloat(rl.returnFee || '0').toFixed(2)) {
                                                                    try {
                                                                        await api.orderReturnsControllerUpdateReturnLine(
                                                                            orderId,
                                                                            ret.returnId,
                                                                            rl.returnLineId,
                                                                            { returnFee: formatted }
                                                                        );
                                                                        await loadReturns();
                                                                    } catch (err) {
                                                                        setError(err instanceof Error ? err.message : tCommon('errors.failedToUpdateReturnLine'));
                                                                    }
                                                                }
                                                            }}
                                                        />
                                                    ) : (
                                                        formatAmount(parseFloat(rl.returnFee || '0'), order.currencyCode || baseCurrency)
                                                    )}
                                                </td>
                                                <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                                    {formatAmount(pricing.amount, order.currencyCode || baseCurrency)}
                                                </td>
                                                {isRetEditable && (
                                                    <td>
                                                        <button
                                                            className="btn btn-danger btn-sm"
                                                            onClick={async () => {
                                                                if (!confirm(tConfirm('removeReturnLine'))) return;
                                                                try {
                                                                    await api.orderReturnsControllerRemoveReturnLine(
                                                                        orderId,
                                                                        ret.returnId,
                                                                        rl.returnLineId
                                                                    );
                                                                    await loadReturns();
                                                                } catch (err) {
                                                                    setError(err instanceof Error ? err.message : t('common.errors.failedToRemoveReturnLine'));
                                                                }
                                                            }}
                                                            title={t('salesOrders.buttons.removeReturnLine')}
                                                        >
                                                            <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} />
                                                        </button>
                                                    </td>
                                                )}
                                            </tr>
                                        );
                                    }}
                                    mobileCard={(rl: any) => {
                                        const origLine = order.lines.find((l) => l.salesOrderLineId === rl.salesOrderLineId);
                                        const disc = parseFloat(origLine?.discountPercentage || '0');
                                        const taxCat = taxCategories.find(c => c.taxCategoryId === origLine?.taxCategoryId);
                                        const taxRate = parseFloat(taxCat?.rate || '0');
                                        const cc = order.currencyCode || baseCurrency;
                                        const pricing = computeLinePrice({
                                            quantity: parseFloat(rl.quantityReturned || '0'),
                                            pricePerUnit: parseFloat(origLine?.pricePerUnit || '0'),
                                            discountPercentage: disc,
                                            taxRate: taxRate,
                                        });
                                        
                                        return (
                                            <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col">
                                                <div className="flex justify-between items-start gap-2 mb-2">
                                                    <div className="font-semibold text-sm text-[var(--accent)]">
                                                        {origLine?.productNumber || origLine?.productId?.substring(0, 8) || '—'}
                                                    </div>
                                                    {isRetEditable && (
                                                        <button
                                                            className="text-red-500 hover:bg-red-50 p-1.5 rounded"
                                                            onClick={async () => {
                                                                if (!confirm(tConfirm('removeReturnLine'))) return;
                                                                try {
                                                                    await api.orderReturnsControllerRemoveReturnLine(
                                                                        orderId,
                                                                        ret.returnId,
                                                                        rl.returnLineId
                                                                    );
                                                                    await loadReturns();
                                                                } catch (err) {
                                                                    setError(err instanceof Error ? err.message : t('common.errors.failedToRemoveReturnLine'));
                                                                }
                                                            }}
                                                            title={t('salesOrders.buttons.removeReturnLine')}
                                                        >
                                                            {/* eslint-disable-next-line i18next/no-literal-string */}
                                                            <span className="material-symbols-outlined text-[16px]">delete</span>
                                                        </button>
                                                    )}
                                                </div>
                                                <div className="text-sm text-slate-600 font-medium mb-3">
                                                    {origLine?.productDescription || '—'}
                                                </div>
                                                
                                                <div className="flex flex-col gap-0 border-t border-slate-100 pt-1">
                                                    <div className="flex justify-between items-center py-2">
                                                        <span className="text-xs font-medium text-slate-500">{tSales('columns.returnQty')}</span>
                                                        {isRetEditable ? (
                                                            <input
                                                                className="input"
                                                                type="number"
                                                                min="1"
                                                                step="1"
                                                                style={{ width: 70, textAlign: 'right' }}
                                                                defaultValue={rl.quantityReturned}
                                                                key={`retqty-${rl.returnLineId}-${rl.quantityReturned}`}
                                                                onBlur={async (e) => {
                                                                    if (e.target.value !== rl.quantityReturned) {
                                                                        try {
                                                                            await api.orderReturnsControllerUpdateReturnLine(
                                                                                orderId,
                                                                                ret.returnId,
                                                                                rl.returnLineId,
                                                                                { quantityReturned: e.target.value }
                                                                            );
                                                                            await loadReturns();
                                                                        } catch (err) {
                                                                            setError(err instanceof Error ? err.message : tCommon('errors.failedToUpdateReturnLine'));
                                                                        }
                                                                    }
                                                                }}
                                                            />
                                                        ) : (
                                                            <span className="font-medium text-sm tabular-nums">{rl.quantityReturned}</span>
                                                        )}
                                                    </div>
                                                    
                                                    <div className="flex flex-col gap-1 py-2">
                                                        <span className="text-xs font-medium text-slate-500">{tSales('columns.reason')}</span>
                                                        {isRetEditable ? (
                                                            <input
                                                                className="input"
                                                                style={{ width: '100%' }}
                                                                defaultValue={rl.reason || ''}
                                                                key={`retrsn-${rl.returnLineId}-${rl.reason}`}
                                                                onBlur={async (e) => {
                                                                    if (e.target.value !== (rl.reason || '')) {
                                                                        try {
                                                                            await api.orderReturnsControllerUpdateReturnLine(
                                                                                orderId,
                                                                                ret.returnId,
                                                                                rl.returnLineId,
                                                                                { reason: e.target.value }
                                                                            );
                                                                            await loadReturns();
                                                                        } catch (err) {
                                                                            setError(err instanceof Error ? err.message : tCommon('errors.failedToUpdateReturnLine'));
                                                                        }
                                                                    }
                                                                }}
                                                                placeholder={tSales('placeholders.reason')}
                                                            />
                                                        ) : (
                                                            <span className="text-sm">{rl.reason || '—'}</span>
                                                        )}
                                                    </div>
                                                    
                                                    <div className="flex justify-between items-center py-2 border-t border-slate-100 mt-1">
                                                        <span className="text-xs font-medium text-slate-500">{tSales('columns.fee')}</span>
                                                        {isRetEditable ? (
                                                            <input
                                                                className="input"
                                                                type="number"
                                                                min="0"
                                                                step="0.01"
                                                                style={{ width: 80, textAlign: 'right' }}
                                                                defaultValue={parseFloat(rl.returnFee || '0').toFixed(2)}
                                                                key={`retfee-${rl.returnLineId}-${rl.returnFee}`}
                                                                onBlur={async (e) => {
                                                                    const val = parseFloat(e.target.value);
                                                                    const formatted = isNaN(val) ? '0.00' : val.toFixed(2);
                                                                    if (formatted !== parseFloat(rl.returnFee || '0').toFixed(2)) {
                                                                        try {
                                                                            await api.orderReturnsControllerUpdateReturnLine(
                                                                                orderId,
                                                                                ret.returnId,
                                                                                rl.returnLineId,
                                                                                { returnFee: formatted }
                                                                            );
                                                                            await loadReturns();
                                                                        } catch (err) {
                                                                            setError(err instanceof Error ? err.message : tCommon('errors.failedToUpdateReturnLine'));
                                                                        }
                                                                    }
                                                                }}
                                                            />
                                                        ) : (
                                                            <span className="font-medium text-sm tabular-nums text-slate-700">
                                                                {formatAmount(parseFloat(rl.returnFee || '0'), order.currencyCode || baseCurrency)}
                                                            </span>
                                                        )}
                                                    </div>
                                                    
                                                    <div className="flex justify-between items-center py-2">
                                                        <span className="text-xs font-medium text-slate-500">{tSales('columns.amount')}</span>
                                                        <span className="font-semibold text-sm tabular-nums text-[var(--accent)]">
                                                            {formatAmount(pricing.amount, order.currencyCode || baseCurrency)}
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    }}
                                    emptyMessage={t('salesOrders.noReturnLines')}
                                    footer={(() => {
                                        if (ret.lines.length === 0) return null;
                                        
                                        const summary = computeReturnCreditSummary(
                                            ret.lines.map((rl) => {
                                                const origLine = order.lines.find((l) => l.salesOrderLineId === rl.salesOrderLineId);
                                                const taxCat = taxCategories.find(c => c.taxCategoryId === origLine?.taxCategoryId);
                                                return {
                                                    quantity: parseFloat(rl.quantityReturned || '0'),
                                                    pricePerUnit: parseFloat(origLine?.pricePerUnit || '0'),
                                                    discountPercentage: parseFloat(origLine?.discountPercentage || '0'),
                                                    taxRate: parseFloat(taxCat?.rate || '0'),
                                                    returnFee: parseFloat(rl.returnFee || '0'),
                                                };
                                            }),
                                        );
                                        const { subtotal, totalTax, totalFees, netCredit } = summary;
                                        const cc = order.currencyCode || baseCurrency;
                                        return (
                                            <>
                                                <tr className="hidden lg:table-row" style={{ borderTop: '2px solid var(--border)' }}>
                                                    <td colSpan={7} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                                        {t('salesOrders.returns.totalCredit')}
                                                    </td>
                                                    <td></td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                                        {formatAmount(subtotal, cc)}
                                                    </td>
                                                    {isRetEditable && <td></td>}
                                                </tr>
                                                <tr className="hidden lg:table-row">
                                                    <td colSpan={7} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                                        {tSales('columns.tax')}
                                                    </td>
                                                    <td></td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                                        {formatAmount(totalTax, cc)}
                                                    </td>
                                                    {isRetEditable && <td></td>}
                                                </tr>
                                                <tr className="hidden lg:table-row">
                                                    <td colSpan={7} style={{ textAlign: 'right', fontWeight: 600, fontSize: 12, color: 'var(--text-muted)' }}>
                                                        {t('salesOrders.returns.totalFees')}
                                                    </td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                                                        {totalFees > 0 ? `−${formatAmount(totalFees, cc)}` : formatAmount(0, cc)}
                                                    </td>
                                                    <td></td>
                                                    {isRetEditable && <td></td>}
                                                </tr>
                                                <tr className="hidden lg:table-row">
                                                    <td colSpan={7} style={{ textAlign: 'right', fontWeight: 700, fontSize: 13 }}>
                                                        {t('salesOrders.returns.netCredit')}
                                                    </td>
                                                    <td></td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 700, fontSize: 13 }}>
                                                        {formatAmount(netCredit, cc)}
                                                    </td>
                                                    {isRetEditable && <td></td>}
                                                </tr>
                                                
                                                <tr className="lg:hidden">
                                                    <td colSpan={8} className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{t('salesOrders.returns.totalCredit')}</td>
                                                    <td className="py-1 text-sm font-semibold text-right tabular-nums">{formatAmount(subtotal, cc)}</td>
                                                </tr>
                                                <tr className="lg:hidden">
                                                    <td colSpan={8} className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tSales('columns.tax')}</td>
                                                    <td className="py-1 text-sm font-semibold text-right tabular-nums">{formatAmount(totalTax, cc)}</td>
                                                </tr>
                                                <tr className="lg:hidden">
                                                    <td colSpan={8} className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{t('salesOrders.returns.totalFees')}</td>
                                                    <td className="py-1 text-sm font-semibold text-right tabular-nums">{totalFees > 0 ? `−${formatAmount(totalFees, cc)}` : formatAmount(0, cc)}</td>
                                                </tr>
                                                <tr className="lg:hidden">
                                                    <td colSpan={8} className="py-2 text-sm font-bold text-[var(--accent)] text-right pr-4">{t('salesOrders.returns.netCredit')}</td>
                                                    <td className="py-2 text-base font-bold text-[var(--accent)] text-right tabular-nums">{formatAmount(netCredit, cc)}</td>
                                                </tr>
                                            </>
                                        );
                                    })()}
                                />
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import StateBadge from '@/components/StateBadge';
import { ValidState } from '@/types/states';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import Link from 'next/link';

interface ShipmentLine {
    shipmentLineId: string;
    salesOrderLineId: string;
    quantityShipped: string;
}

interface Shipment {
    shipmentId: string;
    shipmentNumber: string;
    stateCode: string;
    notes: string | null;
    trackingNumber: string | null;
    createdOn: string;
    createdBy: string;
    lines: ShipmentLine[];
}

interface Props {
    orderId: string;
}

export default function ShipmentsSection({ orderId }: Props) {
    const tShipping = useTranslations('shipping');
    const tCommon = useTranslations('common');

    const [shipments, setShipments] = useState<Shipment[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        setLoading(true);
        api.orderShipmentsControllerFindShipments(orderId)
            .then((res) => setShipments(((res.data as any)?.data || res.data || []) as unknown as Shipment[]))
            .catch((err) => reportError(err, 'ShipmentsSection'))
            .finally(() => setLoading(false));
    }, [orderId]);

    return (
        <div id="shipments-section" className="card">
            <div className="flex items-center justify-between mb-4">
                <h3 className="section-heading">
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined">inventory_2</span>
                    {/* eslint-enable i18next/no-literal-string */}
                    {tShipping('shipmentsTitle')}
                </h3>
            </div>

            {loading ? (
                <div className="text-center py-6 text-sm" style={{ color: 'var(--text-muted)' }}>
                    {tCommon('loading')}
                </div>
            ) : shipments.length === 0 ? (
                <div className="text-center py-6 text-sm" style={{ color: 'var(--text-muted)' }}>
                    {tShipping('noShipmentsFound')}
                </div>
            ) : (
                <div className="flex flex-col gap-2">
                    {shipments.map(shipment => (
                        <Link
                            key={shipment.shipmentId}
                            href={`/shipments/${shipment.shipmentId}`}
                            className="flex items-center justify-between p-3 rounded-lg border border-[var(--border)] hover:bg-[var(--bg-card-hover)] transition-colors"
                        >
                            <div className="flex items-center gap-3">
                                {/* eslint-disable-next-line i18next/no-literal-string */}
                                <span className="material-symbols-outlined text-[var(--text-muted)] text-lg">inventory_2</span>
                                {/* eslint-enable i18next/no-literal-string */}
                                <div>
                                    <div className="font-bold text-sm text-[var(--text-primary)]">{shipment.shipmentNumber}</div>
                                    <div className="text-xs text-[var(--text-muted)]">
                                        {new Date(shipment.createdOn).toLocaleDateString()} · {tShipping('shipmentLines', { count: shipment.lines.length })}
                                        {shipment.trackingNumber && (
                                            <span> · {shipment.trackingNumber}</span>
                                        )}
                                    </div>
                                </div>
                            </div>
                            <StateBadge state={shipment.stateCode as ValidState} />
                        </Link>
                    ))}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useTranslations } from 'next-intl';
import StateBadge from '@/components/StateBadge';
import { ValidState } from '@/types/states';
import * as api from '@modbm/sdk';
import Link from 'next/link';
import { DataTable, MobileCardField } from '@/components/shared/DataTable';

/**
 * ShippingStatusSection — Read-only shipping status for the Sales Order detail page.
 * Fetches the shipping context and shows shipped quantities per line
 * plus a summary of existing shipments.
 */

interface ShippingLine {
    salesOrderLineId: string;
    lineNumber: number;
    productId: string;
    productNumber: string;
    productDescription: string;
    isPhysical: boolean;
    quantity: string;
    quantityPicked: string;
    quantityShipped: string;
    availableToShip: string;
}

interface ShipmentSummary {
    shipmentId: string;
    shipmentNumber: string;
    stateCode: string;
    notes: string | null;
    trackingNumber: string | null;
    createdOn: string;
    lineCount: number;
}

interface ShippingContext {
    lines: ShippingLine[];
    shipments: ShipmentSummary[];
}

interface Props {
    orderId: string;
}

export default function ShippingStatusSection({ orderId }: Props) {
    const tShipping = useTranslations('shipping');
    const tCommon = useTranslations('common');

    const [context, setContext] = useState<ShippingContext | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        setLoading(true);
        api.orderPickingControllerGetShippingContext(orderId)
            .then((res) => setContext(res.data as unknown as ShippingContext))
            .catch((err: unknown) => setError((err as Error).message))
            .finally(() => setLoading(false));
    }, [orderId]);

    if (loading) {
        return (
            <div id="shipping-section" className="card">
                <div className="text-center py-6 text-sm" style={{ color: 'var(--text-muted)' }}>
                    {tCommon('loading')}
                </div>
            </div>
        );
    }

    if (error || !context) {
        return (
            <div id="shipping-section" className="card">
                <div className="text-center py-6 text-sm" style={{ color: 'var(--danger)' }}>
                    {error || tShipping('errors.failedToLoadContextError')}
                </div>
            </div>
        );
    }

    const physicalLines = context.lines.filter(l => l.isPhysical);
    const fullyShippedLines = physicalLines.filter(l => parseFloat(l.availableToShip) <= 0 && parseFloat(l.quantityShipped) > 0).length;
    const isFullyShipped = physicalLines.length > 0 && fullyShippedLines === physicalLines.length;

    return (
        <div id="shipping-section" className="card">
            <div className="flex items-center justify-between mb-4">
                <h3 className="section-heading">
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined">local_shipping</span>
                    {/* eslint-enable i18next/no-literal-string */}
                    {tShipping('title')}
                </h3>
                <div className="flex items-center gap-2">
                    <span className="bg-[var(--accent)] text-white text-xs font-bold px-2 py-0.5 rounded-full">
                        {fullyShippedLines} / {physicalLines.length}
                    </span>
                    {isFullyShipped && (
                        <span className="text-xs font-bold text-[var(--success)]">
                            {/* eslint-disable-next-line i18next/no-literal-string */}
                            <span className="material-symbols-outlined text-sm align-middle mr-0.5">check_circle</span>
                            {/* eslint-enable i18next/no-literal-string */}
                            {tShipping('fullyShipped')}
                        </span>
                    )}
                </div>
            </div>

            {/* Lines Table */}
            <DataTable
                data={physicalLines}
                keyExtractor={(line: any) => line.salesOrderLineId}
                columns={[
                    { header: tShipping('columns.product') },
                    { header: tShipping('columns.ordered'), align: 'right' },
                    { header: tShipping('columns.picked'), align: 'right' },
                    { header: tShipping('columns.shipped'), align: 'right' },
                    { header: tShipping('columns.available'), align: 'right' },
                    { header: tCommon('columns.status'), align: 'center' }
                ]}
                emptyMessage={tShipping('noPhysicalLines')}
                renderCustomRow={(line: any) => {
                    const shipped = parseFloat(line.quantityShipped);
                    const available = parseFloat(line.availableToShip);
                    const ordered = parseFloat(line.quantity);
                    const fullyShipped = shipped >= ordered;

                    return (
                        <tr key={line.salesOrderLineId} className={fullyShipped ? 'opacity-60' : ''}>
                            <td>
                                <div className="font-bold text-sm">
                                    {line.productId ? (
                                        <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                            {line.productNumber}
                                        </Link>
                                    ) : line.productNumber}
                                </div>
                                <div className="text-xs text-[var(--text-muted)] truncate max-w-[250px]">{line.productDescription}</div>
                            </td>
                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                {ordered.toLocaleString()}
                            </td>
                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                {parseFloat(line.quantityPicked).toLocaleString()}
                            </td>
                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                {shipped.toLocaleString()}
                            </td>
                            <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                                <span className={available > 0 ? 'font-semibold text-[var(--success)]' : 'text-[var(--text-muted)]'}>
                                    {available.toLocaleString()}
                                </span>
                            </td>
                            <td style={{ textAlign: 'center' }}>
                                {fullyShipped ? (
                                    <>
                                        {/* eslint-disable-next-line i18next/no-literal-string */}
                                        <span className="material-symbols-outlined text-[var(--success)] text-base" style={{ fontVariationSettings: "'FILL' 1" }}>check_circle</span>
                                        {/* eslint-enable i18next/no-literal-string */}
                                    </>
                                ) : available > 0 ? (
                                    <>
                                        {/* eslint-disable-next-line i18next/no-literal-string */}
                                        <span className="material-symbols-outlined text-[var(--warning)] text-base">pending</span>
                                        {/* eslint-enable i18next/no-literal-string */}
                                    </>
                                ) : (
                                    <>
                                        {/* eslint-disable-next-line i18next/no-literal-string */}
                                        <span className="material-symbols-outlined text-[var(--text-muted)] text-base">hourglass_empty</span>
                                        {/* eslint-enable i18next/no-literal-string */}
                                    </>
                                )}
                            </td>
                        </tr>
                    );
                }}
                mobileCard={(line: any) => {
                    const shipped = parseFloat(line.quantityShipped);
                    const available = parseFloat(line.availableToShip);
                    const ordered = parseFloat(line.quantity);
                    const fullyShipped = shipped >= ordered;

                    return (
                        <div className={`bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col ${fullyShipped ? 'opacity-60' : ''}`}>
                            <div className="flex justify-between items-start mb-2 gap-2">
                                <div className="flex-1 min-w-0">
                                    <div className="font-bold text-[var(--accent)] text-sm mb-1 truncate">
                                        {line.productId ? (
                                            <Link href={`/products/${line.productId}`} className="hover:underline">
                                                {line.productNumber}
                                            </Link>
                                        ) : line.productNumber}
                                    </div>
                                    <div className="text-xs text-[var(--text-muted)] line-clamp-2 leading-relaxed">
                                        {line.productDescription}
                                    </div>
                                </div>
                                <div className="shrink-0 flex items-center">
                                    {fullyShipped ? (
                                        <span className="material-symbols-outlined text-[var(--success)] text-[20px]" style={{ fontVariationSettings: "'FILL' 1" }}>check_circle</span>
                                    ) : available > 0 ? (
                                        <span className="material-symbols-outlined text-[var(--warning)] text-[20px]">pending</span>
                                    ) : (
                                        <span className="material-symbols-outlined text-[var(--text-muted)] text-[20px]">hourglass_empty</span>
                                    )}
                                </div>
                            </div>
                            
                            <div className="mt-3 pt-3 border-t border-slate-100 flex flex-col gap-1.5">
                                <MobileCardField label={tShipping('columns.ordered')} value={ordered.toLocaleString()} />
                                <MobileCardField label={tShipping('columns.picked')} value={parseFloat(line.quantityPicked).toLocaleString()} />
                                <MobileCardField label={tShipping('columns.shipped')} value={shipped.toLocaleString()} />
                                <MobileCardField 
                                    label={tShipping('columns.available')} 
                                    value={
                                        <span className={available > 0 ? 'font-bold text-[var(--success)]' : 'font-medium text-slate-500'}>
                                            {available.toLocaleString()}
                                        </span>
                                    } 
                                />
                            </div>
                        </div>
                    );
                }}
            />

            {/* Existing Shipments */}
            {context.shipments.length > 0 && (
                <div className="mt-6">
                    <h4 className="section-heading !mb-3 !text-[var(--text-muted)]">{tShipping('existingShipments')}</h4>
                    <div className="flex flex-col gap-2">
                        {context.shipments.map(shipment => (
                            <Link
                                key={shipment.shipmentId}
                                href={`/shipments/${shipment.shipmentId}`}
                                className="flex items-center justify-between p-3 rounded-lg border border-[var(--border)] hover:bg-[var(--bg-card-hover)] transition-colors"
                            >
                                <div className="flex items-center gap-3">
                                    {/* eslint-disable-next-line i18next/no-literal-string */}
                                    <span className="material-symbols-outlined text-[var(--text-muted)] text-lg">inventory_2</span>
                                    {/* eslint-enable i18next/no-literal-string */}
                                    <div>
                                        <div className="font-bold text-sm text-[var(--text-primary)]">{shipment.shipmentNumber}</div>
                                        <div className="text-xs text-[var(--text-muted)]">
                                            {new Date(shipment.createdOn).toLocaleDateString()} · {tShipping('shipmentLines', { count: shipment.lineCount })}
                                            {shipment.trackingNumber && (
                                                <span> · {shipment.trackingNumber}</span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                                <StateBadge state={shipment.stateCode as ValidState} />
                            </Link>
                        ))}
                    </div>
                </div>
            )}

            {context.shipments.length === 0 && (
                <div className="mt-4 text-center text-sm text-[var(--text-muted)] py-2">
                    {tShipping('noShipmentsYet')}
                </div>
            )}
        </div>
    );
}

'use client';

import { use, useEffect, useState, useCallback, Fragment } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';

import ProductSearchInput from '@/components/shared/ProductSearchInput';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
