function isBackTransition(
    from: string, to: string,
    lifecycle: Record<string, number> = ORDER_LIFECYCLE,
): boolean {
    return sharedIsBackTransition(lifecycle, from, to);
}


function EventIcon({ type }: { type: string }) {
    const t = useTranslations('common.eventTypes');
    const icons: Record<string, string> = {
        created: '🆕',
        updated: '✏️',
        status_changed: '🔄',
        line_added: '➕',
        line_updated: '📝',
        line_removed: '🗑️',
        quoted: '📨',
        confirmed: '✅',
        cancelled: '❌',
        archived: '📦',
        unarchived: '📦',
        shipment_created: '🚚',
        shipment_updated: '🚚',
        shipment_status_changed: '🚚',
        shipment_processed: '📫',
        shipment_line_added: '📦',
        shipment_line_updated: '📦',
        shipment_line_removed: '🗑️',
        picking_line_updated: '📦',
        picking_line_picked_all: '✅',
        picking_order_picked_all: '✅',
        return_created: '↩️',
        return_updated: '✏️',
        return_status_changed: '🔄',
        return_processed: '✅',
        return_line_added: '➕',
        return_line_updated: '✏️',
        return_line_removed: '🗑️',
    };
    return <span className="mr-2" style={{ fontSize: '1.2rem', lineHeight: 1 }} title={t(type as any)}>{icons[type] || '📌'}</span>;
}

function PurchaseReturnStateBadge({ state }: { state: ValidState }) {
    const t = useTranslations('common.states');
    return <span className={`badge badge-return-${state}`}>{t(state)}</span>;
}



export default function SalesOrderPage({ params }: { params: Promise<{ id: string }> }) {
    const { id } = use(params);
    const router = useRouter();
    const t = useTranslations();
    const tCommon = useTranslations('common');
    const tSales = useTranslations('salesOrders');
    const tToast = useTranslations('toast');
    const tConfirm = useTranslations('confirm');

    const o = useOrder(id);

    /* ── Post-Confirmation Line UI State ───────────────────────────── */
    const [isPostConfirmationAddingEnabled, setIsPostConfirmationAddingEnabled] = useState(false);

    /* ── Quote Dialog ──────────────────────────────────────────────────────── */
    const [showQuoteDialog, setShowQuoteDialog] = useState(false);

    /* ── Discrepancy Modal ─────────────────────────────────────────────────── */
    const [showDiscrepancyModal, setShowDiscrepancyModal] = useState(false);

    // Scroll to hash fragment (e.g. #invoices-section) after data loads
    useEffect(() => {
        if (o.loading || !o.order) return;
        const hash = window.location.hash;
        if (!hash) return;
        // Small delay to let sections render
        const timer = setTimeout(() => {
            const el = document.querySelector(hash);
            if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 300);
        return () => clearTimeout(timer);
    }, [o.loading, o.order]);

    useDocumentTitle(o.order ? (o.order.name ? `${o.order.orderNumber} - ${o.order.name}` : o.order.orderNumber) : null);

    if (o.loading) {
        return (
            <>
                <div className="flex items-center justify-center flex-1">
                    <p style={{ color: 'var(--text-muted)' }}>{tCommon('loading')}</p>
                </div>
            </>
        );
    }

    if (!o.order) {
        return (
            <>
                <div className="flex flex-col items-center justify-center flex-1">
                    <p className="text-lg mb-2" style={{ color: 'var(--danger)' }}>
                        {o.error || tSales('orderNotFound')}
                    </p>
                    <button className="btn btn-secondary" onClick={() => router.push('/sales-orders')}>
                        {tSales('backToOrders')}
                    </button>
                </div>
            </>
        );
    }

    // After null guard, destructure everything for JSX use
    const {
        order, error, setError, saving, copying, locations,
        editName, setEditName, editPO, setEditPO, editNotes, setEditNotes, editFulfillmentLocationId, setEditFulfillmentLocationId, headerDirty,
        taxCategories,
        activeTab, setActiveTab, inventoryData, inventoryLoading,
        returns, returnsLoading, showCreateReturn, setShowCreateReturn,
        invoices, pickingSummary,
        isOrderDetailsEditable, isOrderLinesEditable,
        allowedTransitions, subtotal, totalTax,
        saveHeader, changeState, calculateTaxes, archiveOrder, unarchiveOrder, copyOrder,
        updateLine, updateLineFields, removeLine, addLineFromProduct, addBlankLine, addPostConfirmationBlankLine,
        loadOrder, loadReturns, loadInvoices,
        discrepanciesAcknowledged, setDiscrepanciesAcknowledged
    } = o;

    const handleStateClick = async (state: string) => {
        if (state === SALES_ORDER_STATE.CONFIRMED && gaps.length > 0 && !discrepanciesAcknowledged) {
            setShowDiscrepancyModal(true);
            return;
        }
        await changeState(state, state === SALES_ORDER_STATE.CONFIRMED, discrepanciesAcknowledged);
    };

    const handleGenerateQuote = async (text: string) => {
        try {
            const response = await api.reportsControllerRunHook(
                'sales-order-quote', 
                { quoteIntroText: text }, 
                { id, context: 'sales-order' }
            );
            const blob = response.data ;
            const url = URL.createObjectURL(blob);
            window.open(url, '_blank');
            loadOrder(); // Reload to show the new timeline event
        } catch (err) {
            reportError(err, 'OrderDetailPage:generateQuote');
            setError(err instanceof Error ? err.message : tCommon('errors.failedToGenerateQuote'));
            throw err;
        }
    };

    /* ── Centralised section visibility rules ──────────────────────── */
    const PICKING_INVOICE_STATES: string[] = [
        SALES_ORDER_STATE.PICKING, 
        SALES_ORDER_STATE.SHIPPED, 
        SALES_ORDER_STATE.INVOICED, 
        SALES_ORDER_STATE.LEGACY, 
        SALES_ORDER_STATE.ARCHIVED
    ];
    const sections = {
        details:      { id: 'details-section',      label: 'Details',      show: true },
        lines:        { id: 'lines-section',        label: 'Lines',        show: true },
        fulfillment:  { id: 'fulfillment-section',  label: 'Fulfillment',  show: PICKING_INVOICE_STATES.includes(order.stateCode) },
        shipments:    { id: 'shipments-section',    label: 'Shipments',    show: PICKING_INVOICE_STATES.includes(order.stateCode) },
        invoices:     { id: 'invoices-section',     label: 'Invoices',     show: PICKING_INVOICE_STATES.includes(order.stateCode) },
        returns:      { id: 'returns-section',      label: 'Returns',      show: PICKING_INVOICE_STATES.includes(order.stateCode) },
        activity:     { id: 'activity-section',     label: 'Activity',     show: true },
    };
    const visibleSections = Object.values(sections).filter(s => s.show);
    
    // Pre-calculate gaps for the Availability tab
    const gaps = calculateInventoryGaps(
        order.lines, 
        inventoryData.map(inv => ({ 
            productId: inv.productId, 
            locationId: inv.locationId, 
            quantityAvailable: inv.quantityAvailable 
        })), 
        order.fulfillmentLocationId
    );
    const gapMap = new Map(gaps.map(g => [g.salesOrderLineId, g]));

    return (
        <>
            <DetailsLayout
                header={
                    <EntityHeader
                        title={order.orderNumber}
                        subtitle={order.name || tSales('untitledOrder')}
                        onBack={() => {
                          if (window.history.length > 1) {
                            router.back();
                          } else {
                            router.push('/sales-orders');
                          }
                        }}
                        isSaving={saving}
                        badges={order.stateCode ? <StateBadge state={order.stateCode as any} /> : ''}
                        nav={<PageNav sections={visibleSections} />}
                        actions={
                            <>



                                {[...allowedTransitions]
                                    .filter(state => state !== SALES_ORDER_STATE.PICKING && state !== SALES_ORDER_STATE.SHIPPED)
                                    .sort((a, b) => {
                                        const aBack = isBackTransition(order.stateCode, a);
                                        const bBack = isBackTransition(order.stateCode, b);
                                        if (aBack !== bBack) return aBack ? -1 : 1;
                                        return 0;
                                    })
                                    .map((state) => {
                                        const back = isBackTransition(order.stateCode, state);
                                        return (
                                            <button
                                                key={state}
                                                className={`btn btn-sm ${state === SALES_ORDER_STATE.CANCELLED ? 'btn-danger' : back ? 'btn-secondary' : 'btn-primary'
                                                    }`}
                                                onClick={() => handleStateClick(state)}
                                            >
                                                {state === SALES_ORDER_STATE.CANCELLED ? (
                                                    <>
                                                        {/* eslint-disable-next-line i18next/no-literal-string */}
                                                        <span className="material-symbols-outlined mr-1" style={{ fontSize: 16 }}>close</span>
                                                        {tCommon('cancel')}
                                                    </>
                                                ) : back ? (
                                                    <>← <StateName state={state as ValidState} /></>
                                                ) : (
                                                    <>→ <StateName state={state as ValidState} /></>
                                                )}
                                            </button>
                                        );
                                    })}
                            </>
                        }
                    />
                }
            >



            {order.stateCode === SALES_ORDER_STATE.ARCHIVED && (
                <div
                    className="mb-4 px-4 py-3 rounded-lg flex items-center gap-3"
                    style={{
                        background: 'rgba(245, 158, 11, 0.1)',
                        border: '1px solid rgba(245, 158, 11, 0.3)',
                        color: '#b45309',
                    }}
                >
                    <span style={{ fontSize: '1.2rem' }}>📦</span>
                    <div>
                        <strong className="font-semibold text-amber-800">{tSales('archivedBannerTitle')}</strong> {tSales('archivedBannerBody')}
                    </div>
                </div>
            )}

            <div className="flex flex-col gap-3">
                    <OrderDetailsCard
                        order={order}
                        isOrderDetailsEditable={isOrderDetailsEditable}
                        editName={editName}
                        setEditName={setEditName}
                        editPO={editPO}
                        setEditPO={setEditPO}
                        editFulfillmentLocationId={editFulfillmentLocationId}
                        setEditFulfillmentLocationId={setEditFulfillmentLocationId}
                        editNotes={editNotes}
                        setEditNotes={setEditNotes}
                        saveHeader={saveHeader}
                        locations={locations}
                        copyOrder={copyOrder}
                        copying={copying}
                        onQuoteClick={() => setShowQuoteDialog(true)}
                        reportError={reportError}
                        setError={setError}
                    />

                {/* Line items / Availability tabs */}
                <div id="lines-section" className="card">
                    <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 mb-4">
                        <div className="flex overflow-x-auto w-full lg:w-auto pb-1 lg:pb-0">
                            <div className="flex gap-0 min-w-max">
                                <button
                                    className="text-xs font-medium px-3 py-1.5 rounded-l-lg"
                                    style={{
                                        color: activeTab === 'lines' ? 'var(--accent)' : 'var(--text-muted)',
                                        background: activeTab === 'lines' ? 'rgba(59,130,246,0.1)' : 'transparent',
                                        border: '1px solid',
                                        borderColor: activeTab === 'lines' ? 'rgba(59,130,246,0.3)' : 'var(--border)',
                                        cursor: 'pointer',
                                    }}
                                    onClick={() => setActiveTab('lines')}
                                >
                                    {tSales('lineItems')}
                                </button>
                                <button
                                    className="text-xs font-medium px-3 py-1.5"
                                    style={{
                                        color: activeTab === 'availability' ? 'var(--accent)' : 'var(--text-muted)',
                                        background: activeTab === 'availability' ? 'rgba(59,130,246,0.1)' : 'transparent',
                                        border: '1px solid',
                                        borderColor: activeTab === 'availability' ? 'rgba(59,130,246,0.3)' : 'var(--border)',
                                        borderLeft: activeTab === 'availability' ? '1px solid rgba(59,130,246,0.3)' : 'none',
                                        cursor: 'pointer',
                                    }}
                                    onClick={() => setActiveTab('availability')}
                                >
                                    {tSales('availability')}
                                </button>
                                <button
                                    className="text-xs font-medium px-3 py-1.5 rounded-r-lg"
                                    style={{
                                        color: activeTab === 'backorders' ? 'var(--accent)' : 'var(--text-muted)',
                                        background: activeTab === 'backorders' ? 'rgba(59,130,246,0.1)' : 'transparent',
                                        border: '1px solid',
                                        borderColor: activeTab === 'backorders' ? 'rgba(59,130,246,0.3)' : 'var(--border)',
                                        borderLeft: activeTab === 'backorders' ? '1px solid rgba(59,130,246,0.3)' : 'none',
                                        cursor: 'pointer',
                                    }}
                                    onClick={() => setActiveTab('backorders')}
                                >
                                    {tSales('backordersTab')}
                                </button>
                            </div>
                        </div>
                        
                        <div className="flex flex-wrap items-center gap-2 w-full lg:w-auto justify-start lg:justify-end">
                            {(isOrderLinesEditable || (isOrderDetailsEditable && activeTab === 'lines' && isPostConfirmationAddingEnabled)) && (
                                <>
                                    <div className="flex-1 min-w-[200px] max-w-sm">
                                        <ProductSearchInput
                                            onSelect={addLineFromProduct}
                                            placeholder={tSales('placeholders.searchProduct')}
                                            style={{ width: '100%' }}
                                            fulfillmentLocationId={order?.fulfillmentLocationId || undefined}
                                        />
                                    </div>
                                    <button
                                        className="btn btn-secondary btn-sm whitespace-nowrap"
                                        onClick={addBlankLine}
                                        disabled={saving}
                                    >
                                        + {tSales('buttons.customLine')}
                                    </button>
                                </>
                            )}
                            {!isOrderLinesEditable && isOrderDetailsEditable && activeTab === 'lines' && !isPostConfirmationAddingEnabled && (ORDER_LIFECYCLE[order?.stateCode ?? ''] >= ORDER_LIFECYCLE[SALES_ORDER_STATE.CONFIRMED]) && (
                                <button
                                    className="btn btn-secondary btn-sm whitespace-nowrap"
                                    onClick={() => {
                                        if (window.confirm(tSales('postConfirmationLineWarningBody'))) {
                                            setIsPostConfirmationAddingEnabled(true);
                                        }
                                    }}
                                    disabled={saving}
                                    title={tSales('postConfirmationLineWarningTitle')}
                                >
                                    + {tSales('buttons.addPostConfirmationLine')}
                                </button>
                            )}
                        </div>
                    </div>

                    {activeTab === 'lines' ? (() => {
                        const hasActionColumn = isOrderLinesEditable || (order.lines || []).some((l: any) => l.isPostConfirmation && isOrderDetailsEditable) || isPostConfirmationAddingEnabled;

                        const lineColumns: any[] = [
                            {
                                id: 'lineNumber',
                                header: tSales('columns.lineNumber'),
                                width: 40,
                                render: (line: any) => (
                                    <span style={{ color: 'var(--text-muted)', fontWeight: 400, position: 'relative' }}>
                                        {line.lineNumber}
                                    </span>
                                )
                            },
                            {
                                id: 'product',
                                header: tSales('columns.product'),
                                render: (line: any) => (
                                    <span style={{ fontWeight: 600, fontSize: 12 }}>
                                        {line.productId && line.productId !== '00000000-0000-0000-0000-000000000000' ? (
                                            <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                                {line.productNumber || line.productId?.substring(0, 8)}
                                            </Link>
                                        ) : (
                                            line.productNumber || line.productId?.substring(0, 8) || '—'
                                        )}
                                        {line.isPostConfirmation && (
                                            <span className="ml-2 badge badge-sm badge-accent">
                                                {tSales('columns.postConfirmation')}
                                            </span>
                                        )}
                                    </span>
                                )
                            },
                            {
                                id: 'description',
                                header: tSales('columns.description'),
                                render: (line: any) => {
                                    const isEditable = isOrderLinesEditable || (line.isPostConfirmation && isOrderDetailsEditable);
                                    return (!line.productId || line.productId === '00000000-0000-0000-0000-000000000000') && isEditable ? (
                                        <input
                                            className="input"
                                            style={{ width: '100%', fontSize: 13 }}
                                            defaultValue={line.productDescription || ''}
                                            key={`desc-${line.salesOrderLineId}-${line.productDescription}`}
                                            onBlur={(e) => {
                                                if (e.target.value !== (line.productDescription || '')) {
                                                    updateLine(line.salesOrderLineId, 'productDescription', e.target.value);
                                                }
                                            }}
                                            placeholder="Custom description..."
                                        />
                                    ) : (
                                        <>{line.productDescription || '—'}</>
                                    );
                                }
                            },
                            {
                                id: 'qty',
                                header: tSales('columns.qty'),
                                width: 90,
                                align: 'right',
                                render: (line: any) => {
                                    const isEditable = isOrderLinesEditable || (line.isPostConfirmation && isOrderDetailsEditable);
                                    const hasGap = gapMap.has(line.salesOrderLineId);
                                    const warningIcon = hasGap ? (
                                        <>
                                            {/* eslint-disable-next-line i18next/no-literal-string */}
                                            <span 
                                                className="material-symbols-outlined" 
                                                style={{ fontSize: 14, color: 'var(--danger)', position: isEditable ? 'absolute' : 'relative', left: isEditable ? -16 : undefined, top: isEditable ? '50%' : undefined, transform: isEditable ? 'translateY(-50%)' : undefined, verticalAlign: !isEditable ? 'middle' : undefined, marginRight: !isEditable ? 4 : 0, zIndex: 1 }}
                                                title={tSales('availabilityStatus.shortage')}
                                            >
                                                warning
                                            </span>
                                            {/* eslint-enable i18next/no-literal-string */}
                                        </>
                                    ) : null;

                                    if (isEditable) {
                                        return (
                                            <div style={{ position: 'relative' }}>
                                                {warningIcon}
                                                <input
                                                    className="input"
                                                    type="number"
                                                    min="0"
                                                    step="1"
                                                    style={{ width: '100%', textAlign: 'right', borderColor: hasGap ? 'var(--danger)' : undefined }}
                                                    defaultValue={line.quantity}
                                                    key={`qty-${line.salesOrderLineId}-${line.quantity}`}
                                                    onBlur={(e) => {
                                                        if (e.target.value !== line.quantity) {
                                                            updateLine(line.salesOrderLineId, 'quantity', e.target.value);
                                                        }
                                                    }}
                                                />
                                            </div>
                                        );
                                    }
                                    return (
                                        <span style={{ fontVariantNumeric: 'tabular-nums', color: hasGap ? 'var(--danger)' : undefined, fontWeight: hasGap ? 600 : undefined }}>
                                            {warningIcon}
                                            {line.quantity}
                                        </span>
                                    );
                                }
                            },
                            {
                                id: 'uom',
                                header: tSales('columns.uom'),
                                width: 80,
                                align: 'right',
                                render: (line: any) => {
                                    const isEditable = isOrderLinesEditable || (line.isPostConfirmation && isOrderDetailsEditable);
                                    if (isEditable) {
                                        const uoms: ProductUom[] = line.productUoms || [];
                                        const defaultUom = line.baseUom || 'EA';
                                        const selectOptions = uoms.length > 0 ? uoms : [{ uomCode: defaultUom, ratio: 1 }];
                                        return (
                                            <select
                                                className="input"
                                                style={{ width: '100%', fontSize: 13, textAlign: 'right' }}
                                                value={line.unitOfMeasure || defaultUom}
                                                onChange={(e) => {
                                                    const newVal = e.target.value;
                                                    const oldVal = line.unitOfMeasure || defaultUom;
                                                    if (newVal !== oldVal) {
                                                        const oldO = selectOptions.find((o: any) => o.uomCode === oldVal);
                                                        const oldRatio = typeof oldO?.ratio === 'string' ? parseFloat(oldO.ratio) : (oldO?.ratio || 1);
                                                        const newO = selectOptions.find((o: any) => o.uomCode === newVal);
                                                        const newRatio = typeof newO?.ratio === 'string' ? parseFloat(newO.ratio) : (newO?.ratio || 1);
                                                        const newPrice = calculateUomPriceAdjustment(line.pricePerUnit || 0, oldRatio, newRatio);
                                                        updateLineFields(line.salesOrderLineId, {
                                                            unitOfMeasure: newVal,
                                                            pricePerUnit: isNaN(newPrice) ? '0.00' : newPrice.toFixed(2)
                                                        });
                                                    }
                                                }}
                                            >
                                                {selectOptions.map((o: any) => (
                                                    <option key={o.uomCode} value={o.uomCode}>{o.uomCode}</option>
                                                ))}
                                            </select>
                                        );
                                    }
                                    return <span style={{ fontVariantNumeric: 'tabular-nums' }}>{line.unitOfMeasure || line.baseUom || 'EA'}</span>;
                                }
                            },
                            {
                                id: 'unitPrice',
                                header: tSales('columns.unitPrice'),
                                width: 110,
                                align: 'right',
                                render: (line: any) => {
                                    const isEditable = isOrderLinesEditable || (line.isPostConfirmation && isOrderDetailsEditable);
                                    if (isEditable) {
                                        return (
                                            <input
                                                className="input"
                                                type="number"
                                                min="0"
                                                step="0.01"
                                                style={{ width: '100%', textAlign: 'right' }}
                                                defaultValue={parseFloat(line.pricePerUnit || '0').toFixed(2)}
                                                key={`price-${line.salesOrderLineId}-${line.pricePerUnit}`}
                                                onBlur={(e) => {
                                                    const val = parseFloat(e.target.value);
                                                    const formatted = isNaN(val) ? '0.00' : val.toFixed(2);
                                                    e.target.value = formatted;
                                                    if (formatted !== parseFloat(line.pricePerUnit || '0').toFixed(2)) {
                                                        updateLine(line.salesOrderLineId, 'pricePerUnit', formatted);
                                                    }
                                                }}
                                            />
                                        );
                                    }
                                    return <span style={{ fontVariantNumeric: 'tabular-nums' }}>{formatAmount(parseFloat(line.pricePerUnit || '0'), order.currencyCode || 'EUR')}</span>;
                                }
                            },
                            {
                                id: 'discountPct',
                                header: tSales('columns.discountPct'),
                                width: 80,
                                align: 'right',
                                render: (line: any) => {
                                    const isEditable = isOrderLinesEditable || (line.isPostConfirmation && isOrderDetailsEditable);
                                    if (isEditable) {
                                        return (
                                            <input
                                                className="input"
                                                type="number"
                                                min="0"
                                                max="100"
                                                step="0.1"
                                                style={{ width: '100%', textAlign: 'right' }}
                                                defaultValue={line.discountPercentage || '0'}
                                                key={`disc-${line.salesOrderLineId}-${line.discountPercentage}`}
                                                onBlur={(e) => {
                                                    if (e.target.value !== (line.discountPercentage || '0')) {
                                                        updateLine(line.salesOrderLineId, 'discountPercentage', e.target.value);
                                                    }
                                                }}
                                            />
                                        );
                                    }
                                    return <span style={{ fontVariantNumeric: 'tabular-nums' }}>{parseFloat(line.discountPercentage || '0').toFixed(1)}%</span>;
                                }
                            },
                            {
                                id: 'tax',
                                header: (
                                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: '4px' }}>
                                        {tSales('columns.tax')}
                                        {isOrderDetailsEditable && (
                                            <button
                                                type="button"
                                                onClick={calculateTaxes}
                                                disabled={saving}
                                                style={{ background: 'none', border: 'none', padding: 0, cursor: saving ? 'default' : 'pointer', color: 'var(--accent)', display: 'flex' }}
                                                title={tSales('buttons.calculateTaxes', { defaultValue: 'Calculate Taxes' })}
                                            >
                                                <span className={`material-symbols-outlined ${saving ? 'animate-spin' : ''}`} style={{ fontSize: '16px' }}>sync</span>
                                            </button>
                                        )}
                                    </div>
                                ),
                                width: 110,
                                align: 'right',
                                render: (line: any) => {
                                    const isEditable = isOrderLinesEditable || (line.isPostConfirmation && isOrderDetailsEditable);
                                    const isExternalTax = !!(order as any).taxProvider && (order as any).taxProvider !== 'internal';

                                    if (isExternalTax) {
                                        const isStale = (order as any)?.customFields?.taxIsStale === true || (order as any)?.customFields?.taxIsStale === 'true';
                                        if (isStale) {
                                            return <span className="badge badge-warning" title={`Tax needs to be calculated by ${(order as any).taxProvider}`}>Pending</span>;
                                        }
                                        return <span title={`Calculated by ${(order as any).taxProvider}`} style={{ cursor: 'help', borderBottom: '1px dotted var(--text-muted)' }}>
                                            {formatAmount(parseFloat(line.tax || '0'), order.currencyCode || 'EUR')}
                                        </span>;
                                    }

                                    if (isEditable) {
                                        return (
                                            <select
                                                className="input"
                                                style={{ width: '100%', fontSize: 12, textAlign: 'right' }}
                                                value={line.taxCategoryId || ''}
                                                onChange={(e) => {
                                                    updateLine(line.salesOrderLineId, 'taxCategoryId', e.target.value);
                                                }}
                                            >
                                                {taxCategories.map((c: TaxCategory) => (
                                                    <option key={c.taxCategoryId} value={c.taxCategoryId}>
                                                        {getTaxLabel(c)}
                                                    </option>
                                                ))}
                                            </select>
                                        );
                                    }
                                    return (
                                        <span style={{ fontSize: 12 }}>
                                            {(() => {
                                                const c = taxCategories.find((c: TaxCategory) => c.taxCategoryId === line.taxCategoryId);
                                                if (c) {
                                                    const pct = parseFloat(c.rate || '0');
                                                    const formattedPct = pct % 1 === 0 ? pct.toFixed(0) : pct.toString();
                                                    return <span title={`Tax Category: ${c.title}`} style={{ cursor: 'help', borderBottom: '1px dotted var(--text-muted)' }}>{formattedPct}%</span>;
                                                }
                                                const amt = parseFloat(line.amount || '0');
                                                const tax = parseFloat(line.tax || '0');
                                                if (amt > 0 && tax > 0) {
                                                    const pct = (tax / amt) * 100;
                                                    return <span title="Tax Category: Custom" style={{ cursor: 'help', borderBottom: '1px dotted var(--text-muted)' }}>{`${pct % 1 === 0 ? pct.toFixed(0) : pct.toFixed(1)}%`}</span>;
                                                }
                                                if (amt > 0 && tax === 0) return <span title={tCommon('taxLabels.exempt')} style={{ cursor: 'help', borderBottom: '1px dotted var(--text-muted)' }}>0%</span>;
                                                return '—';
                                            })()}
                                        </span>
                                    );
                                }
                            },
                            {
                                id: 'amount',
                                header: tSales('columns.amount'),
                                width: 110,
                                align: 'right',
                                render: (line: any) => {
                                    const isEditable = isOrderLinesEditable || (line.isPostConfirmation && isOrderDetailsEditable);
                                    return (
                                        <span style={{ fontWeight: 600, fontVariantNumeric: 'tabular-nums', color: isEditable ? 'var(--text-primary)' : undefined }}>
                                            {formatAmount(parseFloat(line.amount || '0'), order.currencyCode || 'EUR')}
                                        </span>
                                    );
                                }
                            }
                        ];

                        if (hasActionColumn) {
                            lineColumns.push({
                                id: 'actions',
                                header: '',
                                width: 50,
                                align: 'right',
                                render: (line: any) => {
                                    const isEditable = isOrderLinesEditable || (line.isPostConfirmation && isOrderDetailsEditable);
                                    if (!isEditable) return null;
                                    return (
                                        <button
                                            className="btn btn-danger btn-sm"
                                            onClick={() => removeLine(line.salesOrderLineId)}
                                            title={tSales('buttons.removeLine')}
                                        >
                                            <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} />
                                        </button>
                                    );
                                }
                            });
                        }

                        return (
                            <DataTable
                                data={order.lines}
                                keyExtractor={(line: any, idx: number) => line.salesOrderLineId || idx}
                                columns={lineColumns}
                                emptyMessage={tSales('noLineItems')}
                                mobileCard={(line: any) => {
                                    const actionCol = lineColumns.find(c => c.id === 'actions')?.render?.(line, 0);
                                    return (
                                        <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col">
                                            <div className="flex justify-between items-start gap-2 mb-2">
                                                <div className="font-semibold text-sm text-[var(--accent)]">
                                                    {lineColumns.find(c => c.id === 'product')?.render?.(line, 0)}
                                                </div>
                                                <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">#{line.lineNumber}</div>
                                            </div>
                                            <div className="text-sm text-slate-600 font-medium mb-3 [&_.input]:w-full [&_.input]:text-sm [&_.input]:h-8 [&_.input]:!py-1">
                                                {lineColumns.find(c => c.id === 'description')?.render?.(line, 0)}
                                            </div>
                                            <div className="flex flex-col gap-0 border-t border-slate-100 pt-1">
                                                {lineColumns.filter(c => ['qty', 'uom', 'unitPrice', 'discountPct', 'tax', 'amount'].includes(c.id!)).map(col => (
                                                    <MobileCardField 
                                                        key={col.id} 
                                                        label={col.id === 'tax' ? tSales('columns.tax') : col.header} 
                                                        value={
                                                            <div className={col.id === 'amount' ? 'font-bold text-[var(--accent)] text-base' : '[&_.input]:text-sm [&_.input]:h-8 [&_.input]:!py-1 [&_.input]:w-24 [&_select.input]:w-32'}>
                                                                {col.render?.(line, 0)}
                                                            </div>
                                                        } 
                                                    />
                                                ))}
                                                {actionCol && (
                                                    <div className="flex justify-end mt-2">
                                                        {actionCol}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    );
                                }}
                            footer={
                                (order.lines || []).length > 0 ? (() => {
                                    const isExternalTax = !!(order as any).taxProvider && (order as any).taxProvider !== 'internal';
                                    const isStale = isExternalTax && ((order as any)?.customFields?.taxIsStale === true || (order as any)?.customFields?.taxIsStale === 'true');
                                    const taxPct = subtotal > 0 && !isStale ? (totalTax / subtotal) * 100 : 0;
                                    return (
                                        <>
                                            <tr className="hidden lg:table-row" style={{ borderTop: '2px solid var(--border)' }}>
                                                <td colSpan={8} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                                                    {tCommon('subtotal')}
                                                </td>
                                                <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                                                    {formatAmount(subtotal, order.currencyCode || 'EUR')}
                                                </td>
                                                {(isOrderLinesEditable || (order.lines || []).some((l: any) => l.isPostConfirmation && isOrderDetailsEditable)) && <td></td>}
                                            </tr>
                                            <tr className="hidden lg:table-row">
                                                <td colSpan={8} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                                                    {tCommon('tax')}{taxPct > 0 && !isStale ? ` (${taxPct % 1 === 0 ? taxPct.toFixed(0) : taxPct.toFixed(1)}%)` : ''}
                                                </td>
                                                <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                                                    {isStale ? <span className="badge badge-warning text-xs font-normal" style={{ marginLeft: 'auto' }}>Pending</span> : formatAmount(totalTax, order.currencyCode || 'EUR')}
                                                </td>
                                                {(isOrderLinesEditable || (order.lines || []).some((l: any) => l.isPostConfirmation && isOrderDetailsEditable)) && <td></td>}
                                            </tr>
                                            <tr className="hidden lg:table-row" style={{ backgroundColor: 'rgba(59,130,246,0.02)' }}>
                                                <td colSpan={8} style={{ textAlign: 'right', fontWeight: 700, fontSize: 13, color: 'var(--text-primary)' }}>
                                                    {tCommon('total')}
                                                </td>
                                                <td style={{ textAlign: 'right', fontWeight: 800, fontSize: 14, color: 'var(--accent)', fontVariantNumeric: 'tabular-nums' }}>
                                                    {isStale ? <span className="badge badge-warning text-xs font-normal" style={{ marginLeft: 'auto' }}>Pending</span> : formatAmount(subtotal + totalTax, order.currencyCode || 'EUR')}
                                                </td>
                                                {(isOrderLinesEditable || (order.lines || []).some((l: any) => l.isPostConfirmation && isOrderDetailsEditable)) && <td></td>}
                                            </tr>
                                            {/* button moved to header */}
                                            {/* Mobile summary rows - hidden on lg, visible on mobile because the footer is wrapped in a normal div */}
                                            <tr className="lg:hidden">
                                                <td className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tCommon('subtotal')}</td>
                                                <td className="py-1 text-sm font-semibold text-right tabular-nums">{formatAmount(subtotal, order.currencyCode || 'EUR')}</td>
                                            </tr>
                                            <tr className="lg:hidden">
                                                <td className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tCommon('tax')}</td>
                                                <td className="py-1 text-sm font-semibold text-right tabular-nums">{isStale ? <span className="badge badge-warning text-[10px] font-normal" style={{ display: 'inline-block' }}>Pending</span> : formatAmount(totalTax, order.currencyCode || 'EUR')}</td>
                                            </tr>
                                            <tr className="lg:hidden">
                                                <td className="py-2 text-sm font-bold text-[var(--accent)] text-right pr-4">{tCommon('total')}</td>
                                                <td className="py-2 text-base font-bold text-[var(--accent)] text-right tabular-nums">{isStale ? <span className="badge badge-warning text-[10px] font-normal" style={{ display: 'inline-block' }}>Pending</span> : formatAmount(subtotal + totalTax, order.currencyCode || 'EUR')}</td>
                                            </tr>
                                            {/* button moved to header */}
                                        </>
                                    );
                                })() : null
                            }
                        />
                        );
                    })() : activeTab === 'availability' ? (
                        /* Availability tab */
                        inventoryLoading ? (
                            <p className="text-sm" style={{ color: 'var(--text-muted)', padding: '20px 0', textAlign: 'center' }}>{tSales('loadingInventory')}</p>
                        ) : (
                            <DataTable
                                data={order.lines}
                                keyExtractor={(line: any, idx: number) => line.salesOrderLineId || idx}
                                columns={[
                                    { header: tSales('columns.lineNumber'), width: 40 },
                                    { header: tSales('columns.product') },
                                    { header: tSales('columns.description') },
                                    { header: tSales('columns.ordered'), width: 90, align: 'right' },
                                    { header: tSales('columns.fulfillment'), width: 140, align: 'left' },
                                    { header: tSales('columns.location'), width: 100, align: 'right' },
                                    { header: tSales('columns.onHand'), width: 90, align: 'right' },
                                    { header: tSales('columns.committed'), width: 90, align: 'right' },
                                    { header: tSales('columns.incoming'), width: 90, align: 'right' },
                                    { header: tSales('columns.available'), width: 90, align: 'right' },
                                    { header: tSales('columns.status'), width: 70, align: 'center' }
                                ]}
                                renderCustomRow={(line: any, idx: number) => {
                                    const lineInventory = inventoryData.filter(
                                        (inv: any) => inv.productId === line.productId && line.productId !== '00000000-0000-0000-0000-000000000000',
                                    );
                                    const totalAvail = lineInventory.reduce(
                                        (sum: number, inv: any) => sum + parseFloat(inv.quantityAvailable || '0'), 0,
                                    );
                                    const gap = gapMap.get(line.salesOrderLineId);
                                    const canFulfil = !gap;

                                    const isCustom = !line.productId || line.productId === '00000000-0000-0000-0000-000000000000';
                                    if (line.productType === 'non-stock' || line.productType === 'service' || line.productType === 'freight' || isCustom) {
                                        return (
                                            <tr key={line.salesOrderLineId} style={{ backgroundColor: 'var(--bg-subtle)' }}>
                                                <td style={{ color: 'var(--text-muted)' }}>{line.lineNumber}</td>
                                                <td style={{ fontWeight: 600, fontSize: 12 }}>
                                                    {line.productNumber || line.productId?.substring(0, 8) || '—'}
                                                </td>
                                                <td>
                                                    {line.productDescription || '—'}
                                                    <span className="ml-2 badge badge-sm badge-draft">
                                                        {/* eslint-disable-next-line no-restricted-syntax */}
                                                        {line.productType || 'custom'}
                                                    </span>
                                                </td>
                                                <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{line.quantity}</td>
                                                <td colSpan={6} style={{ textAlign: 'center', color: 'var(--text-muted)', fontSize: 12, fontStyle: 'italic' }}>
                                                    {tSales('virtualFulfillmentBypass')}
                                                </td>
                                                <td style={{ textAlign: 'center' }}>✅</td>
                                            </tr>
                                        );
                                    }

                                    return (
                                        <Fragment key={line.salesOrderLineId || idx}>
                                            {lineInventory.length === 0 ? (
                                                <tr key={line.salesOrderLineId}>
                                                    <td style={{ color: 'var(--text-muted)' }}>{line.lineNumber}</td>
                                                    <td style={{ fontWeight: 600, fontSize: 12 }}>
                                                        {line.productId && line.productId !== '00000000-0000-0000-0000-000000000000' ? (
                                                            <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                                                {line.productNumber}
                                                            </Link>
                                                        ) : (
                                                            line.productNumber || '—'
                                                        )}
                                                    </td>
                                                    <td style={{ fontSize: 12, color: 'var(--text-muted)' }}>{line.productDescription}</td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{line.quantity}</td>
                                                    <td colSpan={6} style={{ textAlign: 'center', color: 'var(--danger)', fontSize: 12, fontStyle: 'italic' }}>
                                                        {tSales('noInventoryFound')}
                                                    </td>
                                                    <td style={{ textAlign: 'center' }}>❌</td>
                                                </tr>
                                            ) : lineInventory.map((inv: any, idx: number) => (
                                                <tr key={`${line.salesOrderLineId}-${inv.locationId}`}>
                                                    {idx === 0 && (
                                                        <>
                                                            <td rowSpan={lineInventory.length} style={{ color: 'var(--text-muted)' }}>{line.lineNumber}</td>
                                                            <td rowSpan={lineInventory.length} style={{ fontWeight: 600, fontSize: 12 }}>
                                                                {line.productId && line.productId !== '00000000-0000-0000-0000-000000000000' ? (
                                                                    <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                                                                        {line.productNumber}
                                                                    </Link>
                                                                ) : (
                                                                    line.productNumber || '—'
                                                                )}
                                                            </td>
                                                            <td rowSpan={lineInventory.length} style={{ fontSize: 12 }}>{line.productDescription}</td>
                                                            <td rowSpan={lineInventory.length} style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>{line.quantity}</td>
                                                            <td rowSpan={lineInventory.length}>
                                                                {(() => {
                                                                    if (canFulfil) {
                                                                        return <span className="text-emerald-600 font-medium flex items-center gap-1">✅ {tSales('availabilityStatus.local')}</span>;
                                                                    }
                                                                    if (gap && totalAvail >= gap.orderedQuantity) {
                                                                        return <span className="text-amber-600 font-medium flex items-center gap-1">🚚 {tSales('availabilityStatus.others')}</span>;
                                                                    }
                                                                    return <span className="text-rose-600 font-medium flex items-center gap-1">❌ {tSales('availabilityStatus.shortage')}</span>;
                                                                })()}
                                                            </td>
                                                        </>
                                                    )}
                                                    <td style={{ textAlign: 'right', fontSize: 12, color: inv.locationId === order.fulfillmentLocationId ? 'var(--accent)' : 'var(--text-muted)', fontWeight: inv.locationId === order.fulfillmentLocationId ? 600 : 400 }}>
                                                        {inv.locationName}
                                                    </td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{parseFloat(inv.quantityOnHand || '0')}</td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: 'var(--danger)' }}>{parseFloat(inv.quantityCommitted || '0')}</td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: 'var(--success)' }}>{parseFloat(inv.quantityOnOrder || '0')}</td>
                                                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', fontWeight: 600, color: parseFloat(inv.quantityAvailable || '0') > 0 ? 'var(--text-primary)' : 'var(--danger)' }}>
                                                        {parseFloat(inv.quantityAvailable || '0')}
                                                    </td>
                                                    <td style={{ textAlign: 'center' }}>
                                                        {parseFloat(inv.quantityAvailable || '0') >= Number(line.quantity) ? '✅' : '⚠️'}
                                                    </td>
                                                </tr>
                                            ))}
                                        </Fragment>
                                    );
                                }}
                                mobileCard={(line: any) => {
                                    const lineInventory = inventoryData.filter(
                                        (inv: any) => inv.productId === line.productId && line.productId !== '00000000-0000-0000-0000-000000000000',
                                    );
                                    const totalAvail = lineInventory.reduce(
                                        (sum: number, inv: any) => sum + parseFloat(inv.quantityAvailable || '0'), 0,
                                    );
                                    const gap = gapMap.get(line.salesOrderLineId);
                                    const canFulfil = !gap;
                                    const isCustom = !line.productId || line.productId === '00000000-0000-0000-0000-000000000000';

                                    return (
                                        <div className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col">
                                            <div className="flex justify-between items-start gap-2 mb-2">
                                                <div className="font-semibold text-sm text-[var(--accent)]">
                                                    {line.productNumber || line.productId?.substring(0, 8) || '—'}
                                                </div>
                                                <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">#{line.lineNumber}</div>
                                            </div>
                                            <div className="text-sm text-slate-600 font-medium mb-3">
                                                {line.productDescription} {isCustom && <span className="badge badge-sm badge-draft ml-2">{line.productType || 'custom'}</span>}
                                            </div>
                                            
                                            {isCustom || line.productType === 'non-stock' || line.productType === 'service' || line.productType === 'freight' ? (
                                                <div className="text-sm text-slate-500 italic text-center py-2 bg-slate-50 rounded border border-slate-100">{tSales('virtualFulfillmentBypass')} ✅</div>
                                            ) : lineInventory.length === 0 ? (
                                                <div className="text-sm text-rose-500 italic text-center py-2 bg-rose-50 rounded border border-rose-100">{tSales('noInventoryFound')} ❌</div>
                                            ) : (
                                                <>
                                                    <div className="flex justify-between items-center py-2 border-t border-slate-100">
                                                        <span className="text-xs font-medium text-slate-500">{tSales('columns.ordered')}</span>
                                                        <span className="text-sm font-semibold">{line.quantity}</span>
                                                    </div>
                                                    <div className="flex justify-between items-center py-2 border-b border-slate-100">
                                                        <span className="text-xs font-medium text-slate-500">{tSales('columns.fulfillment')}</span>
                                                        <span className="text-sm font-medium">
                                                            {canFulfil ? <span className="text-emerald-600">✅ {tSales('availabilityStatus.local')}</span> :
                                                             gap && totalAvail >= gap.orderedQuantity ? <span className="text-amber-600">🚚 {tSales('availabilityStatus.others')}</span> :
                                                             <span className="text-rose-600">❌ {tSales('availabilityStatus.shortage')}</span>}
                                                        </span>
                                                    </div>
                                                    
                                                    <div className="mt-3 flex flex-col gap-2">
                                                        <span className="text-xs font-medium text-slate-500">{tSales('columns.location')}:</span>
                                                        {lineInventory.map((inv: any) => (
                                                            <div key={inv.locationId} className="bg-slate-50 rounded p-2 text-xs flex flex-col gap-1 border border-slate-100">
                                                                <div className="flex justify-between font-medium">
                                                                    <span className={inv.locationId === order.fulfillmentLocationId ? 'text-[var(--accent)]' : ''}>{inv.locationName}</span>
                                                                    <span className={parseFloat(inv.quantityAvailable) >= line.quantity ? 'text-emerald-600' : 'text-rose-600'}>{parseFloat(inv.quantityAvailable)} avail</span>
                                                                </div>
                                                                <div className="flex justify-between text-slate-500">
                                                                    <span>{parseFloat(inv.quantityOnHand)} on hand</span>
                                                                    <span>{parseFloat(inv.quantityCommitted)} cmt / {parseFloat(inv.quantityOnOrder)} in</span>
                                                                </div>
                                                            </div>
                                                        ))}
                                                    </div>
                                                </>
                                            )}
                                        </div>
                                    );
                                }}
                            />
                        )
                    ) : (
                        /* Backorders tab */
                        <div>
                            <DataTable
                                data={order.backorders || []}
                                keyExtractor={(bo: any, idx: number) => bo.salesOrderLineId || bo.purchaseOrderId || idx}
                                emptyMessage={tSales('noBackordersFound')}
                                columns={[
                                    { header: tSales('columns.lineNumber') },
                                    { header: tSales('columns.product') },
                                    { header: tSales('columns.allocatedTo') },
                                    { header: tSales('columns.status') },
                                    { header: tSales('columns.demandDate') },
                                ]}
                                renderCustomRow={(bo: any, bo_idx: number) => {
                                    const isPo = !!bo.purchaseOrderId;
                                    const displayOrderNumber = isPo ? bo.purchaseOrderNumber || '—' : '—';
                                    const displayStatus = isPo ? bo.purchaseOrderState || PURCHASE_ORDER_STATE.DRAFT : bo.stateCode || BACKORDER_STATE.PENDING_SUPPLY;
                                    
                                    return (
                                        <tr 
                                            key={bo_idx} 
                                            className={isPo ? "cursor-pointer hover:bg-gray-50" : ""} 
                                            onClick={() => {
                                                if (isPo) {
                                                    router.push(`/purchase-orders/${bo.purchaseOrderId}`);
                                                }
                                            }}
                                        >
                                            <td className="w-12 text-center text-[var(--text-muted)] font-medium">
                                                {bo.lineNumber || '—'}
                                            </td>
                                            <td>
                                                {bo.productNumber || '—'}
                                                <div style={{ fontSize: 11, color: 'var(--text-muted)' }}>{tSales('demandedQty', { qty: bo.quantity })}</div>
                                            </td>
                                            <td style={{ color: isPo ? 'var(--accent)' : 'var(--text-muted)', fontWeight: 400 }}>{displayOrderNumber}</td>
                                            <td>
                                                {isPo ? (
                                                    <div className="flex flex-col gap-1 items-start">
                                                        <span className="badge badge-sm badge-success">{tSales('allocated')}</span>
                                                        <StateBadge state={bo.purchaseOrderState as ValidState} />
                                                    </div>
                                                ) : (
                                                    <span className="badge badge-draft">{tSales('openDemandBadge')}</span>
                                                )}
                                            </td>
                                            <td>{new Date(bo.createdOn).toLocaleDateString()}</td>
                                        </tr>
                                    );
                                }}
                                mobileCard={(bo: any) => {
                                    const isPo = !!bo.purchaseOrderId;
                                    const displayOrderNumber = isPo ? bo.purchaseOrderNumber || '—' : '—';
                                    
                                    return (
                                        <div 
                                            className={`bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col ${isPo ? 'cursor-pointer active:bg-gray-50' : ''}`}
                                            onClick={() => {
                                                if (isPo) {
                                                    router.push(`/purchase-orders/${bo.purchaseOrderId}`);
                                                }
                                            }}
                                        >
                                            <div className="flex justify-between items-start gap-2 mb-2">
                                                <div className="font-semibold text-sm text-[var(--text-primary)]">
                                                    {bo.productNumber || '—'}
                                                </div>
                                                <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">#{bo.lineNumber || '—'}</div>
                                            </div>
                                            
                                            <div className="flex flex-col gap-0 border-t border-slate-100 pt-1 mt-2">
                                                <MobileCardField label={tSales('columns.allocatedTo')} value={
                                                    <span className={isPo ? 'text-[var(--accent)]' : 'text-slate-400'}>{displayOrderNumber}</span>
                                                } />
                                                <MobileCardField label={tSales('columns.demandDate')} value={
                                                    new Date(bo.createdOn).toLocaleDateString()
                                                } />
                                                <MobileCardField label={tSales('demandedQty', { qty: bo.quantity })} value={
                                                    isPo ? (
                                                        <div className="flex flex-col gap-1 items-end mt-1">
                                                            <span className="badge badge-sm badge-success">{tSales('allocated')}</span>
                                                            <StateBadge state={bo.purchaseOrderState as ValidState} />
                                                        </div>
                                                    ) : (
                                                        <span className="badge badge-draft mt-1">{tSales('openDemandBadge')}</span>
                                                    )
                                                } />
                                            </div>
                                        </div>
                                    );
                                }}
                            />
                        </div>
                    )}
                </div>

                {sections.fulfillment.show && (
                    <FulfillmentSection orderId={id} pickingSummary={pickingSummary} />
                )}

                {sections.shipments.show && (
                    <ShipmentsSection orderId={id} />
                )}

                {sections.invoices.show && (
                    <InvoicesSection 
                        orderId={id}
                        order={order} 
                        invoices={invoices} 
                        taxCategories={taxCategories}
                        pickingSummary={pickingSummary}
                        setError={setError}
                        loadInvoices={loadInvoices}
                        loadOrder={loadOrder}
                    />
                )}

                {sections.returns.show && (
                    <ReturnsSection 
                        orderId={id}
                        order={order} 
                        returns={returns} 
                        returnsLoading={returnsLoading}
                        showCreateReturn={showCreateReturn}
                        setShowCreateReturn={setShowCreateReturn} 
                        setError={setError}
                        loadReturns={loadReturns}
                        loadOrder={loadOrder}
                        pickingSummary={pickingSummary}
                        taxCategories={taxCategories}
                        locations={locations}
                    />
                )}

                <div id="activity-section" className="card">
                    <ActivityTimeline events={order.events} />
                </div>
            </div>

            </DetailsLayout>

            <QuoteGenerationDialog
                isOpen={showQuoteDialog}
                onClose={() => setShowQuoteDialog(false)}
                onGenerate={handleGenerateQuote}
            />

            {showDiscrepancyModal && (
                <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl flex flex-col overflow-hidden">
                        <div className="px-6 py-4 border-b border-gray-200 flex justify-between items-center bg-gray-50">
                            <h2 className="text-xl font-bold text-gray-900">{tSales('discrepancies.title')}</h2>
                            <button onClick={() => setShowDiscrepancyModal(false)} className="text-gray-400 hover:text-gray-600">
                                {/* eslint-disable-next-line i18next/no-literal-string */}
                                <span className="material-symbols-outlined">close</span>
                            </button>
                        </div>
                        
                        <div className="p-6 flex flex-col gap-4">
                            <div className="max-h-96 overflow-y-auto border border-gray-200 rounded-lg">
                                <table className="w-full text-left border-collapse">
                                    <thead className="bg-gray-50 sticky top-0">
                                        <tr>
                                            <th className="px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider border-b border-gray-200">{tSales('columns.lineNumber')}</th>
                                            <th className="px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider border-b border-gray-200">{tSales('columns.product')}</th>
                                            <th className="px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider border-b border-gray-200">{tSales('columns.description')}</th>
                                            <th className="px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider border-b border-gray-200 text-right">{tSales('columns.ordered')}</th>
                                            <th className="px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider border-b border-gray-200 text-right">{tSales('columns.available')}</th>
                                            <th className="px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider border-b border-gray-200 text-right text-red-600">{tSales('columns.gap')}</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-gray-200 bg-white">
                                        {order.lines
                                            .filter(l => gapMap.has(l.salesOrderLineId))
                                            .map((line: any) => {
                                                const gap = gapMap.get(line.salesOrderLineId);
                                                return (
                                                    <tr key={line.salesOrderLineId} className="hover:bg-gray-50 transition-colors">
                                                        <td className="px-4 py-3 text-xs text-gray-500 font-medium">{line.lineNumber}</td>
                                                        <td className="px-4 py-3 text-xs text-gray-900 font-bold">{line.productNumber}</td>
                                                        <td className="px-4 py-3 text-xs text-gray-600 truncate max-w-[150px]" title={line.productDescription}>{line.productDescription}</td>
                                                        <td className="px-4 py-3 text-xs text-gray-900 text-right font-medium">{gap?.orderedQuantity}</td>
                                                        <td className="px-4 py-3 text-xs text-gray-600 text-right">{gap?.availableQuantity}</td>
                                                        <td className="px-4 py-3 text-xs text-red-600 text-right font-bold">{gap?.shortage}</td>
                                                    </tr>
                                                );
                                            })
                                        }
                                    </tbody>
                                </table>
                            </div>

                            <div className="flex justify-end gap-2 mt-4 pt-4 border-t border-gray-100">
                                <button
                                    className="btn btn-secondary"
                                    onClick={() => setShowDiscrepancyModal(false)}
                                >
                                    {tCommon('cancel')}
                                </button>
                                <button 
                                    className="btn btn-primary" 
                                    onClick={async () => {
                                        setDiscrepanciesAcknowledged(true);
                                        setShowDiscrepancyModal(false);
                                        await changeState(SALES_ORDER_STATE.CONFIRMED, true, true);
                                    }}
                                >
                                    {tCommon('confirm')}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            <style jsx>{`
                .table-lines {
                    width: 100%;
                    border-collapse: collapse;
                    margin-bottom: 1.5rem;
                }
                .table-lines th {
                    text-align: left;
                    padding: 10px 12px;
                    font-size: 11px;
                    font-weight: 700;
                    text-transform: uppercase;
                    letter-spacing: 0.05em;
                    color: var(--text-muted);
                    border-bottom: 2px solid var(--border);
                }
                .table-lines td {
                    padding: 12px;
                    font-size: 13px;
                    border-bottom: 1px solid var(--border);
                    vertical-align: middle;
                }

                .badge-draft { background: #f3f4f6; color: #374151; }
                .badge-quoted { background: #e0f2fe; color: #0369a1; }
                .badge-confirm { background: #ecfdf5; color: #047857; }
            `}</style>
        </>
    );
}

'use client';

import { use, useEffect, useState } from 'react';
import { useTranslations } from 'next-intl';
import { useRouter } from 'next/navigation';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import StateBadge, { StateName } from '@/components/StateBadge';
import { ValidState } from '@/types/states';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import ActivityTimeline, { TimelineEvent } from '@/components/shared/ActivityTimeline';
import Link from 'next/link';
import { toast } from 'react-hot-toast';
import { SHIPMENT_STATE } from '@modbm/shared';
import MobileLineItemCard from '@/components/shared/MobileLineItemCard';
import { getErrorMessage } from '@modbm/shared';

interface ShipmentLine {
  shipmentLineId: string;
  salesOrderLineId: string;
  quantityShipped: string;
  productId: string;
  productNumber: string;
  productDescription: string;
  orderNumber: string;
}

interface ShipmentDetail {
  shipmentId: string;
  shipmentNumber: string;
  salesOrderId: string;
  orderNumber: string;
  customerId: string;
  customerName: string;
  stateCode: string;
  notes: string | null;
  trackingNumber: string | null;
  createdOn: string;
  createdBy: string | null;
  lines: ShipmentLine[];
  events: TimelineEvent[];
}

export default function ShipmentDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const t = useTranslations('shipments');
  const tCommon = useTranslations('common');
  const router = useRouter();
  const [shipment, setShipment] = useState<ShipmentDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const [isCancelling, setIsCancelling] = useState(false);

  const loadShipment = () => {
    setLoading(true);
    (api.globalShipmentsControllerFindOne(id) )
      .then((res: any) => {
        setShipment(res.data ? res.data : res);
        setLoading(false);
      })
      .catch((err: any) => {
        reportError(err, 'ShipmentDetailPage.loadShipment');
        setLoading(false);
      });
  };

  useEffect(() => {
    loadShipment();
  }, [id]);

  const handleCancel = async () => {
    if (!shipment) return;
    if (!window.confirm(t('confirmCancel'))) return;

    setIsCancelling(true);
    try {
      await api.orderShipmentsControllerCancelShipment(shipment.salesOrderId, shipment.shipmentId, { body: JSON.stringify({}) });
      loadShipment();
    } catch (err: unknown) {
      reportError(err, 'ShipmentDetailPage.handleCancel');
      alert(getErrorMessage(err) || t('cancelFailed'));
    } finally {
      setIsCancelling(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center flex-1">
        <p style={{ color: 'var(--text-muted)' }}>{tCommon('loading')}</p>
      </div>
    );
  }

  if (!shipment) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-[var(--text-muted)]">
        <p className="mb-4">{t('notFound')}</p>
        <button className="btn btn-primary" onClick={() => router.push('/shipments')}>
          {t('backToShipments')}
        </button>
      </div>
    );
  }

  return (
    <DetailsLayout
      header={
        <EntityHeader
          title={shipment.shipmentNumber}
          subtitle={`${t('shipmentDetails')} • ${new Date(shipment.createdOn).toLocaleDateString()}`}
          onBack={() => router.push('/shipments')}
          badges={<StateBadge state={shipment.stateCode as ValidState} />}
          actions={
            shipment.stateCode === SHIPMENT_STATE.DISPATCHED && (
              <button
                className="btn btn-danger btn-sm"
                onClick={handleCancel}
                disabled={isCancelling}
              >
                {isCancelling ? (
                  tCommon('resolving')
                ) : (
                  <>
                    {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined mr-1" style={{ fontSize: 16 }}>close</span>
            {/* eslint-enable i18next/no-literal-string */}
                    {tCommon('cancel')}
                  </>
                )}
              </button>
            )
          }
        />
      }
    >
      <div className="flex flex-col gap-3">
        {/* Shipment Details Card */}
        <div id="details-section" className="card">
          <div className="flex items-center justify-between mb-4 gap-4">
            <h3 className="section-heading flex items-center gap-2 truncate">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined shrink-0">local_shipping</span>
              {/* eslint-enable i18next/no-literal-string */}
              <span className="truncate">{t('shipmentDetails')}</span>
            </h3>
            <button
              className="btn btn-secondary btn-sm flex items-center shrink-0"
              onClick={async () => {
                try {
                  const api = await import('@modbm/sdk');
                  const res = await api.reportsControllerRunHook('shipping-docket', {}, { id, context: 'shipment' });
                  const blob = res.data as Blob;
                  const url = URL.createObjectURL(blob);
                  window.open(url, '_blank');
                } catch (err) {
                  reportError(err, 'ShipmentDetailPage.generateDocket');
                  toast.error('Failed to generate shipping docket.');
                }
              }}
            >
              {t('docketPdf')}
            </button>
          </div>
          
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {t('columns.customer')}
              </label>
              <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                {shipment.customerName || '—'}
              </p>
            </div>
            
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {t('columns.tracking')}
              </label>
              <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                {shipment.trackingNumber || '—'}
              </p>
            </div>

            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {t('columns.date')}
              </label>
              <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                {new Date(shipment.createdOn).toLocaleString()} {tCommon('by')} {shipment.createdBy || tCommon('system')}
              </p>
            </div>

            <div className="col-span-2">
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {tCommon('notesCardHeading')}
              </label>
              <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                {shipment.notes || '—'}
              </p>
            </div>
          </div>
        </div>

        {/* Line Items Card */}
        <div id="lines-section" className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading flex items-center gap-2">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined shrink-0">list_alt</span>
              {/* eslint-enable i18next/no-literal-string */}
              <span>{t('lineItems')}</span>
            </h3>
          </div>
          
          {/* Desktop Table */}
          <div className="hidden sm:block overflow-x-auto">
            <table className="table-lines min-w-[500px]">
              <thead>
                <tr>
                <th style={{ width: 120 }}>{t('columns.orderNumber')}</th>
                <th>{t('columns.product')}</th>
                <th>{t('columns.description')}</th>
                <th style={{ width: 90, textAlign: 'right' }}>{t('columns.qty')}</th>
              </tr>
            </thead>
            <tbody>
              {shipment.lines.map((line) => (
                <tr key={line.shipmentLineId}>
                  <td style={{ color: 'var(--text-muted)', fontWeight: 400 }}>
                    {line.orderNumber}
                  </td>
                  <td style={{ fontWeight: 600, fontSize: 12 }}>
                    <Link href={`/products/${line.productId}`} style={{ color: 'var(--accent)', textDecoration: 'none' }}>
                      {line.productNumber || '—'}
                    </Link>
                  </td>
                  <td>{line.productDescription || '—'}</td>
                  <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                    {line.quantityShipped}
                  </td>
                </tr>
              ))}
              {shipment.lines.length === 0 && (
                <tr>
                  <td colSpan={4} style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '20px 0' }}>
                    {tCommon('orderReadView.noLineItems')}
                  </td>
                </tr>
              )}
              </tbody>
            </table>
          </div>

          {/* Mobile Cards */}
          <div className="flex flex-col lg:hidden mt-2">
            {shipment.lines.map((line, idx) => (
              <MobileLineItemCard
                key={line.shipmentLineId}
                title={
                  <Link href={`/products/${line.productId}`} className="text-[var(--accent)] hover:underline">
                    {line.productNumber || '—'}
                  </Link>
                }
                subtitle={line.productDescription || '—'}
                topRightBadge={`#${idx + 1}`}
                details={[
                  {
                    label: t('columns.qty'),
                    value: line.quantityShipped
                  },
                  {
                    label: t('columns.orderNumber'),
                    value: <span className="font-semibold text-[var(--text-secondary)]">{line.orderNumber}</span>
                  }
                ]}
              />
            ))}
            {shipment.lines.length === 0 && (
              <div className="text-center text-sm text-[var(--text-muted)] py-4 border border-[var(--border)] rounded-lg">
                {tCommon('orderReadView.noLineItems')}
              </div>
            )}
          </div>
        </div>

        {/* Activity Timeline Card */}
        <div id="activity-section" className="card">
          <ActivityTimeline events={shipment.events} />
        </div>
      </div>
    </DetailsLayout>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import StateBadge from '@/components/StateBadge';
import { formatAmount } from '@/lib/currency';
import { ValidState } from '@/types/states';
import POMatchingPanel from '@/components/shared/POMatchingPanel';
import ProductSearchInput from '@/components/shared/ProductSearchInput';
import SupplierSelect from '@/components/shared/SupplierSelect';
import MobileLineItemCard from '@/components/shared/MobileLineItemCard';
import { cap, isBackTransition, PURCHASE_INVOICE_LIFECYCLE, PURCHASE_INVOICE_STATE, MATCH_STATUS } from '@modbm/shared';
import { useSupplierInvoice, PurchaseInvoiceDetails } from './useSupplierInvoice';
import PaymentManagerSlideOver from '@/app/payments/PaymentManagerSlideOver';

export default function PurchaseInvoiceDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const router = useRouter();
  const { id } = React.use(params);
  const t = useTranslations('purchaseOrders');
  const tCommon = useTranslations('common');
  const [selectedPaymentId, setSelectedPaymentId] = useState<string | null>(null);

  const {
    invoice, loading, saving,
    isMatchingMode, setIsMatchingMode,
    selectedInvoiceLineId, setSelectedInvoiceLineId,
    showDiscrepancyModal, setShowDiscrepancyModal,
    pendingState,
    setDiscrepanciesAcknowledged,
    editSupplierInvoiceNumber, setEditSupplierInvoiceNumber,
    editReceiptFilename, setEditReceiptFilename,
    editCurrencyCode, setEditCurrencyCode,
    editTaxAmount, setEditTaxAmount,
    editNotes, setEditNotes,
    editVendorId, setEditVendorId,
    glAccounts,
    headerDirty,
    discrepancies,
    matchingPanelLines,
    allowedTransitions,
    saveHeader,
    changeState,
    handleAutoMatch,
    handlePanelMatch,
    updateLine,
    removeLine,
    addBlankLine,
    addRoundingLine,
    handleProductSelect,
    handleUnresolve,
    loadInvoice,
  } = useSupplierInvoice(id);

  useDocumentTitle(invoice ? `Invoice ${invoice.invoiceNumber}` : 'Loading Invoice...');

  // Auto-select first unmatched line when entering matching mode
  useEffect(() => {
    if (isMatchingMode && !selectedInvoiceLineId) {
      const first = invoice?.lines.find((l) => l.matchStatus !== MATCH_STATUS.MATCHED);
      if (first) setSelectedInvoiceLineId(first.lineId);
    }
    if (!isMatchingMode) setSelectedInvoiceLineId(null);
  }, [isMatchingMode]);

  if (loading) {
    return <div className="flex items-center justify-center p-12 text-gray-500 text-sm">Loading...</div>;
  }

  if (!invoice) {
    return <div className="flex items-center justify-center p-12 text-gray-500 text-sm">{tCommon('errors.failedToLoadOrder', { defaultValue: 'Invoice not found.' })}</div>;
  }

  const isEditable = invoice.stateCode === PURCHASE_INVOICE_STATE.DRAFT;
  const canEditLines = isEditable && !isMatchingMode;
  const isBack = (from: string, to: string) => isBackTransition(PURCHASE_INVOICE_LIFECYCLE, from, to);

  const InvoiceAllocationCell = ({ line }: { line: PurchaseInvoiceDetails['lines'][0] }) => {
    if (line.matchStatus === MATCH_STATUS.MATCHED) {
      return (
        <div className="flex items-center justify-between gap-2 h-full w-full">
          <div className="flex flex-col gap-1">
            { }
            <span className="text-xs text-gray-500 font-semibold uppercase tracking-wider">{t('inventoryAsset')}</span>
            { }
            <span style={{ fontWeight: 500, fontSize: 12 }}>{t('poNumberLabel', { number: line.purchaseOrderNumber || '' })}</span>
          </div>
          {isEditable && (
            <button
              onClick={() => handleUnresolve(line.lineId)}
              className="btn btn-secondary btn-sm"
              style={{ padding: '0 6px', height: 22, fontSize: 11 }}
              title="Change Allocation"
            >
              {t('buttons.change')}
            </button>
          )}
        </div>
      );
    }

    return (
      <div className="flex items-center justify-between gap-2 w-full h-full">
        {isEditable ? (
          <select
            className="input"
            style={{ width: '100%', fontSize: 12, padding: '2px 6px' }}
            value={line.glAccountId || ''}
            onChange={(e) => updateLine(line.lineId, 'glAccountId', e.target.value)}
          >
            { }
            <option value="" disabled>{t('selectGlAccount')}</option>
            {glAccounts
              .filter(a => a.accountType === 'expense' || a.accountType === 'asset' || a.accountType === 'liability')
              .map((acc) => (
                <option key={acc.glAccountId} value={acc.glAccountId}>
                  {acc.accountCode} - {acc.name}
                </option>
              ))}
          </select>
        ) : (
          <div className="text-xs truncate">
            {glAccounts.find(a => a.glAccountId === line.glAccountId)?.name || t('defaultExpense')}
          </div>
        )}
      </div>
    );
  };

  const matchIcon = isMatchingMode ? 'check' : 'link';

  return (
    <DetailsLayout
      header={
        <EntityHeader
          title={invoice.invoiceNumber}
          subtitle={invoice.supplierInvoiceNumber ? `Supplier Ref: ${invoice.supplierInvoiceNumber}` : undefined}
          onBack={() => router.push('/supplier-invoices')}
          badges={<StateBadge state={invoice.stateCode as ValidState} />}
          isSaving={saving}
          actions={
            <>

              {!headerDirty && allowedTransitions.includes(PURCHASE_INVOICE_STATE.CANCELLED) && (
                <button
                  className="btn btn-danger btn-sm"
                  onClick={() => {
                    if (confirm('Are you sure you want to cancel this invoice?')) {
                      changeState(PURCHASE_INVOICE_STATE.CANCELLED);
                    }
                  }}
                  disabled={saving}
                >
                  {tCommon('cancel')}
                </button>
              )}
              {!headerDirty && invoice.stateCode === PURCHASE_INVOICE_STATE.DRAFT && allowedTransitions.includes(PURCHASE_INVOICE_STATE.INVOICED) && (
                <button
                  className="btn btn-primary btn-sm"
                  onClick={() => changeState(PURCHASE_INVOICE_STATE.INVOICED)}
                  disabled={saving}
                >
                  {t('buttons.approveInvoice')}
                </button>
              )}
            </>
          }
        />
      }
    >
      <div className="flex flex-col gap-3">
        <div className="card">
          <h3 className="section-heading">
            {/* eslint-disable-next-line i18next/no-literal-string */}
            <span className="material-symbols-outlined">receipt_long</span>
            Invoice Details
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

            <div>
              <label className="block text-xs font-medium mb-1" style={{ color: 'var(--text-muted)' }}>
                {t('labels.supplier')}
              </label>
              {isEditable ? (
                <div style={{ height: 38 }}>
                  <SupplierSelect
                    value={editVendorId}
                    initialSearchTerm={invoice.vendorName || invoice.vendorId}
                    onChange={(s) => {
                      if (s) {
                        setEditVendorId(s.vendorId);
                        saveHeader(s.vendorId);
                      }
                    }}
                    placeholder="Select supplier..."
                  />
                </div>
              ) : (
                <div className="text-sm">{invoice.vendorName || invoice.vendorId}</div>
              )}
            </div>
            <div>
              <label className="block text-xs font-medium mb-1" style={{ color: 'var(--text-muted)' }}>
                {t('columns.supplierInvoiceNumber')}
              </label>
              {isEditable ? (
                <input
                  className="input"
                  value={editSupplierInvoiceNumber}
                  onChange={(e) => setEditSupplierInvoiceNumber(e.target.value)}
                  onBlur={() => saveHeader()}
                  placeholder="e.g. INV-2024-999"
                />
              ) : (
                <div className="text-sm">{invoice.supplierInvoiceNumber || '—'}</div>
              )}
            </div>
            <div>
              <label className="block text-xs font-medium mb-1" style={{ color: 'var(--text-muted)' }}>
                {tCommon('columns.currency')}
              </label>
              {isEditable ? (
                <input
                  className="input"
                  value={editCurrencyCode}
                  onChange={(e) => setEditCurrencyCode(e.target.value)}
                  onBlur={() => saveHeader()}
                  maxLength={3}
                />
              ) : (
                <div className="text-sm">{invoice.currencyCode}</div>
              )}
            </div>
            <div>
              <label className="block text-xs font-medium mb-1" style={{ color: 'var(--text-muted)' }}>
                {t('labels.receiptFilename')}
              </label>
              {isEditable ? (
                <input
                  className="input"
                  value={editReceiptFilename}
                  onChange={(e) => setEditReceiptFilename(e.target.value)}
                  onBlur={() => saveHeader()}
                  placeholder="e.g. receipt_scan.pdf"
                />
              ) : (
                <div className="text-sm">{invoice.receiptFilename || '—'}</div>
              )}
            </div>
            <div className="md:col-span-2 mt-2">
              <label className="block text-xs font-medium mb-1" style={{ color: 'var(--text-muted)' }}>
                {tCommon('notesCardHeading')}
              </label>
              {isEditable ? (
                <input
                  className="input w-full"
                  value={editNotes}
                  onChange={(e) => setEditNotes(e.target.value)}
                  onBlur={() => saveHeader()}
                  placeholder={tCommon('notesCardPlaceholder')}
                />
              ) : invoice.notes ? (
                <div className="text-sm bg-gray-50 p-3 rounded">{invoice.notes}</div>
              ) : (
                <div className="text-sm" style={{ color: 'var(--text-muted)' }}>—</div>
              )}
            </div>
          </div>
        </div>

        <div style={{ display: 'flex', gap: 0, minHeight: 0 }}>
          <div className="card" style={{ flex: 1, minWidth: 0 }}>
            <div className="flex items-center justify-between mb-4">
              <h3 className="section-heading" style={{ marginBottom: 0 }}>
                {/* eslint-disable-next-line i18next/no-literal-string */}
                <span className="material-symbols-outlined">list</span>
                {t('lineItems')}
              </h3>
              {isEditable && (
                <div className="flex gap-2">
                  <button
                    className={`btn btn-sm ${isMatchingMode ? 'btn-primary' : 'btn-secondary'}`}
                    onClick={() => setIsMatchingMode(!isMatchingMode)}
                    disabled={saving}
                  >
                    <span className="material-symbols-outlined" style={{ fontSize: 16, verticalAlign: 'middle', marginRight: 4 }}>
                      {matchIcon}
                    </span>
                    {isMatchingMode ? t('matching.panelTitle') : t('matching.panelTitle')}
                  </button>
                  {!isMatchingMode && (
                    <>
                      <button
                        className="btn btn-secondary btn-sm"
                        onClick={addBlankLine}
                        disabled={saving}
                      >
                        {t('addLine')}
                      </button>
                      <button
                        className="btn btn-secondary btn-sm"
                        onClick={addRoundingLine}
                        disabled={saving}
                      >
                        {t('addRoundingAdj')}
                      </button>
                    </>
                  )}
                </div>
              )}
            </div>
            {/* Desktop Table */}
            <table className="table-lines hidden lg:table" style={isMatchingMode ? { fontSize: 11 } : undefined}>
              <thead>
                <tr>
                  <th style={{ width: 40 }}>#</th>
                  <th style={{ width: 150 }}>{t('columns.product')}</th>
                  <th>{t('columns.description')}</th>
                  {!isMatchingMode && <th style={{ width: 280 }}>{t('columns.allocation')}</th>}
                  <th style={{ width: 90, textAlign: 'right' }}>{t('columns.qtyToBill', { defaultValue: 'Qty' })}</th>
                  <th style={{ width: 110, textAlign: 'right' }}>{t('columns.unitPrice')}</th>
                  <th style={{ width: 110, textAlign: 'right' }}>{t('columns.amount')}</th>
                  {!isMatchingMode && isEditable && <th style={{ width: 50 }}></th>}
                  {isMatchingMode && <th style={{ width: 70, textAlign: 'center' }}>{t('columns.status')}</th>}
                </tr>
              </thead>
              <tbody>
                {invoice.lines?.map((line, idx) => {
                  const isSelected = isMatchingMode && selectedInvoiceLineId === line.lineId;
                  const isUnmatched = line.matchStatus !== MATCH_STATUS.MATCHED;
                  return (
                    <tr
                      key={line.lineId}
                      onClick={isMatchingMode && isUnmatched && isEditable ? () => setSelectedInvoiceLineId(line.lineId) : undefined}
                      style={{
                        cursor: isMatchingMode && isUnmatched && isEditable ? 'pointer' : undefined,
                        borderLeft: isSelected ? '3px solid var(--accent)' : '3px solid transparent',
                        background: isSelected ? 'rgba(0, 107, 92, 0.04)' : undefined,
                        transition: 'background 0.15s, border-color 0.15s',
                      }}
                    >
                      <td style={{ color: 'var(--text-muted)' }}>{idx + 1}</td>
                      <td>
                        {canEditLines && (!line.productId || line.productId === '00000000-0000-0000-0000-000000000000') ? (
                          <ProductSearchInput
                            onSelect={(p) => handleProductSelect(line.lineId, p)}
                            placeholder="Search product…"
                            style={{ minWidth: 120 }}
                          />
                        ) : line.productId && line.productId !== '00000000-0000-0000-0000-000000000000' ? (
                          <div className="font-semibold" style={{ color: 'var(--accent)' }}>
                            {line.productNumber || line.productId.substring(0, 8)}
                          </div>
                        ) : (
                          <span style={{ color: 'var(--text-muted)' }}>—</span>
                        )}
                      </td>
                      <td>
                        {canEditLines ? (
                          <input
                            className="input"
                            style={{ width: '100%', fontSize: 13 }}
                            defaultValue={line.description || ''}
                            key={`desc-${line.lineId}-${line.description}`}
                            onBlur={(e) => {
                              if (e.target.value !== (line.description || '')) {
                                updateLine(line.lineId, 'description', e.target.value);
                              }
                            }}
                            placeholder="Description"
                          />
                        ) : (
                          <div>{line.description || '—'}</div>
                        )}
                      </td>
                      {!isMatchingMode && (
                        <td>
                          <InvoiceAllocationCell line={line} />
                        </td>
                      )}
                      <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                        {canEditLines ? (
                          <input
                            className="input"
                            type="number"
                            min="0"
                            step="0.01"
                            style={{ width: '100%', textAlign: 'right' }}
                            defaultValue={line.quantityInvoiced}
                            key={`qty-${line.lineId}-${line.quantityInvoiced}`}
                            onBlur={(e) => {
                              if (e.target.value !== line.quantityInvoiced) {
                                updateLine(line.lineId, 'quantityInvoiced', e.target.value);
                              }
                            }}
                          />
                        ) : (
                          parseFloat(line.quantityInvoiced)
                        )}
                      </td>
                      <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                        {canEditLines ? (
                          <input
                            className="input"
                            type="number"
                            min="0"
                            step="0.01"
                            style={{ width: '100%', textAlign: 'right' }}
                            defaultValue={parseFloat(line.pricePerUnit || '0').toFixed(2)}
                            key={`price-${line.lineId}-${line.pricePerUnit}`}
                            onBlur={(e) => {
                              const val = parseFloat(e.target.value);
                              const formatted = isNaN(val) ? '0.00' : val.toFixed(2);
                              e.target.value = formatted;
                              if (formatted !== parseFloat(line.pricePerUnit || '0').toFixed(2)) {
                                updateLine(line.lineId, 'pricePerUnit', formatted);
                              }
                            }}
                          />
                        ) : (
                          formatAmount(parseFloat(line.pricePerUnit), invoice.currencyCode)
                        )}
                      </td>
                      <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                        {formatAmount(parseFloat(line.amount), invoice.currencyCode)}
                      </td>
                      {canEditLines && (
                        <td style={{ textAlign: 'center' }}>
                          <button
                            className="text-gray-400 hover:text-red-500"
                            onClick={() => removeLine(line.lineId)}
                            title="Remove Line"
                          >
                            { }
                            {'✕'}
                          </button>
                        </td>
                      )}
                      {isMatchingMode && (
                        <td style={{ textAlign: 'center' }}>
                          {line.matchStatus === MATCH_STATUS.MATCHED ? (
                            <>
                              { }
                              <span style={{ fontSize: 10, fontWeight: 600, color: 'var(--badge-shipped)' }}>{'✓'}</span>
                            </>
                          ) : (
                            <span style={{ fontSize: 10, color: 'var(--text-muted)' }}>—</span>
                          )}
                        </td>
                      )}
                    </tr>
                  );
                })}
                {(!invoice.lines || invoice.lines.length === 0) && (
                  <tr>
                    <td colSpan={isEditable ? 8 : 7} style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '20px 0' }}>
                      {t('noItems')}
                    </td>
                  </tr>
                )}
                <tr style={{ borderTop: '2px solid var(--border)' }}>
                  <td colSpan={6} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                    {tCommon('subtotal')}
                  </td>
                  <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                    {formatAmount(parseFloat(invoice.totalAmount) - parseFloat(invoice.taxAmount), invoice.currencyCode)}
                  </td>
                  {isEditable && <td></td>}
                </tr>
                <tr>
                  <td colSpan={6} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                    {tCommon('tax')}
                  </td>
                  <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                    {isEditable ? (
                      <input
                        className="input"
                        type="number"
                        min="0"
                        step="0.01"
                        style={{ width: 100, textAlign: 'right', padding: '2px 8px', height: 26 }}
                        value={editTaxAmount}
                        onFocus={(e) => {
                          if (parseFloat(e.target.value) === 0) {
                            setEditTaxAmount('');
                          }
                        }}
                        onChange={(e) => setEditTaxAmount(e.target.value)}
                        onBlur={() => {
                          if (editTaxAmount === '') {
                            setEditTaxAmount('0.00');
                          }
                          saveHeader();
                        }}
                      />
                    ) : (
                      formatAmount(parseFloat(invoice.taxAmount), invoice.currencyCode)
                    )}
                  </td>
                  {isEditable && <td></td>}
                </tr>
                <tr style={{ backgroundColor: 'rgba(59,130,246,0.02)' }}>
                  <td colSpan={6} style={{ textAlign: 'right', fontWeight: 700, fontSize: 13, color: 'var(--text-primary)' }}>
                    {tCommon('total')}
                  </td>
                  <td style={{ textAlign: 'right', fontWeight: 800, fontSize: 14, color: 'var(--accent)', fontVariantNumeric: 'tabular-nums' }}>
                    {formatAmount(parseFloat(invoice.totalAmount), invoice.currencyCode)}
                  </td>
                  {isEditable && <td></td>}
                </tr>
              </tbody>
            </table>

            {/* Mobile Cards */}
            <div className="flex flex-col gap-3 lg:hidden mt-2">
              {invoice.lines?.map((line, idx) => {
                const isSelected = isMatchingMode && selectedInvoiceLineId === line.lineId;
                const isUnmatched = line.matchStatus !== MATCH_STATUS.MATCHED;
                return (
                  <div
                    key={`mob-wrap-${line.lineId}`}
                    onClick={isMatchingMode && isUnmatched && isEditable ? () => setSelectedInvoiceLineId(line.lineId) : undefined}
                    style={{
                      cursor: isMatchingMode && isUnmatched && isEditable ? 'pointer' : undefined,
                      borderLeft: isSelected ? '3px solid var(--accent)' : undefined,
                      background: isSelected ? 'rgba(0, 107, 92, 0.04)' : undefined,
                      transition: 'background 0.15s, border-color 0.15s',
                    }}
                  >
                    <MobileLineItemCard
                      key={`mob-${line.lineId}`}
                      topRightBadge={`#${idx + 1}`}
                      title={
                        <div className="flex items-center gap-2">
                          {canEditLines && (!line.productId || line.productId === '00000000-0000-0000-0000-000000000000') ? (
                            <ProductSearchInput
                              onSelect={(p) => handleProductSelect(line.lineId, p)}
                              placeholder="Search product…"
                            />
                          ) : line.productId && line.productId !== '00000000-0000-0000-0000-000000000000' ? (
                            <span className="font-bold" style={{ color: 'var(--accent)' }}>
                              {line.productNumber || line.productId.substring(0, 8)}
                            </span>
                          ) : (
                            <span className="font-medium text-slate-500">Custom Item</span>
                          )}
                          {canEditLines && (
                            <button className="text-gray-400 hover:text-red-500 ml-auto" onClick={(e) => { e.stopPropagation(); removeLine(line.lineId); }}>
                              <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} />
                            </button>
                          )}
                        </div>
                      }
                      subtitle={
                        canEditLines ? (
                          <input
                            className="input w-full text-sm mt-1"
                            defaultValue={line.description || ''}
                            key={`desc-mob-${line.lineId}-${line.description}`}
                            onBlur={(e) => {
                              if (e.target.value !== (line.description || '')) {
                                updateLine(line.lineId, 'description', e.target.value);
                              }
                            }}
                            placeholder="Description"
                          />
                        ) : (
                          <span>{line.description || '—'}</span>
                        )
                      }
                      details={[
                        ...(isMatchingMode ? [{
                          label: 'Status',
                          value: line.matchStatus === MATCH_STATUS.MATCHED ? (
                            <span style={{ fontWeight: 600, color: 'var(--badge-shipped)' }}>{'✓ Matched'}</span>
                          ) : (
                            <span className="text-[var(--text-muted)]">Unmatched</span>
                          )
                        }] : []),
                        {
                          label: t('columns.qtyToBill', { defaultValue: 'Qty' }),
                          value: canEditLines ? (
                            <input
                              className="input"
                              type="number"
                              min="0"
                              step="0.01"
                              style={{ width: '80px', textAlign: 'right' }}
                              defaultValue={line.quantityInvoiced}
                              key={`qty-mob-${line.lineId}-${line.quantityInvoiced}`}
                              onBlur={(e) => {
                                if (e.target.value !== line.quantityInvoiced) {
                                  updateLine(line.lineId, 'quantityInvoiced', e.target.value);
                                }
                              }}
                            />
                          ) : (
                            <span className="font-medium text-[var(--text-primary)]">{parseFloat(line.quantityInvoiced)}</span>
                          ),
                        },
                        {
                          label: t('columns.unitPrice'),
                          value: canEditLines ? (
                            <input
                              className="input"
                              type="number"
                              min="0"
                              step="0.01"
                              style={{ width: '90px', textAlign: 'right' }}
                              defaultValue={parseFloat(line.pricePerUnit || '0').toFixed(2)}
                              key={`price-mob-${line.lineId}-${line.pricePerUnit}`}
                              onBlur={(e) => {
                                const val = parseFloat(e.target.value);
                                const formatted = isNaN(val) ? '0.00' : val.toFixed(2);
                                e.target.value = formatted;
                                if (formatted !== parseFloat(line.pricePerUnit || '0').toFixed(2)) {
                                  updateLine(line.lineId, 'pricePerUnit', formatted);
                                }
                              }}
                            />
                          ) : (
                            <span className="font-medium text-[var(--text-primary)]">{formatAmount(parseFloat(line.pricePerUnit), invoice.currencyCode)}</span>
                          ),
                        },
                        {
                          label: t('columns.amount'),
                          value: formatAmount(parseFloat(line.amount), invoice.currencyCode),
                          isHighlighted: true
                        }
                      ]}
                    >
                      {!isMatchingMode && (
                        <div className="pt-2 mt-2 border-t border-slate-100">
                          <label className="text-[11px] uppercase tracking-wider font-semibold text-slate-500 mb-1.5 block">{t('columns.allocation')}</label>
                          <div className="border border-slate-200 rounded p-2 bg-[var(--bg-primary)]">
                            <InvoiceAllocationCell line={line} />
                          </div>
                        </div>
                      )}
                    </MobileLineItemCard>
                  </div>
                );
              })}

              {(!invoice.lines || invoice.lines.length === 0) && (
                <div className="text-center text-[var(--text-muted)] py-6 text-sm">
                  {t('noItems')}
                </div>
              )}

              <div className="mt-2 bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4">
                <table className="w-full text-sm">
                  <tbody>
                    <tr>
                      <td className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tCommon('subtotal')}</td>
                      <td className="py-1 text-sm font-semibold text-right tabular-nums">
                        {formatAmount(parseFloat(invoice.totalAmount) - parseFloat(invoice.taxAmount), invoice.currencyCode)}
                      </td>
                    </tr>
                    <tr>
                      <td className="py-1 text-xs font-medium text-slate-500 text-right pr-4">{tCommon('tax')}</td>
                      <td className="py-1 text-sm font-semibold text-right tabular-nums">
                        {isEditable ? (
                          <input
                            className="input"
                            type="number"
                            min="0"
                            step="0.01"
                            style={{ width: 100, textAlign: 'right', padding: '2px 8px', height: 26 }}
                            value={editTaxAmount}
                            onFocus={(e) => {
                              if (parseFloat(e.target.value) === 0) {
                                setEditTaxAmount('');
                              }
                            }}
                            onChange={(e) => setEditTaxAmount(e.target.value)}
                            onBlur={() => {
                              if (editTaxAmount === '') {
                                setEditTaxAmount('0.00');
                              }
                              saveHeader();
                            }}
                          />
                        ) : (
                          formatAmount(parseFloat(invoice.taxAmount), invoice.currencyCode)
                        )}
                      </td>
                    </tr>
                    <tr>
                      <td className="py-2 text-sm font-bold text-[var(--accent)] text-right pr-4">{tCommon('total')}</td>
                      <td className="py-2 text-base font-bold text-[var(--accent)] text-right tabular-nums">
                        {formatAmount(parseFloat(invoice.totalAmount), invoice.currencyCode)}
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          </div>

          {/* Right: Matching Panel */}
          {isMatchingMode && isEditable && invoice.vendorId && (
            <POMatchingPanel
              vendorId={invoice.vendorId}
              currencyCode={invoice.currencyCode}
              invoiceLines={matchingPanelLines}
              selectedLineId={selectedInvoiceLineId}
              onMatch={handlePanelMatch}
              onAutoMatch={handleAutoMatch}
              onClose={() => setIsMatchingMode(false)}
            />
          )}

          {showDiscrepancyModal && (
            <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl flex flex-col overflow-hidden">
                <div className="px-6 py-4 border-b border-gray-200 flex justify-between items-center bg-gray-50">
                  <h2 className="text-xl font-bold text-gray-900">{t('invoiceDiscrepancies')}</h2>
                  <button onClick={() => setShowDiscrepancyModal(false)} className="text-gray-400 hover:text-gray-600">
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined">close</span>
                  </button>
                </div>

                <div className="p-6 flex flex-col gap-4">
                  <div className="max-h-96 overflow-y-auto border border-gray-200 rounded-lg">
                    <table className="w-full text-left border-collapse">
                      <thead className="bg-gray-50 sticky top-0">
                        <tr>
                          <th className="px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider border-b border-gray-200">{t('columns.line')}</th>
                          <th className="px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider border-b border-gray-200">{t('columns.issueType')}</th>
                          <th className="px-4 py-2 text-[10px] font-bold text-gray-500 uppercase tracking-wider border-b border-gray-200">{t('columns.details')}</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-gray-200 bg-white">
                        {discrepancies.map((d, i) => {
                          const lineIdx = invoice.lines.findIndex(l => l.lineId === d.lineId);
                          return (
                            <tr key={i} className="hover:bg-gray-50 transition-colors">
                              <td className="px-4 py-3 text-xs text-gray-500 font-medium">{lineIdx + 1}</td>
                              <td className="px-4 py-3 text-xs text-gray-900 font-bold uppercase tracking-tight">
                                {d.type.replace(/_/g, ' ')}
                              </td>
                              <td className="px-4 py-3 text-xs text-gray-600">{d.message}</td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>

                  <div className="flex justify-end gap-2 mt-4 pt-4 border-t border-gray-100">
                    <button
                      className="btn btn-secondary"
                      onClick={() => setShowDiscrepancyModal(false)}
                    >
                      {tCommon('cancel')}
                    </button>
                    <button
                      className="btn btn-primary"
                      onClick={async () => {
                        setDiscrepanciesAcknowledged(true);
                        setShowDiscrepancyModal(false);
                        if (pendingState) {
                          await changeState(pendingState, true);
                        }
                      }}
                    >
                      {tCommon('confirm')}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Payment Allocations Card */}
        <div className="card mt-4 p-5">
          <h2 className="text-sm font-bold text-gray-500 uppercase tracking-wider mb-4">{t('paymentAllocations')}</h2>
          {invoice.allocations && invoice.allocations.length > 0 ? (
            <>
              <div className="hidden lg:block overflow-x-auto">
                <table className="w-full text-left border-collapse mt-2">
                  <thead>
                    <tr className="border-b border-[var(--border)]">
                      <th className="py-2 text-xs font-semibold" style={{ color: 'var(--text-muted)' }}>{t('columns.paymentNo')}</th>
                      <th className="py-2 text-xs font-semibold" style={{ color: 'var(--text-muted)' }}>{t('columns.date')}</th>
                      <th className="py-2 text-xs font-semibold text-right" style={{ color: 'var(--text-muted)' }}>{t('columns.allocatedAmount')}</th>
                    </tr>
                  </thead>
                  <tbody>
                    {invoice.allocations.map((alloc) => (
                      <tr key={alloc.allocationId} className="border-b border-[var(--border)] last:border-0 hover:bg-[var(--bg-card-hover)] transition-colors">
                        <td className="py-2 text-sm font-medium">
                          <span className="text-[var(--accent)] cursor-pointer hover:underline" onClick={() => setSelectedPaymentId(alloc.paymentId)}>
                            {alloc.paymentNumber}
                          </span>
                        </td>
                        <td className="py-2 text-sm" style={{ color: 'var(--text-secondary)' }}>
                          {new Date(alloc.paymentDate).toLocaleDateString()}
                        </td>
                        <td className="py-2 text-sm font-semibold text-right" style={{ fontVariantNumeric: 'tabular-nums' }}>
                          {formatAmount(parseFloat(alloc.allocatedAmount), alloc.currencyCode)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <div className="flex flex-col lg:hidden gap-3 mt-2">
                {invoice.allocations.map((alloc) => (
                  <MobileLineItemCard
                    key={alloc.allocationId}
                    title={
                      <span className="text-[var(--accent)] cursor-pointer hover:underline" onClick={() => setSelectedPaymentId(alloc.paymentId)}>
                        {alloc.paymentNumber}
                      </span>
                    }
                    subtitle={new Date(alloc.paymentDate).toLocaleDateString()}
                    details={[
                      {
                        label: t('columns.allocatedAmount'),
                        value: formatAmount(parseFloat(alloc.allocatedAmount), alloc.currencyCode),
                        isHighlighted: true
                      }
                    ]}
                  />
                ))}
              </div>
            </>
          ) : (
            <p className="text-sm mt-2" style={{ color: 'var(--text-muted)' }}>
              {t('noPaymentsAllocated')}
            </p>
          )}
        </div>

      </div>

      {selectedPaymentId && (
        <PaymentManagerSlideOver
          paymentId={selectedPaymentId}
          onClose={() => setSelectedPaymentId(null)}
          onSaved={(close) => {
            if (close !== false) setSelectedPaymentId(null);
            loadInvoice();
          }}
        />
      )}
    </DetailsLayout>
  );
}

'use client';

import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import { useState, useEffect } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import { formatAmount } from '@/lib/currency';
import { useTranslations } from 'next-intl';
import { computeLinePrice } from '@modbm/shared';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import SupplierSelect from '@/components/shared/SupplierSelect';
import ProductSearchInput from '@/components/shared/ProductSearchInput';
import { useSettings } from '@/components/SettingsProvider';
import { calculatePurchaseInvoiceableQuantities, PurchaseInvoice } from '@/lib/purchase-order-utils';
import type { OrderDetail } from '@/app/purchase-orders/[id]/types';

interface LineItem {
  key: number;
  productId?: string;
  productNumber?: string;
  productDescription: string;
  quantityInvoiced: string;
  pricePerUnit: string;
  purchaseOrderLineId?: string;
}

let lineKey = 0;

function emptyLine(): LineItem {
  return {
    key: ++lineKey,
    productDescription: '',
    quantityInvoiced: '1',
    pricePerUnit: '0',
  };
}

export default function NewPurchaseInvoicePage() {
  const { baseCurrency } = useSettings();
  const t = useTranslations('purchaseOrders');
  const tCommon = useTranslations('common');
  useDocumentTitle('Enter Supplier Invoice');
  const router = useRouter();
  const searchParams = useSearchParams();
  const initialPurchaseOrderId = searchParams.get('purchaseOrderId');

  const [vendorId, setVendorId] = useState('');
  const [initialVendorSearchTerm, setInitialVendorSearchTerm] = useState('');
  const [currencyCode, setCurrencyCode] = useState(baseCurrency || '');
  const [supplierInvoiceNumber, setSupplierInvoiceNumber] = useState('');
  const [receiptFilename, setReceiptFilename] = useState('');
  const [notes, setNotes] = useState('');
  const [taxAmountInput, setTaxAmountInput] = useState('0');

  const [lines, setLines] = useState<LineItem[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [loadingInitial, setLoadingInitial] = useState(!!initialPurchaseOrderId);

  // Auto-fill logic from PO
  useEffect(() => {
    if (initialPurchaseOrderId) {
      Promise.all([
        api.purchaseOrdersControllerFindOne(initialPurchaseOrderId).then(r => r.data),
        api.purchaseInvoiceControllerGetPurchaseBills(initialPurchaseOrderId).then(r => r.data),
      ]).then(([order, invoicesRes]) => {
        setVendorId(order.vendorId || '');
        if (order.vendorName) {
          setInitialVendorSearchTerm(order.vendorName);
        }
        setCurrencyCode(order.currencyCode || baseCurrency || '');

        const invoices = ((invoicesRes as any).data || []) ;
        const linesToInvoice = calculatePurchaseInvoiceableQuantities(order.lines as any[], invoices);
        
        const prefilledLines: LineItem[] = linesToInvoice.map(lti => {
          const poLine = order.lines?.find(l => l.purchaseOrderLineId === lti.purchaseOrderLineId);
          return {
            key: ++lineKey,
            productId: poLine?.productId || '',
            productNumber: poLine ? (poLine as any).productNumber || poLine?.productId?.substring(0,8) : '',
            productDescription: poLine?.productDescription || '',
            quantityInvoiced: lti.defaultQty,
            pricePerUnit: poLine?.pricePerUnit || '0',
            purchaseOrderLineId: lti.purchaseOrderLineId,
          };
        });

        if (prefilledLines.length > 0) {
          setLines(prefilledLines);
        } else {
          setLines([emptyLine()]);
        }
      }).catch(err => {
        reportError(err, 'NewPurchaseInvoicePage');
      }).finally(() => {
        setLoadingInitial(false);
      });
    }
  }, [initialPurchaseOrderId]);

  const updateLine = (idx: number, field: keyof LineItem, value: string) => {
    setLines((prev) =>
      prev.map((l, i) => (i === idx ? { ...l, [field]: value } : l)),
    );
  };

  const removeLine = (idx: number) => {
    setLines((prev) => prev.filter((_, i) => i !== idx));
  };

  const addLine = () => {
    setLines((prev) => [...prev, emptyLine()]);
  };

  const computeAmount = (line: LineItem) => {
    return computeLinePrice({
      quantity: parseFloat(line.quantityInvoiced) || 0,
      pricePerUnit: parseFloat(line.pricePerUnit) || 0,
    }).amount;
  };

  const subtotal = lines.reduce((sum, line) => sum + computeAmount(line), 0);
  const totalTax = parseFloat(taxAmountInput) || 0;
  const grandTotal = subtotal + totalTax;

  const handleSubmit = async () => {
    if (!vendorId) {
      setError(tCommon('errors.pleaseSelectSupplier'));
      return;
    }
    if (!supplierInvoiceNumber.trim()) {
      setError('Supplier Invoice Number is required.');
      return;
    }

    setSubmitting(true);
    setError('');

    try {
      const { data: invoice } = await api.invoiceDetailControllerCreateDraftInvoice({
          vendorId,
          supplierInvoiceNumber,
          currencyCode,
          purchaseOrderId: initialPurchaseOrderId || undefined,
          totalAmount: grandTotal,
          taxAmount: totalTax,
          receiptFilename: receiptFilename || undefined,
          notes: notes || undefined,
          lines: lines.map((l: LineItem) => ({
            description: l.productDescription,
            productId: l.productId,
            quantityInvoiced: parseFloat(l.quantityInvoiced),
            pricePerUnit: parseFloat(l.pricePerUnit),
            purchaseOrderLineId: l.purchaseOrderLineId,
          })),
      });
      router.push(`/supplier-invoices/${(invoice).invoiceId}`);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : tCommon('errors.failedToGenerateInvoice'));
    } finally {
      setSubmitting(false);
    }
  };

  if (loadingInitial) {
    return (
      <div className="flex items-center justify-center p-12 text-gray-500 text-sm">
        Loading...
      </div>
    );
  }

  return (
    <>
      <DetailsLayout
        header={
          <EntityHeader
            title="Enter Supplier Invoice"
            onBack={() => router.push(initialPurchaseOrderId ? `/purchase-orders/${initialPurchaseOrderId}` : '/supplier-invoices')}
            actions={
              <>
                <button
                  className="btn btn-secondary btn-sm"
                  onClick={() => router.push(initialPurchaseOrderId ? `/purchase-orders/${initialPurchaseOrderId}` : '/supplier-invoices')}
                  disabled={submitting}
                >
                  {tCommon('cancel')}
                </button>
                <button
                  className="btn btn-primary btn-sm"
                  onClick={handleSubmit}
                  disabled={submitting}
                >
                  {submitting ? tCommon('saving') : t('buttons.submitBill', { defaultValue: 'Submit Bill' })}
                </button>
              </>
            }
            showPrint={false}
          />
        }
      >
        {error && (
          <div
            className="mb-4 px-4 py-3 rounded-lg text-sm"
            style={{
              background: 'rgba(239, 68, 68, 0.1)',
              border: '1px solid rgba(239, 68, 68, 0.3)',
              color: '#f87171',
            }}
          >
            {error}
          </div>
        )}

        <div className="flex flex-col gap-3">
          <div className="card">
            <h3 className="section-heading">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined">receipt_long</span>
              Invoice Details
            </h3>
            <div className="grid grid-cols-2 gap-4">
              <div className="relative">
                <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                  {t('labels.supplier')} *
                </label>
                <SupplierSelect
                  value={vendorId}
                  onChange={(s) => {
                    setVendorId(s?.vendorId || '');
                    setCurrencyCode(s?.currencyCode || baseCurrency);
                  }}
                  placeholder={t('placeholders.searchSuppliers')}
                  required
                  initialSearchTerm={initialVendorSearchTerm}
                />
              </div>

              <div>
                <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                  {t('supplierInvoice.invoiceNumberLabel')}
                </label>
                <input
                  className="input"
                  placeholder="e.g. INV-2024-999"
                  value={supplierInvoiceNumber}
                  onChange={(e) => setSupplierInvoiceNumber(e.target.value)}
                />
              </div>

              <div>
                <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                  {tCommon('columns.currency')}
                </label>
                <input
                  className="input"
                  placeholder={baseCurrency}
                  value={currencyCode}
                  onChange={(e) => setCurrencyCode(e.target.value.toUpperCase())}
                />
              </div>

              <div>
                <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                  {t('supplierInvoice.receiptFilenameLabel')}
                </label>
                <input
                  className="input"
                  placeholder="e.g. receipt.pdf"
                  value={receiptFilename}
                  onChange={(e) => setReceiptFilename(e.target.value)}
                />
              </div>

              <div className="col-span-2 mt-2">
                <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                  {tCommon('notesCardHeading')}
                </label>
                <textarea
                  className="input w-full"
                  style={{ minHeight: 80, paddingTop: 12, resize: 'vertical' }}
                  placeholder={tCommon('notesCardPlaceholder')}
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                />
              </div>
            </div>
          </div>

          <div className="card">
            <div className="flex items-center justify-between mb-4">
              <h3 className="section-heading !mb-0">
                {/* eslint-disable-next-line i18next/no-literal-string */}
                <span className="material-symbols-outlined">list</span>
                {t('lineItems')}
              </h3>
              <div className="flex items-center gap-3">
                <button className="btn btn-secondary btn-sm" onClick={addLine}>
                  {t('supplierInvoice.addLine')}
                </button>
              </div>
            </div>

            {/* Desktop Table */}
            <table className="table-lines hidden lg:table">
              <thead>
                <tr>
                  <th style={{ width: 40 }}>#</th>
                  <th style={{ width: 160 }}>{t('columns.product')}</th>
                  <th>{t('columns.description')}</th>
                  <th style={{ width: 110, textAlign: 'right' }}>{t('columns.qtyToBill', { defaultValue: 'Qty' })}</th>
                  <th style={{ width: 130, textAlign: 'right' }}>{t('columns.unitPrice')}</th>
                  <th style={{ width: 130, textAlign: 'right' }}>{t('columns.amount')}</th>
                  <th style={{ width: 50 }}></th>
                </tr>
              </thead>
              <tbody>
                {lines.map((line, idx) => (
                  <tr key={line.key}>
                    <td style={{ color: 'var(--text-muted)' }}>{idx + 1}</td>
                    <td>
                      {line.productId ? (
                        <div className="font-semibold" style={{ color: 'var(--accent)' }}>
                          {line.productNumber || line.productId.substring(0, 8)}
                        </div>
                      ) : (
                        <ProductSearchInput
                          onSelect={(p) => {
                            setLines((prev) =>
                              prev.map((l, i) =>
                                i === idx
                                  ? { ...l, productId: p.productId, productNumber: p.productNumber, productDescription: l.productDescription || p.name }
                                  : l,
                              ),
                            );
                          }}
                          placeholder="Search product…"
                          style={{ minWidth: 120 }}
                        />
                      )}
                    </td>
                    <td>
                      <input
                        className="input"
                        style={{ width: '100%', fontSize: 13 }}
                        value={line.productDescription || ''}
                        onChange={(e) => updateLine(idx, 'productDescription', e.target.value)}
                        placeholder="Description..."
                      />
                    </td>
                    <td style={{ textAlign: 'right' }}>
                      <input
                        className="input"
                        type="number"
                        min="0"
                        step="1"
                        style={{ width: '100%', textAlign: 'right' }}
                        value={line.quantityInvoiced}
                        onChange={(e) => updateLine(idx, 'quantityInvoiced', e.target.value)}
                      />
                    </td>
                    <td style={{ textAlign: 'right' }}>
                      <input
                        className="input"
                        type="number"
                        min="0"
                        step="0.01"
                        style={{ width: '100%', textAlign: 'right' }}
                        value={line.pricePerUnit}
                        onChange={(e) => updateLine(idx, 'pricePerUnit', e.target.value)}
                        onBlur={(e) => {
                          const val = parseFloat(e.target.value);
                          if (!isNaN(val)) updateLine(idx, 'pricePerUnit', val.toFixed(2));
                        }}
                      />
                    </td>
                    <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                      {formatAmount(computeAmount(line), currencyCode)}
                    </td>
                    <td>
                      {lines.length > 1 && (
                        <button className="btn btn-danger btn-sm" onClick={() => removeLine(idx)}>
                          <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} />
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
                {lines.length === 0 && (
                  <tr>
                    <td colSpan={7} style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '20px 0' }}>
                      {t('supplierInvoice.noItems')}
                    </td>
                  </tr>
                )}
                <tr style={{ borderTop: '2px solid var(--border)' }}>
                  <td colSpan={5} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                    {tCommon('subtotal')}
                  </td>
                  <td style={{ textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                    {formatAmount(subtotal, currencyCode)}
                  </td>
                  <td></td>
                </tr>
                <tr>
                  <td colSpan={5} style={{ textAlign: 'right', fontWeight: 600, color: 'var(--text-muted)' }}>
                    {t('supplierInvoice.taxTotalAmount', { tax: tCommon('tax') })}
                  </td>
                  <td style={{ textAlign: 'right' }}>
                    <input
                      className="input"
                      type="number"
                      min="0"
                      step="0.01"
                      style={{ width: '100%', textAlign: 'right', fontWeight: 600, fontVariantNumeric: 'tabular-nums', padding: '4px 8px' }}
                      value={taxAmountInput}
                      onFocus={(e) => {
                        if (parseFloat(e.target.value) === 0) {
                          setTaxAmountInput('');
                        }
                      }}
                      onChange={(e) => setTaxAmountInput(e.target.value)}
                      onBlur={(e) => {
                        const val = parseFloat(e.target.value);
                        if (!isNaN(val)) {
                          setTaxAmountInput(val.toFixed(2));
                        } else {
                          setTaxAmountInput('0.00');
                        }
                      }}
                    />
                  </td>
                  <td></td>
                </tr>
                <tr style={{ backgroundColor: 'rgba(59,130,246,0.02)' }}>
                  <td colSpan={5} style={{ textAlign: 'right', fontWeight: 700, fontSize: 13, color: 'var(--text-primary)' }}>
                    {tCommon('total')}
                  </td>
                  <td style={{ textAlign: 'right', fontWeight: 800, fontSize: 14, color: 'var(--accent)', fontVariantNumeric: 'tabular-nums' }}>
                    {formatAmount(grandTotal, currencyCode)}
                  </td>
                  <td></td>
                </tr>
              </tbody>
            </table>

            {/* Mobile Cards */}
            <div className="lg:hidden flex flex-col gap-4 mt-2">
              {lines.map((line, idx) => (
                <div key={line.key} className="bg-white border border-slate-200 rounded-lg p-4 flex flex-col gap-3 relative">
                  <div className="flex justify-between items-center pb-2 border-b border-slate-100">
                    <span className="font-bold text-slate-500 text-sm">Line {idx + 1}</span>
                    {lines.length > 1 && (
                      <button className="text-gray-400 hover:text-red-500" onClick={() => removeLine(idx)}>
                        <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} />
                      </button>
                    )}
                  </div>
                  
                  <div>
                    <label className="text-xs text-slate-500 mb-1 block">{t('columns.product')}</label>
                    {line.productId ? (
                      <div className="font-semibold" style={{ color: 'var(--accent)' }}>
                        {line.productNumber || line.productId.substring(0, 8)}
                      </div>
                    ) : (
                      <ProductSearchInput
                        onSelect={(p) => {
                          setLines((prev) =>
                            prev.map((l, i) =>
                              i === idx
                                ? { ...l, productId: p.productId, productNumber: p.productNumber, productDescription: l.productDescription || p.name }
                                : l,
                            ),
                          );
                        }}
                        placeholder="Search product…"
                      />
                    )}
                  </div>
                  
                  <div>
                    <label className="text-xs text-slate-500 mb-1 block">{t('columns.description')}</label>
                    <input
                      className="input w-full text-sm"
                      value={line.productDescription || ''}
                      onChange={(e) => updateLine(idx, 'productDescription', e.target.value)}
                      placeholder="Description..."
                    />
                  </div>
                  
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="text-xs text-slate-500 mb-1 block">{t('columns.qtyToBill', { defaultValue: 'Qty' })}</label>
                      <input
                        className="input w-full text-right tabular-nums"
                        type="number"
                        min="0"
                        step="1"
                        value={line.quantityInvoiced}
                        onChange={(e) => updateLine(idx, 'quantityInvoiced', e.target.value)}
                      />
                    </div>
                    <div>
                      <label className="text-xs text-slate-500 mb-1 block">{t('columns.unitPrice')}</label>
                      <input
                        className="input w-full text-right tabular-nums"
                        type="number"
                        min="0"
                        step="0.01"
                        value={line.pricePerUnit}
                        onChange={(e) => updateLine(idx, 'pricePerUnit', e.target.value)}
                        onBlur={(e) => {
                          const val = parseFloat(e.target.value);
                          if (!isNaN(val)) updateLine(idx, 'pricePerUnit', val.toFixed(2));
                        }}
                      />
                    </div>
                  </div>
                  
                  <div className="flex justify-between items-center pt-2 border-t border-slate-100">
                    <span className="text-sm font-bold text-slate-500">{t('columns.amount')}</span>
                    <span className="font-semibold text-[15px] text-[var(--accent)] tabular-nums">{formatAmount(computeAmount(line), currencyCode)}</span>
                  </div>
                </div>
              ))}

              {lines.length === 0 && (
                <div className="text-center text-slate-400 py-6 text-sm">
                  {t('supplierInvoice.noItems')}
                </div>
              )}

              <div className="bg-white border border-slate-200 rounded-lg p-4 flex flex-col gap-3 mt-2">
                <div className="flex justify-between items-center">
                  <span className="text-sm font-semibold text-slate-500">{tCommon('subtotal')}</span>
                  <span className="font-semibold tabular-nums">{formatAmount(subtotal, currencyCode)}</span>
                </div>
                
                <div className="flex justify-between items-center gap-4">
                  <span className="text-sm font-semibold text-slate-500 whitespace-nowrap">{t('supplierInvoice.taxTotalAmount', { tax: tCommon('tax') })}</span>
                  <input
                    className="input text-right font-semibold py-1 px-2 w-24 tabular-nums"
                    type="number"
                    min="0"
                    step="0.01"
                    value={taxAmountInput}
                    onFocus={(e) => {
                      if (parseFloat(e.target.value) === 0) {
                        setTaxAmountInput('');
                      }
                    }}
                    onChange={(e) => setTaxAmountInput(e.target.value)}
                    onBlur={(e) => {
                      const val = parseFloat(e.target.value);
                      if (!isNaN(val)) {
                        setTaxAmountInput(val.toFixed(2));
                      } else {
                        setTaxAmountInput('0.00');
                      }
                    }}
                  />
                </div>
                
                <div className="flex justify-between items-center pt-3 border-t border-slate-100 bg-[rgba(59,130,246,0.02)] -mx-4 px-4 pb-1">
                  <span className="font-bold text-[13px] text-slate-700">{tCommon('total')}</span>
                  <span className="font-extrabold text-lg text-[var(--accent)] tabular-nums">{formatAmount(grandTotal, currencyCode)}</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </DetailsLayout>
    </>
  );
}
